const t=[{id:1,code:"FACT-101",icon:"HardHat",accent:"#ea580c",title:"معدات الوقاية الشخصية (PPE)",subtitle:"Personal Protective Equipment",summary:"التعرّف على معدات الوقاية الشخصية واستخدامها الصحيح",blocks:[{body:"معدات الوقاية الشخصية (PPE) هي خط الدفاع الأخير ضد الإصابات: فقبل اللجوء إليها يجب إزالة الخطر أو تقليله بالضوابط الهندسية وإجراءات العمل (تسلسل الضوابط Hierarchy of Controls). واستخدام معدات الوقاية الشخصية في المصانع ليس اختياريًا، بل إلزامي."},{heading:"1. الأنواع الرئيسية لمعدات الوقاية الشخصية",body:"لكل جزء من الجسم معدات خاصة به:",points:["الرأس: خوذة الحماية (Hard Hat) — للحماية من سقوط الأجسام والصدمات.","العينان: نظارات السلامة (Safety Glasses) — للحماية من الغبار والمواد الكيميائية والشرر والرذاذ المتطاير.","الأذنان: واقيات السمع (Earmuffs / Earplugs) — للحماية من الضجيج العالي للآلات (85 dB(A) فأكثر).","اليدان: القفازات — للحماية من الجروح القطعية والحرارة والمواد الكيميائية.","القدمان: أحذية السلامة ذات المقدمة الفولاذية (Steel Toe) — للحماية من السحق وسقوط الأجسام الثقيلة.","الجسم: ملابس عالية الوضوح (Hi-Vis) بألوان زاهية — ليراك السائقون والعمال الآخرون."]},{heading:"2. اختيار معدات الوقاية الشخصية وملاءمتها وفحصها",body:"لا تحمي معدات الوقاية الشخصية إلا إذا كانت مناسبة للخطر، وملائمة لجسم العامل، وفي حالة جيدة:",points:["اختر معدات الوقاية وفق تقييم المخاطر وصحيفة بيانات السلامة (SDS) للمواد المستخدمة، لا وفق العادة.","افحص كل قطعة قبل الاستخدام: الشقوق في الخوذة، والعدسات المخدوشة، والقفازات الممزقة، والأحذية التالفة.","يجب أن يناسب القفاز الخطر: القفاز المقاوم للقطع لا يمنع المواد الكيميائية، والقفاز الكيميائي يجب أن يكون من النوع المذكور في صحيفة SDS.","استبدل القطع التالفة أو البالية، وأبلغ مشرفك إذا نقصت معدات الوقاية بدلًا من العمل من دونها."]},{heading:"3. واجبات المديرين والعمال",body:"لا تنجح معدات الوقاية الشخصية إلا كنظام مشترك بين المديرين والعمال:",points:["يقيّم صاحب العمل المخاطر، ويوفّر معدات وقاية مناسبة بالمقاسات الصحيحة، ويدرّب العمال على استخدامها، ويستبدلها عند تلفها.","يرتدي العامل معدات الوقاية بشكل صحيح طوال مدة المهمة، ويعتني بها، ويبلّغ عن أي عيب.","لا تعمل واقيات السمع إلا إذا ارتُديت طوال الوقت في المنطقة الصاخبة؛ ونزعها، ولو لفترة قصيرة، يقلّل الحماية.","المتطلبات القانونية لمعدات الوقاية: اتبع متطلبات الدفاع المدني والجهة المختصة."]}],media:[{kind:"video",src:"media/videos/ppe_tutorial.mp4",title:"معدات الوقاية الشخصية (PPE)",description:"الطريقة الصحيحة لارتدائها"}],quiz:[{question:"وفقًا للمعايير الأوروبية، متى يصبح استخدام واقيات السمع إلزاميًا؟",options:[{text:"50 dB",correct:!1},{text:"70 dB(A) فأكثر (متوسط 8 ساعات عمل)",correct:!1},{text:"85 dB(A) فأكثر (متوسط 8 ساعات عمل)",correct:!0},{text:"120 dB(A) فأكثر (متوسط 8 ساعات عمل)",correct:!1}],explanation:"وفقًا للتوجيه الأوروبي 2003/10/EC، عندما يبلغ متوسط مستوى الضجيج خلال 8 ساعات عمل 85 dB(A)، يجب استخدام واقيات السمع. كما تشترط OSHA عند 85 dBA تطبيق برنامج للمحافظة على السمع."},{question:"معدات الوقاية الشخصية (PPE) هي خط الدفاع الأخير ضد الإصابات. ما الذي يجب أن يأتي قبلها؟",options:[{text:"شراء معدات وقاية أغلى ثمنًا",correct:!1},{text:"إزالة الخطر أو تقليله",correct:!0},{text:"مطالبة العمال بالعمل أسرع لتقليل مدة التعرض للخطر",correct:!1},{text:"الانتظار حتى تكشف إصابةٌ مكانَ الخطر",correct:!1}],explanation:"قبل اللجوء إلى معدات الوقاية الشخصية يجب إزالة الخطر أو تقليله بالضوابط الهندسية وإجراءات العمل (تسلسل الضوابط Hierarchy of Controls)؛ فهي خط الدفاع الأخير، واستخدامها في المصانع يبقى إلزاميًا."},{question:"لماذا يرتدي العمال ملابس عالية الوضوح (Hi-Vis) بألوان زاهية؟",options:[{text:"لحماية الجلد من المواد الكيميائية والحرارة",correct:!1},{text:"لتمييز القسم الذي ينتمي إليه كل عامل",correct:!1},{text:"للحفاظ على دفء الجسم في الورش الباردة",correct:!1},{text:"ليراهم السائقون والعمال الآخرون",correct:!0}],explanation:"الملابس عالية الوضوح بألوان زاهية تجعل العامل ظاهرًا ليراه السائقون والعمال الآخرون؛ أما الحماية من المواد الكيميائية والحرارة فتوفّرها معدات أخرى مثل القفازات."},{question:"في خوذة أحد العمال شق ظاهر، لكنها ما زالت مناسبة لرأسه. ماذا يجب أن يفعل؟",options:[{text:"يستبدلها قبل المهمة التالية، لأن الشق قد ينهار عند الصدمة",correct:!0},{text:"يستمر في استخدامها لأنها مناسبة والشق صغير",correct:!1},{text:"يغطي الشق بشريط لاصق ويستخدمها حتى نهاية الشهر",correct:!1},{text:"يلبسها بالمقلوب حتى يكون الشق بعيدًا عن جهة العمل",correct:!1}],explanation:"لا يجوز استخدام معدات الوقاية التالفة: فالخوذة المشقوقة قد تنهار عند الصدمة. أبلغ عنها واستبدلها قبل متابعة العمل."},{question:"سيسكب عامل مادة تنظيف كيميائية أكّالة. كيف تختار قفازاته؟",options:[{text:"نوع القفاز الذي تحدده صحيفة SDS لتلك المادة",correct:!0},{text:"أي قفازات عمل سميكة، لأنها تحمي من الحرارة والجروح",correct:!1},{text:"قفازات قطنية، لأنها مريحة وتمتص الرذاذ",correct:!1},{text:"لا قفازات أبدًا، فغسل اليدين بعد العمل يكفي",correct:!1}],explanation:"تحدد صحيفة SDS (القسم 8) الحماية لكل مادة. القفاز المقاوم للقطع أو القطني لا يمنع المواد الكيميائية، والقطن يبقيها ملامسة للجلد."},{question:"في منطقة صاخبة، ينزع عامل سدادات أذنيه من حين لآخر ليتكلم. ما المشكلة؟",options:[{text:"في كل مرة يصل الضجيج إلى أذنيه وتنخفض حمايته",correct:!0},{text:"لا مشكلة ما دام يرتديها معظم الوردية",correct:!1},{text:"السدادات مهمة فقط في نهاية الوردية عندما يتعب",correct:!1},{text:"المسألة مسألة راحة فقط؛ فالضجيج لا يضر إلا عندما يؤلم",correct:!1}],explanation:"لا تعمل واقيات السمع إلا إذا ارتُديت طوال الوقت في المنطقة الصاخبة؛ ونزعها ولو لفترة قصيرة يسمح للضجيج بالوصول إلى الأذنين. استخدم إشارات يدوية متفقًا عليها أو اخرج من المنطقة الصاخبة لتتكلم."}],steps:[{title:"اعرف الخطر",detail:"قبل المهمة، اقرأ تقييم المخاطر وتعليمات العمل وصحيفة SDS، واعرف ما الذي قد يصدمك أو يجرحك أو يحرقك أو يتناثر عليك أو يضر بسمعك."},{title:"اختر المعدات الصحيحة",detail:"خذ المعدات التي تتطلبها المهمة لكل جزء من الجسم؛ واسأل مشرفك إذا لم تكن متأكدًا."},{title:"افحصها قبل الاستخدام",detail:"افحص كل قطعة بحثًا عن التلف، وتأكد من المقاس الصحيح والملاءمة الجيدة؛ ولا تستخدم معدات تالفة.",critical:!0},{title:"ارتدِها بشكل صحيح طوال الوقت",detail:"اربط حزام الذقن، وأدخل سدادات الأذن بالكامل، وثبّت النظارات قريبة من الوجه؛ وأبقِ كل شيء عليك ما دمت في منطقة الخطر.",critical:!0},{title:"الخلع والتنظيف والحفظ",detail:"اخلع المعدات الملوثة من دون أن يلمس جلدك المكشوف سطحها الخارجي، ونظّفها أو تخلّص منها وفق التعليمات، واحفظها نظيفة وجافة، وأبلغ عن أي عيب."}],warnings:["لا تعمل أبدًا من دون معدات الوقاية التي تتطلبها المهمة: فهي لا تزيل الخطر، لكن من دونها يصل الخطر إلى جسمك مباشرة.","لا تستخدم أبدًا معدات تالفة أو مصممة لخطر آخر: فالخوذة المشقوقة أو القفاز الخطأ يعطيان ثقة زائفة وقد يفشلان عند الحاجة."],tips:["اكتب اسمك على معداتك الشخصية لتكون مناسبة لك ولتعرف تاريخها.","اطلب مقاسًا أو طرازًا آخر إذا كانت المعدات غير مريحة؛ فالمعدات المؤلمة كثيرًا ما تُخلع.","المشرفون قدوة: ارتدوا معدات الوقاية نفسها التي يرتديها العمال في كل منطقة خطر."],activity:{prompt:"أنت مشرف. عامل جديد على وشك تجليخ قطعة معدنية بالجلّاخة (Grinder). يرتدي الخوذة والقفازات لكن من دون نظارات السلامة، ويقول إن العمل قصير جدًا. ماذا تفعل؟",options:[{text:"أوقف المهمة حتى تتوفر له نظارات سلامة مناسبة للتجليخ، وأشرح له السبب.",correct:!0,feedback:"صحيح: التجليخ يقذف جزيئات متطايرة؛ والأعمال القصيرة تصيب العيون أيضًا، ولا يجوز للمشرف أن يسمح بالعمل من دون معدات الوقاية المطلوبة."},{text:"أتركه يعمل لأن العمل قصير.",correct:!1,feedback:"خطأ: إصابة العين تحدث في جزء من الثانية؛ وقصر المهمة لا يقلل الخطر."},{text:"أطلب منه أن يدير وجهه جانبًا أثناء التجليخ.",correct:!1,feedback:"خطأ: إدارة الوجه ليست حماية؛ فالجزيئات ترتد وقد تصل إلى العينين."},{text:"أعيره نظاراتي العادية.",correct:!1,feedback:"خطأ: النظارات العادية ليست نظارات سلامة؛ فقد تتحطم وتسمح بدخول الجزيئات من الجانبين."}]},caseStudy:[{prompt:"في قسم الطلاء، يخلط عامل مادة مذيبة (Solvent). تطلب صحيفة SDS قفازات كيميائية وحماية للعينين، لكن القفازات الكيميائية نفدت من المخزن وهو يرتدي قفازات قطنية. أنت مشرف الوردية. ماذا تفعل أولًا؟",options:[{text:"أوقف الخلط حتى تتوفر القفازات الكيميائية الصحيحة، وأبلغ عن النقص.",correct:!0,feedback:"صحيح: صحيفة SDS هي التي تحدد معدات الوقاية؛ والقطن يمتص المذيب ويبقيه ملامسًا للجلد."},{text:"أتركه يكمل بالقفازات القطنية ثم يغسل يديه.",correct:!1,feedback:"خطأ: القفازات القطنية تمتص المذيب وتزيد ملامسته للجلد."},{text:"أعطيه زوجًا آخر من القفازات القطنية ليلبسه فوقها.",correct:!1,feedback:"خطأ: زيادة طبقات المادة الخطأ لا توقف المادة الكيميائية."}]},{prompt:"بينما ترتّب قفازات جديدة، يخبرك العامل أن المذيب نفذ عبر قفازه إلى يده قبل بضع دقائق. ماذا تفعل الآن؟",options:[{text:"أنزع القفاز الملوث، وأغسل الجلد بكمية وفيرة من الماء الجاري، وأتبع الإسعافات الأولية في صحيفة SDS، وأتصل بالرقم 122 عند الحاجة.",correct:!0,feedback:"صحيح: أزل التلوث بسرعة واتبع قسم الإسعافات الأولية في صحيفة SDS؛ ثم سجّل الحادثة."},{text:"أمسح يده بقطعة قماش جافة وأتركه يرتاح.",correct:!1,feedback:"خطأ: المسح يُبقي المادة على الجلد؛ والغسل بالماء الجاري هو إجراء الإسعاف الأولي."},{text:"أنتظر لأرى هل يحمرّ الجلد قبل أن أفعل أي شيء.",correct:!1,feedback:"خطأ: بعض المواد تضر الجلد أو تنفذ عبره قبل ظهور أي علامة؛ تصرّف فورًا."}]}],realCase:"في ورشة معادن، طُلب من عامل ارتداء نظارات السلامة أثناء قطع الفولاذ. فخلعها لأنها كانت تتغشّى بالبخار، وواصل العمل قرب الجلّاخة. أصابت عينه شظية معدنية صغيرة، فاحتاج إلى علاج في المستشفى وإلى عدة أيام من الانقطاع عن العمل. وكشف التحقيق أن الورشة لم يكن فيها سوى طراز واحد من النظارات ولا يوجد نوع مضاد للتغشّي. فاشترت الإدارة نظارات بعدة مقاسات وطرازات مضادة للتغشّي، ودرّبت المشرفين على فحص معدات الوقاية في بداية كل وردية، وبدأت تسجيل كل حادثة كادت أن تقع."},{id:2,code:"FACT-102",icon:"Cog",accent:"#2563eb",title:"سلامة الآلات",subtitle:"Machine Safety & Guarding",summary:"حماية العمال من الأجزاء المتحركة في الآلات",blocks:[{body:"الآلات الصناعية ذات قوة كبيرة، ويمكنها في ثانية واحدة أن تسبب إصابات بالغة أو فقدان أحد أعضاء الجسم."},{heading:"1. حواجز حماية الآلات (Machine Guards)",body:"يجب توفر وسائل الحماية هذه على جميع الآلات الخطرة:",points:["الحواجز الثابتة: لتغطية السيور والتروس المتحركة.","زر إيقاف الطوارئ (E-Stop): يجب أن يكون قريبًا من يد العامل، وباللون الأحمر على خلفية صفراء.","حساسات الإيقاف: تتوقف الآلة إذا اقتربت اليد أو الجسم من المنطقة الخطرة."]},{heading:"2. القواعد الذهبية",body:"قبل العمل وفي أثنائه:",points:["لا تُزِل أبدًا حاجز الحماية عن الآلة وهي تعمل.","لا ترتدِ الملابس الفضفاضة أو السلاسل أو الخواتم، واربط الشعر الطويل، كي لا تعلق في الآلة.","إذا تعطّلت الآلة، فأوقفها فورًا بزر E-Stop، ولا تُدخل يدك في الآلة دون تطبيق إجراء عزل الطاقة وإقفالها (LOTO)."]},{heading:"3. قبل تشغيل الآلة",body:"فحص قصير في بداية كل وردية يمنع كثيرًا من الإصابات:",points:["الحواجز في مكانها ومثبتة؛ والأبواب ذات الأقفال البينية (Interlock) وحساسات السلامة تعمل.","زر إيقاف الطوارئ (E-Stop) في متناول اليد ويُختبر وفق تعليمات العمل.","مكان العمل نظيف، ولا توجد أدوات أو خرق أو بقايا على الآلة.","لا يشغّل الآلة إلا العمال المدرَّبون والمخوَّلون.","يُبلَّغ عن أي حاجز مفقود أو عطل، ولا تُشغَّل الآلة حتى يُصلَح."]},{heading:"4. الانحشار والتنظيف والصيانة",body:"تقع كثير من إصابات الآلات الخطيرة أثناء الأعمال غير الروتينية، مثل إزالة الانحشار والتنظيف والضبط:",points:["إيقاف الآلة بزر E-Stop لا يكفي للعمل داخلها: طبّق الإقفال والوسم (LOTO) (انظر درس السلامة الكهربائية).","انتظر حتى تتوقف كل الأجزاء المتحركة تمامًا؛ فبعض الأجزاء تواصل الدوران بعد قطع الكهرباء.","حرّر الطاقة المخزّنة أو ثبّتها، مثل النوابض والضغط والأجزاء المرفوعة، وفق الإجراء.","استخدم الأدوات المخصّصة لإزالة الانحشار، ولا تستخدم يديك أبدًا داخل منطقة الخطر.","أعِد تركيب كل الحواجز وافحصها قبل إعادة التشغيل، ونبّه الجميع إلى أن الآلة ستبدأ العمل."]}],media:[{kind:"image",src:"media/images/machine_guard.png",title:"حواجز حماية الآلات",description:"مثال على حاجز حماية صحيح"}],quiz:[{question:"هل يجوز إزالة حاجز حماية الآلة وهي تعمل؟",options:[{text:"نعم، إذا دعت الحاجة",correct:!1},{text:"لا، لا يجوز ذلك بأي حال من الأحوال",correct:!0},{text:"فقط من أجل التنظيف",correct:!1},{text:"فقط إذا أذن المسؤول المباشر بذلك",correct:!1}],explanation:"إزالة حاجز حماية الآلة وهي تعمل من أخطر السلوكيات. ولا يُجرى التنظيف والإصلاح إلا بعد إيقاف الآلة وعزل طاقتها وإقفالها (LOTO)."},{question:"إذا تعطّلت الآلة في أثناء عملك عليها، فماذا تفعل؟",options:[{text:"أُوقفها فورًا بزر E-Stop",correct:!0},{text:"أُدخل يدي بسرعة وأزيل العائق بيدي",correct:!1},{text:"أتركها تعمل وأبلغ المسؤول لاحقًا",correct:!1},{text:"أُزيل حاجز الحماية لأرى سبب العطل",correct:!1}],explanation:"إذا تعطّلت الآلة، فأوقفها فورًا بزر E-Stop، ولا تُدخل يدك في الآلة دون تطبيق إجراء عزل الطاقة وإقفالها (LOTO)."},{question:"لماذا يجب ألّا ترتدي الملابس الفضفاضة أو السلاسل أو الخواتم قرب الآلات؟",options:[{text:"لأنها تجعل قراءة أزرار التحكم أصعب",correct:!1},{text:"لأنها تخالف قواعد لباس المصنع فقط",correct:!1},{text:"لأنها قد تعلق في الآلة",correct:!0},{text:"لأنها قد تُتلف حواجز حماية الآلة",correct:!1}],explanation:"قد تعلق الملابس الفضفاضة والسلاسل والخواتم والشعر الطويل في الآلة، والآلة يمكن أن تسبب إصابة بالغة في ثانية واحدة؛ لذلك اربط الشعر الطويل أيضًا."},{question:"حساس سلامة يوقف مكبسًا (Press) مرارًا أثناء الإنتاج. ما الإجراء الصحيح؟",options:[{text:"أبلغ عنه واطلب فحص السبب؛ ويبقى الحساس فعّالًا",correct:!0},{text:"غطِّ الحساس بشريط لاصق حتى تنتهي الطلبية",correct:!1},{text:"أطفئ الحساس واطلب من المشغّل أن ينتبه ليديه",correct:!1},{text:"شغّل المكبس ببطء أكثر ليقلّ توقفه بسبب الحساس",correct:!1}],explanation:"الحساس الذي يوقف الآلة إما يؤدي عمله أو معطّل؛ وفي الحالتين يفحصه شخص مؤهل. وتعطيل جهاز السلامة يزيل الحاجز بين العامل ومنطقة الخطر."},{question:"ضغطت زر E-Stop وتريد إزالة انحشار داخل الآلة. هل يكفي ذلك قبل أن تُدخل يدك؟",options:[{text:"لا؛ يجب عزل الطاقة بالإقفال والوسم والتحقق أولًا",correct:!0},{text:"نعم، لأن زر E-Stop يقطع كل الطاقة عن الآلة",correct:!1},{text:"نعم، إذا طلبت من زميل ألا يلمس أدوات التحكم",correct:!1},{text:"نعم، إذا كان الانحشار قريبًا من حافة الآلة",correct:!1}],explanation:"زر E-Stop للطوارئ: قد يعيد أحدهم ضبطه، وقد تبقى طاقة مخزّنة. قبل أي عمل داخل الآلة، طبّق الإقفال والوسم وتحقق من أنها لا تستطيع الحركة."},{question:"أي عامل يرتدي ملابس آمنة لتشغيل آلة الثقب (Drill)؟",options:[{text:"أكمام ضيقة، وشعر طويل مربوط، ومن دون خواتم",correct:!0},{text:"معطف عمل فضفاض مزرّر ليبقى نظيفًا",correct:!1},{text:"وشاح طويل مدسوس داخل قميص فضفاض",correct:!1},{text:"شعر قصير، وساعة، وسوار سلسلة على المعصم",correct:!1}],explanation:"الملابس الفضفاضة والحلي والشعر الطويل قد تعلق في الأجزاء الدوّارة: يجب أن تكون الأكمام ضيقة، ويُربط الشعر الطويل، وتُنزع الخواتم والسلاسل والأساور."}],steps:[{title:"أوقف الآلة",detail:"اضغط زر E-Stop أو أوقفها بوسيلة التحكم العادية، ونبّه من حولك.",critical:!0},{title:"لا تُدخل يدك",detail:"أبقِ يديك وجسمك خارج منطقة الخطر، حتى لو بدت الآلة متوقفة.",critical:!0},{title:"أبلغ واعزل الطاقة",detail:"أبلغ المشرف؛ ويطبّق شخص مخوَّل الإقفال والوسم (LOTO)، بقفل وبطاقة على كل مصدر طاقة.",critical:!0},{title:"تأكد من أن شيئًا لن يتحرك",detail:"انتظر حتى تتوقف كل الأجزاء، وحرّر الطاقة المخزّنة، ثم جرّب زر التشغيل والجميع بعيدون للتأكد من أن الآلة لا تتحرك؛ ثم أعِده إلى وضع الإيقاف.",critical:!0},{title:"الإصلاح وإعادة الحواجز والتشغيل",detail:"أزل الانحشار بأدوات مناسبة، وأعِد الحواجز وافحصها؛ ولا يزيل أي قفل إلا صاحبه، ويُنبَّه الجميع قبل إعادة التشغيل."}],warnings:["لا تتجاوز أبدًا حساس السلامة أو القفل البيني ولا تسده ولا تغطه بشريط لاصق لإبقاء الإنتاج مستمرًا: فهذا يزيل الحاجز الوحيد بين العامل والأجزاء المتحركة.","لا تعتمد أبدًا على زر E-Stop وحده عندما تعمل داخل الآلة: فقد يعيد أحدهم ضبطه؛ ووحده الإقفال والوسم يُبقي الطاقة معزولة."],tips:["اعرف مكان زر E-Stop لكل آلة قبل أن تحتاج إليه.","أبقِ الأرضية حول الآلات نظيفة وجافة حتى لا ينزلق أحد نحو الأجزاء المتحركة.","إذا كان الحاجز يصعّب العمل، فأبلغ المشرف ليُحسَّن الحاجز، لا ليُزال."],activity:{prompt:"آلة تغليف تنحشر باستمرار. يطلب مدير الإنتاج من المشغّل إزالة الحاجز لبقية الوردية لتُزال حالات الانحشار بسرعة أكبر. أنت مشرف المشغّل. ماذا تفعل؟",options:[{text:"أرفض: يبقى الحاجز، ولا يُزال الانحشار إلا بعد الإيقاف والإقفال والوسم، ويُبلَّغ عن سبب الانحشار لإصلاحه.",correct:!0,feedback:"صحيح: ضغط الإنتاج لا يبرر أبدًا إزالة الحاجز؛ عالج سبب الانحشار بدلًا من ذلك."},{text:"أسمح بذلك، لكن أطلب من المشغّل أن يكون حذرًا جدًا.",correct:!1,feedback:"خطأ: الحذر لا يوقف الآلة؛ ولحظة سهو تكفي لإصابة بالغة."},{text:"أسمح بذلك فقط إذا راقبه عامل آخر.",correct:!1,feedback:"خطأ: المراقب لا يستطيع إيقاف الأجزاء المتحركة في الوقت المناسب؛ الحاجز هو الحماية."},{text:"أطلب من المشغّل إزالة الانحشار بعصا والآلة تعمل.",correct:!1,feedback:"خطأ: الآلة العاملة قد تسحب العصا واليد معها؛ أوقفها واعزل الطاقة أولًا."}]},caseStudy:[{prompt:"على خط ناقل (Conveyor)، علق كمّ أحد العمال قرب أسطوانة وهو يُسحب نحوها. أنت أقرب عامل إليه. ماذا تفعل أولًا؟",options:[{text:"أضغط فورًا أقرب زر E-Stop أو حبل إيقاف وأصرخ طلبًا للمساعدة.",correct:!0,feedback:"صحيح: إيقاف الآلة أسرع طريقة لإيقاف السحب؛ ثم ساعده."},{text:"أمسك العامل وأشدّه إلى الخلف والناقل ما زال يعمل.",correct:!1,feedback:"خطأ: قد تُسحب أنت أيضًا، والآلة تواصل السحب؛ أوقفها أولًا."},{text:"أركض إلى المكتب لإبلاغ المشرف.",correct:!1,feedback:"خطأ: الثواني مهمة؛ أوقف الآلة بنفسك ثم اطلب المساعدة."}]},{prompt:"توقف الناقل. ذراع العامل ما زالت عالقة بين الأسطوانة والحزام، وهو ينزف. ماذا تفعل الآن؟",options:[{text:"أبقي الآلة متوقفة ومعزولة الطاقة، وأتصل بالرقمين 115 و122، وأسيطر على النزيف بالضغط، ولا أعيد تشغيل الناقل ولا أعكس حركته.",correct:!0,feedback:"صحيح: إعادة التشغيل أو عكس الحركة قد يزيد الإصابة؛ والمنقذون المدرَّبون وفريق الصيانة يحرّرون الذراع بطريقة مسيطر عليها بينما تسيطر أنت على النزيف."},{text:"أشغّل الناقل بالاتجاه المعاكس لتحرير الذراع بسرعة.",correct:!1,feedback:"خطأ: الحركة غير المسيطر عليها قد تزيد الإصابة سوءًا؛ اترك التحرير للرقم 115 وفريق الصيانة."},{text:"أزيل الحاجز وأسحب الذراع بالقوة.",correct:!1,feedback:"خطأ: سحب طرف عالق قد يمزّق الأنسجة ويزيد النزيف؛ انتظر المنقذين المدرَّبين وسيطر على النزيف."}]}],realCase:"في مصنع للأغذية، رأى عامل منتجًا عالقًا داخل خلّاطة (Mixer). كانت الخلّاطة متوقفة لكن طاقتها لم تُعزل. ففتح الغطاء وأدخل يده. وضغط عامل آخر زر التشغيل وهو لا يعلم أن أحدًا عند الخلّاطة، فأُصيبت يد العامل الأول إصابة بالغة. وكشف التحقيق أن القفل البيني للغطاء كان معطّلًا منذ أسابيع، وأن أحدًا لم يكن يطبّق الإقفال والوسم في أعمال التنظيف القصيرة. فأصلحت الشركة القفل البيني، وأعطت كل عامل قفلًا شخصيًا، وجعلت الإقفال والوسم جزءًا من كل عملية تنظيف وإزالة انحشار."},{id:3,code:"FACT-103",icon:"PlugZap",accent:"#ca8a04",title:"السلامة الكهربائية",subtitle:"Industrial Electrical Safety (LOTO)",summary:"مخاطر الكهرباء ونظام الإقفال والوسم (LOTO)",blocks:[{body:"تعمل الكهرباء في المصانع بجهد عالٍ؛ ويمكن أن يؤدي الصعق الكهربائي إلى الوفاة أو إلى حروق بالغة."},{heading:"1. نظام الإقفال والوسم (Lockout/Tagout — LOTO)",body:"هذا أهم إجراء قبل إصلاح الآلات أو تنظيفها:",points:["الإقفال (Lockout): افصل مصدر الكهرباء الرئيسي وضع عليه قفلك الشخصي.","الوسم (Tagout): علّق عليه بطاقة مكتوبًا عليها: «يجري العمل عليه — لا تشغّل»، مع اسمك والتاريخ.","يجب أن يبقى المفتاح بيد الشخص الذي يجري الإصلاح فقط؛ وقبل البدء تأكّد من أن الآلة خالية فعلًا من الطاقة (Verify)."]},{heading:"2. فحص الكابلات",body:"افحص دائمًا:",points:["لا تستخدم الكابلات المقطوعة أو التي تظهر أسلاكها.","الكهرباء والماء عدوّان؛ لا تستخدم الأجهزة الكهربائية في الأماكن المبتلة."]},{heading:"3. تسلسل الإقفال والوسم (LOTO)",body:"يضبط الإقفال والوسم كل مصادر الطاقة، لا الكهرباء وحدها (الضغط، والنوابض، والأجزاء المتحركة، والحرارة):",points:["التحضير: حدّد كل مصادر طاقة الآلة من إجرائها.","الإبلاغ: أخبر المشغّلين وكل من يعنيهم الأمر بأن الآلة ستُوقف.","الإيقاف والعزل: أوقف الآلة بالطريقة العادية، ثم افتح مفاتيح العزل وأغلق الصمامات.","القفل والبطاقة: يضع كل عامل قفله الشخصي وبطاقة باسمه والتاريخ.","تحرير الطاقة المخزّنة: فرّغها أو انزفها أو ثبّتها وفق الإجراء.","التحقق: والجميع بعيدون، حاول تشغيل الآلة وافحص وجود الجهد، ثم أعِد أدوات التحكم إلى وضع الإيقاف."]},{heading:"4. المخاطر الكهربائية اليومية",body:"تبدأ كثير من الحوادث الكهربائية بأعطال صغيرة جرى تجاهلها:",points:["لا تحمّل المقابس فوق طاقتها ولا تصل أسلاك التمديد بعضها ببعض.","أبقِ المساحة أمام اللوحات الكهربائية خالية وأبواب اللوحات مغلقة.","لا يفتح اللوحات أو يصلح الأسلاك إلا كهربائي مؤهل؛ والباقون يبلّغون عن العطل.","أبلغ فورًا عن الحرارة أو رائحة الاحتراق أو الشرر أو قاطع (Breaker) يفصل مرارًا.","لا تلمس أبدًا شخصًا قد يكون ما زال متصلًا بالكهرباء: اقطع الكهرباء أولًا (انظر درس الإسعافات الأولية)."]}],media:[{kind:"video",src:"media/videos/loto_safety.mp4",title:"الإقفال والوسم (LOTO)",description:"كيف نستخدم القفل؟"}],quiz:[{question:"ما المقصود بـ LOTO؟",options:[{text:"التنظيف",correct:!1},{text:"فصل الطاقة وإقفالها قبل الإصلاح",correct:!0},{text:"زيادة سرعة الآلة",correct:!1},{text:"إقفال باب الورشة في نهاية الدوام",correct:!1}],explanation:"يُستخدم نظام LOTO كي لا يعيد أحدٌ توصيل الكهرباء بينما يعمل العامل على الآلة (OSHA 29 CFR 1910.147)."},{question:"وضعت قفلك الشخصي وعلّقت البطاقة. ماذا يجب أن تفعل قبل البدء بالإصلاح؟",options:[{text:"أعطي المفتاح لزميل ليحتفظ به",correct:!1},{text:"أشغّل الآلة لحظة لأختبر القفل",correct:!1},{text:"أتأكد من أن الآلة خالية فعلًا من الطاقة",correct:!0},{text:"أبدأ فورًا، فالقفل وحده يكفي للسلامة",correct:!1}],explanation:"قبل البدء تأكّد من أن الآلة خالية فعلًا من الطاقة (Verify)؛ ويبقى المفتاح بيد الشخص الذي يجري الإصلاح فقط، كي لا يعيد أحدٌ توصيل الكهرباء."},{question:"إذا وجدت كابلًا مقطوعًا تظهر أسلاكه، فماذا تفعل؟",options:[{text:"أستخدمه في الأماكن الجافة فقط",correct:!1},{text:"لا أستخدمه",correct:!0},{text:"ألفّه بشريط لاصق وأواصل استخدامه",correct:!1},{text:"أستخدمه للأدوات الخفيفة فقط",correct:!1}],explanation:"لا تستخدم الكابلات المقطوعة أو التي تظهر أسلاكها؛ فالصعق الكهربائي يمكن أن يؤدي إلى الوفاة أو إلى حروق بالغة."},{question:"سيصلح ثلاثة عمال الآلة نفسها. كيف يجب إقفالها؟",options:[{text:"يضع كل عامل قفله الخاص على مفتاح العزل باستخدام مشبك متعدد الأقفال (Hasp)",correct:!0},{text:"قفل واحد للفريق كله، ويحتفظ المشرف بالمفتاح",correct:!1},{text:"يقفلها عامل واحد ويخبر الآخرين عندما يصبح التشغيل آمنًا",correct:!1},{text:"لا حاجة إلى أقفال إذا عمل الثلاثة معًا طوال الوقت",correct:!1}],explanation:"لا يحمي كل عامل إلا قفله الخاص. ومع المشبك متعدد الأقفال، لا يمكن تشغيل الآلة حتى يزيل آخر عامل قفله."},{question:"أُطفئت آلة من لوحة التحكم. هل من الآمن البدء بإصلاحها؟",options:[{text:"لا؛ اعزل المصدر الرئيسي واقفله، ثم تحقق من انعدام الطاقة",correct:!0},{text:"نعم، إذا أظهرت لوحة التحكم أن الآلة متوقفة",correct:!1},{text:"نعم، إذا وضعت لافتة تحذير على لوحة التحكم",correct:!1},{text:"نعم، إذا كان الإصلاح يستغرق بضع دقائق فقط",correct:!1}],explanation:"يمكن لشخص آخر أن يشغّل زر التحكم. قبل الإصلاح يُعزل مصدر الطاقة الرئيسي ويُقفل، ويُتحقق من انعدام الطاقة."},{question:"لاحظت رائحة احتراق وغطاءً ساخنًا على لوحة كهربائية. ماذا تفعل أولًا؟",options:[{text:"أبعد الناس وأبلغ فورًا لعزل الكهرباء بأمان",correct:!0},{text:"أفتح باب اللوحة لأعرف أي سلك يحترق بالضبط",correct:!1},{text:"أبرّد غطاء اللوحة الساخن بقطعة قماش مبللة",correct:!1},{text:"أواصل العمل وأخبر المشرف في نهاية الوردية",correct:!1}],explanation:"الحرارة ورائحة الاحتراق علامات تحذير من عطل كهربائي. لا تفتح اللوحة ولا تلمسها؛ أبعد الناس وأبلغ لكي يقطع كهربائي مؤهل الكهرباء. وإذا وقع حريق، أطلق الإنذار واتصل بالرقم 115."}],steps:[{title:"ابقَ بعيدًا",detail:"لا تلمس الكابلات التالفة أو المعدات المبتلة أو لوحة يتطاير منها الشرر أو ساخنة؛ وأبعد الآخرين.",critical:!0},{title:"اقطع الكهرباء فقط إذا كان ذلك آمنًا",detail:"افصل من القاطع أو مفتاح العزل فقط إذا استطعت الوصول إليه من دون لمس المعدة المعطلة أو الوقوف في الماء.",critical:!0},{title:"أبلغ وضع علامة",detail:"أبلغ المشرف والكهربائي، وضع على المعدة علامة تفيد بأنها خارج الخدمة."},{title:"الإصلاح فقط مع الإقفال والوسم",detail:"لا يصلحها إلا شخص مؤهل، بعد العزل والقفل والوسم والتحقق من عدم بقاء أي طاقة.",critical:!0},{title:"حريق أو إصابة: اطلب المساعدة",detail:"إذا وقع حريق أو أُصيب أحد، أطلق الإنذار، واتصل بالرقمين 115 و122، ولا تستخدم الماء أبدًا على معدات فيها كهرباء.",critical:!0}],warnings:["لا تُزل أبدًا قفل شخص آخر أو بطاقته، حتى لو بدا أن العمل انتهى: فقد يكون ذلك العامل ما زال داخل الآلة.","لا تعمل أبدًا على معدة أُطفئت بزر التحكم فقط: فقد يشغّلها شخص آخر؛ اعزل المصدر الرئيسي واقفله."],tips:["احتفظ بقفل شخصي بمفتاح واحد لا يحمله أحد غيرك.","افحص كابلات العُدد اليدوية الكهربائية وقوابسها قبل كل وردية.","يختبر الكهربائيون جهاز فحص الجهد على مصدر حي معروف قبل كل قياس وبعده."],activity:{prompt:"في نهاية الوردية، يجد كهربائي قفلًا وبطاقة على مفتاح عزل ناقل. العامل الذي وضعهما ذهب إلى بيته، والإنتاج يريد الناقل للوردية الليلية. ما الذي يجب أن يحدث؟",options:[{text:"يبقى القفل: يُتصل بصاحبه، وإذا تعذّر حضوره يتبع المشرف إجراء الموقع لإزالة القفل بعد التأكد من عدم وجود أحد في خطر.",correct:!0,feedback:"صحيح: لا يزيل القفل إلا صاحبه؛ ولا يُستخدم الإجراء الاستثنائي المضبوط إلا بعد التأكد من أن الآلة خالية وآمنة."},{text:"يُقطع القفل لأن العامل لم يعد في الموقع.",correct:!1,feedback:"خطأ: ربما ترك العامل الآلة في حالة غير آمنة أو يكون أحد بداخلها؛ والإزالة تتبع إجراءً مضبوطًا."},{text:"يُشغَّل الناقل من التحكم المحلي ويبقى القفل مكانه.",correct:!1,feedback:"خطأ: تجاوز العزل يُبطل الإقفال والوسم وقد يصيب أي شخص يعمل على الآلة."},{text:"تُزال البطاقة ويبقى القفل.",correct:!1,feedback:"خطأ: البطاقة تبيّن من عزل الآلة ولماذا؛ وإزالتها تخفي التحذير ولا تجعل شيئًا أكثر أمانًا."}]},caseStudy:[{prompt:"في قسم التغليف، ينتشر الماء من أنبوب يسرّب نحو سلك تمديد يغذّي آلة لحام أكياس (Sealing). عامل على وشك أن يخطو في الماء لينزع القابس. أنت المشرف. ماذا تفعل أولًا؟",options:[{text:"أوقفه وأفصل الدائرة من القاطع الذي أصل إليه من مكان جاف.",correct:!0,feedback:"صحيح: الكهرباء والماء لا يجتمعان؛ اقطع الكهرباء من نقطة آمنة وجافة قبل أن يقترب أحد."},{text:"أتركه ينزع القابس بسرعة ما دامت يداه جافتين.",correct:!1,feedback:"خطأ: الوقوف في الماء قرب معدات فيها كهرباء قد يسبب صعقًا كهربائيًا حتى مع اليدين الجافتين."},{text:"أرمي منشفة على الماء ونواصل العمل.",correct:!1,feedback:"خطأ: الخطر باقٍ؛ يجب قطع الكهرباء وإيقاف التسرب."}]},{prompt:"قُطعت الكهرباء. عامل لمس آلة اللحام سابقًا يقول إنه شعر بوخز في يده لكنه بخير الآن. ماذا تفعل؟",options:[{text:"أرسله لفحص طبي (وأتصل بالرقم 122 إذا ظهرت عليه أي أعراض) وأبقي الآلة خارج الخدمة حتى يفحصها كهربائي مع الإقفال والوسم.",correct:!0,feedback:"صحيح: كل من تعرّض لصعق كهربائي يُفحص طبيًا، وتبقى الآلة خارج الخدمة حتى تُفحص."},{text:"لا شيء آخر، لأنه يشعر أنه بخير.",correct:!1,feedback:"خطأ: كل من تعرّض لصعق كهربائي يحتاج إلى فحص طبي حتى لو شعر أنه بخير."},{text:"أعيد الكهرباء لأرى هل ما زالت الآلة معطلة.",correct:!1,feedback:"خطأ: الاختبار بإعادة الكهرباء يعرّض الجميع للخطر من جديد؛ يفحصها كهربائي مع الإقفال والوسم."}]}],realCase:"كان فنيان يصلحان مضخة. أطفأها أحدهما من لوحة التحكم لكنه لم يقفل مفتاح العزل. وأثناء عملهما، رأى مشغّل من الوردية التالية أن المضخة متوقفة فشغّلها ليستمر الإنتاج. تعرّض أحد الفنيين لصعق كهربائي وسقط، وعولج في المستشفى. وكشف التحقيق أن المصنع لم يكن لديه أقفال شخصية وأن إجراء الإقفال والوسم كان موجودًا على الورق فقط. فاشترى المصنع أقفالًا وبطاقات شخصية، ودرّب كل الفنيين والمشرفين، وبدأ التحقق من الإقفال والوسم في كل عملية إصلاح."},{id:4,code:"FIRE-104",icon:"FireExtinguisher",accent:"#dc2626",title:"مطفأة الحريق — تدريب شامل",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"التعرّف على أنواع المطافئ وفئات الحريق، وشرح مفصّل لإجراء PASS",blocks:[{body:"مطفأة الحريق (Fire Extinguisher) أداة أساسية لإخماد الحرائق الصغيرة في مرحلتها الأولى. وفي المصانع يجب على كل موظف أن يعرف كيف يستخدم المطفأة بسرعة وبطريقة صحيحة. إن معرفة أنواع المطافئ وفئات الحريق ستحمي حياتك وحياة زملائك. المطفأة اليدوية لا تعمل إلا بضع ثوانٍ، لذا يجب توجيهها بشكل صحيح. وإذا كبرت النار أو كثر الدخان، فاترك المطفأة واخرج واتصل بالرقم 115."},{heading:"1. فئات الحريق وفق NFPA (Fire Classes)",body:"وفقًا للنظام الأمريكي (NFPA) تُقسم الحرائق إلى 5 فئات، وتحتاج كل فئة إلى مطفأة مناسبة. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.",points:["الفئة A (المواد الصلبة): الخشب، الورق، القماش، البلاستيك. المطفأة: الماء، الرغوة، مسحوق ABC.","الفئة B (السوائل والغازات القابلة للاشتعال): البنزين، النفط الأبيض (الكيروسين)، الزيوت، الكحول، الغاز. السوائل: CO₂ أو مسحوق ABC أو الرغوة؛ وللكحول والمذيبات القطبية الأخرى: CO₂ أو المسحوق الجاف أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها. الغاز: أوقف الغاز أولًا إذا كان ذلك آمنًا، ولا تُطفئ أبدًا لهب غاز لا تستطيع إيقافه. (لا تستخدم الماء أبدًا!)","الفئة C (المعدات الكهربائية الموصولة بالتيار): المفاتيح الكهربائية، المحوّلات، اللوحات الكهربائية، المولّدات. المطفأة: CO₂، مسحوق ABC، العامل النظيف (Clean Agent). (لا تستخدم الماء أو الرغوة إلا إذا أظهر الملصق تصنيف الفئة C أو علامة الاختبار الكهربائي، كما في بعض مطافئ رذاذ الماء (water mist)!)","الفئة D (المعادن): المعادن القابلة للاشتعال — المغنيسيوم، التيتانيوم، الصوديوم، ومسحوق الألمنيوم. المطفأة: فقط مطفأة من الفئة D أو مادة يذكر ملصقها هذا المعدن؛ فالمادة تختلف من معدن لآخر. (قد يسبب الماء انفجارًا!)","الفئة K (المطابخ): زيوت الطهي والدهون. المطفأة: المادة الكيميائية الرطبة (Wet Chemical). (الماء ينثر الزيت الساخن!) — وهي الفئة F في EN 2."]},{heading:"2. أنواع المطافئ في المصانع",body:"اللون ليس فئة الحريق. وفق BS EN 3 يكون جسم المطفأة أحمر، وفي بريطانيا يدلّ شريط ملوّن (BS 7863) على المادة. وتستخدم دول أخرى ألوانًا مختلفة، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق ورموز الفئات دائمًا. والفئات أدناه بأحرف NFPA:",points:["مطفأة الماء (Water): أحمر بالكامل، بلا شريط — للفئة A فقط (الخشب، الورق). لا تستخدمها أبدًا للكهرباء أو الزيت!","مطفأة CO₂: شريط أسود في بريطانيا — للفئة B وللمعدات الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ أما في EN 2 فالفئة C هي الغاز، ولا تُصنَّف مطفأة CO₂ لحرائق الغاز). يخرج منها غاز شديد البرودة ويصبح البوق (Horn) شديد البرودة؛ أمسك المقبض فقط ولا تمسك البوق أبدًا، فقد تُصاب يدك بحروق البرد! مدى CO₂ قصير ولا تصلح لحرائق الخشب والورق العميقة: ابدأ من المسافة المحددة على ملصقها ولا تقترب إلا كلما صغرت النار. وفي الغرف الصغيرة اخرج بعد الاستخدام وهوِّ المكان، لأن CO₂ يقلّل الأكسجين.","مطفأة مسحوق ABC (Dry Powder): شريط أزرق في بريطانيا — للفئات A وB وC (وليس D وK). وهي النوع الأكثر انتشارًا. يخرج منها مسحوق أبيض؛ ومن عيوبها أنها تحجب الرؤية وتلوّث المعدات.","مطفأة الرغوة (Foam/AFFF): شريط كريمي في بريطانيا — للفئتين A وB. تنتشر الرغوة على سطح السائل وتعزله عن الأكسجين. لا تستخدمها للكهرباء!","مطفأة العامل النظيف (Clean Agent): يختلف تصنيفها حسب الطراز، فاقرأ الملصق (غالبًا B وC بأحرف NFPA، وبعض الطرازات للفئة A أيضًا) — للمعدات الحساسة وغرف الخوادم. لا تترك بقايا ولا تُلحق ضررًا بالأجهزة الإلكترونية.","المطفأة الخاصة (Class D): للمعادن القابلة للاشتعال في المصانع — ويجب أن يذكر ملصقها المعدن المستخدم في المكان. لا ترشّ الماء أبدًا على معدن مشتعل!"]},{heading:"3. إجراء PASS — بالتفصيل",body:"قبل استخدام المطفأة، يجب أن تكون كل الإجابات «نعم»: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك. وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب. وPASS هي الطريقة العامة لمعظم المطافئ اليدوية؛ أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعامل النظيف (Clean Agent) والمطافئ ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة:",points:["P = Pull (اسحب): اسحب مسمار الأمان (Safety Pin). يمنع هذا المسمار تشغيل المطفأة عن طريق الخطأ.","A = Aim (صوّب): وجّه فوهة المطفأة نحو قاعدة النار — لا نحو رأس اللهب! فوقود النار في القاعدة.","S = Squeeze (اضغط): اضغط على مقبضي المطفأة بقوة لتخرج مادة الإطفاء.","S = Sweep (حرّك): حرّك الفوهة يمينًا ويسارًا فوق قاعدة النار حتى تنطفئ تمامًا؛ ثم راقب المكان كي لا تشتعل النار من جديد."]},{heading:"4. الفحص الشهري للمطافئ",body:"الفحص البصري مرة كل شهر، يجريه الشخص المسؤول (NFPA 10):",points:["ضغط المطفأة (Pressure Gauge)، إن وُجد مؤشر: يجب أن يكون المؤشر ضمن المنطقة الخضراء. مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة.","مسمار الأمان وختمه: يجب أن يكونا في مكانهما وغير مكسورين.","الفوهة (Nozzle): يجب ألّا تكون مكسورة أو مسدودة.","جسم المطفأة: يجب ألّا يكون صدئًا أو مشقوقًا أو متضررًا.","بطاقة الفحص والملصق: يجب أن يُدوَّن على البطاقة تاريخ آخر فحص؛ وأن يكون الملصق مقروءًا ومتّجهًا إلى الخارج؛ وأن تكون المطفأة في مكانها، ظاهرة وسهلة الوصول.","ملاحظة: افصل بين هذه الأمور. الفحص والصيانة السنوية على يد فنّي مؤهَّل؛ وإعادة التعبئة (Recharge) بعد أي استخدام، ولو كان قصيرًا؛ وصيانة السنوات الست: تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن (stored-pressure) التي تحتاج إلى اختبار هيدروستاتيكي كل 12 سنة ويُفحص داخلها كل 6 سنوات؛ والاختبار الهيدروستاتيكي (Hydrostatic Test، اختبار ضغط جسم المطفأة) كل 5 سنوات لمطافئ الماء والرغوة (AFFF) وCO₂ والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ، وكل 12 سنة لمطافئ المسحوق الجاف ذات الضغط المخزَّن التي جسمها من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم. وموعد الاختبار ليس موعدًا للاستبدال. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك."]},{heading:"5. مخاطر خاصة في المصانع",body:"المصنع مكان حساس للأسباب الآتية:",points:["المواد الكيميائية: المذيبات، الكحول، الثنر — كلها من الفئة B.","الكهرباء ذات الجهد العالي: اللوحات الكهربائية والمحوّلات — الفئة C (NFPA).","غبار الخشب والطحين: قد يسبب انفجار الغبار (Dust Explosion) في بعض المصانع.","اللحام والقطع: يمكن أن يسبب شرر اللحام حرائق من الفئتين A وB.","مخزن الوقود: يجب أن يكون في غرفة خاصة أو خارج المبنى، وأن تكون المطفأة المناسبة (رغوة أو مسحوق) قريبة منه.","أماكن التثبيت: ضع المطافئ قرب الأبواب والممرات؛ ويجب ألّا تزيد مسافة الوصول إلى مطفأة الفئة A على 23 مترًا (75 قدمًا)، وللسوائل 9-15 مترًا (NFPA 10)."],critical:!0}],media:[{kind:"video",src:"media/videos/fire_ext_factory.mp4",title:"مطفأة الحريق في المصانع",description:"إجراء PASS وأنواع المطافئ بالفيديو"}],quiz:[{question:"بأحرف NFPA، لأيّ فئات الحريق تصلح مطفأة CO₂؟",options:[{text:"A وD",correct:!1},{text:"B وC",correct:!0},{text:"A وK",correct:!1},{text:"D وK",correct:!1}],explanation:"تصلح مطفأة CO₂ للسوائل القابلة للاشتعال (B) والمعدات الكهربائية (C)، لأنها لا تترك بقايا ولا توصل الكهرباء. وفي EN 2 تعني C حرائق الغاز، ولا تُصنَّف مطفأة CO₂ لها."},{question:"في إجراء PASS، إلى أين يجب توجيه فوهة المطفأة؟",options:[{text:"رأس اللهب",correct:!1},{text:"قاعدة النار",correct:!0},{text:"بعيدًا عن النار",correct:!1},{text:"الدخان قرب سقف الغرفة",correct:!1}],explanation:"وجّه الفوهة دائمًا نحو قاعدة النار، لأن وقود النار موجود هناك."},{question:"لماذا لا يُسكب الماء على حريق الزيت (الفئة K)؟",options:[{text:"لا يُحدث أيّ تأثير",correct:!1},{text:"الماء ينثر الزيت المشتعل ويُحدث لهبًا كبيرًا",correct:!0},{text:"الزيت يمتص الماء فيحترق ببطء أكثر فقط",correct:!1},{text:"الماء نفسه يحترق",correct:!1}],explanation:"يغلي الماء فورًا عند ملامسته الزيت الساخن ويقذف الزيت المشتعل في الهواء، فتتكوّن كرة لهب كبيرة (Fireball). استخدم مطفأة المادة الكيميائية الرطبة (Wet Chemical) أو غطاءً، واقطع مصدر الحرارة."},{question:"قبل أن تستخدم المطفأة، أي حالة تعني «لا»؟",options:[{text:"النار بينك وبين مخرجك الوحيد",correct:!0},{text:"الملصق يبيّن فئة المادة المشتعلة",correct:!1},{text:"زميل أطلق الإنذار واتصل بالرقم 115",correct:!1},{text:"تدرّبت على PASS في آخر تمرين",correct:!1}],explanation:"إذا كانت النار بينك وبين مخرجك الوحيد، فقد تحاصرك إذا كبرت. يجب أن تكون كل الإجابات «نعم»: حريق صغير، ومطفأة مناسبة، والمخرج خلفك، والإنذار أُطلق وتمّ الاتصال بالرقم 115، وأنت مدرَّب، ولا دخان أو حرارة يمنعان الخروج."},{question:"كم يجب أن تبعد عن النار عندما تبدأ التفريغ؟",options:[{text:"على المسافة المذكورة في الملصق، وتقترب كلما صغرت النار",correct:!0},{text:"دائمًا على مسافة ثابتة واحدة أيًّا كان نوع المطفأة",correct:!1},{text:"أقرب ما يمكن حتى لا تُهدر أي كمية من المادة",correct:!1},{text:"بعيدًا جدًا بحيث لا تشعر بأي حرارة إطلاقًا",correct:!1}],explanation:"لا توجد مسافة واحدة لكل المطافئ: فالمدى يختلف باختلاف الطراز والمادة، ولذلك يحدد الملصق وتعليمات الشركة المصنّعة المسافة. ولا تقترب إلا كلما صغرت النار، وأبقِ المخرج خلفك."},{question:"يبدأ حريق صغير في مقلاة عميقة (Deep Fryer) في مطعم العاملين. أي إجراء صحيح؟",options:[{text:"أوقف الحرارة إن أمكن بأمان واستخدم مطفأة المادة الكيميائية الرطبة",correct:!0},{text:"استخدم مطفأة الماء وصوّب نحو قاعدة اللهب داخل المقلاة مباشرة",correct:!1},{text:"استخدم مطفأة CO₂ لأنها لا توصل الكهرباء ولا تترك أي بقايا",correct:!1},{text:"احمل المقلاة إلى الخارج ليحترق الزيت في الهواء الطلق حتى ينتهي",correct:!1}],explanation:"حريق زيت الطهي من الفئة K (وفي EN هي الفئة F): استخدم المادة الكيميائية الرطبة وفق ملصقها، وأوقف الحرارة إن كان ذلك آمنًا. الماء يقذف الزيت المشتعل في الهواء، وCO₂ غير مصنَّف لحرائق زيت الطهي، ونقل مقلاة مشتعلة يسكب الزيت. وإذا لم تنطفئ النار فورًا، فاخرج واتصل بالرقم 115."}],steps:[{title:"أطلق الإنذار أولًا",detail:"اصرخ لتحذير الآخرين، واضغط جهاز إنذار الحريق، وتأكد من أن أحدًا يتصل بالرقم 115.",critical:!0},{title:"أجرِ فحص «نعم / لا»",detail:"لا تستخدم المطفأة إلا إذا كانت كل الإجابات «نعم»: الحريق صغير وفي بدايته، والمطفأة مناسبة له، وطريق الخروج خلفك، وأُطلق الإنذار وتمّ الاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك. وإذا كانت أي إجابة «لا»، فاخرج.",critical:!0},{title:"اقرأ الملصق واتخذ موقعك",detail:"تحقق من رموز الفئات وتعليمات التشغيل على الملصق؛ وابدأ من المسافة التي يحددها الملصق، وطريق الخروج خلفك.",critical:!0},{title:"استخدم PASS",detail:"اسحب المسمار، وصوّب نحو قاعدة النار، واضغط المقبض، وحرّك الفوهة فوق القاعدة. أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعامل النظيف (Clean Agent) والمطافئ ذات العجلات فوفق الملصق وتعليمات الشركة المصنّعة.",critical:!0},{title:"إذا لم تنطفئ النار فورًا، فاخرج",detail:"توقف، واخرج، وأغلق الباب خلفك، واذهب إلى نقطة التجمع لإبلاغ فريق 115.",critical:!0},{title:"بعد الاستخدام",detail:"واصل مراقبة المكان كي لا تشتعل النار من جديد، وأبلغ عن الاستخدام، وأخرج المطفأة من الخدمة لإعادة تعبئتها حتى بعد تفريغ قصير."}],warnings:["لا تستخدم أبدًا الماء أو CO₂ على زيت الطهي المشتعل، ولا تطفئ أبدًا لهب الغاز ما لم يمكن إيقاف الغاز بأمان: فالماء يقذف الزيت المشتعل، والغاز غير المحترق قد يتجمع وينفجر.","لا تكافح أبدًا حريقًا يقع بينك وبين طريق خروجك: إذا كبر، فستُحاصَر.","لا تمسك أبدًا بوق مطفأة CO₂: فهو يبرد بشدة ويسبب حروق البرد."],tips:["اعرف أماكن المطافئ في قسمك والفئات التي تبيّنها ملصقاتها.","في التمارين، قل فحص «نعم / لا» بصوت مسموع قبل التدرّب على PASS.","أبلغ فورًا عن أي مطفأة مستخدمة أو تالفة أو مفقودة لتُعاد تعبئتها أو تُستبدل.","أبقِ المطافئ ظاهرة وغير محجوبة؛ ولا تكدّس الصناديق أو المنصات أمامها أبدًا."],activity:{prompt:"يبدأ حريق صغير في سلة مهملات فيها ورق وكرتون بجانب طاولة لحام. أنت مدرَّب، وأُطلق الإنذار، وزميل يتصل بالرقم 115. بقربك مطفأة CO₂ ومطفأة مسحوق ABC، وطريق الخروج خلفك. ماذا تفعل؟",options:[{text:"أستخدم مطفأة مسحوق ABC بطريقة PASS، مصوّبًا نحو القاعدة، وأخرج إذا لم تنطفئ النار فورًا.",correct:!0,feedback:"صحيح: كل إجابات فحص «نعم / لا» نعم، ومسحوق ABC مصنَّف للفئة A؛ أما CO₂ فليس لحرائق الورق العميقة."},{text:"أستخدم مطفأة CO₂ لأنها لا تترك بقايا.",correct:!1,feedback:"خطأ: CO₂ ليس لحرائق الخشب والورق العميقة، وقد تعود النار؛ مسحوق ABC مصنَّف للفئة A."},{text:"أسكب دلو ماء على السلة وطاولة اللحام.",correct:!1,feedback:"خطأ: قد تكون معدات اللحام موصولة بالكهرباء، والكهرباء والماء لا يجتمعان؛ استخدم المطفأة المصنَّفة لهذا الحريق."},{text:"أصوّب المطفأة نحو رأس اللهب والدخان.",correct:!1,feedback:"خطأ: صوّب نحو القاعدة حيث الوقود؛ فالتصويب نحو اللهب يهدر التفريغ القصير."}]},caseStudy:[{prompt:"في مخزن الطلاء، يبدأ حريق صغير في صينية فيها مخفّف الطلاء (التنر). الباب الذي دخلت منه في الجهة الأخرى من النار، وهناك مخرج ثانٍ خلفك. بجانبك مطفأة رغوة مصنّفة للفئة B، وأنت مدرَّب. ولم يُطلق الإنذار بعد. ماذا تفعل أولًا؟",options:[{text:"أطلق الإنذار وأتأكد من الاتصال بالرقم 115، ثم أقرر بشأن مطفأة الرغوة بفحص «نعم / لا».",correct:!0,feedback:"صحيح: الإنذار أولًا؛ ولا تُستخدم المطفأة إلا إذا كانت كل إجابات فحص «نعم / لا» نعم."},{text:"أكافح النار فورًا ولا أطلق الإنذار إلا إذا كبرت.",correct:!1,feedback:"خطأ: الإنذار يسبق الإطفاء؛ فإذا فشلت المحاولة، يخسر الآخرون الوقت الذي يحتاجون إليه للخروج."},{text:"أسكب الماء على التنر لتبريده.",correct:!1,feedback:"خطأ: الماء ليس لحرائق السوائل القابلة للاشتعال؛ وقد ينشر السائل المشتعل."}]},{prompt:"يدوّي الإنذار وتمّ الاتصال بالرقم 115. تفرّغ الرغوة على قاعدة النار، لكن اللهب ينتشر على الأرض نحو براميل المذيبات والدخان يتزايد. ماذا تفعل الآن؟",options:[{text:"أتوقف، وأخرج من المخرج الذي خلفي، وأغلق الباب، وأبلغ عند نقطة التجمع بمكان البراميل.",correct:!0,feedback:"صحيح: لم تنطفئ النار فورًا ولم تعد صغيرة؛ وإغلاق الباب يبطئ انتشارها، وفريق 115 يحتاج إلى معرفة مكان البراميل."},{text:"أحضر مطفأة ثانية وأواصل مكافحة النار.",correct:!1,feedback:"خطأ: النار تكبر والدخان يتزايد؛ وإجابة فحص «نعم / لا» الآن هي لا."},{text:"أدحرج براميل المذيبات بعيدًا عن النار قبل أن أخرج.",correct:!1,feedback:"خطأ: البقاء قرب حريق يكبر يعرّض حياتك للخطر؛ اخرج وأخبر فريق 115 بمكان البراميل."}]}],realCase:"في ورشة نجارة، اشتعلت نشارة الخشب تحت إحدى الآلات في نهاية اليوم. فأمسك عامل أقرب مطفأة، وكانت مطفأة CO₂، من دون أن يقرأ ملصقها. خمد اللهب، ثم عاد من النشارة المشتعلة ببطء بمجرد أن تبدّد الغاز. وكان عامل آخر قد أطلق الإنذار واتصل بالرقم 115؛ فأحضر مطفأة مسحوق ABC، وتأكد من أن طريق الخروج خلفهما، وأطفأ النار. ثم خرجا معًا وانتظرا فريق 115 في الخارج. وبعد الحادثة، كتبت الورشة عند موضع كل مطفأة الفئات التي تغطيها، وتدرّبت على فحص «نعم / لا» في التمارين."},{id:5,code:"AID-105",icon:"HeartPulse",accent:"#db2777",title:"الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)",subtitle:"First Aid & CPR — Complete Training",summary:"تدريب شامل على الإسعافات الأولية والإنعاش القلبي الرئوي (CPR) والتصرّف في حالات الطوارئ في المصانع",blocks:[{body:"الإسعافات الأولية (First Aid) هي المساعدة الأولية التي تُقدَّم للشخص المصاب أو المريض قبل وصول الفرق الطبية. وخطر الإصابة في المصانع مرتفع جدًا — بدءًا من الجروح والحروق وصولًا إلى الصدمات الكهربائية والسقوط من أماكن مرتفعة. لذا يجب على كل موظف أن يعرف كيف يتصل بالإسعاف (122)، وكيف يُجري الإنعاش القلبي الرئوي (CPR)، ويوقف النزيف، ويحمي المصاب حتى وصول سيارة الإسعاف. وقد أُعدّ هذا الدرس وفق إرشادات AHA 2025 وبرنامج Stop the Bleed."},{heading:"1. الضغطات الصدرية والتنفس (CPR) — بالتفصيل",body:"الإنعاش القلبي الرئوي (CPR) إجراء لإنقاذ الحياة عندما يتوقف قلب الإنسان ويتوقف تنفّسه الطبيعي. اتبع الخطوات الآتية:",points:["1. سلامة المكان: قبل أي شيء تأكّد من أن المكان آمن (لا كهرباء ولا نار ولا غاز)، كي لا تصبح أنت الضحية الثانية.","2. الاستجابة: اهزز كتفي المصاب بقوة واسأله بصوت عالٍ: «هل أنت بخير؟ هل تسمعني؟».","3. طلب المساعدة: إذا لم يستجب وكان لا يتنفس، أو يتنفس تنفسًا غير طبيعي فقط (شهقات)، فاتصل فورًا بالرقم 122 (أو كلّف شخصًا آخر بالاتصال) واطلب إحضار جهاز إزالة الرجفان الخارجي الآلي (AED).","4. الضغطات الصدرية (Compressions): ضع كعب إحدى يديك في منتصف الصدر (النصف السفلي من عظم القص) وضع اليد الأخرى فوقها. اضغط 30 ضغطة قوية وسريعة: بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة، واترك الصدر يرتدّ كاملًا.","5. التنفس: أمِل الرأس إلى الخلف وارفع الذقن، وأغلق الأنف وأعطِ نفَسين (مدة كل منهما نحو ثانية واحدة، حتى يرتفع الصدر). وإذا لم تستطع أو لم ترغب في إعطاء الأنفاس، فاستمر في الضغطات الصدرية فقط.","6. الاستمرار (30:2): استمر في 30 ضغطة ونفَسين حتى تصل سيارة الإسعاف، أو يصبح جهاز AED جاهزًا، أو يبدأ المصاب بالتنفس الطبيعي.","7. استخدام جهاز AED: فور وصوله شغّله، وألصق الأقطاب اللاصقة (Pads) على الصدر العاري، واتبع الأوامر الصوتية للجهاز؛ ولا تلمس المصاب في أثناء إعطاء الصدمة."]},{heading:"2. السيطرة على النزيف (Stop the Bleed)",body:"النزيف الشديد قد يقتل الإنسان في وقت قصير، لذا اتصل بالرقم 122 ونفّذ الخطوات الآتية بسرعة:",points:["الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بقوة بكلتا يديك. وإذا تشبّع القماش بالدم فلا تُزِله؛ بل ضع قطعة أخرى فوقه واستمر في الضغط.","حشو الجرح (Wound Packing): إذا كان الجرح عميقًا (كما في الفخذ أو الإبط أو الرقبة)، فاحشُ الجرح من الداخل بقماش نظيف أو بشاش مرقئ (موقف للنزيف) واضغط بقوة. لا ترفع الطرف المصاب ولا تبحث عن نقاط الضغط (Pressure Points).","العاصبة (Tourniquet): إذا كان نزيف الذراع أو الساق مهددًا للحياة، فاربط العاصبة مبكرًا وبإحكام على بعد 5-7 سم فوق الجرح (باتجاه الجسم)، وسجّل الوقت، ولا تُرخِها أبدًا.","الجسم المنغرس: إذا انغرس جسم حديدي أو زجاجي في الجرح، فلا تُخرجه أبدًا! فذلك سيزيد النزيف. اضغط حوله وثبّته."]},{heading:"3. علاج الحروق",body:"الحروق في المصانع خطيرة؛ تعامل معها على النحو الآتي، واتصل بالرقم 122 في حالة الحروق الكبيرة أو حروق الوجه واليدين:",points:["الحروق الحرارية: صبّ فورًا ماءً جاريًا باردًا (وليس ماءً مثلّجًا) على الحرق لمدة 20 دقيقة. وانزع الخواتم والساعة بسرعة قبل أن يتورّم الطرف المصاب.","الحروق الكيميائية: انزع الملابس الملوّثة واغسل الجلد بكمية كبيرة من الماء الجاري لمدة 20 دقيقة أو أكثر، وراجع صحيفة بيانات السلامة (SDS) الخاصة بالمادة.","الحروق الكهربائية: أول ما تفعله هو قطع الكهرباء! ثم برّد الحرق كما تبرّد الحرق الحراري واتصل بالرقم 122، لأن الكهرباء قد تُلحق الضرر بالقلب وبالأعضاء الداخلية.","تنبيه: لا تفقأ فقاعات الحروق، ولا تستخدم الثلج أو الزبدة والدهون أو معجون الأسنان أو المراهم دون إرشاد طبي."]},{heading:"4. الكسور وإصابات العمود الفقري",body:"عند السقوط من أماكن مرتفعة أو الاشتباه بوجود كسر:",points:["التجبير (Splinting): إذا اشتبهت بوجود كسر، فلا تحرّك الطرف المصاب. ثبّته على الوضع الذي هو عليه بقطعة خشب أو كرتون لتخفيف الألم.","حماية الظهر والرقبة: إذا سقط شخص من مكان مرتفع، فلا تحرّكه إلا إذا كان المكان خطرًا (كوجود حريق)، لأن التحريك قد يسبب الشلل. ثبّت الرأس واتصل بالرقم 122.","التبريد: لتخفيف التورّم (Swelling)، لُفّ الثلج بقطعة قماش وضعه على موضع الألم لمدة 20 دقيقة؛ ولا تضع الثلج مباشرة على الجلد."]},{heading:"5. الصعق الكهربائي والإنقاذ",body:"يمكن للكهرباء أن توقف القلب؛ نفّذ الإجراءات الآتية:",points:["اقطع الكهرباء فورًا: لا تلمس المصاب حتى تُقطع الكهرباء، لأن الكهرباء ستصعقك أنت أيضًا.","الإبعاد الآمن: إذا لم تتمكن من قطع الكهرباء وكان الجهد منخفضًا، فأبعد السلك عن المصاب بعصا خشبية جافة أو بأداة بلاستيكية، وقف على سطح جاف. ولا تقترب من خطوط الجهد العالي، واتصل بالرقم 115.","الفحص الطبي: يجب على كل من تعرّض للصعق الكهربائي، حتى لو شعر بأنه بخير، أن يذهب إلى المستشفى لفحص القلب؛ اتصل بالرقم 122."],critical:!0}],media:[{kind:"video",src:"media/videos/cpr_factory.mp4",title:"الإنعاش القلبي الرئوي (CPR) والإسعافات الأولية",description:"التدريب على CPR ومساعدة المصابين في المصانع"}],quiz:[{question:"في الإنعاش القلبي الرئوي (CPR)، كم يجب أن يكون معدل الضغطات الصدرية في الدقيقة؟",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"140-160",correct:!1}],explanation:"وفقًا لإرشادات AHA 2025، يبلغ معدل الضغطات 100-120 ضغطة في الدقيقة، بعمق 5-6 سم للبالغين، كي يصل الدم إلى الدماغ."},{question:"إذا انغرس جسم حادّ في الجرح، فماذا تفعل؟",options:[{text:"أُخرجه",correct:!1},{text:"أتركه في مكانه وأتصل بالرقم 122",correct:!0},{text:"أُبعد يدي عنه ولا أفعل شيئًا",correct:!1},{text:"أغسله بالماء",correct:!1}],explanation:"إخراج الجسم سيزيد النزيف. يجب أن يبقى في مكانه وأن يُثبَّت حتى يُخرجه الطبيب في المستشفى."},{question:"إذا تعرّض شخص للصعق الكهربائي، فما أول ما تفعله؟",options:[{text:"أمسك يده",correct:!1},{text:"أُجري له CPR",correct:!1},{text:"أقطع الكهرباء",correct:!0},{text:"أصبّ عليه الماء",correct:!1}],explanation:"يجب أولًا قطع مصدر الكهرباء كي لا تصعقك الكهرباء أنت أيضًا؛ ثم اتصل بالرقم 122 وابدأ CPR إذا لزم الأمر."},{question:"تعرّض عامل لصعق كهربائي من آلة. قُطعت الكهرباء. لا يستجيب ولا يتنفس طبيعيًا. ماذا تفعل؟",options:[{text:"أتصل بالرقم 122 وأبدأ الإنعاش وأطلب جهاز AED",correct:!0},{text:"أنتظر حتى يستفيق وحده قبل الاتصال بأي أحد",correct:!1},{text:"أسكب ماءً باردًا على وجهه ليستفيق بسرعة",correct:!1},{text:"أضعه في وضعية الإفاقة وأنتظر وصول الإسعاف",correct:!1}],explanation:"بعد قطع الكهرباء أصبح المكان آمنًا. الشخص الذي لا يستجيب ولا يتنفس طبيعيًا في حالة توقف قلب: اتصل بالرقم 122، وابدأ الإنعاش، واستخدم جهاز AED فور وصوله."},{question:"زميل غير مدرَّب يرغب في المساعدة لكنه لا يريد إعطاء أنفاس الإنقاذ. ماذا يجب أن يفعل؟",options:[{text:"الإنعاش بالضغط فقط: ضغطات متواصلة حتى وصول المساعدة",correct:!0},{text:"لا يفعل شيئًا، لأن الإنعاش من دون أنفاس لا يفيد إطلاقًا",correct:!1},{text:"يعطي أنفاس الإنقاذ فقط، لأن تعلّمها أسهل",correct:!1},{text:"يضغط على الصدر برفق حتى لا يسبب ضررًا",correct:!1}],explanation:"المسعفون غير المدرَّبين أو غير الراغبين يعطون الإنعاش بالضغط فقط: ضغطات قوية وسريعة من دون أنفاس (AHA 2025). والضغطات الخفيفة لا تدفع ما يكفي من الدم."},{question:"سقط عامل من سقالة. هو واعٍ، ويقول إن رقبته تؤلمه، والمكان آمن. ما الصحيح؟",options:[{text:"أبقِه ساكنًا، وثبّت رأسه، واتصل بالرقم 122",correct:!0},{text:"ساعده على الوقوف لترى هل يستطيع المشي",correct:!1},{text:"ضعه في وضعية الإفاقة لحماية مجرى التنفس",correct:!1},{text:"احمله إلى المكتب ليستلقي على أريكة",correct:!1}],explanation:"بعد سقوط مع ألم في الرقبة يُشتبه في إصابة العمود الفقري: لا تحرّكه إلا إذا كان المكان غير آمن، وثبّت الرأس، واتصل بالرقم 122. ولا تُستخدم وضعية الإفاقة مع الاشتباه في إصابة الرقبة أو الظهر."}],steps:[{title:"اجعل المكان آمنًا",detail:"تحقق من وجود كهرباء حية أو نار أو غاز أو آلات متحركة أو مواد كيميائية؛ ولا توقف الآلة أو تقطع الكهرباء إلا إذا كان ذلك آمنًا. لا تصبح مصابًا ثانيًا.",critical:!0},{title:"افحص واتصل",detail:"اربت على الكتفين ونادِ بصوت عالٍ. إذا لم يستجب ولم يكن يتنفس طبيعيًا، فاتصل بالرقم 122 (وبالرقم 115 إذا وُجدت نار أو كهرباء أو انحشار أو مواد كيميائية)، وأرسل أحدًا لإحضار جهاز AED وحقيبة الإسعافات الأولية.",critical:!0},{title:"ابدأ الإنعاش القلبي الرئوي",detail:"اضغط بقوة وسرعة في وسط الصدر: 100–120 ضغطة في الدقيقة بعمق 5–6 سم. إذا كنت مدرَّبًا وراغبًا فأعطِ 30 ضغطة ونفسين؛ وإلا فأعطِ الإنعاش بالضغط فقط (Hands-Only CPR).",critical:!0},{title:"استخدم جهاز AED",detail:"شغّله فور وصوله واتبع تعليماته الصوتية؛ ولا يلمس أحد المصاب أثناء الصدمة.",critical:!0},{title:"أوقف النزيف الشديد",detail:"اضغط بقوة على الجرح، واحشُ الجروح العميقة، وضع العاصبة مبكرًا للنزيف المهدد للحياة من الذراع أو الساق؛ وسجّل الوقت.",critical:!0},{title:"احمِ المصاب وسلّمه",detail:"لا تحرّك الشخص بعد السقوط إلا إذا كان المكان غير آمن؛ أبقه دافئًا، ولا تعطه شيئًا عن طريق الفم، وأخبر فريق الإسعاف بما حدث وبما فعلت."}],warnings:["لا تلمس أبدًا مصابًا قد يكون ما زال متصلًا بالكهرباء: اقطع الكهرباء أولًا، وإلا سيمرّ التيار عبرك أيضًا.","لا تحرّك أبدًا المصاب بعد السقوط من ارتفاع إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش: فالتحريك قد يسبب الشلل.","لا تعطِ أبدًا طعامًا أو شرابًا أو دواءً لشخص فاقد الوعي أو مصاب إصابة بالغة: ففاقد الوعي قد يختنق، والعلاج يقرره الفريق الطبي."],tips:["اعرف المسعفين المدرَّبين في ورديتك ومكان حقيبة الإسعافات الأولية وجهاز AED.","اكتب عنوان المصنع وعلامة قريبة بجانب الهاتف ليكون الاتصال بالرقم 122 سريعًا.","تدرّب على الإنعاش القلبي الرئوي على دمية التدريب (Manikin) بانتظام؛ فالمهارة تضعف من دون تدريب.","أعِد تجهيز حقيبة الإسعافات الأولية بعد كل استخدام."],activity:{prompt:"يسقط عامل على أرضية الإنتاج. لا يستجيب ويتنفس شهيقًا متقطعًا فقط (Gasping). ذهب زميل للاتصال بالرقم 122، ويوجد جهاز AED في الممر. أنت مدرَّب على الإنعاش القلبي الرئوي. ماذا تفعل؟",options:[{text:"أبدأ ضغطات الصدر فورًا وأطلب من شخص آخر إحضار جهاز AED.",correct:!0,feedback:"صحيح: الشهيق المتقطع ليس تنفسًا طبيعيًا؛ ابدأ الإنعاش فورًا واستخدم الجهاز فور وصوله."},{text:"أنتظر الإسعاف لأنه ما زال يتنفس.",correct:!1,feedback:"خطأ: الشهيق المتقطع علامة على توقف القلب، لا تنفس طبيعي؛ وكل دقيقة من دون إنعاش تقلّل فرصة نجاته."},{text:"أضعه في وضعية الإفاقة (Recovery Position) وأراقبه.",correct:!1,feedback:"خطأ: وضعية الإفاقة لمن يتنفس طبيعيًا؛ والشهيق المتقطع يحتاج إلى الإنعاش."},{text:"أتركه وأذهب لإحضار الجهاز بنفسي قبل أي شيء آخر.",correct:!1,feedback:"خطأ: أنت لست وحدك؛ أرسل شخصًا آخر لإحضار الجهاز وابدأ الضغطات فورًا."}]},caseStudy:[{prompt:"في قسم القطع، ينكسر لوح زجاج ويجرح فخذ عامل جرحًا عميقًا. الدم يندفع ويتجمع بسرعة على الأرض. معك حقيبة الإسعافات الأولية وفيها عاصبة. ماذا تفعل أولًا؟",options:[{text:"أطلب من أحدهم الاتصال بالرقم 122 وأضع العاصبة فوق الجرح فورًا، لأن النزيف مهدد للحياة.",correct:!0,feedback:"صحيح: الدم المندفع الذي يتجمع بسرعة نزيف طرفي مهدد للحياة؛ ضع العاصبة مبكرًا على بعد 5–7 سم فوق الجرح وسجّل الوقت."},{text:"أرفع الساق وأضغط على نقطة ضغط في أعلى الفخذ.",correct:!1,feedback:"خطأ: رفع الطرف ونقاط الضغط لم تعد تُدرَّس؛ استخدم الضغط المباشر وحشو الجرح والعاصبة."},{text:"أغسل الجرح بالماء أولًا لأراه بوضوح.",correct:!1,feedback:"خطأ: الغسل يضيّع الوقت بينما يفقد المصاب الدم؛ سيطر على النزيف أولًا."}]},{prompt:"وُضعت العاصبة وتوقف النزيف. العامل شاحب ويقول إن العاصبة تؤلمه كثيرًا. لم يصل الإسعاف بعد. ماذا تفعل؟",options:[{text:"أبقي العاصبة مشدودة، وأبقيه مستلقيًا ودافئًا، وأخبر فريق الإسعاف بوقت وضعها.",correct:!0,feedback:"صحيح: العاصبة تؤلم عندما تعمل؛ والمسعف لا يرخيها أبدًا، والوقت يساعد فريق المستشفى."},{text:"أرخي العاصبة قليلًا ليرتاح.",correct:!1,feedback:"خطأ: الإرخاء قد يعيد النزيف الشديد؛ ولا يزيل العاصبة إلا الطاقم الطبي."},{text:"أمشي به إلى المطعم ليرتاح ريثما ننتظر.",correct:!1,feedback:"خطأ: المشي قد يعيد النزيف ويزيد الصدمة سوءًا؛ أبقه مستلقيًا."}]}],realCase:"سقط عامل صيانة بجانب ضاغط هواء. رأى زميل أنه لا يتنفس طبيعيًا، فنادى طلبًا للمساعدة وبدأ ضغطات الصدر. واتصل عامل ثانٍ بالرقم 122 وأعطى عنوان المصنع والبوابة التي يجب الدخول منها، بينما أحضر عامل ثالث جهاز AED من الممر. نصح الجهاز بإعطاء صدمة، وواصل الفريق الإنعاش حتى تسلّم فريق الإسعاف. وفي المراجعة بعد ذلك، وجد المصنع أن البدء السريع جاء من تدريب الإنعاش الذي قُدِّم لكل وردية ومن اللافتات الواضحة التي تبيّن مكان الجهاز. وأضاف رقم البوابة إلى بطاقة الاتصال في الطوارئ."},{id:6,code:"CHEM-106",icon:"FlaskConical",accent:"#16a34a",title:"المواد الكيميائية (SDS)",subtitle:"Chemical Safety & Labelling",summary:"التعامل مع المواد الكيميائية والتعرّف على مخاطرها",blocks:[{body:"يمكن أن تسبب المواد الكيميائية في المصانع حروقًا جلدية أو تسممًا أو حرائق أو انفجارات."},{heading:"1. ما صحيفة بيانات السلامة (SDS)؟",body:"تقدّم صحيفة بيانات السلامة (Safety Data Sheet — SDS) معلومات كل مادة في 16 قسمًا، منها:",points:["تركيب المادة ومخاطرها.","معدات الوقاية الشخصية (PPE) المطلوبة (قناع التنفس، القفازات، النظارات).","الإسعافات الأولية في حال ملامسة المادة للجسم، وطرق إطفاء الحريق."]},{heading:"2. رموز GHS",body:"بعض العلامات الموجودة على العبوات والعلب:",points:["اللهب (Flame): مادة قابلة للاشتعال.","الجمجمة والعظمتان المتقاطعتان (Skull and Crossbones): مادة سامة قاتلة.","التآكل (Corrosion): مادة حمضية أو قلوية تُتلف الجلد والمعادن."]},{heading:"3. قراءة ملصق العبوة",body:"يجب أن يحمل كل وعاء لمادة كيميائية خطرة ملصقًا. قبل الاستخدام اقرأ:",points:["اسم المنتج والمورّد، لتجد صحيفة SDS الصحيحة.","كلمة التنبيه: «خطر» (Danger) للمخاطر الأشد، و«تحذير» (Warning) للأقل شدة.","الرموز وعبارات الخطر: ما الذي يمكن أن تفعله المادة بك.","العبارات التحذيرية: كيف تُخزَّن المادة وتُستخدم، وكيف تحمي نفسك، وما الإسعافات الأولية.","إذا لم يكن على الوعاء ملصق أو تعذّرت قراءته، فلا تستخدمه؛ وأبلغ عنه."]},{heading:"4. التخزين والاستخدام الآمن",body:"تبدأ كثير من حوادث المواد الكيميائية في المخزن أو أثناء نقلها من وعاء إلى آخر:",points:["خزّن المواد غير المتوافقة منفصلة وفق القسمين 7 و10 من صحيفة SDS، مثل إبعاد الأحماض عن القلويات والمواد المؤكسدة عن المواد القابلة للاشتعال.","احفظ السوائل القابلة للاشتعال في أوعية مغلقة وعليها ملصقات بعيدًا عن الحرارة والشرر.","لا تضع أبدًا مادة كيميائية في قنينة مشروبات أو في أي وعاء بلا ملصق.","لا تخلط أبدًا المواد الكيميائية إلا إذا نصّ الإجراء على ذلك: فبعض الخلائط تطلق غازًا سامًا.","استخدم التهوية ومعدات الوقاية المذكورة في صحيفة SDS، واغسل يديك قبل الأكل أو الشرب أو التدخين."]}],media:[{kind:"image",src:"media/images/ghs_pictograms.png",title:"صحيفة بيانات السلامة (SDS)",description:"علامات الخطر وفق GHS"}],quiz:[{question:"أين يمكننا أن نعرف نوع قناع التنفس المطلوب لمادة كيميائية؟",options:[{text:"من العلامات الموجودة على الجدار",correct:!1},{text:"في صحيفة SDS",correct:!0},{text:"أسأل زميلي",correct:!1},{text:"لا حاجة إلى قناع",correct:!1}],explanation:"تقدّم صحيفة SDS جميع معلومات الحماية الخاصة بتلك المادة، ومنها نوع معدات الوقاية الشخصية المطلوبة (القسم 8)."},{question:"ماذا يعني رمز الجمجمة والعظمتين المتقاطعتين (Skull and Crossbones) على العبوة؟",options:[{text:"مادة قابلة للاشتعال تشتعل بسهولة",correct:!1},{text:"مادة سامة قاتلة",correct:!0},{text:"مادة حمضية أو قلوية تُتلف الجلد والمعادن",correct:!1},{text:"مادة تضر بالبيئة فقط",correct:!1}],explanation:"الجمجمة والعظمتان المتقاطعتان علامة المادة السامة القاتلة؛ أما اللهب (Flame) فهو علامة المادة القابلة للاشتعال، والتآكل (Corrosion) علامة المادة الحمضية أو القلوية."},{question:"إلى جانب المخاطر ومعدات الوقاية الشخصية المطلوبة، ما الذي تقدّمه صحيفة SDS أيضًا؟",options:[{text:"سعر المادة واسم المورّد",correct:!1},{text:"مواعيد تنظيف مخزن المواد الكيميائية",correct:!1},{text:"أسماء العمال المسموح لهم باستخدامها",correct:!1},{text:"الإسعافات الأولية وطرق إطفاء الحريق",correct:!0}],explanation:"تقدّم صحيفة SDS معلومات كل مادة في 16 قسمًا، منها: المخاطر، ومعدات الوقاية الشخصية المطلوبة، والإسعافات الأولية في حال ملامسة المادة للجسم، وطرق إطفاء الحريق."},{question:"ستستخدم مادة كيميائية لأول مرة. ماذا تفعل قبل فتحها؟",options:[{text:"أقرأ الملصق وصحيفة SDS لمعرفة مخاطرها ووقايتها",correct:!0},{text:"أشمّ الوعاء المفتوح قليلًا لأقدّر مدى قوة المادة",correct:!1},{text:"أسأل سائق شاحنة التوصيل عن مدى خطورة المادة",correct:!1},{text:"أضع قليلًا منها على جلدي لأرى هل تحرق أم لا",correct:!1}],explanation:"يبيّن الملصق وصحيفة SDS المخاطر ومعدات الوقاية والإسعافات الأولية والتخزين لكل مادة. وشمّ المادة الكيميائية أو لمسها قد يسممك أو يحرقك."},{question:"أي من هذه الممارسات خاطئة؟",options:[{text:"حفظ مادة تنظيف كيميائية في قنينة مشروبات فارغة",correct:!0},{text:"إبعاد الأحماض عن القلويات كما تقول صحيفة SDS",correct:!1},{text:"وضع ملصق على الوعاء الجديد قبل تعبئته",correct:!1},{text:"إغلاق أوعية السوائل القابلة للاشتعال بعد الاستخدام",correct:!1}],explanation:"المادة الكيميائية في قنينة مشروبات قد تُشرب خطأً ولا تحمل ملصق خطر. تبقى المواد الكيميائية في أوعية عليها ملصقات وبعيدة عن المواد غير المتوافقة، وتُبقى السوائل القابلة للاشتعال مغلقة."},{question:"انسكاب كبير لمادة كيميائية مجهولة تتصاعد منه أبخرة في مستودع. ما الإجراء الصحيح؟",options:[{text:"غادر وأبعد الآخرين واتصل بالرقم 115",correct:!0},{text:"غطِّه بنشارة الخشب واكنسه بسرعة وأزله",correct:!1},{text:"اغسله نحو أقرب مصرف بكمية كبيرة من الماء",correct:!1},{text:"اعرف ما هي المادة بشمّ أبخرتها",correct:!1}],explanation:"الانسكاب الكبير أو المجهول أو الذي تتصاعد منه أبخرة يتجاوز حقيبة الانسكاب لدى العامل: غادر، وأبعد الآخرين، واتصل بالرقم 115 من مكان آمن. ونشارة الخشب قد تتفاعل مع بعض المواد، والمصرف ينشر الخطر."}],steps:[{title:"حذّر وابتعد",detail:"حذّر من حولك وأبعد الجميع عن المادة المنسكبة وأبخرتها؛ وإذا وُجدت أبخرة فابتعد إلى الهواء النقي.",critical:!0},{title:"ساعد من تلوّث",detail:"انزع الملابس الملوثة واغسل الجلد أو العينين بكمية وفيرة من الماء الجاري؛ واتبع الإسعافات الأولية في صحيفة SDS واتصل بالرقم 122.",critical:!0},{title:"راجع صحيفة SDS قبل التصرف",detail:"حدّد المادة واقرأ مخاطرها ومعدات الوقاية التي تحتاجها وتدابير الانسكاب (القسم 6 من صحيفة SDS)."},{title:"انسكاب صغير: احتوِه فقط إذا كنت مدرَّبًا",detail:"بمعدات الوقاية الصحيحة وحقيبة الانسكاب (Spill Kit)، أوقف المصدر واحتوِ الانسكاب؛ وأبعده عن المصارف."},{title:"انسكاب كبير أو مجهول أو تتصاعد منه أبخرة: أخلِ المكان",detail:"غادر المكان، وأغلق الأبواب إن كان ذلك آمنًا، واتصل بالرقم 115 من مكان آمن، وأعطِ الفريق اسم المادة وصحيفة SDS الخاصة بها.",critical:!0}],warnings:["لا تخلط أبدًا المواد الكيميائية ولا تسكب مادة في وعاء مادة أخرى: فبعض الخلائط تنتج غازًا سامًا أو حرارة قد تؤدي إلى حريق أو انفجار.","لا تشمّ أبدًا وعاءً لتعرف ما فيه: فالملصق وصحيفة SDS يحددان المادة، واستنشاق الأبخرة قد يسممك."],tips:["ضع ملف صحائف SDS حيث يصل إليه العمال بسرعة، وبلغة يفهمونها.","اعرف أقرب مغسلة عيون ودُش أمان وحقيبة انسكاب.","قبل نقل مادة كيميائية إلى وعاء جديد، اكتب عليه اسم المنتج ومخاطره."],activity:{prompt:"في مخزن الصيانة، يجد عامل وعاءً بلاستيكيًا قديمًا فيه سائل شفاف بلا ملصق. يريد استخدامه لتنظيف قطعة لأن رائحته كرائحة المذيب. أنت مشرف المخزن. ماذا تفعل؟",options:[{text:"أوقفه، وأضع الوعاء جانبًا بأمان، وأعلّمه بأنه «مجهول»، وأرتّب لتحديد المادة أو التخلص منها بالطريقة الصحيحة.",correct:!0,feedback:"صحيح: المادة بلا ملصق مادة مجهولة، والرائحة لا تحدد هويتها؛ ولا تُستخدم حتى تُعرف."},{text:"أتركه يستخدمه في الخارج حيث تنتشر الأبخرة.",correct:!1,feedback:"خطأ: قد يكون السائل أكّالًا أو سامًا أو متفاعلًا؛ والهواء الطلق لا يجعل مادة مجهولة آمنة."},{text:"أسكبه في عبوة مذيب عليها ملصق حتى يُستهلك.",correct:!1,feedback:"خطأ: خلط سائل مجهول بمذيب قد يسبب تفاعلًا، وستحمل العبوة ملصقًا غير صحيح."},{text:"أسكبه في المصرف للتخلص من الخطر.",correct:!1,feedback:"خطأ: المواد الكيميائية في المصارف قد تتفاعل أو تشعل حريقًا أو تلوّث المياه؛ والتخلص يكون وفق صحيفة SDS والقواعد الرسمية."}]},caseStudy:[{prompt:"أثناء التنظيف، يسكب عامل منظّفًا يحتوي على الكلور (Bleach) في دلو ما زال فيه حمض لإزالة الترسبات الكلسية. تملأ رائحة لاذعة المغسلة الصغيرة ويبدأ بالسعال. أنت قريب منه. ماذا تفعل أولًا؟",options:[{text:"أُخرجه هو والجميع فورًا إلى الهواء النقي وأمنع الآخرين من الدخول.",correct:!0,feedback:"صحيح: خلط الكلور بالحمض يطلق غاز الكلور؛ والخروج من المكان أولًا."},{text:"أضيف الماء إلى الدلو لتخفيف الخليط.",correct:!1,feedback:"خطأ: البقاء بجانب الدلو يُبقيك في الغاز؛ اخرج أولًا."},{text:"أفتح النافذة وأكمل التنظيف بكمامة غبار من الرف.",correct:!1,feedback:"خطأ: كمامة الغبار لا تحمي من غاز الكلور؛ غادر المكان."}]},{prompt:"في الخارج، ما زال العامل يسعل ويقول إن صدره يضيق. باب المغسلة مغلق. ماذا تفعل الآن؟",options:[{text:"أتصل بالرقم 122، وأبقيه مستريحًا في الهواء النقي، وأخبر فريق الإسعاف بالمنتجات التي خُلطت، وأبقي المغسلة مغلقة حتى تُطهَّر.",correct:!0,feedback:"صحيح: أعراض التنفس بعد التعرض لمادة كيميائية تحتاج إلى رعاية طبية، والفريق يحتاج إلى معرفة المنتجات."},{text:"أعطيه حليبًا ليشربه ليعادل الغاز.",correct:!1,feedback:"خطأ: لا علاجات منزلية؛ ولا طعام أو شراب إلا إذا قال الطبيب. اتصل بالرقم 122."},{text:"أعيده إلى العمل عندما يخف السعال.",correct:!1,feedback:"خطأ: أعراض التنفس بعد التعرض لمادة كيميائية تحتاج إلى فحص طبي، لأنها قد تسوء لاحقًا."}]}],realCase:"احتاج عامل إلى كمية صغيرة من الحمض لعمل تنظيف. فسكبها في قنينة ماء فارغة وتركها على طاولة. وفي وقت لاحق، رأى زميل القنينة فظنها ماءً وكاد يشرب منها؛ ولم يتوقف إلا بسبب الرائحة. وكشف التحقيق أن المصنع لم تكن فيه أوعية صغيرة عليها ملصقات للنقل. فوفّرت الإدارة أوعية عليها ملصقات، ومنعت قناني المشروبات في مناطق المواد الكيميائية، وأضافت قراءة الملصقات إلى التدريب التمهيدي. ويتحقق المشرفون الآن في بداية كل وردية من أن كل وعاء في منطقتهم عليه ملصق."},{id:7,code:"HGHT-107",icon:"Construction",accent:"#0284c7",title:"العمل في الأماكن المرتفعة",subtitle:"Fall Protection & Ladders",summary:"الوقاية من السقوط من السقالات والأسطح والسلالم",blocks:[{body:"السقوط من الأماكن المرتفعة أحد الأسباب الرئيسية للوفاة في المصانع ومواقع البناء."},{heading:"1. الحماية من السقوط",body:"يتطلب كل عمل على ارتفاع (وفق OSHA: من 1.2 متر في أماكن العمل الصناعية، ومن 1.8 متر في أعمال البناء) ما يأتي:",points:["حزام الأمان الكامل للجسم (Full Body Harness): يُرتدى بشكل صحيح ومُحكم.","حبل الأمان (Lanyard): يجب أن يكون مثبّتًا بنقطة تثبيت متينة (Anchor Point).","حواجز الحماية (Guardrails): حول السقالات والأسطح والحواف المكشوفة."]},{heading:"2. سلامة السلالم (Ladders)",body:"قاعدة نقاط التماس الثلاث:",points:["يجب أن تكون 3 من أطراف الجسم (قدمان ويد، أو يدان وقدم) على السلّم دائمًا.","يجب أن تكون زاوية وضع السلّم بنسبة 4:1 (لكل 4 أمتار من الارتفاع، تكون قاعدة السلّم على بُعد متر واحد من الجدار)."]},{heading:"3. تخطيط العمل على ارتفاع",body:"قبل أي عمل على ارتفاع، يخطط له المشرف بهذا الترتيب:",points:["تجنّب العمل على ارتفاع حيثما أمكن، مثل استخدام أدوات ذات مقابض طويلة من الأرض.","امنع السقوط بحواجز الحماية أو سقالة مكتملة أو منصة عمل مناسبة.","حيث لا يمكن منع السقوط، استخدم نظام إيقاف السقوط: حزام الأمان الكامل وحبل الأمان ونقطة تثبيت متينة.","خطّط للإنقاذ قبل بدء العمل: فالعامل المعلّق في حزام الأمان يحتاج إلى مساعدة سريعة.","لا يستخدم أحزمة الأمان والسقالات ومنصات العمل إلا العمال المدرَّبون."]},{heading:"4. السلالم والسقالات والفتحات",body:"أسباب شائعة للسقوط وكيف نمنعها:",points:["افحص السلّم قبل استخدامه: لا شقوق في القائمين، ولا درجات مفقودة، ولا أقدام مكسورة.","ضع السلّم على أرض صلبة ومستوية واربطه من الأعلى، أو اطلب من أحد أن يمسك قاعدته.","لا تقف على الدرجات العليا ولا تمدّ جسمك أكثر من اللازم؛ انزل وانقل السلّم بدلًا من ذلك.","لا تستخدم إلا سقالات مكتملة، بحواجز حماية وألواح قدم (Toe Boards)، فحصها شخص كفء.","غطِّ فتحات الأرضيات وحواف الأسطح أو ضع عليها حواجز، ولا تخطُ أبدًا على ألواح سقف هشة أو نوافذ السقف."]}],media:[{kind:"video",src:"media/videos/fall_protection.mp4",title:"العمل على ارتفاع",description:"استخدام حزام الأمان الكامل للجسم"}],quiz:[{question:"ما معنى قاعدة النقاط الثلاث على السلّم؟",options:[{text:"ألا يقف على السلّم أكثر من 3 أشخاص في الوقت نفسه",correct:!1},{text:"أن تبقى عليه 3 دقائق",correct:!1},{text:"أن تكون 3 من أطراف الجسم متصلة بالسلّم دائمًا",correct:!0},{text:"أن تربط السلّم بـ 3 حبال",correct:!1}],explanation:"تهدف قاعدة النقاط الثلاث إلى ألّا يفقد العامل توازنه فيسقط."},{question:"يصل سلّم إلى ارتفاع 4 أمتار على الجدار. على أي بُعد من الجدار يجب أن تكون قاعدته؟",options:[{text:"نصف متر",correct:!1},{text:"متر واحد",correct:!0},{text:"متران",correct:!1},{text:"4 أمتار",correct:!1}],explanation:"يجب أن تكون زاوية وضع السلّم بنسبة 4:1: لكل 4 أمتار من الارتفاع، تكون قاعدة السلّم على بُعد متر واحد من الجدار."},{question:"بماذا يجب تثبيت حبل الأمان (Lanyard) الخاص بحزام الأمان الكامل للجسم؟",options:[{text:"بحزام أدوات العامل نفسه",correct:!1},{text:"بالسلّم الذي يقف عليه العامل",correct:!1},{text:"بنقطة تثبيت متينة (Anchor Point)",correct:!0},{text:"بأي أنبوب أو كابل قريب",correct:!1}],explanation:"يجب أن يكون حبل الأمان مثبّتًا بنقطة تثبيت متينة (Anchor Point)، وأن يُرتدى حزام الأمان الكامل للجسم بشكل صحيح ومُحكم."},{question:"أوقف حزام الأمان وحبل الأمان سقوط عامل. لم يُصب بأذى. ماذا يحدث للمعدات؟",options:[{text:"تُخرج من الخدمة حتى يفحصها شخص كفء",correct:!0},{text:"تُستخدم من جديد فورًا لأنها عملت جيدًا",correct:!1},{text:"تُستخدم من جديد بعد نظرة سريعة على الخياطة الممزقة",correct:!1},{text:"تُعطى لعامل يعمل على ارتفاع أقل",correct:!1}],explanation:"المعدات التي أوقفت سقوطًا تحمّلت حملًا كبيرًا وقد تكون تالفة من الداخل. تُخرج من الخدمة ولا تُستخدم مجددًا حتى يفحصها شخص كفء، وفق تعليمات الشركة المصنّعة."},{question:"على السلّم، تحتاج إلى الوصول إلى نقطة بعيدة قليلًا إلى أحد الجانبين. ماذا تفعل؟",options:[{text:"أنزل وأقرّب السلّم من تلك النقطة",correct:!0},{text:"أميل إلى الجانب وأمسك بيد واحدة",correct:!1},{text:"أخطو إلى رف أو آلة قريبة",correct:!1},{text:"أقف على الدرجة العليا لأصل أبعد",correct:!1}],explanation:"مدّ الجسم أكثر من اللازم ينقل وزنك خارج السلّم فيجعله ينزلق أو ينقلب. حافظ على نقاط التماس الثلاث وانقل السلّم بدلًا من ذلك."},{question:"ما الترتيب الصحيح للضوابط عند تخطيط العمل على ارتفاع؟",options:[{text:"تجنّب العمل على ارتفاع، ثم منع السقوط، ثم إيقاف السقوط",correct:!0},{text:"حزام الأمان أولًا، ثم حواجز الحماية، ثم تجنّب العمل",correct:!1},{text:"السلّم أولًا، لأنه أسرع حل",correct:!1},{text:"الاعتماد على عمال حذرين، ثم إضافة المعدات بعد السقوط",correct:!1}],explanation:"أولًا تجنّب العمل على ارتفاع حيثما أمكن؛ وإلا فامنع السقوط بحواجز الحماية أو المنصات؛ وحيث لا يمكن منعه فقط، استخدم حزام الأمان وحبل الأمان لإيقافه، مع خطة إنقاذ."}],steps:[{title:"راجع الخطة",detail:"اعرف المهمة والمخاطر وخطة الإنقاذ؛ واتبع تصريح العمل على ارتفاع في الموقع إن وُجد."},{title:"افحص معداتك",detail:"افحص أشرطة حزام الأمان وخياطته وأبازيمه، وحبل الأمان وخطافاته؛ ولا تستخدم معدات تالفة أو معدات أوقفت سقوطًا من قبل.",critical:!0},{title:"ارتدِ حزام الأمان واضبطه",detail:"اربط كل الأبازيم واضبط الأشرطة حتى يكون الحزام ملائمًا ومحكمًا.",critical:!0},{title:"ثبّت نفسك قبل التعرّض للخطر",detail:"ثبّت حبل الأمان بنقطة تثبيت متينة قبل أن تصل إلى الحافة، وابقَ مثبّتًا طوال الوقت.",critical:!0},{title:"أبقِ المنطقة السفلية آمنة",detail:"ضع حاجزًا حول المنطقة السفلية، وثبّت الأدوات كي لا تسقط، وأبعد الناس عن منطقة السقوط."}],warnings:["لا تثبّت أبدًا حبل الأمان بحاجز أو أنبوب أو كابل لم يُختر نقطة تثبيت: فقد لا يتحمل شخصًا يسقط.","لا تترك أبدًا عاملًا سقط معلّقًا في حزام الأمان بينما تنتظر: اتصل بالرقم 115 وابدأ خطة الإنقاذ فورًا، لأن التعلّق في الحزام يصبح خطرًا بسرعة."],tips:["احمل الأدوات في حقيبة أو بحبل أدوات عندما تصعد، لتبقى يداك حرتين.","أوقف العمل على ارتفاع عند الرياح القوية أو المطر أو الإضاءة الضعيفة وأبلغ المشرف.","اجعل وجهك نحو السلّم عند الصعود والنزول."],activity:{prompt:"يجب على عامل تبديل مصباح في سقف مرتفع. السقالة في مبنى آخر، فيقترح زميله الوقوف على كرسي موضوع فوق طاولة. أنت المشرف. ماذا تفعل؟",options:[{text:"أوقف العمل حتى يتوفر سلّم مناسب أو منصة عمل ويُخطَّط للعمل.",correct:!0,feedback:"صحيح: المنصات المرتجلة غير مستقرة؛ والمعدات الصحيحة تمنع السقوط."},{text:"أسمح بذلك إذا أمسك زميله الطاولة.",correct:!1,feedback:"خطأ: إمساك الطاولة لا يجعل الكرسي فوقها مستقرًا؛ والسقوط منه قد يقتل."},{text:"أسمح بذلك لأن العمل قصير.",correct:!1,feedback:"خطأ: السقوط يحدث في ثوانٍ، حتى في الأعمال القصيرة."},{text:"أطلب منه ارتداء الخوذة والبدء.",correct:!1,feedback:"خطأ: الخوذة لا تمنع السقوط؛ استخدم المعدات الصحيحة."}]},caseStudy:[{prompt:"يصلح عاملان لوحًا في السقف. أحدهما يرتدي حزام الأمان لكنه لم يثبّت حبل الأمان، لأن نقطة التثبيت بعيدة عن مكان عمله. تراه يمشي قرب حافة السقف. ماذا تفعل أولًا؟",options:[{text:"أطلب منه الابتعاد عن الحافة فورًا وأوقف العمل حتى يستطيع البقاء مثبّتًا بنقطة تثبيت متينة.",correct:!0,feedback:"صحيح: أوقف الفعل غير الآمن الآن؛ ولا يستمر العمل إلا عندما يستطيع البقاء مثبّتًا طوال الوقت."},{text:"أنتظر حتى ينتهي ثم أتحدث معه.",correct:!1,feedback:"خطأ: قد يقع السقوط في أي لحظة؛ أوقف الفعل غير الآمن الآن."},{text:"أطلب منه تثبيت حبل الأمان بمزراب المطر عند الحافة.",correct:!1,feedback:"خطأ: المزراب ليس نقطة تثبيت مختبرة وقد يُقتلع تحت حمل السقوط."}]},{prompt:"لاحقًا، وبينما هو مثبّت، ينزلق العامل نفسه عن الحافة. يوقف الحزام سقوطه وهو معلّق تحت الحافة وواعٍ. ماذا تفعل؟",options:[{text:"أتصل بالرقم 115، وأبدأ خطة الإنقاذ في الموقع فورًا، وأتحدث معه ليبقى هادئًا؛ ولا أقترب من الحافة من دون حماية من السقوط.",correct:!0,feedback:"صحيح: التعلّق في الحزام يصبح خطرًا بسرعة، لذلك يبدأ الإنقاذ فورًا بالطريقة والمعدات المخطط لها."},{text:"أنزل إليه من دون حزام وأسحبه إلى الأعلى.",correct:!1,feedback:"خطأ: قد تسقط أنت أيضًا؛ والإنقاذ يتم بالطريقة المخطط لها والمعدات الصحيحة."},{text:"أتركه معلّقًا حتى يصل فريق 115، لأن الحزام أوقف السقوط.",correct:!1,feedback:"خطأ: التعلّق في الحزام يصبح خطرًا بسرعة؛ ابدأ خطة الإنقاذ بينما الفريق في الطريق."}]}],realCase:"صعد عامل سلّمًا لإصلاح أنبوب. كان السلّم على أرضية عليها زيت، ولم يكن أحد يمسكه. وعندما مدّ جسمه إلى أحد الجانبين، انزلق السلّم فسقط على الأرضية الخرسانية وأُصيب في ظهره. لم يحرّكه زملاؤه واتصلوا بالرقم 122. وكشف التحقيق أن السلّم بلا أقدام مانعة للانزلاق، وأن الأرضية لم تُنظَّف، وأن العمل لم يُخطَّط له. فاستبدل المصنع سلالمه القديمة، وأضاف فحص السلالم إلى الفحص اليومي، وألزم المشرفين بالموافقة على كل عمل على ارتفاع قبل أن يبدأ."},{id:8,code:"CONF-108",icon:"Container",accent:"#9333ea",title:"الأماكن الضيقة والمحصورة",subtitle:"Confined Space Safety",summary:"العمل داخل الخزانات والأنابيب وغرف التفتيش",blocks:[{body:"الأماكن المحصورة خطرة لأن الهواء لا يتجدّد فيها، وقد ينخفض فيها الأكسجين، وتتجمّع فيها الغازات القاتلة."},{heading:"1. المخاطر الرئيسية",body:"قبل أن تدخل، اعلم ما يأتي:",points:["نقص الأكسجين (أقل من 19.5%): يؤدي إلى الاختناق.","الغازات السامة مثل CO (عديم الرائحة) وH₂S (الذي يُعطّل حاسة الشم عند التراكيز العالية).","خطر الحريق والانفجار إذا وُجدت غازات أو أبخرة قابلة للاشتعال."]},{heading:"2. إجراءات الدخول",body:"يجب توفّر الشروط الآتية:",points:["فحص الهواء بجهاز قياس الغازات (Gas Monitor) قبل الدخول وفي أثناء العمل.","وجود مراقب (Attendant) يبقى في الخارج، ويُبقي عينه على العامل في الداخل، ولا يدخل بأي حال من الأحوال.","يجب أن يكون تصريح العمل (Permit) ووسائل الاتصال وخطة الإنقاذ جاهزة."]},{heading:"3. أين توجد الأماكن المحصورة في المصنع؟",body:"المكان المحصور مكان يتسع لدخول الإنسان، لكن مداخله ومخارجه محدودة، ولم يُصمَّم لبقاء العمال فيه:",points:["الخزانات والصوامع والأوعية الكبيرة والحُفر.","مجاري الصرف الصحي وفتحات التفتيش وقنوات الهواء والأنابيب الكبيرة.","الحُفر تحت الآلات والمراجل من الداخل.","إذا لم تكن متأكدًا من أن المكان محصور، فتعامل معه على أنه محصور واسأل المشرف."]}],media:[{kind:"image",src:"media/images/confined_entry.png",title:"الأماكن المحصورة",description:"فحص الهواء"}],quiz:[{question:"هل يجوز للمراقب في الخارج أن يدخل دون معدات لإنقاذ زميله؟",options:[{text:"نعم، بدافع الإنسانية",correct:!1},{text:"لا، لأنه هو أيضًا سيختنق",correct:!0},{text:"نعم، إذا حبس أنفاسه",correct:!1},{text:"نعم، إذا كان الزميل قريبًا جدًا من المدخل",correct:!1}],explanation:"وفقًا لدراسات NIOSH، فإن جزءًا كبيرًا من الوفيات في الأماكن المحصورة هم أشخاص دخلوا للإنقاذ دون معدات أو تدريب. ويجب على المراقب أن يستدعي فريق الإنقاذ ويتصل بالرقم 115."},{question:"متى يجب فحص الهواء في المكان المحصور بجهاز قياس الغازات (Gas Monitor)؟",options:[{text:"مرة واحدة فقط في اليوم الأول من العمل",correct:!1},{text:"فقط إذا شمّ أحدٌ رائحة غير عادية",correct:!1},{text:"بعد انتهاء العمل",correct:!1},{text:"قبل الدخول وفي أثناء العمل",correct:!0}],explanation:"يُفحص الهواء قبل الدخول وفي أثناء العمل، لأن الأكسجين قد ينخفض والغازات القاتلة قد تتجمّع؛ وCO عديم الرائحة، فالشمّ ليس فحصًا."},{question:"داخل خزان، لم يعد أحد العمال يشمّ رائحة H₂S فجأة. ماذا قد يعني ذلك؟",options:[{text:"أن الغاز زال وأصبح الهواء آمنًا للتنفس",correct:!1},{text:"أن الغاز عطّل حاسة الشم",correct:!0},{text:"أن مروحة التهوية بدأت تعمل بشكل صحيح",correct:!1},{text:"أن الغاز تحوّل إلى بخار ماء غير ضار",correct:!1}],explanation:"يُعطّل H₂S حاسة الشم عند التراكيز العالية، لذا فإن اختفاء الرائحة لا يعني زوال الغاز؛ ولا يبيّن سلامة الهواء إلا جهاز قياس الغازات (Gas Monitor)."},{question:"أنت المشرف وستوقّع تصريح الدخول إلى مكان محصور. أيّ مما يأتي إذا غاب لا يجوز أن يبدأ العمل؟",options:[{text:"زوج إضافي من القفازات للعامل في الداخل",correct:!1},{text:"خطة الإنقاذ والأشخاص والمعدات اللازمة لها",correct:!0},{text:"قائمة مكتوبة بكل الأدوات التي ستُدخل إلى المكان",correct:!1},{text:"صورة للمكان التُقطت قبل بدء العمل",correct:!1}],explanation:"يجب أن يكون التصريح ووسائل الاتصال وخطة الإنقاذ جاهزة قبل الدخول؛ فالإنقاذ غير المخطط له يدفع أشخاصًا غير مدرَّبين إلى الدخول."},{question:"أيّ مما يأتي خطأ من المراقب؟",options:[{text:"البقاء على اتصال بالعامل في الداخل طوال الوقت",correct:!1},{text:"الأمر بالخروج عندما يُطلق جهاز الغاز إنذارًا",correct:!1},{text:"الدخول لوقت قصير لمساعدة عامل شعر بتوعّك",correct:!0},{text:"إطلاق الإنذار والاتصال بالرقم 115 إذا سقط العامل",correct:!1}],explanation:"المراقب لا يدخل أبدًا؛ عمله المراقبة، والأمر بالخروج، وإطلاق الإنذار، واستدعاء الإنقاذ."},{question:"كانت نتيجة الفحص قبل الدخول جيدة. لماذا يجب فحص الهواء في أثناء العمل أيضًا؟",options:[{text:"لأن الفحص الأول صالح للمشرف فقط",correct:!1},{text:"لأن العمل نفسه قد يُطلق غازات أو يُنقص الأكسجين",correct:!0},{text:"لأن جهاز القياس يجب أن يبقى مشغّلًا كي تبقى بطاريته مشحونة",correct:!1},{text:"لأن التصريح دون فحص ثانٍ مجرد ورقة",correct:!1}],explanation:"تتغيّر الظروف في أثناء العمل: التنظيف أو اللحام أو الطلاء أو الحمأة قد تُطلق غازات، وقد ينخفض الأكسجين، لذلك يستمر الفحص."}],steps:[{title:"قبل الدخول: التصريح والخطة",detail:"لا يدخل أحد حتى يُوقَّع تصريح العمل (Permit)، وتُعرف مخاطر هذا المكان، وتعمل وسائل الاتصال، وتكون خطة الإنقاذ جاهزة. اعمل وفق متطلبات الدفاع المدني والجهة المختصة.",critical:!0},{title:"العزل والتهوية",detail:"تُغلق الأنابيب التي تُدخل السوائل أو الغازات أو البخار إلى المكان وتُقفل، وتُوقف الأجزاء المتحركة بإجراء الإقفال والوسم (LOTO)، ويُهوّى المكان قبل الدخول.",critical:!0},{title:"فحص الهواء",detail:"قِس الأكسجين والغازات القابلة للاشتعال والغازات السامة بجهاز قياس الغازات (Gas Monitor) قبل الدخول، واستمر في القياس في أثناء العمل. إذا أطلق الجهاز إنذارًا، يخرج الجميع فورًا.",critical:!0},{title:"المراقب يبقى في الخارج",detail:"يبقى المراقب (Attendant) على تواصل بصري واتصال دائم مع العامل في الداخل، ولا يدخل أبدًا. إذا تغيّر أي شيء، يأمر العامل بالخروج.",critical:!0},{title:"إذا سقط العامل في الداخل",detail:"لا يدخل المراقب. أطلق الإنذار، واتصل بفريق الإنقاذ وبالرقم 115، واستخدم حبل الإنقاذ من الخارج فقط إذا كانت الخطة تنص على ذلك. لا يدخل إلا فريق مدرَّب مزوَّد بجهاز التنفس المستقل (SCBA).",critical:!0}],warnings:["لا تدخل أبدًا لإنقاذ عامل سقط دون خطة إنقاذ وجهاز تنفس وتدريب: المنقذ غير المدرَّب يصبح الضحية التالية.","لا تعتمد على حاسة الشم: CO عديم الرائحة، وH₂S قد يُعطّل حاسة الشم.","لا تعتمد على فحص قديم أو فحص الأمس: الهواء يتغيّر في أثناء العمل."],tips:["اتفق مع المراقب قبل العمل على إشارات بسيطة تعني «كل شيء بخير» و«اخرج» و«النجدة».","أبقِ مدخل المكان مفتوحًا وخاليًا من العوائق، ليخرج العامل بسرعة ويصل إليه فريق الإنقاذ.","إذا شعرت في الداخل بدوار أو صداع أو ضيق في التنفس، فاخرج فورًا وأبلغ المراقب.","المشرف: قبل توقيع التصريح، افحص بنفسك التصريح وجهاز قياس الغازات ومعدات الإنقاذ."],activity:{prompt:"أنت المراقب عند فتحة تفتيش يعمل فيها زميلك على تنظيف خزان. فجأة لم يعد يرد على ندائك، وتراه ممددًا على الأرض. ماذا تفعل؟",options:[{text:"أنزل بسرعة لأُخرجه",correct:!1,feedback:"الهواء الذي أسقطه سيُسقطك أيضًا؛ فجزء كبير من وفيات الأماكن المحصورة هم أشخاص دخلوا دون معدات لمحاولة الإنقاذ."},{text:"أبقى في الخارج، وأُطلق الإنذار، وأتصل بفريق الإنقاذ وبالرقم 115، وأستخدم حبل الإنقاذ من الخارج إذا كانت الخطة تنص على ذلك",correct:!0,feedback:"صحيح: بهذا تبقى حيًا، ويصل إليه بسرعة فريق مدرَّب مزوَّد بجهاز التنفس."},{text:"أحبس أنفاسي وأدخل لبضع ثوانٍ",correct:!1,feedback:"لا يمكنك تقدير الوقت اللازم؛ ففي هواء خالٍ من الأكسجين أو مليء بغاز سام قد يُفقدك نفَس واحد وعيك."},{text:"أربط قطعة قماش مبللة على فمي وأنفي وأدخل",correct:!1,feedback:"القماش المبلل لا يحمي من CO أو H₂S أو نقص الأكسجين؛ وحده جهاز التنفس مع التدريب يحمي."}]},caseStudy:[{prompt:"سينظّف فريق داخل خزان مياه. التصريح جاهز، لكن جهاز قياس الغازات غير موجود لأنه نُقل إلى موقع آخر. يقول المشرف: «لم يكن فيه إلا الماء، ابدأوا.» ماذا تفعل؟",options:[{text:"أبدأ دون فحص، لأنه لم يكن فيه إلا الماء",correct:!1,feedback:"الصدأ والمواد المتحللة والأنابيب القريبة قد تُنقص الأكسجين أو تُطلق غازات، حتى في خزان المياه."},{text:"أوقف العمل حتى يُحضَر جهاز قياس صالح ويُفحص الهواء",correct:!0,feedback:"صحيح: الفحص قبل الدخول شرط من شروط التصريح؛ ودون فحص لا يعرف أحد هل الهواء آمن أم لا."},{text:"أُرسل العامل الأصغر أولًا ليجرّب الهواء",correct:!1,feedback:"الإنسان ليس جهاز قياس؛ هذا يُعرّض حياة شخص للخطر."},{text:"أفتح الفتحة مدة ثم أدخل دون فحص",correct:!1,feedback:"فتح الفتحة لا يُثبت أن الأكسجين كافٍ أو أن الغاز زال؛ الفحص وحده يُثبت ذلك."}]},{prompt:"وصل الجهاز، وكانت نتيجة الفحص جيدة، ودخل أحد العمال. بعد مدة أطلق الجهاز المثبّت على صدره إنذارًا، ويقول إنه يشعر بالدوار. ماذا تفعل بصفتك المراقب؟",options:[{text:"أطلب منه أن يُنهي العمل بسرعة ثم يخرج",correct:!1,feedback:"الإنذار يعني أن الهواء لم يعد آمنًا؛ وكل دقيقة إضافية في الداخل تزيد الخطر."},{text:"آمره بالخروج فورًا، وأساعده من الخارج، وأوقف الدخول، وأبلغ لمعرفة السبب",correct:!0,feedback:"صحيح: الإنذار إشارة للخروج؛ ولا يدخل أحد حتى يُعرف السبب ويعود الهواء آمنًا."},{text:"أدخل لأرى قراءة جهازه بنفسي",correct:!1,feedback:"المراقب لا يدخل أبدًا؛ ودخولك يضع شخصين في الخطر."},{text:"أُسكت الإنذار لأن الجهاز قد يكون معطّلًا",correct:!1,feedback:"تعامل مع كل إنذار على أنه حقيقي؛ يُفحص الجهاز في الخارج بعد خروج الجميع."}]}],realCase:"في أثناء تنظيف خزان، لاحظت المراقبة أن العامل في الداخل يجيب ببطء وأن كلامه غير واضح. فأمرته بالخروج فورًا وساعدته من الفتحة دون أن تدخل. تعافى في الهواء الطلق وفحصه طبيب. وأظهر جهاز قياس الغازات عند الفتحة أن الأكسجين في الداخل قد انخفض. وكشف التحقيق أن أنبوب نيتروجين يدخل إلى الخزان لم يُقفل. فأضاف المصنع قاعدة جديدة: يُغلق كل أنبوب يدخل إلى مكان محصور ويُقفل ويُفحص قبل توقيع التصريح."},{id:9,code:"NOIS-109",icon:"Ear",accent:"#db2777",title:"الضجيج وحماية السمع",subtitle:"Hearing Conservation",summary:"الحماية من ضجيج الآلات الكبيرة",blocks:[{body:"يحدث الصمم أو ضعف السمع الناتج عن ضجيج المصانع تدريجيًا، ولا يمكن علاجه."},{heading:"1. مستويات الضجيج",body:"متى يصبح الضجيج خطرًا؟",points:["85 dB(A): حدّ بداية الخطر لمدة 8 ساعات عمل.","100 dB(A): دون حماية يكون آمنًا لمدة 15 دقيقة فقط في اليوم (NIOSH).","علامة: إذا شعرت بطنين (Tinnitus) في أذنيك بعد العمل، فهذا يعني أن الضجيج كان عاليًا جدًا."]},{heading:"2. معدات الحماية",body:"معدات حماية السمع (Hearing Protection Devices — HPD):",points:["سدادات الأذن (Earplugs): توفّر حماية جيدة إذا وُضعت بشكل صحيح.","أغطية الأذن (Earmuffs): سهلة الارتداء ومناسبة للضجيج العالي.","استخدام النوعين معًا في الأماكن شديدة الضجيج."]},{heading:"3. التحكم في الضجيج في مكان العمل",body:"معدات الحماية هي آخر وسيلة. يبدأ مكان العمل بما يأتي:",points:["يشتري آلات أهدأ، ويُصلح الأجزاء المرتخية أو البالية أو غير المتوازنة.","يغلّف الآلات الصاخبة أو يفصلها عن أماكن العمل.","يحدّد الأماكن الصاخبة بالعلامات، ويوفّر حماية السمع عند مداخلها.","ينظّم فحوص السمع لعمال الأماكن الصاخبة، ويتصرّف بناءً على نتائجها."]}],media:[{kind:"video",src:"media/videos/hearing_protection.mp4",title:"الضجيج",description:"كيف تستخدم واقيات السمع؟"}],quiz:[{question:"إذا بلغ الضجيج 100 dB(A)، فكم من الوقت يمكنك البقاء دون واقيات سمع وفقًا لـ NIOSH؟",options:[{text:"45 دقيقة",correct:!1},{text:"15 دقيقة",correct:!0},{text:"4 ساعات",correct:!1},{text:"وردية كاملة من 8 ساعات",correct:!1}],explanation:"وفقًا لـ NIOSH، كل زيادة بمقدار 3 dB تخفض الوقت الآمن إلى النصف: 85 dB(A) لمدة 8 ساعات، و100 dB(A) لمدة 15 دقيقة فقط."},{question:"بعد انتهاء العمل، شعرت بطنين (Tinnitus) في أذنيك. ماذا يعني ذلك؟",options:[{text:"أن أذنيك بدأتا تعتادان الضجيج",correct:!1},{text:"أن الضجيج كان عاليًا جدًا",correct:!0},{text:"أن سدادات الأذن كانت ضيقة جدًا",correct:!1},{text:"أنه أمر طبيعي ولا يعني شيئًا",correct:!1}],explanation:"الطنين في الأذنين بعد العمل علامة على أن الضجيج كان عاليًا جدًا؛ وضعف السمع الناتج عن الضجيج يحدث تدريجيًا ولا يمكن علاجه، لذا استخدم واقيات السمع."},{question:"في الأماكن شديدة الضجيج، كيف يجب أن تكون حماية السمع؟",options:[{text:"القطن بدلًا من سدادات الأذن",correct:!1},{text:"دون حماية، ولكن مع فترات راحة قصيرة",correct:!1},{text:"سدادات الأذن وأغطية الأذن معًا",correct:!0},{text:"وضع اليدين على الأذنين عند ارتفاع الصوت",correct:!1}],explanation:"في الأماكن شديدة الضجيج استخدم النوعين معًا: سدادات الأذن توفّر حماية جيدة إذا وُضعت بشكل صحيح، وأغطية الأذن سهلة الارتداء ومناسبة للضجيج العالي."},{question:"تضطر إلى رفع صوتك ليسمعك زميل على بُعد ذراع. ماذا يدل ذلك؟",options:[{text:"الأرجح أن الضجيج عالٍ بما يكفي لإتلاف السمع",correct:!0},{text:"ربما يعاني زميلك مسبقًا من مشكلة في السمع",correct:!1},{text:"الآلات تحتاج إلى تزييت وستهدأ قريبًا",correct:!1},{text:"هذا ضجيج عادي في المصانع ولا يحتاج إلى أي إجراء",correct:!1}],explanation:"الحاجة إلى رفع الصوت للتحدث على بُعد ذراع علامة بسيطة على أن الضجيج خطِر؛ قيسوا مستوى الضجيج واستخدموا الحماية."},{question:"ما أفضل طريقة لحماية العمال من آلة صاخبة؟",options:[{text:"خفض الضجيج من مصدره، ثم حماية السمع لما تبقّى",correct:!0},{text:"إعطاء السدادات فقط للعمال الذين يشتكون من الضجيج",correct:!1},{text:"السماح للعمال بسماع الموسيقى بالسماعات لتغطية الضجيج",correct:!1},{text:"الطلب من العمال الوقوف خلف الآلة لا أمامها",correct:!1}],explanation:"خفض الضجيج من مصدره يحمي الجميع؛ ومعدات الحماية آخر وسيلة، والموسيقى تزيد الصوت."},{question:"يخلع عامل أغطية أذنيه كل ساعة لوقت قصير ليريح أذنيه. ما المشكلة؟",options:[{text:"الأغطية تبلى أسرع إذا خُلعت كثيرًا",correct:!1},{text:"الفترات القصيرة دون حماية في الضجيج تُلحق الضرر أيضًا",correct:!0},{text:"لا مشكلة، لأن الاستراحات القصيرة في الضجيج لا تضر أبدًا",correct:!1},{text:"ستعتاد أذناه على الضجيج وتصبحان أقوى",correct:!1}],explanation:"يجب ارتداء الحماية طوال الوقت في الضجيج؛ للاستراحة انتقل إلى مكان هادئ واخلعها هناك."}],steps:[{title:"تعرّف على الأماكن الصاخبة",detail:"انتبه إلى أماكن علامات حماية السمع، واسأل عن الآلات والأماكن الصاخبة. إذا اضطررت إلى رفع صوتك ليسمعك شخص على بُعد ذراع، فالأرجح أن الضجيج خطِر."},{title:"خفّض الضجيج من مصدره أولًا",detail:"للمسؤولين وفرق الصيانة: الآلات الأهدأ، وتغليف الآلات الصاخبة، وإصلاح الأجزاء المرتخية أو البالية، وإبعاد العمال عن مصدر الضجيج، كلها تأتي قبل معدات الحماية."},{title:"ارتدِ الحماية بشكل صحيح",detail:"أدخل سدادات الأذن بالكامل كما شُرح في التدريب. ويجب أن تُحكم أغطية الأذن الإغلاق حول الأذن دون شعر أو ذراعي نظارة أو قبعة تحتها."},{title:"ارتدِها طوال وجودك في الضجيج",detail:"لا تعمل الحماية إلا إذا ارتُديت طوال الوقت. فخلعها ولو لوقت قصير في الضجيج يسمح لجزء كبير من الضرر بالوصول إلى أذنيك."},{title:"أبلغ وافحص سمعك",detail:"أبلغ عن طنين الأذن أو ضعف وضوح السمع بعد العمل، وشارك في فحوص السمع التي ينظمها مكان العمل."}],warnings:["لا تستخدم القطن أو المناديل الورقية بدل سدادات الأذن: فهي لا توفّر حماية حقيقية.","لا تستخدم سماعات الموسيقى لتغطية ضجيج المصنع: فهي تضيف صوتًا ولا تحمي.","لا تخلع الحماية في الضجيج لتتحدث أو لترد على الهاتف: انتقل أولًا إلى مكان أهدأ."],tips:["حافظ على نظافة سدادات الأذن واستبدلها إذا اتسخت أو تلفت، واغسل يديك قبل وضعها.","استخدم حماية السمع في البيت أيضًا عند العمل بأدوات صاخبة.","للمسؤولين: ضعوا العلامات عند مداخل الأماكن الصاخبة، ووفّروا هناك ما يكفي من معدات حماية السمع."],activity:{prompt:"في قسم المكابس الضجيج عالٍ جدًا. ينزع عامل جديد أغطية أذنيه لأنها حارة، ويقول إن الضجيج لا يزعجه. أنت مسؤوله. ماذا تفعل؟",options:[{text:"أتركه، فإذا لم يزعجه الضجيج فلن يضرّه",correct:!1,feedback:"الضجيج يُتلف السمع دون ألم؛ والضرر يتراكم تدريجيًا ولا يمكن علاجه."},{text:"أشرح له الضرر، وأجعله يرتدي الحماية من جديد، وأبحث له عن نوع أكثر راحة مثل سدادات الأذن",correct:!0,feedback:"صحيح: الحماية لا تعمل إلا إذا ارتُديت، والنوع المريح يزيد احتمال أن يرتديها."},{text:"أعطيه قطنًا ليضعه في أذنيه بدل الأغطية",correct:!1,feedback:"القطن لا يوفّر حماية حقيقية، ويوهم العامل بأنه محمي."},{text:"أسمح له بالعمل دون حماية لنصف الوردية فقط",correct:!1,feedback:"يُحدَّد الوقت الآمن وفق مستوى الضجيج المقاس لا وفق إحساس العامل، وفي مكان شديد الضجيج يكون هذا الوقت قصيرًا جدًا."}]},caseStudy:[{prompt:"يقول عمال قاعة التعبئة إنهم منذ تركيب ضاغط هواء جديد يضطرون إلى الصراخ ليسمع بعضهم بعضًا. أنت المسؤول. ماذا تفعل أولًا؟",options:[{text:"لا أفعل شيئًا، لأن أحدًا لم يشكُ من ألم",correct:!1,feedback:"الضجيج يضر دون ألم، والصراخ للتحدث علامة على ضجيج خطِر."},{text:"أُبلغ ليُقاس مستوى الضجيج، وأوزّع حماية السمع على العمال إلى أن يُضبط",correct:!0,feedback:"صحيح: القياس يبيّن حجم الخطر، والحماية تحمي العمال إلى أن يُخفَّض الضجيج."},{text:"أطلب من العمال أن يقلّلوا الكلام",correct:!1,feedback:"قلة الكلام لا تخفّض ضجيج الضاغط، والضرر يستمر."},{text:"أرفع صوت المذياع حتى لا يُسمع الضاغط",correct:!1,feedback:"المذياع يضيف صوتًا فوق الضجيج ويزيد الضرر."}]},{prompt:"أظهر القياس أن القاعة صاخبة. تسأل الإدارة عمّا يجب فعله. أيّ خطة هي الأفضل؟",options:[{text:"توزيع سدادات الأذن فقط دون تغيير أي شيء آخر",correct:!1,feedback:"معدات الحماية هي آخر وسيلة؛ وخفض الضجيج من مصدره يحمي الجميع."},{text:"تغليف الضاغط أو نقله، وإبقاء الحماية والعلامات إلى أن ينخفض الضجيج، وتنظيم فحوص السمع",correct:!0,feedback:"صحيح: يُخفَّض الضجيج من مصدره، وتبقى الحماية لما تبقّى منه، وتكشف فحوص السمع الضرر مبكرًا."},{text:"منح العمال استراحات أطول داخل القاعة الصاخبة نفسها",correct:!1,feedback:"الاستراحة داخل الضجيج نفسه لا تُبعد العامل عن الضجيج."},{text:"تعيين عمال لديهم ضعف سمع سابق فقط",correct:!1,feedback:"هذا غير عادل، وما تبقّى من سمعهم سيتضرر أيضًا."}]}],realCase:"عمل عامل سنوات طويلة بجانب آلات القطع، ولم يكن يضع سدادات أذنيه إلا «عندما يكون الضجيج عاليًا جدًا». كان يشعر بطنين في أذنيه بعد الوردية لكنه ظنّه أمرًا عاديًا. ومع الوقت لم يعد يتابع الحديث وسط مجموعة، ولم يعد يسمع أطفاله بوضوح في البيت. وأظهر فحص السمع ضعفًا دائمًا في السمع. بعد ذلك قاس المصنع الضجيج في كل القاعات، ووضع العلامات في الأماكن الصاخبة، وغلّف أكثر الآلات ضجيجًا، ودرّب جميع العمال على ارتداء الحماية طوال وجودهم في الضجيج."},{id:10,code:"ERGO-110",icon:"Package",accent:"#0d9488",title:"رفع الأحمال (Ergonomics)",subtitle:"Safe Lifting Techniques",summary:"الوقاية من آلام الظهر والعضلات",blocks:[{body:"إصابات الظهر من أكثر الإصابات انتشارًا في المصانع، وسببها الرفع الخاطئ للأحمال."},{heading:"1. الطريقة الصحيحة للرفع",body:"تطبيق الخطوات الآتية يحمي ظهرك:",points:["اثنِ ركبتيك: استخدم قوة ساقيك، لا قوة ظهرك.","قرّب الحمل من جسمك: كلما ابتعد الحمل عنك زاد الضغط على ظهرك.","حافظ على استقامة ظهرك: لا تحنِ ظهرك عندما ترفع شيئًا ثقيلًا.","لا تلوِ جسمك: إذا أردت نقل الحمل إلى أحد الجانبين، فاستدر بجسمك كله مستخدمًا قدميك."]},{heading:"2. فكّر قبل أن ترفع",body:"يمكن منع معظم إصابات الرفع بالتخطيط:",points:["لا ترفع الحمل بيديك حيث يمكن أن تقوم بالعمل عربة أو رافعة منصّات أو رافعة.","قيّم الحمل: الوزن والحجم ومكان الإمساك، وهل يتحرك ما بداخله.","قيّم نفسك والمكان: المساحة والأرضية والدرج والإضاءة والحرارة.","إذا كان الحمل ثقيلًا أو صعبًا، فاطلب المساعدة أو المعدات، ولا تخاطر."]}],media:[{kind:"image",src:"media/images/safe_lifting.png",title:"رفع الحمل",description:"الأسلوب الصحيح"}],quiz:[{question:"عند رفع شيء ثقيل، على ماذا يجب أن يقع الجهد؟",options:[{text:"عضلات أسفل الظهر",correct:!1},{text:"عضلات الساقين",correct:!0},{text:"عضلات الكتفين",correct:!1},{text:"اليدان فقط",correct:!1}],explanation:"عضلات الساقين أقوى، وهي تحمي الظهر من الإصابة."},{question:"عند رفع حمل ثقيل، أين يجب أن يكون الحمل؟",options:[{text:"على امتداد ذراعيك بعيدًا عن جسمك",correct:!1},{text:"فوق رأسك",correct:!1},{text:"على أحد جانبي جسمك",correct:!1},{text:"قريبًا من جسمك",correct:!0}],explanation:"قرّب الحمل من جسمك: كلما ابتعد الحمل عنك زاد الضغط على ظهرك."},{question:"تحتاج إلى نقل حمل إلى أحد الجانبين. كيف تستدير؟",options:[{text:"ألوي جسمي وأُبقي قدميّ في مكانهما",correct:!1},{text:"أستدير بجسمي كله مستخدمًا قدميّ",correct:!0},{text:"أحني ظهري جانبًا نحو المكان الجديد",correct:!1},{text:"أرمي الحمل بسرعة إلى الجهة الأخرى لأوفّر الجهد",correct:!1}],explanation:"لا تلوِ جسمك: إذا أردت نقل الحمل إلى أحد الجانبين، فاستدر بجسمك كله مستخدمًا قدميك، وحافظ على استقامة ظهرك."},{question:"قبل رفع صندوق لم تحمله من قبل، ماذا تفعل أولًا؟",options:[{text:"أحرّكه بلطف لأقدّر وزنه وأتفقّد مكان الإمساك",correct:!0},{text:"أرفعه بسرعة حتى لا يُتعبني وزنه",correct:!1},{text:"أطلب من شخص أن يضعه على ظهري",correct:!1},{text:"أنحني فوقه بساقين مستقيمتين لأصل إليه بسهولة",correct:!1}],explanation:"اختبار الوزن والإمساك قبل الرفع يبيّن هل تستطيع حمله وحدك أم تحتاج إلى مساعدة أو معدات."},{question:"حمل يحجب رؤيتك للطريق وأنت تحمله. ما القرار الصحيح؟",options:[{text:"أحمله وأمشي أسرع لأصل في وقت أقصر",correct:!1},{text:"أستخدم عربة أو رفعًا جماعيًا أو أقسّم الحمل لأرى الطريق",correct:!0},{text:"أحمله فوق رأسي لتبقى عيناي حرّتين",correct:!1},{text:"أطلب من زميل أن يرشدني بالصياح إلى الطريق وأنا لا أرى أمامي شيئًا",correct:!1}],explanation:"إذا لم ترَ الطريق فقد تصطدم بالأشياء أو تسقط؛ والمعدات المساعدة أو الرفع الجماعي أو الأحمال الأصغر تعيد إليك الرؤية."},{question:"في الرفع الجماعي، أيّ مما يأتي خطأ؟",options:[{text:"الاتفاق على الطريق ومكان وضع الحمل قبل البدء",correct:!1},{text:"الرفع معًا عند أمر واحد واضح",correct:!1},{text:"يرفع كل شخص حين يشعر بأنه جاهز",correct:!0},{text:"اختيار شركاء متقاربين في الطول إن أمكن",correct:!1}],explanation:"الرفع غير المتزامن يُلقي الوزن كله لحظة على شخص واحد فيُصيب ظهره؛ يجب أن يكون الرفع عند أمر واحد."}],steps:[{title:"خطّط للرفع",detail:"افحص وزن الحمل وحجمه ومكان الإمساك به والطريق. إذا كان الحمل ثقيلًا أو صعب الحمل، فاستخدم عربة أو رافعة أو شخصًا ثانيًا."},{title:"أخلِ الطريق",detail:"أزل العوائق من الطريق، وافتح الأبواب قبل الرفع، واعرف أين ستضع الحمل."},{title:"وقفة ثابتة ومسكة جيدة",detail:"باعد بين قدميك لتبقى متوازنًا، واثنِ ركبتيك، وحافظ على استقامة ظهرك، وأمسك الحمل بإحكام."},{title:"ارفع بساقيك وبسلاسة",detail:"قرّب الحمل من جسمك وارفعه بقوة ساقيك دون عجلة أو جذب مفاجئ، وأبقِ رأسك مرفوعًا."},{title:"النقل والوضع",detail:"استدر بقدميك لا بلَيّ جسمك، وضع الحمل ثم عدّل موضعه. إذا تعبت، فضع الحمل أولًا ثم استرح."}],warnings:["لا ترفع حملًا لست متأكدًا من قدرتك على حمله: اختبره أولًا بلطف، واطلب المساعدة أو المعدات.","لا ترفع وتلوِ جسمك في الوقت نفسه، ولا تحمل حملًا يحجب عنك رؤية الطريق."],tips:["ضع الأحمال الثقيلة على رفوف بارتفاع الخصر، لا على الأرض ولا على الرفوف العالية.","قسّم الحمل الكبير إلى أحمال أصغر إن أمكن.","في الرفع الجماعي، يعطي شخص واحد الأوامر ليرفع الجميع ويضعوا الحمل معًا.","أبلغ عن ألم الظهر مبكرًا، قبل أن يتحول إلى إصابة خطيرة."],activity:{prompt:"وصلت أكياس ثقيلة إلى المخزن والعربة معطّلة. يريد مسؤولك نقلها بسرعة. ماذا تفعل؟",options:[{text:"أحمل كيسين في كل مرة لأنتهي أسرع",correct:!1,feedback:"الحمل المضاعف يزيد الضغط على الظهر ويرفع احتمال الإصابة."},{text:"أُبلغ عن العربة المعطّلة، وأطلب معدات أخرى أو مساعدة، وأخطّط لرفع جماعي",correct:!0,feedback:"صحيح: المعدات المساعدة والرفع الجماعي يخفّفان الضغط على الظهر، والإبلاغ يضمن إصلاح العربة."},{text:"أجرّ الأكياس على الأرض وأنا منحنٍ بظهري",correct:!1,feedback:"الجرّ والظهر منحنٍ يضع ضغطًا كبيرًا على أسفل الظهر."},{text:"أرمي الأكياس من الأسفل إلى الرف",correct:!1,feedback:"الرمي يلوي الجسم بسرعة، وقد يسقط الحمل عليك أو على غيرك."}]},caseStudy:[{prompt:"عليك نقل محرك ثقيل من الأرض إلى طاولة العمل، والإمساك به صعب. ماذا تفعل أولًا؟",options:[{text:"أرفعه فورًا بساقين مستقيمتين وظهر منحنٍ",correct:!1,feedback:"هذا يضع أكبر ضغط على الظهر، وهو أخطر طريقة."},{text:"أقدّر الوزن وطريقة الإمساك، وأستخدم رافعة أو شخصًا آخر",correct:!0,feedback:"صحيح: التخطيط والمعدات المساعدة أول خطوة؛ والحمل الثقيل الصعب لا يُرفع منفردًا."},{text:"أسحبه وأرفعه من سلكه",correct:!1,feedback:"السلك غير مصمَّم للرفع وقد ينقطع، فيسقط الحمل على القدمين."},{text:"أطلب من أصغر العمال أن يرفعه وحده",correct:!1,feedback:"العمر لا يقلّل الخطر؛ فالحمل الثقيل الصعب يُصيب ظهر أي شخص."}]},{prompt:"سيساعدك زميل لترفعا المحرك معًا. كيف تنفّذان الرفع الجماعي؟",options:[{text:"يرفع كلٌّ منا حين يكون جاهزًا",correct:!1,feedback:"الرفع غير المتزامن يُلقي الوزن كله على شخص واحد."},{text:"يعطي شخص واحد الأوامر؛ نرفع معًا، ويبقى الحمل قريبًا من الجسم، وننقله ونضعه معًا",correct:!0,feedback:"صحيح: أوامر شخص واحد توزّع الوزن بالتساوي، فلا يجد أحد نفسه فجأة يحمل الحمل وحده."},{text:"يحمل الأقوى معظم الوزن ويكتفي الآخر بالتوجيه",correct:!1,feedback:"هذا ليس رفعًا جماعيًا؛ فالأقوى ما زال يحمل حملًا ثقيلًا وحده."},{text:"نرفعه بسرعة لنقصّر مدة الحمل",correct:!1,feedback:"الجذب السريع المفاجئ يُصيب الظهر؛ يجب أن يكون الرفع سلسًا ومنظّمًا."}]}],realCase:"كان أمين مخزن يرفع كل يوم صناديق ثقيلة من الأرض إلى رف عالٍ، وهو يحني ظهره ويلوي جسمه عند وضعها. وفي صباح أحد الأيام شعر بألم حاد في أسفل ظهره في أثناء الرفع، ولم يستطع الوقوف مستقيمًا. وغاب عن العمل مدة طويلة. بعد ذلك نقل المصنع الأحمال الثقيلة إلى رفوف بارتفاع الخصر، ووفّر عربة وطاولة رفع صغيرة، ودرّب جميع موظفي المخزن على التخطيط لكل عملية رفع، وطلب المساعدة مع الأحمال الصعبة، والاستدارة بالقدمين."},{id:11,code:"GAS-111",icon:"Wind",accent:"#0891b2",title:"الغازات والتهوية",subtitle:"Ventilation & Toxic Gases",summary:"التحكم في جودة الهواء والغازات السامة",blocks:[{body:"التهوية الصحيحة في المصنع مهمة لمنع تراكم الغبار والغازات التي تسبب أمراض الجهاز التنفسي."},{heading:"1. أول أكسيد الكربون (CO)",body:"الغاز القاتل الصامت:",points:["عديم اللون والرائحة.","ينتج عن احتراق الوقود وعن محركات البنزين والديزل (مثل المولّدات والرافعات الشوكية).","الأعراض: الصداع، والدوار، والغثيان، وفقدان الوعي. إذا شعرت بهذه الأعراض، فاخرج فورًا إلى الهواء الطلق واتصل بالرقم 122."]},{heading:"2. أنواع التهوية",body:"كيف يتجدّد الهواء؟",points:["التهوية الطبيعية: الأبواب والنوافذ المفتوحة.","التهوية الاصطناعية: المراوح وأنظمة الشفط الموضعي للهواء (Local Exhaust).","الوقاية الشخصية: أقنعة التنفس ذات المرشّحات وفق صحيفة SDS؛ لكن أقنعة المرشّحات لا تحمي من CO ولا من نقص الأكسجين."]},{heading:"3. غازات خطرة أخرى في مكان العمل",body:"ليس CO الغاز الخطِر الوحيد:",points:["H₂S: ينتج عن مياه الصرف والمجاري والمواد المتحللة، وقد يُعطّل حاسة الشم.","غازات مثل النيتروجين والأرغون قد تحلّ محل الأكسجين دون أي لون أو رائحة.","أبخرة المذيبات والدهانات والوقود قد تكون سامة وقابلة للاشتعال أيضًا.","اقرأ صحيفة SDS لكل مادة: ففيها المخاطر والتهوية والحماية اللازمة."]}],media:[{kind:"video",src:"media/videos/ventilation_safety.mp4",title:"الغازات",description:"غاز أول أكسيد الكربون (CO)"}],quiz:[{question:"لماذا يُعدّ غاز CO خطرًا؟",options:[{text:"لأن رائحته كريهة",correct:!1},{text:"لأنه لا يُرى ولا يُشمّ",correct:!0},{text:"لأن لونه أحمر",correct:!1},{text:"لأنه لا يتكوّن إلا في الليل",correct:!1}],explanation:"لأنه لا يمكن الإحساس به، يتسمّم العمال دون أن يدركوا ذلك. ضع أجهزة كشف CO (CO Detector) في الأماكن التي تعمل فيها المحركات."},{question:"في أثناء العمل قرب مولّد يعمل، أصابك صداع ودوار وغثيان. ماذا تفعل؟",options:[{text:"أتناول مسكّنًا وأواصل العمل",correct:!1},{text:"أجلس قرب المولّد لأستريح",correct:!1},{text:"أرتدي قناع تنفس بمرشّح وأبقى في مكاني",correct:!1},{text:"أخرج فورًا إلى الهواء الطلق وأتصل بالرقم 122",correct:!0}],explanation:"الصداع والدوار والغثيان قد تكون أعراض التسمم بغاز CO؛ فاخرج فورًا إلى الهواء الطلق واتصل بالرقم 122، لأن CO لا يُرى ولا يُشمّ."},{question:"هل يحمي قناع التنفس ذو المرشّح العاملَ من غاز CO؟",options:[{text:"لا، لا يحمي من CO",correct:!0},{text:"نعم، أي قناع بمرشّح يوقف CO",correct:!1},{text:"نعم، إذا ارتُدي أقل من ساعة",correct:!1},{text:"فقط إذا تغيّر المرشّح كل يوم",correct:!1}],explanation:"تُختار أقنعة التنفس ذات المرشّحات وفق صحيفة SDS، لكنها لا تحمي من CO ولا من نقص الأكسجين؛ وفي الأماكن التي تعمل فيها المحركات تلزم التهوية وأجهزة كشف CO."},{question:"يُطلق جهاز كشف الغاز في مكانك إنذارًا، لكنك لا تشم شيئًا. ماذا تفعل؟",options:[{text:"أغادر المكان وأُبلغ، لأن كثيرًا من الغازات بلا رائحة",correct:!0},{text:"أبقى، لأن الإنذار دون رائحة غالبًا ما يكون خاطئًا",correct:!1},{text:"أطفئ الجهاز وأختبره مرة أخرى بعد الوردية",correct:!1},{text:"أفتح نافذة وأتابع العمل الذي كنت أقوم به",correct:!1}],explanation:"CO وغازات كثيرة أخرى بلا رائحة، وH₂S قد يُعطّل حاسة الشم؛ تعامل مع الإنذار على أنه حقيقي واخرج."},{question:"ما الطريقة الأفضل لإزالة الأبخرة عند نقطة عمل مثل طاولة التنظيف بالمذيبات؟",options:[{text:"مروحة عادية تدفع الهواء مباشرة نحو العمال عند الطاولة",correct:!1},{text:"الشفط الموضعي (Local Exhaust) الذي يلتقط الأبخرة من مصدرها",correct:!0},{text:"رشّ معطّر الجو في الورشة بانتظام ودون توقف",correct:!1},{text:"قناع غبار لكل عامل يعمل عند طاولة التنظيف",correct:!1}],explanation:"يلتقط الشفط الموضعي الأبخرة قبل أن تصل إلى منطقة تنفس العامل؛ أما المروحة العادية فتنشرها، وقناع الغبار لا يحمي من الأبخرة."},{question:"سقط عامل في منطقة غاز. أيّ تصرف خطأ؟",options:[{text:"إطلاق الإنذار والاتصال بالرقمين 115 و122 فورًا",correct:!1},{text:"الدخول بقماش مبلل على الفم لإخراجه",correct:!0},{text:"إبعاد الآخرين عن منطقة الغاز حتى وصول الفريق",correct:!1},{text:"إخبار فريق الإنقاذ بالغاز الذي قد يكون موجودًا",correct:!1}],explanation:"القماش المبلل لا يحمي من الغازات السامة ولا من نقص الأكسجين؛ لا يدخل إلا فريق مدرَّب بجهاز التنفس."}],steps:[{title:"قبل العمل: التهوية وأجهزة الكشف",detail:"تأكد من أن التهوية والشفط الموضعي (Local Exhaust) يعملان، وأن أجهزة كشف الغاز صالحة. لا تشغّل محركات البنزين والديزل في مكان مغلق دون تهوية مصمَّمة لذلك."},{title:"تعرّف على علامات الإنذار",detail:"إنذار جهاز كشف الغاز، أو رائحة غير معتادة، أو صداع ودوار وغثيان عند عدة عمال في الوقت نفسه، كلها علامات على وجود غاز."},{title:"اخرج وحذّر الآخرين",detail:"أوقف العمل، واخرج إلى الهواء الطلق، وحذّر الآخرين. إذا كان الغاز قابلًا للاشتعال، فلا تستخدم أي مفتاح كهربائي أو لهب أو هاتف داخل المكان. لا تُغلق الصمام إلا إذا كان قريبًا، ويمكن الوصول إليه دون دخول منطقة الغاز، وكنت مدرَّبًا على ذلك؛ وإلا فاخرج.",critical:!0},{title:"اتصل من الخارج",detail:"اتصل من الهواء الطلق بالرقم 115 لتسرّب الغاز، وبالرقم 122 لأي شخص مريض. أخبرهم بالغاز أو المادة المحتملة وبمكان الأشخاص.",critical:!0},{title:"لا تعد إلى الداخل للإنقاذ",detail:"إذا سقط شخص في منطقة الغاز، فلا تدخل دون جهاز التنفس المستقل (SCBA) وخطة وتدريب: المنقذ غير المدرَّب يصبح الضحية التالية. أطلق الإنذار، واتصل بالرقم 115، وأبعد الناس عن المكان.",critical:!0},{title:"لا تعد إلا بعد الإذن",detail:"لا يعود أحد إلى الداخل حتى يُفحص الهواء ويأذن مسؤول السلامة أو فرق 115.",critical:!0}],warnings:["لا تدخل أبدًا منطقة الغاز لإنقاذ عامل سقط دون جهاز تنفس وتدريب: المنقذ غير المدرَّب يصبح الضحية التالية؛ أطلق الإنذار واتصل بالرقم 115.","لا تشغّل أبدًا محرك بنزين أو ديزل في مكان مغلق دون تهوية مصمَّمة لذلك: CO يتراكم دون أي علامة.","لا تستخدم قناع المرشّح للبقاء في منطقة الغاز: فهو لا يحمي من CO ولا من نقص الأكسجين."],tips:["اعرف أماكن أجهزة كشف الغاز وأجهزة الإنذار والمخارج في مكان عملك.","أبلغ فورًا إذا توقفت مروحة التهوية أو الشفط الموضعي، أو ضعفت، أو أصدرت صوتًا غير معتاد.","إذا أُصيب عدة عمال بالصداع في المكان نفسه وفي الوقت نفسه، فاشتبه بوجود غاز وأخرجهم جميعًا.","للمسؤولين: وفّروا صحائف بيانات السلامة (SDS) لكل المواد الكيميائية، ودرّبوا العمال عليها."],activity:{prompt:"في ورشة تعمل فيها رافعة شوكية بالديزل، يُطلق جهاز كشف CO إنذارًا، ويقول عاملان إنهما يشعران بصداع. ماذا تفعل؟",options:[{text:"أُسكت الإنذار وأفتح نافذة",correct:!1,feedback:"نافذة واحدة لا تكفي، والأعراض لدى العمال تدل على أن CO بلغ مستوى خطِرًا."},{text:"أُخرج الجميع إلى الهواء الطلق، وأتصل بالرقم 122 لمن ظهرت عليهم الأعراض، ولا يعود أحد حتى يُفحص الهواء",correct:!0,feedback:"صحيح: الهواء الطلق أول علاج لـ CO، والأعراض تحتاج إلى طبيب، والعودة لا تكون إلا بعد الفحص."},{text:"أعطيهما مسكّنًا ويستمر العمل",correct:!1,feedback:"المسكّن لا يُخرج CO من الجسم، ويبقى العمال في الغاز وقد يفقدون الوعي."},{text:"أوزّع أقنعة بمرشّحات ويستمر العمل",correct:!1,feedback:"أقنعة المرشّحات لا تحمي من CO؛ وحده الخروج إلى الهواء الطلق يحمي."}]},caseStudy:[{prompt:"في أثناء الوردية ترى عاملًا ساقطًا داخل حفرة تتجمع فيها أبخرة كيميائية. ويركض عامل آخر نحو الحفرة ليُخرجه. ماذا تفعل؟",options:[{text:"أدخل معه لنُخرج العامل بسرعة أكبر",correct:!1,feedback:"سيصبح الضحايا ثلاثة بدل واحد؛ فالأبخرة التي أسقطت الأول ستُسقطكما."},{text:"أمنعه من الدخول، وأُطلق الإنذار، وأتصل بالرقمين 115 و122",correct:!0,feedback:"صحيح: منع المنقذ غير المدرَّب يحمي حياته، وفريق 115 يدخل بجهاز التنفس."},{text:"أضع قماشًا مبللًا على فمي وأنزل إلى الحفرة",correct:!1,feedback:"القماش المبلل لا يحمي من الأبخرة السامة ولا من نقص الأكسجين."},{text:"أنتظر لأرى هل يستعيد العامل وعيه وحده",correct:!1,feedback:"كل دقيقة في الغاز مهمة؛ يجب إبلاغ فرق الإنقاذ فورًا."}]},{prompt:"فريق 115 في الطريق. ماذا تفعل حتى يصل؟",options:[{text:"أُبعد الناس عن منطقة الغاز، وأُخلي الطريق للفريق، وأُجهّز المعلومات: مكان العامل، والمادة، وصحيفة SDS",correct:!0,feedback:"صحيح: هذه المعلومات تمكّن الفريق من الدخول بسرعة وبالحماية الصحيحة."},{text:"أصبّ الماء في الحفرة ليزول الغاز",correct:!1,feedback:"الماء لا يزيل كل الغازات، وقد ينشر المادة أو يعرّض العامل الساقط لخطر الغرق."},{text:"أشغّل مروحة كهربائية قرب الحفرة لطرد الغاز",correct:!1,feedback:"إذا كان الغاز قابلًا للاشتعال فقد تسبب مروحة غير مناسبة انفجارًا، وقد تدفع الغاز نحو الآخرين."},{text:"أرسل جميع العمال إلى بيوتهم ليهدأ المكان",correct:!1,feedback:"يجب عدّ العمال وتقديم المعلومات للفريق عند وصوله؛ وتفرّقهم يصعّب عمل الفريق."}]}],realCase:"في الشتاء، كانت أبواب ورشة مغلقة، وكان ضاغط هواء يعمل بمحرك بنزين داخلها. أُصيب عدة عمال بالصداع والدوار، وفقد أحدهم وعيه. تعرّف زميل على أعراض CO، فأخرج الجميع إلى الهواء الطلق، واتصل بالرقم 122، ولم يسمح لأحد بالعودة لإحضار الأدوات. وفحص الطاقم الطبي جميع العمال. بعد ذلك نُقل المحرك إلى خارج المبنى، ورُكّبت أجهزة كشف CO، وفُحصت التهوية."},{id:12,code:"EVAC-112",icon:"Megaphone",accent:"#dc2626",title:"الإخلاء الطارئ (Evacuation)",subtitle:"Emergency Assembly Points",summary:"خطة الخروج في أثناء الحريق أو الكارثة",blocks:[{body:"معرفة طريق الخروج قد تصنع الفرق بين الحياة والموت."},{heading:"1. قواعد الإخلاء",body:"عندما يدقّ جرس الإنذار:",points:["امشِ بهدوء وبسرعة، ولا تركض، ولا تستخدم المصعد.","أغلق الأبواب خلفك كي لا تنتشر النار والدخان، لكن لا تقفلها بالمفتاح.","توجّه إلى نقطة التجمع (Assembly Point) ليُجرى عدّ الموظفين.","لا تعد إلى الداخل بأي حال من الأحوال حتى يسمح لك مسؤول السلامة أو فرق الدفاع المدني (115)."]},{heading:"2. الأدوار في خطة الإخلاء",body:"يحتاج كل مصنع إلى خطة طوارئ مكتوبة يعرفها الجميع:",points:["مسؤولو الإخلاء (Warden): يُرشدون الناس إلى الخارج، ويتفقّدون مناطقهم إذا كان ذلك آمنًا، ويُبلغون المسؤول العام.","المسؤول العام: يستلم نتيجة العدّ ويُطلع فريق 115.","الجميع: يعرفون مخرجين وصوت الإنذار ونقطة التجمع.","تشمل الخطة الزوار وعمال المقاولين والزملاء من ذوي الاحتياجات الخاصة. اعمل وفق متطلبات الدفاع المدني والجهة المختصة."]}],media:[{kind:"video",src:"media/videos/evacuation_drill.mp4",title:"تمرين الإخلاء",description:"التدريب على الإخلاء"}],quiz:[{question:"عندما يدقّ جرس الإنذار، ماذا تفعل؟",options:[{text:"جمع أغراضي ثم الخروج",correct:!1},{text:"التوجّه بهدوء نحو المخرج",correct:!0},{text:"الاختباء تحت الطاولة حتى يتوقف الإنذار",correct:!1},{text:"الصراخ",correct:!1}],explanation:"الخروج بهدوء وبسرعة هو أفضل طريقة لحماية الأرواح."},{question:"ماذا تفعل بالأبواب في أثناء خروجك عند الإخلاء؟",options:[{text:"أقفلها كي لا يعود أحد إلى الداخل",correct:!1},{text:"أتركها مفتوحة تمامًا ليخرج الدخان",correct:!1},{text:"أغلقها خلفي، لكن لا أقفلها بالمفتاح",correct:!0},{text:"أُبقيها مفتوحة بشيء ما للفرق التي تصل لاحقًا",correct:!1}],explanation:"أغلق الأبواب خلفك كي لا تنتشر النار والدخان، لكن لا تقفلها بالمفتاح."},{question:"أنت في نقطة التجمع. متى يمكنك العودة إلى الداخل؟",options:[{text:"بمجرد أن يتوقف جرس الإنذار في المبنى",correct:!1},{text:"عندما يسمح مسؤول السلامة أو فرق الدفاع المدني (115)",correct:!0},{text:"عندما لا يخرج دخان من النوافذ",correct:!1},{text:"بعد 10 دقائق إذا لم تظهر أي نار",correct:!1}],explanation:"لا تعد إلى الداخل بأي حال من الأحوال حتى يسمح لك مسؤول السلامة أو فرق الدفاع المدني (115)؛ وفي نقطة التجمع يُجرى عدّ الموظفين أيضًا."},{question:"عند نقطة التجمع تلاحظ أن زميلًا مفقود. ماذا تفعل؟",options:[{text:"أُخبر فورًا مسؤول الإخلاء أو فريق 115 بآخر مكان رأيته فيه",correct:!0},{text:"أعود بسرعة إلى الداخل لأبحث عنه في مكان عمله",correct:!1},{text:"أنتظر حتى نهاية اليوم لأرى هل يظهر من تلقاء نفسه",correct:!1},{text:"أتصل بعائلته لأسأل هل عاد إلى البيت قبل أن يدقّ الإنذار",correct:!1}],explanation:"تستطيع فرق 115 بمعدات الحماية البحث بأمان إذا عرفت المكان؛ أما عودتك أو الانتظار فيضيّعان الوقت والأرواح."},{question:"ترى منصّات موضوعة أمام باب خروج. ما التصرف الصحيح؟",options:[{text:"أتركها، لأن هناك مخرجًا آخر في آخر القاعة",correct:!1},{text:"أُزيلها أو أُبلغ فورًا، لأن المخارج يجب أن تبقى خالية",correct:!0},{text:"أقفل الباب حتى لا يستخدم أحد هذا المخرج خطأً",correct:!1},{text:"أضع لافتة على المنصّات تطلب من الناس تخطّيها",correct:!1}],explanation:"في الحريق قد يسدّ الدخان المخرج الآخر؛ لذا يجب أن يبقى كل مخرج خاليًا وأن يُفتح من الداخل دون مفتاح."},{question:"أيّ مما يأتي خطأ في أثناء الإخلاء؟",options:[{text:"مساعدة زائر لا يعرف طريق الخروج",correct:!1},{text:"استخدام المصعد لأن الدرج مزدحم",correct:!0},{text:"إغلاق الأبواب خلفك دون قفلها",correct:!1},{text:"تسجيل الحضور لدى مسؤول الإخلاء عند نقطة التجمع",correct:!1}],explanation:"قد يتوقف المصعد في الحريق ويحتجز من فيه؛ أما بقية التصرفات فهي جزء من الإخلاء الصحيح."}],steps:[{title:"أطلق الإنذار",detail:"إذا رأيت حريقًا أو خطرًا، فأطلق الإنذار واتصل بالرقم 115 من مكان آمن.",critical:!0},{title:"أوقف العمل بأمان",detail:"أوقف آلتك بأمان فقط إذا كان ذلك يستغرق لحظة وكنت مدرَّبًا عليه. اترك أغراضك واخرج فورًا.",critical:!0},{title:"اخرج من أقرب مخرج آمن",detail:"امشِ بهدوء، ولا تستخدم المصعد، وأغلق الأبواب خلفك. إذا وُجد دخان، فابقَ منخفضًا واستخدم الطريق الآخر.",critical:!0},{title:"ساعد الآخرين",detail:"ساعد الزوار والزملاء الذين يحتاجون إلى مساعدة كما تنص الخطة. ويتفقّد مسؤولو الإخلاء (Warden) مناطقهم إذا كان ذلك آمنًا."},{title:"سجّل حضورك عند نقطة التجمع",detail:"أعطِ اسمك لمسؤول الإخلاء. إذا كان أحد مفقودًا أو عالقًا في الداخل، فقل أين كان؛ ولا تعد بنفسك للبحث عنه.",critical:!0},{title:"انتظر الإذن",detail:"ابقَ عند نقطة التجمع بعيدًا عن المبنى وعن طرق مركبات الطوارئ، حتى يأذن مسؤول السلامة أو فرق 115.",critical:!0}],warnings:["لا تعد أبدًا إلى الداخل لأخذ أغراضك أو للبحث عن شخص مفقود: أخبر مسؤول الإخلاء أو فريق 115 بالمكان الذي قد يكون فيه.","لا تُغلق أبدًا طرق الخروج وأبوابه، ولا تقفلها، ولا تخزّن فيها شيئًا: يجب أن يُفتح باب الخروج من الداخل دون مفتاح."],tips:["اعرف طريقين للخروج من مكان عملك.","شارك بجدية في تدريبات الإخلاء؛ فهي تكشف المخارج المسدودة والأشخاص المفقودين.","للمسؤولين: احتفظوا بقائمة محدَّثة بكل الموجودين في الموقع، بمن فيهم الزوار وعمال المقاولين.","خطّط مسبقًا لمساعدة الزملاء الذين لا يستطيعون استخدام الدرج."],activity:{prompt:"يدقّ إنذار الحريق وأنت في منتصف طلبية عاجلة. يقول مسؤولك: «غالبًا هو تدريب، أنهِ العمل أولًا.» ماذا تفعل؟",options:[{text:"أُنهي الطلبية، لأنه غالبًا تدريب",correct:!1,feedback:"تعامل مع كل إنذار على أنه حقيقي؛ ففي أثناء انتظارك قد يسدّ الدخان طرق الخروج."},{text:"أوقف الآلة بأمان إن استغرق ذلك لحظة، ثم أخرج من أقرب مخرج إلى نقطة التجمع",correct:!0,feedback:"صحيح: الإنذار أمر بالخروج للجميع؛ ويمكن إكمال العمل لاحقًا."},{text:"أذهب إلى المكتب لأعرف هل هو حقيقي",correct:!1,feedback:"الذهاب إلى المكتب يضيّع الوقت، وقد يقودك نحو الحريق."},{text:"أبقى عند آلتي حتى يخبرني أحد",correct:!1,feedback:"الإنذار نفسه هو الأمر؛ والانتظار قد يجعل النار أو الدخان يقطع طريقك."}]},caseStudy:[{prompt:"عند نقطة التجمع، يلاحظ مسؤول الإخلاء أن عاملًا من مخزن الدهانات مفقود. يقول زميل إنه ربما في دورة المياه. ماذا تفعل؟",options:[{text:"أعود مسرعًا إلى الداخل لأتفقّد دورة المياه",correct:!1,feedback:"العودة تعرّض حياتك للخطر، وقد تجعل فريق 115 يبحث عن شخصين بدل واحد."},{text:"أُخبر فورًا مسؤول الإخلاء وفريق 115 بالمكان المحتمل لوجوده",correct:!0,feedback:"صحيح: تستطيع فرق 115 بمعدات الحماية الوصول إلى المكان بسرعة إذا عرفت أين تبحث."},{text:"أتصل بهاتفه وأنتظر دون أن أخبر أحدًا",correct:!1,feedback:"قد لا يرد؛ فيضيع الوقت ولا يعرف الفريق أن أحدًا في الداخل."},{text:"أفترض أنه خرج من مخرج آخر وأذهب إلى البيت",correct:!1,feedback:"الافتراض ليس يقينًا؛ يجب الإبلاغ فورًا عن أي شخص مفقود."}]},{prompt:"وصل فريق 115. الحريق في مخزن الدهانات. يريد بعض العمال العودة لإخراج سياراتهم من الساحة المجاورة للمبنى. ماذا تفعل؟",options:[{text:"أسمح لهم بإخراج سياراتهم بسرعة",correct:!1,feedback:"سيقتربون من الحريق، وقد يسدّون طريق مركبات الطوارئ."},{text:"أُبقي الجميع عند نقطة التجمع بعيدًا عن الحريق وعن طرق الفريق، وأتّبع تعليمات الفريق",correct:!0,feedback:"صحيح: يمكن إخراج السيارات لاحقًا؛ فالأرواح وعمل الفريق أولًا."},{text:"أعود إلى الداخل لإحضار سجل الحضور",correct:!1,feedback:"لا تعد إلى الداخل أبدًا؛ يُجرى العدّ بقائمة خارجية أو بالأسماء."},{text:"أنقل نقطة التجمع أقرب لنرى الحريق أفضل",correct:!1,feedback:"الاقتراب من الحريق يزيد خطر الدخان وانفجار مواد الدهان."}]}],realCase:"عندما دقّ إنذار الحريق في مصنع، خرج معظم العمال فورًا، لكن مجموعة في قسم التعبئة واصلت العمل لأنها ظنّت الإنذار كاذبًا. وكان أحد المخارج مسدودًا بالمنصّات، فاضطروا إلى العودة عبر ممر مليء بالدخان للوصول إلى المخرج الآخر. وعند نقطة التجمع كان أحد العمال مفقودًا؛ فأخبر مسؤول الإخلاء فريق 115 بمكان عمله، فوجده الفريق في أحد المخازن. بعد ذلك أخلى المصنع كل طرق الخروج، وأجرى تدريبات منتظمة، وجعل مسؤولي الإخلاء مسؤولين عن تفقّد كل قسم."},{id:13,code:"WELD-113",icon:"Sparkles",accent:"#2563eb",title:"سلامة اللحام",subtitle:"Welding & Cutting Hazards",summary:"الحماية من إشعاع اللحام وحرارته ودخانه",blocks:[{body:"ينطوي اللحام على خطر الأشعة فوق البنفسجية (UV)، والحروق البالغة، والغازات والأدخنة السامة."},{heading:"1. حماية العينين والجلد",body:"متطلبات عمال اللحام:",points:["خوذة اللحام (Welding Helmet) بمرشّح مناسب: لحماية العينين من الأشعة فوق البنفسجية ومن الضوء الشديد لقوس اللحام (Arc).","قفازات جلدية طويلة: للحماية من الحرارة والشرر.","مريلة جلدية (Apron): لحماية الجسم."]},{heading:"2. خطر الحريق (Hot Work)",body:"قبل البدء احصل على تصريح العمل الساخن (Hot Work Permit)، ثم:",points:["أخلِ محيط مكان العمل من المواد القابلة للاشتعال (NFPA 51B: ضمن مسافة 11 مترًا / 35 قدمًا)، أو غطّها بستائر واقية.","جهّز مطفأة مناسبة بالقرب منك.","مراقب الحريق (Fire Watch): يبقى في المكان في أثناء العمل ولمدة ساعة واحدة على الأقل بعد انتهائه؛ ثم يُراقَب المكان مدة تصل إلى 3 ساعات إضافية، بحسب قرار المسؤول عن التصريح (NFPA 51B)."]},{heading:"3. الأدخنة والغازات والأسطوانات",body:"يُنتج اللحام أدخنة ويستخدم غازات تحتاج إلى ضبط:",points:["قد تضر أدخنة المعادن والطلاءات بالرئتين؛ استخدم الشفط الموضعي أو تهوية جيدة.","في المكان المحصور قد تحلّ غازات اللحام الواقية مثل الأرغون محل الأكسجين؛ طبّق قواعد الأماكن المحصورة.","تُوضع أسطوانات الغاز قائمة، وتُثبّت حتى لا تسقط، وتُبعد عن الحرارة؛ وتُغلق صماماتها عند توقف العمل.","تُسحب الكابلات والخراطيم التالفة من الاستخدام ويُبلَّغ عنها."]}],media:[{kind:"image",src:"media/images/welding_safety.png",title:"اللحام",description:"الارتداء الصحيح لمعدات الوقاية"}],quiz:[{question:"لماذا يبقى مراقب الحريق في المكان ساعة واحدة على الأقل بعد اللحام؟",options:[{text:"لتنظيف بقايا قطع الحديد",correct:!1},{text:"كي لا ينشأ حريق كامن",correct:!0},{text:"لانتظار أن يبرد الحديد الملحوم",correct:!1},{text:"لا حاجة إلى ذلك",correct:!1}],explanation:"كثيرًا ما يسقط الشرر في الشقوق وبين المواد، ويُحدث حريقًا بعد مدة. ووفقًا لـ NFPA 51B (إصدار 2019 وما بعده)، تستمر المراقبة ساعة واحدة على الأقل بعد العمل."},{question:"قبل بدء العمل الساخن (Hot Work)، ماذا يجب أن يُفعل بالمواد القابلة للاشتعال حول مكان العمل؟",options:[{text:"تُترك في مكانها، لأن مراقب الحريق سيكون موجودًا",correct:!1},{text:"تُزال أو تُغطّى بستائر واقية",correct:!0},{text:"تُرشّ بالماء مرة واحدة ثم يبدأ اللحام فورًا",correct:!1},{text:"تُنقل إلى خلف عامل اللحام بعيدًا عن الشرر المباشر",correct:!1}],explanation:"قبل البدء احصل على تصريح العمل الساخن (Hot Work Permit)، وأخلِ محيط مكان العمل من المواد القابلة للاشتعال (NFPA 51B: ضمن مسافة 11 مترًا / 35 قدمًا)، أو غطّها بستائر واقية."},{question:"ما الذي يحمي عيني عامل اللحام من الأشعة فوق البنفسجية والضوء الشديد لقوس اللحام؟",options:[{text:"نظارات السلامة العادية الشفافة، كالتي تُستخدم للغبار",correct:!1},{text:"نظارات شمسية داكنة تحت خوذة الحماية",correct:!1},{text:"خوذة اللحام بمرشّح مناسب",correct:!0},{text:"النظر إلى القوس بضع ثوانٍ فقط",correct:!1}],explanation:"تحمي خوذة اللحام (Welding Helmet) بمرشّح مناسب العينين من الأشعة فوق البنفسجية ومن الضوء الشديد لقوس اللحام؛ أما القفازات الجلدية الطويلة والمريلة الجلدية فتحمي اليدين والجسم."},{question:"يُطلب منك قطع برميل قديم كان فيه وقود. ما القرار الصحيح؟",options:[{text:"لا أقطعه حتى ينظّفه شخص مختص ويتحقق من سلامته",correct:!0},{text:"أغسله بالماء مرة واحدة وأقطعه وهو ما زال مبللًا",correct:!1},{text:"أقطعه في الخارج، لأن الأبخرة هناك لا تتجمع ولا تنفجر",correct:!1},{text:"أقطعه بسرعة حتى لا تصل الحرارة إلى داخله",correct:!1}],explanation:"الأبخرة المتبقية في البرميل قد تنفجر بشرارة واحدة حتى في الخارج؛ ولا يزيل الخطر إلا التنظيف والفحص على يد شخص مختص."},{question:"في أثناء العمل يتصاعد دخان اللحام نحو وجهك. ما أفضل تصرف؟",options:[{text:"أحبس أنفاسي في أثناء لحام كل وصلة",correct:!1},{text:"أستخدم الشفط الموضعي وأُبعد رأسي عن الدخان",correct:!0},{text:"أرفع خوذة اللحام قليلًا ليصلني هواء أكثر",correct:!1},{text:"أرتدي قناع غبار وأستمر في الوضعية نفسها",correct:!1}],explanation:"يحتوي دخان اللحام على جزيئات معدنية وغازات؛ يزيله الشفط الموضعي من مصدره، وإبعاد الرأس يحمي التنفس. أما رفع الخوذة فيعرّض العينين للقوس."},{question:"أيّ مما يأتي خطأ من مراقب الحريق؟",options:[{text:"تجهيز مطفأة مناسبة قرب مكان العمل",correct:!1},{text:"تفقّد الأماكن المخفية مثل الشقوق والطابق السفلي",correct:!1},{text:"مغادرة المكان بمجرد أن يتوقف اللحّام عن العمل",correct:!0},{text:"معرفة طريقة إطلاق الإنذار والاتصال بالرقم 115",correct:!1}],explanation:"تستمر المراقبة بعد العمل أيضًا (ساعة واحدة على الأقل وفق NFPA 51B)، لأن الشرر المخفي قد يُشعل حريقًا بعد مدة."}],steps:[{title:"التصريح وفحص المكان",detail:"احصل على تصريح العمل الساخن (Hot Work Permit)، وأزل المواد القابلة للاشتعال أو غطّها، وسدّ الفتحات في الأرضيات والجدران حتى لا يعبرها الشرر.",critical:!0},{title:"فحص المعدات",detail:"افحص الكابلات والخراطيم والوصلات وأسطوانات الغاز بحثًا عن أي تلف. وتبقى الأسطوانات قائمة ومثبّتة حتى لا تسقط."},{title:"احمِ نفسك والآخرين",detail:"ارتدِ خوذة اللحام بالمرشّح المناسب والقفازات الجلدية والمريلة. وضع ستائر واقية لحماية الأشخاص القريبين من ضوء القوس."},{title:"تحكّم في الأدخنة",detail:"اعمل مع الشفط الموضعي (Local Exhaust) أو تهوية جيدة، وأبعد رأسك عن عمود الدخان المتصاعد.",critical:!0},{title:"مراقب الحريق في أثناء العمل وبعده",detail:"يجهّز مراقب الحريق (Fire Watch) مطفأة مناسبة، ويعرف كيف يُطلق الإنذار ويتصل بالرقم 115، ويبقى في المكان المدة التي يحددها التصريح.",critical:!0}],warnings:["لا تلحم ولا تقطع أبدًا برميلًا أو خزانًا أو أنبوبًا كان فيه مواد قابلة للاشتعال، حتى ينظّفه شخص مختص ويتحقق من سلامته: فقد ينفجر.","لا تنظر أبدًا إلى قوس اللحام دون مرشّح: فضوؤه يحرق العينين ولو لوقت قصير.","لا تلحم داخل مكان محصور ما لم تُطبَّق قواعد الأماكن المحصورة (التصريح وفحص الهواء والمراقب)."],tips:["ارتدِ ملابس نظيفة من القطن أو الصوف خالية من الزيوت؛ فالأقمشة الصناعية قد تذوب على الجلد.","أغلق صمامات أسطوانات الغاز عند توقف العمل.","نبّه من حولك قبل إشعال القوس حتى لا ينظروا إليه.","يتفقّد مراقب الحريق الأماكن المخفية أيضًا: خلف الجدران وتحت الأرضيات وداخل القنوات."],activity:{prompt:"ستلحم قطعة في الورشة. توجد صناديق كرتون وعلبة مذيب قرب مكان العمل. التصريح موقَّع، لكن لم يُعيَّن أحد مراقبًا للحريق. ماذا تفعل؟",options:[{text:"أبدأ اللحام وأراقب الصناديق بنفسي",correct:!1,feedback:"بخوذة اللحام لا يمكنك رؤية ما حولك؛ فمراقب الحريق شخص آخر."},{text:"أُزيل المواد القابلة للاشتعال أو أغطّيها، ولا أبدأ حتى يحضر مراقب حريق معه مطفأة",correct:!0,feedback:"صحيح: التصريح ليس مجرد ورقة؛ فإزالة المواد القابلة للاشتعال ووجود مراقب الحريق شرطان للعمل الساخن."},{text:"ألحم بسرعة حتى لا يجد الشرر وقتًا لإشعال حريق",correct:!1,feedback:"يصل الشرر في لحظة إلى الكرتون وأبخرة المذيب؛ والسرعة لا تقلّل الخطر."},{text:"أرشّ الصناديق بالماء مرة واحدة وأبدأ",correct:!1,feedback:"يجف الكرتون المبلل بسرعة، وعلبة المذيب ما زالت هناك؛ يجب إزالة المواد أو تغطيتها."}]},caseStudy:[{prompt:"ينهي لحّام عمله قرب جدار خشبي في نهاية الوردية. يريد المسؤول أن يذهب الجميع إلى بيوتهم الآن. أنت مراقب الحريق. ماذا تفعل؟",options:[{text:"أغادر مع الجميع لأن اللحام توقف",correct:!1,feedback:"قد يبقى الشرر متّقدًا في الشقوق ويُشعل حريقًا بعد مدة؛ لذلك تستمر المراقبة بعد العمل."},{text:"أبقى وأراقب المكان كما يحدد التصريح، وأتفقّد الأماكن المخفية",correct:!0,feedback:"صحيح: المراقبة بعد العمل تكشف الحرائق المخفية قبل أن تنتشر."},{text:"أرشّ الجدار بالماء وأغادر",correct:!1,feedback:"الماء لا يصل إلى كل الشقوق وما خلف الجدار، ولن يبقى أحد ليرى الحريق."},{text:"أقفل الورشة حتى لا يدخلها أحد",correct:!1,feedback:"القفل لا يوقف الحريق؛ فالحريق المخفي سيكبر دون أن يعلم أحد."}]},{prompt:"بعد مدة ترى دخانًا يخرج من شق خلف الجدار. ماذا تفعل؟",options:[{text:"أُطلق الإنذار وأتصل بالرقم 115؛ ولا أستخدم المطفأة إلا إذا كان الحريق صغيرًا والمخرج خلفي وكنت مدرَّبًا",correct:!0,feedback:"صحيح: الإنذار و115 أولًا، ثم فحص «هل أستطيع أم لا» قبل استخدام المطفأة؛ وإذا لم ينطفئ الحريق فورًا فاخرج."},{text:"أفتح لوح الجدار بيديّ العاريتين لأرى الحريق",correct:!1,feedback:"الفتح باليدين العاريتين قد يحرقك، ويمدّ النار بالهواء فتكبر فجأة."},{text:"أنتظر لأرى هل ينطفئ وحده",correct:!1,feedback:"الدخان علامة على حريق مخفي قد ينتشر بسرعة؛ والانتظار يضيّع وقتًا ثمينًا."},{text:"أذهب إلى البيت وأُبلغ في الصباح",correct:!1,feedback:"حريق دون مراقبة قد يحرق المبنى كله ليلًا؛ يجب الإبلاغ فورًا."}]}],realCase:"أصلح لحّام في نهاية يوم العمل إطارًا فولاذيًا قرب منطقة تخزين. لم تُزَل المواد القابلة للاشتعال القريبة، ولم يبقَ مراقب حريق في المكان بعد العمل. وفي وقت متأخر من الليل اشتعل حريق من شرر سقط في مواد التغليف، وانتشر في منطقة التخزين قبل أن يُكتشف. لم يكن أحد في الداخل، لكن البضائع وجزءًا من المبنى احترقت. بعد ذلك جعل المصنع تصريح العمل الساخن، وإزالة المواد القابلة للاشتعال أو تغطيتها، ووجود مراقب الحريق في أثناء كل عمل وبعده، قاعدة ثابتة."},{id:14,code:"FORK-114",icon:"Forklift",accent:"#475569",title:"معدات النقل",subtitle:"Forklift & Vehicle Safety",summary:"سلامة الرافعة الشوكية والقيادة داخل المصنع",blocks:[{body:"الرافعة الشوكية آلة ثقيلة، وتنطوي على خطر السحق والانقلاب إذا لم تُقَد بشكل صحيح."},{heading:"1. قواعد القيادة",body:"لسائقي الرافعات الشوكية:",points:["لا يقود الرافعة الشوكية إلا الأشخاص المدرَّبون والمرخَّصون (OSHA 1910.178).","لا تحمل أبدًا أي شخص على شوكتي الرافعة (Forks) أو بجانبك.","لا تحمّل الرافعة أكثر من سعتها كي لا تنقلب، واربط حزام الأمان.","خفّف السرعة عند كل زاوية أو باب، واستخدم البوق (Horn)."]},{heading:"2. سلامة المشاة",body:"إذا كنت تمشي بالقرب من رافعة شوكية:",points:["احرص على التواصل البصري مع السائق (Eye Contact) وحافظ على مسافة آمنة.","امشِ في الممرات المخصّصة للمشاة والمحدّدة بعلامات."]},{heading:"3. الحمل والتوازن",body:"تحدث معظم حالات الانقلاب بسبب حمل خاطئ أو قيادة خاطئة:",points:["اقرأ لوحة السعة: الحمل الآمن يتغير بحسب الوزن وبُعد مركز الحمل عن سارية الرفع.","أدخل الشوكتين تحت الحمل بالكامل، وأمِل الحمل قليلًا إلى الخلف قبل التحرك.","على المنحدر مع حمل، اجعل الحمل باتجاه أعلى المنحدر، ولا تستدر على المنحدر.","لا تتوقف أبدًا أمام المخارج أو معدات الإطفاء أو طرق الطوارئ."]}],media:[{kind:"video",src:"media/videos/forklift_safety.mp4",title:"الرافعة الشوكية",description:"التعرّف على النقاط العمياء (Blind Spots)"}],quiz:[{question:"إذا كان سائق الرافعة الشوكية يحمل حمولة عالية تحجب رؤيته للأمام، فماذا يفعل؟",options:[{text:"يقود بسرعة",correct:!1},{text:"يقود إلى الخلف (Reverse)",correct:!0},{text:"يستخدم البوق ويُغمض عينيه",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"عندما يحجب الحمل رؤية السائق، يجب أن يقود إلى الخلف ليرى طريقه (OSHA 1910.178)."},{question:"يطلب منك زميل أن يركب على شوكتي (Forks) رافعتك الشوكية. ماذا تفعل؟",options:[{text:"أسمح له بالركوب إذا قدتُ ببطء",correct:!1},{text:"أسمح له بالوقوف على الشوكتين والتمسك بالرافعة",correct:!1},{text:"أسمح له بالجلوس بجانبي بدلًا من الشوكتين",correct:!1},{text:"أرفض، فلا يجوز أن يركب أحد على الشوكتين",correct:!0}],explanation:"لا تحمل أبدًا أي شخص على شوكتي الرافعة أو بجانبك؛ فالرافعة الشوكية آلة ثقيلة، وتنطوي على خطر السحق والانقلاب."},{question:"تمشي بالقرب من رافعة شوكية تتحرك. ماذا يجب أن تفعل؟",options:[{text:"أتواصل بصريًا مع السائق وأحافظ على مسافة آمنة",correct:!0},{text:"أمشي قريبًا منها ليراني السائق بشكل أفضل",correct:!1},{text:"أعبر من أمامها بسرعة قبل أن تصل إليّ",correct:!1},{text:"ألوّح بيدي وأواصل السير، فعلى السائق أن يتوقف",correct:!1}],explanation:"بالقرب من الرافعة الشوكية، احرص على التواصل البصري مع السائق (Eye Contact)، وحافظ على مسافة آمنة، وامشِ في الممرات المخصّصة للمشاة؛ فقد لا يراك السائق في النقاط العمياء (Blind Spots)."},{question:"عندما تتحرك الرافعة الشوكية، أين يجب أن تكون الشوكتان؟",options:[{text:"منخفضتين قريبًا من الأرض في أثناء الحركة",correct:!0},{text:"بمستوى العينين ليراهما السائق جيدًا",correct:!1},{text:"مرفوعتين قدر الإمكان لتعبرا فوق العوائق",correct:!1},{text:"على أي ارتفاع ما دام السائق يقود ببطء",correct:!1}],explanation:"انخفاض الشوكتين والحمل يجعل الرافعة أكثر توازنًا ويقلّل احتمال الانقلاب؛ أما الحمل المرفوع في أثناء الحركة فيُفقدها التوازن."},{question:"بدأت الرافعة الشوكية بالانقلاب على جانبها. ماذا يفعل السائق الذي ربط حزامه؟",options:[{text:"يقفز بسرعة من الجهة المنخفضة",correct:!1},{text:"يبقى في المقعد ويتمسّك بقوة ويميل بعكس اتجاه السقوط",correct:!0},{text:"يقفز من الجهة العالية ويركض بعيدًا عن الآلة",correct:!1},{text:"يدير المقود بقوة إلى الجهة الأخرى",correct:!1}],explanation:"تحدث معظم الإصابات البالغة حين يقفز السائق فيعلق تحت الآلة؛ أما الحزام والمقعد فيُبقيانه داخل إطار الحماية."},{question:"كشف الفحص اليومي تسرّبًا في الزيت الهيدروليكي. ما القرار الصحيح؟",options:[{text:"أستخدمها حتى نهاية الوردية ثم أُبلغ",correct:!1},{text:"أُخرجها من الخدمة وأُبلغ لإصلاحها",correct:!0},{text:"أضع رملًا تحتها وأستخدمها كالمعتاد",correct:!1},{text:"أستخدمها للأحمال الخفيفة فقط حتى تُصلح",correct:!1}],explanation:"قد يؤدي تسرّب الزيت الهيدروليكي إلى سقوط الحمل أو تعطّل الرفع، ويجعل الأرض زلقة؛ لا تُستخدم الرافعة المعطّلة حتى تُصلح."}],steps:[{title:"افحص الآلة قبل العمل",detail:"افحص قبل كل وردية المكابح والتوجيه والبوق والأضواء والشوكتين والسلاسل والإطارات والتسرّبات. أبلغ عن الرافعة المعطّلة ولا تستخدمها.",critical:!0},{title:"افحص الحمل",detail:"لا يتجاوز الحمل السعة المبيّنة على لوحة الآلة، ويجب أن يكون ثابتًا ومتمركزًا، وأن تكون الشوكتان تحته بالكامل."},{title:"قُد بأمان",detail:"اربط حزام الأمان، وأبقِ الشوكتين منخفضتين في أثناء الحركة، وخفّف السرعة عند الزوايا، واستخدم البوق عند الأبواب. وإذا حجب الحمل الرؤية، فقُد إلى الخلف.",critical:!0},{title:"انتبه للمشاة",detail:"إذا اقترب أحد المشاة فتوقف حتى يبتعد. ولا يجوز لأحد أن يقف أو يمر تحت الشوكتين المرفوعتين أو الحمل المرفوع.",critical:!0},{title:"أوقف الآلة بأمان",detail:"أنزل الشوكتين إلى الأرض، وضع أذرع التحكم في الوضع المحايد، وشدّ فرامل اليد، وأطفئ المحرك واسحب المفتاح. ولا تتوقف أمام المخارج أو معدات الإطفاء."}],warnings:["لا ترفع أبدًا أي شخص على الشوكتين أو على منصّة: فقد يسقط أو يُسحق.","إذا بدأت الرافعة الشوكية بالانقلاب فلا تقفز منها: ابقَ في المقعد مع حزام الأمان، وتمسّك بقوة، ومِل بجسمك بعكس اتجاه السقوط.","لا ترفع أبدًا حملًا يتجاوز سعة الآلة ولو على ارتفاع منخفض: فقد لا يعمل التوجيه والمكابح كما يجب وتنقلب الآلة."],tips:["للمشاة: لا تستخدموا الهاتف عند عبور مسارات الرافعات الشوكية.","للمسؤولين: افصلوا ممرات المشاة عن مسارات الرافعات بعلامات أو حواجز.","المرايا عند الزوايا العمياء مفيدة، لكنها لا تغني عن تخفيف السرعة واستخدام البوق.","اشحن البطاريات وتزوّد بالوقود في الأماكن المخصّصة لذلك فقط."],activity:{prompt:"سائق مستعجل يريد رفع منصّة أثقل من السعة المبيّنة على لوحة الرافعة، ويقول: «فعلت ذلك من قبل.» أنت مسؤول الوردية. ماذا تفعل؟",options:[{text:"أسمح له هذه المرة إن قاد ببطء",correct:!1,feedback:"القيادة البطيئة لا تجعل الحمولة الزائدة آمنة؛ فقد تنقلب الآلة عند زاوية أو عند التوقف."},{text:"أوقفه؛ يُقسَّم الحمل أو تُستخدم رافعة ذات سعة كافية",correct:!0,feedback:"صحيح: السعة المبيّنة على اللوحة حدّ لكل حمل على هذه الآلة؛ والتجربة السابقة لا تُثبت السلامة."},{text:"أطلب من عاملين الجلوس على مؤخرة الرافعة لزيادة الوزن",correct:!1,feedback:"هذا حمل للأشخاص على الرافعة وقد يقتلهم؛ وإضافة ثقل خلفي ممنوعة أيضًا."},{text:"أسمح له برفعه قليلًا فقط عن الأرض",correct:!1,feedback:"الحمولة الزائدة ممنوعة على أي ارتفاع؛ فقد لا يعمل التوجيه والمكابح كما يجب، وتنقلب الآلة عند الدوران."}]},caseStudy:[{prompt:"في فحص الصباح يكتشف سائق أن بوق الرافعة لا يعمل وأن المكابح أصبحت رخوة. والإنتاج يحتاج إلى الرافعة الآن. ماذا تفعل؟",options:[{text:"أستخدمها اليوم بحذر وأُبلغ في نهاية الوردية",correct:!1,feedback:"المكابح الرخوة قد لا تعمل عند الحاجة؛ والحذر لا يحلّ محل المكابح."},{text:"أُخرجها من الخدمة، وأضع عليها بطاقة «لا تستخدم»، وأُبلغ لإصلاحها",correct:!0,feedback:"صحيح: لا تُستخدم الرافعة المعطّلة حتى تُصلح؛ والبطاقة تمنع الآخرين من استخدامها."},{text:"أستخدمها فقط في الأماكن الخالية من الناس",correct:!1,feedback:"دون مكابح قد تصطدم الآلة بالرفوف أو الأعمدة ويسقط الحمل؛ فالخطر لا يقتصر على المشاة."},{text:"أطلب من سائق آخر أكثر خبرة أن يستخدمها",correct:!1,feedback:"الخبرة لا تُصلح المكابح المعطّلة؛ فالآلة ما زالت غير آمنة."}]},{prompt:"وصلت رافعة بديلة. يقودها السائق بحمل عالٍ في ممر مزدحم ولا يرى ما أمامه، والعمال يمشون قريبًا منه. ماذا يجب أن يفعل؟",options:[{text:"يتقدّم بسرعة ليخرج من الممر بسرعة",correct:!1,feedback:"القيادة دون رؤية وبسرعة قرب الناس ترفع كثيرًا احتمال الدهس."},{text:"يقود إلى الخلف ببطء، وينظر في اتجاه سيره، ويستخدم البوق، ويتوقف إذا اقترب أحد",correct:!0,feedback:"صحيح: القيادة إلى الخلف تعيد الرؤية، والتوقف عند اقتراب الناس يحمي المشاة."},{text:"يرفع الحمل أعلى ليرى من تحته",correct:!1,feedback:"الحمل المرفوع في أثناء الحركة يُضعف التوازن، فقد تنقلب الآلة أو يسقط الحمل."},{text:"يطلب من عامل الوقوف على الشوكتين ليرشده",correct:!1,feedback:"لا يركب أحد على الشوكتين؛ فقد يسقط ويُسحق."}]}],realCase:"في أحد المخازن، دار سائق رافعة شوكية حول زاوية بسرعة وهو يحمل حملًا مرفوعًا. فانقلبت الرافعة. ولم يكن السائق قد ربط حزام الأمان فقفز منها، فعلق تحتها وأُصيب إصابة بالغة. وكشف التحقيق أن الحمل كان مرفوعًا أكثر من اللازم، وأن السرعة عند الزاوية كانت عالية، وأن الحزام لم يكن مربوطًا. بعد ذلك جعل المصنع ربط الحزام إلزاميًا، وخفّض السرعة عند الزوايا، واشترط نقل الأحمال منخفضة، وفصل ممرات المشاة عن مسارات الرافعات."},{id:15,code:"SIGN-115",icon:"AlertTriangle",accent:"#ea580c",title:"علامات السلامة",subtitle:"Safety Signs & Symbols",summary:"التعرّف على ألوان السلامة ورموزها (ISO 7010)",blocks:[{body:"تنبّهنا علامات السلامة إلى المخاطر بلغة عالمية."},{heading:"1. دلالة الألوان (ISO 7010)",body:"يحمل كل لون رسالة خاصة:",points:["الأحمر: المنع أو معدات مكافحة الحريق (مثال: التدخين ممنوع).","الأصفر: التحذير والخطر (مثال: خطر الكهرباء).","الأزرق: الإلزام (مثال: يجب ارتداء خوذة الحماية).","الأخضر: السلامة والإخلاء (مثال: باب الخروج)."]},{heading:"2. الأشكال ودلالاتها (ISO 7010)",body:"يحدد الشكل واللون والرمز معًا معنى العلامة:",points:["دائرة بإطار أحمر وخط مائل: منع (لا تفعل هذا).","مثلث أصفر بإطار أسود: تحذير من خطر.","دائرة زرقاء: إجراء إلزامي (يجب أن تفعل هذا).","مربع أو مستطيل أخضر: حالة آمنة — المخارج والإسعافات الأولية ونقطة التجمع.","مربع أو مستطيل أحمر: معدات مكافحة الحريق — مطفأة الحريق وبكرة خرطوم الحريق ونقطة نداء إنذار الحريق."]},{heading:"3. العلامات في مكان العمل: واجبات العمال والمسؤولين",body:"لا تحمي العلامات إلا إذا رُئيت وفُهمت:",points:["اقرأ العلامات على باب كل قسم قبل أن تبدأ العمل.","لا تغطِّ العلامات ولا تنقلها ولا تنزعها؛ وأبلغ المشرف عن العلامات المكسورة أو الباهتة أو المفقودة.","يجب أن تُرى علامات الخروج ومعدات مكافحة الحريق من مكان العمل؛ ولا يجوز أن تحجبها البضائع المكدّسة.","العلامة لا تزيل الخطر: إنها تذكّرك بوسيلة الحماية المطلوبة (معدات الوقاية أو الإجراء أو تصريح العمل).","تحمل عبوات المواد الكيميائية رموز الخطر وفق GHS (معيّن بإطار أحمر)؛ اقرأ الملصق وصحيفة بيانات السلامة (SDS).","أما العلامات المطلوبة في مكان العمل فاتبع فيها متطلبات الدفاع المدني والجهة المختصة."]}],media:[{kind:"image",src:"media/images/safety_signs.png",title:"علامات السلامة",description:"الرموز القياسية"}],quiz:[{question:"ما معنى العلامة ذات اللون الأصفر؟",options:[{text:"منع القيام بعمل ما",correct:!1},{text:"التحذير والخطر",correct:!0},{text:"مكان آمن وطريق للهروب",correct:!1},{text:"استخدام الماء",correct:!1}],explanation:"اللون الأصفر يعني دائمًا «انتبه» أو «يوجد خطر»."},{question:"علامة زرقاء عند باب الورشة تُظهر خوذة حماية. ماذا تعني؟",options:[{text:"خوذة الحماية ممنوعة هنا",correct:!1},{text:"تحذير: قد تسقط أجسام هنا",correct:!1},{text:"يجب ارتداء خوذة الحماية هنا",correct:!0},{text:"تُحفظ خوذ الحماية خلف هذا الباب",correct:!1}],explanation:"اللون الأزرق يعني الإلزام، مثل: يجب ارتداء خوذة الحماية؛ أما الأحمر فللمنع أو معدات مكافحة الحريق، والأصفر للتحذير، والأخضر للسلامة والإخلاء."},{question:"أي لون يُستخدم للسلامة والإخلاء، مثل باب الخروج؟",options:[{text:"الأحمر",correct:!1},{text:"الأصفر",correct:!1},{text:"الأزرق",correct:!1},{text:"الأخضر",correct:!0}],explanation:"يدلّ اللون الأخضر على السلامة والإخلاء، مثل باب الخروج؛ أما الأحمر فللمنع أو معدات مكافحة الحريق."},{question:"على باب دائرة بإطار أحمر وخط مائل فوق رمز لهب. ماذا تعني؟",options:[{text:"اللهب المكشوف ممنوع هنا",correct:!0},{text:"مطفأة الحريق خلف هذا الباب",correct:!1},{text:"تحذير: أسطح ساخنة في الداخل",correct:!1},{text:"يجب ارتداء ملابس مقاومة للهب هنا",correct:!1}],explanation:"الدائرة ذات الإطار الأحمر والخط المائل تعني المنع دائمًا؛ أما التحذير فمثلث أصفر، والإلزام دائرة زرقاء، ومعدات الحريق مربع أحمر."},{question:"أي علامة تدل على مكان مطفأة الحريق؟",options:[{text:"مربع أحمر عليه رمز المطفأة",correct:!0},{text:"مربع أخضر عليه سهم وشخص يركض",correct:!1},{text:"دائرة زرقاء عليها رمز المطفأة",correct:!1},{text:"مثلث أصفر عليه رمز لهب",correct:!1}],explanation:"تُبيَّن معدات مكافحة الحريق بمربع أو مستطيل أحمر؛ والأخضر لطريق الخروج، والأزرق للإلزام، والمثلث الأصفر للتحذير."},{question:"علّق زميلك سترته فوق علامة الخروج الخضراء. ماذا تفعل؟",options:[{text:"أطلب منه إزالتها فورًا لتبقى العلامة ظاهرة",correct:!0},{text:"أتركها لأن الجميع يعرفون مكان المخرج",correct:!1},{text:"أنقل العلامة إلى مكان لا يعلّق عليه أحد شيئًا",correct:!1},{text:"أتركها حتى تكتشفها جولة التفتيش القادمة",correct:!1}],explanation:"يجب أن تبقى علامة الخروج ظاهرة دائمًا؛ ففي الدخان أو الظلام يعتمد عليها العمال الجدد والزوار. ونقل العلامة ليس من عمل العامل."}],steps:[{title:"انظر عند الباب",detail:"قبل دخول أي قسم، اقرأ العلامات على بابه: أي معدات وقاية شخصية (PPE) إلزامية، وما الممنوع، وما المخاطر الموجودة في الداخل.",critical:!0},{title:"اقرأ الشكل واللون والرمز معًا",detail:"الشكل يحدد نوع العلامة (دائرة أو مثلث أو مربع)، واللون يؤكد الرسالة، والرمز يبيّن موضوعها. والنص المرافق تحت العلامة يضيف تفاصيل."},{title:"نفّذ ما تطلبه العلامة",detail:"العلامة الزرقاء: استخدم معدات الوقاية أو نفّذ الإجراء الإلزامي. علامة المنع: لا تقم بذلك العمل. العلامة الصفراء: انتبه واتبع إجراء الحماية من ذلك الخطر.",critical:!0},{title:"اعرف إلى أين تقود العلامات الخضراء",detail:"في أثناء التدريب التعريفي، امشِ مع العلامات الخضراء على طريق الخروج حتى نقطة التجمع، وتعرّف من العلامات الحمراء على مكان مطفأة الحريق ونقطة نداء إنذار الحريق.",critical:!0},{title:"أبلغ عن العلامات التالفة",detail:"أبلغ مشرفك فورًا عن أي علامة مكسورة أو باهتة أو مفقودة أو تحجبها المواد. ولا تنزع علامة أو تنقلها بنفسك أبدًا."}],warnings:["لا تحجب علامة الخروج أو علامات معدات مكافحة الحريق أبدًا، ولو لوقت قصير: ففي الدخان يعتمد الناس عليها للوصول إلى المخرج والمعدات.","لا تعتمد على اللون وحده، وغياب العلامة لا يعني غياب الخطر: إذا كانت العلامة باهتة أو مفقودة فاسأل قبل أن تبدأ العمل."],tips:["احفظ الأشكال الخمسة؛ فالعلامة تُفهم حتى من دون كلمات.","إذا لم تفهم علامة ما، فاسأل مشرفك قبل أن تبدأ العمل.","للمديرين: افحصوا العلامات في جولات التفتيش المعتادة لمكان العمل وبعد أي تغيير في ترتيب المكان.","اشرح العلامات الجديدة للعمال الجدد في التدريب التعريفي، لا بالكتابة على الجدار وحدها."],activity:{prompt:"أنت عامل جديد. على باب ورشة علامة زرقاء لحماية السمع، وفي الداخل علامة صفراء لخطر الكهرباء على لوحة. يقول المشرف: «ادخل لدقيقة واحدة، لا حاجة إلى حماية السمع». ماذا تفعل؟",options:[{text:"أدخل من دون حماية السمع لأنها دقيقة واحدة فقط",correct:!1,feedback:"العلامة الزرقاء إلزامية في كل مرة تدخل فيها، لا في الأعمال الطويلة فقط؛ فالضجيج العالي قد يضرّ السمع سريعًا."},{text:"أستخدم حماية السمع وأبتعد عن لوحة الكهرباء وأسأل المشرف بأدب عن القاعدة",correct:!0,feedback:"صحيح: العلامة الزرقاء إلزامية والصفراء تطلب الابتعاد عن الخطر؛ والسؤال هو الطريق الصحيح لتوضيح القاعدة."},{text:"أنزع العلامة الزرقاء لأنها تربك الناس",correct:!1,feedback:"العامل لا ينزع العلامات؛ إذا بدت العلامة خاطئة فإنه يبلغ المسؤول ليقرر."},{text:"أفتح باب لوحة الكهرباء لأتأكد من أن الخطر حقيقي",correct:!1,feedback:"العلامة الصفراء تعني أن الخطر موجود؛ ولا يفتح اللوحة إلا كهربائي مختص ومكلَّف."}]},caseStudy:[{prompt:"أنت مشرف الوردية الليلية في مستودع. كدّس سائق رافعة شوكية منصّات أمام علامة الخروج الخضراء وعلامة المطفأة الحمراء في أحد الممرات. ما أول ما تفعله؟",options:[{text:"أُبعد المنصّات فورًا ليظهر المخرج والعلامات، ثم أسجّل ما حدث",correct:!0,feedback:"صحيح: يجب أن يبقى طريق الخروج والعلامات ظاهرة دائمًا؛ والتسجيل يساعد على معالجة السبب."},{text:"أتركها حتى وردية الصباح لأن لا أحد يعمل هناك الآن",correct:!1,feedback:"قد يندلع حريق في أي وقت؛ وعمال الوردية الليلية يحتاجون أيضًا إلى طريق الخروج."},{text:"ألصق ورقة مكتوبًا عليها «مخرج» على المنصّات",correct:!1,feedback:"الورقة لا تحل محل العلامة الصحيحة والطريق المفتوح؛ فطريق الخروج ما زال مسدودًا."},{text:"أنزع العلامة لأن الطريق مسدود على أي حال",correct:!1,feedback:"هذا يضاعف الخطر: الطريق مسدود ولا أحد يعرف مكانه؛ المطلوب فتح الطريق."}]},{prompt:"بعد أسبوع، يدوّي إنذار الحريق في المستودع نفسه وينتشر دخان خفيف تحت السقف. عامل جديد لا يعرف إلى أين يذهب. ماذا تقول له؟",options:[{text:"اتبع علامات الخروج الخضراء وابقَ منخفضًا تحت الدخان واذهب إلى نقطة التجمع",correct:!0,feedback:"صحيح: العلامات الخضراء تدل على طريق الخروج، والهواء الأنظف قريب من الأرض."},{text:"اتبع العلامات الحمراء لأنها تدل على طريق الخروج",correct:!1,feedback:"العلامات الحمراء تدل على المنع أو على معدات مكافحة الحريق، لا على طريق الخروج."},{text:"ابقَ عند آلتك حتى يأتي المشرف ويأخذك",correct:!1,feedback:"الانتظار يضيّع وقتًا ثمينًا؛ على كل شخص أن يخرج فورًا عبر الطريق المعلَّم."},{text:"استخدم مصعد البضائع لأنه أسرع من الدرج",correct:!1,feedback:"لا تُستخدم المصاعد في أثناء الحريق: فقد تتوقف ويُحتجز من فيها."}]}],realCase:"في مصنع للتعبئة والتغليف، كان العمال يكدّسون الكراتين في ممر فحجبوا علامة الخروج عند أحد التقاطعات. وفي أثناء تمرين، انعطف عدد من العمال الجدد في الاتجاه الخطأ ووصلوا إلى مخزن مغلق. سجّل مسؤول السلامة ذلك في تقرير التمرين. فأمر مدير المصنع بإخلاء الممر، وأضاف العلامات إلى قائمة التفتيش المعتادة، وعرّف جميع العمال الجدد بطرق الخروج في التدريب التعريفي. وفي التمرين التالي، اتبع الجميع العلامات الخضراء إلى نقطة التجمع. والدرس: العلامة لا تحمي إلا إذا كانت ظاهرة وكان الناس يعرفون معناها."},{id:16,code:"HOUS-116",icon:"ClipboardCheck",accent:"#4f46e5",title:"النظافة والترتيب (Housekeeping)",subtitle:"Order & Maintenance",summary:"تنظيم مكان العمل لتقليل المخاطر",blocks:[{body:"مكان العمل النظيف مكان آمن. وتقع حوادث كثيرة بسبب الانزلاق أو التعثّر بالأدوات والمواد المبعثرة."},{heading:"1. القواعد العامة",body:"لجميع العمال:",points:["تنظيف الزيت أو الماء المسكوب في أسرع وقت.","جمع النفايات في حاويات خاصة.","إبقاء الممرات والمخارج مفتوحة وخالية من العوائق.","إعادة كل أداة إلى مكانها بعد انتهاء العمل."]},{heading:"2. النظافة والترتيب واجب للسلامة ومنع الحريق",body:"الفوضى والنفايات توفّر الوقود للحريق والعوائق أمام الهروب:",points:["النفايات والخِرق الزيتية والكرتون والغبار وقود: شرارة صغيرة قد تشعل حريقًا ينتشر عبر الفوضى.","الخِرق المبللة بالزيت أو المذيبات قد تسخن ذاتيًا وتشتعل؛ ضعها في حاوية معدنية مغلقة وأفرغها بانتظام.","لا تدع الغبار القابل للاحتراق يتراكم على الأرض والعوارض والآلات؛ فقد يسبب انفجار غبار (انظر درس تصنيف الحرائق).","اترك مساحة خالية حول لوحات الكهرباء والمطافئ ونقاط نداء الإنذار وبكرات الخراطيم ورؤوس المرشات.","تبقى أبواب الحريق مغلقة ولا تُثبَّت مفتوحة بأي شيء.","تُفتح أبواب الخروج من الداخل من دون مفتاح، ولا تُقفل ولا تُسدّ في أثناء العمل."]},{heading:"3. الانسكابات والكابلات والتخزين",body:"قواعد العمل اليومي:",points:["الانسكاب: نبّه الآخرين وضع علامة ثم نظّف؛ وفي المواد الكيميائية اقرأ صحيفة بيانات السلامة أولًا.","إذا لم تستطع التنظيف بأمان (مادة مجهولة أو انسكاب كبير أو أبخرة) فأبعد الناس وأبلغ فورًا.","أبعد الكابلات والخراطيم عن الممرات أو غطِّها؛ ولا تتركها في طريق الناس.","لا تحمّل الرفوف فوق طاقتها، ولا ترفع الأكوام فوق الارتفاع المحدد للموقع.","للمديرين: حدّدوا بوضوح المسؤول عن كل قسم، واجعلوا النظافة جزءًا من التفتيش المعتاد؛ واتبعوا متطلبات الدفاع المدني وجهة الترخيص."]}],media:[{kind:"image",src:"media/images/clean_factory.png",title:"النظافة والترتيب",description:"مثال على مكان عمل نظيف"}],quiz:[{question:"إذا رأيت زيتًا مسكوبًا على الأرض، فماذا تفعل؟",options:[{text:"أتركه كما هو حتى يأتي عامل النظافة في المناوبة التالية",correct:!1},{text:"أنظّفه أو أضع عليه علامة تحذير وأُبلغ عنه",correct:!0},{text:"أقفز فوقه",correct:!1},{text:"لا أهتم به",correct:!1}],explanation:"كل عامل مسؤول عن نظافة مكان عمله وسلامته، كي لا يسقط أحد."},{question:"كيف يجب أن تبقى الممرات والمخارج؟",options:[{text:"مفتوحة وخالية من العوائق",correct:!0},{text:"مكانًا لوضع الصناديق عند امتلاء المخزن",correct:!1},{text:"مغلقة لفترات قصيرة في أثناء العمل",correct:!1},{text:"خالية فقط قبل زيارة التفتيش",correct:!1}],explanation:"أبقِ الممرات والمخارج مفتوحة وخالية من العوائق؛ فحوادث كثيرة تقع بسبب الانزلاق أو التعثّر بالأدوات والمواد المبعثرة."},{question:"أنهيت عملك. ماذا تفعل بالأدوات التي استخدمتها؟",options:[{text:"أتركها على الأرض للنوبة التالية",correct:!1},{text:"أعيد كل أداة إلى مكانها",correct:!0},{text:"أضعها في حاوية النفايات مع البقايا",correct:!1},{text:"أجمعها في الممر قرب المخرج",correct:!1}],explanation:"أعِد كل أداة إلى مكانها بعد انتهاء العمل، واجمع النفايات في حاويات خاصة؛ فالأدوات والمواد المبعثرة تسبّب الانزلاق والتعثّر."},{question:"في نهاية الوردية، أين توضع الخِرق المبللة بالزيت؟",options:[{text:"في حاوية معدنية مغلقة مخصصة لها",correct:!0},{text:"في حاوية النفايات العامة مع الورق",correct:!1},{text:"كومة في زاوية لغسلها لاحقًا",correct:!1},{text:"في صندوق كرتون تحت طاولة العمل",correct:!1}],explanation:"الخِرق الزيتية قد تسخن ذاتيًا وتشتعل؛ والحاوية المعدنية المغلقة تقلل الهواء وتحصر النار داخلها، أما الكرتون والحاوية العامة فيزيدان الوقود."},{question:"رأيت باب حريق مثبتًا مفتوحًا بقطعة خشب لتمرّ العربات. ماذا تفعل؟",options:[{text:"أزيل الخشبة وأبلّغ ليُوجَد حل آمن",correct:!0},{text:"أتركه لأنه يجعل مرور العربات أسرع بكثير",correct:!1},{text:"أربطه مفتوحًا بحبل أقوى كي لا ينغلق وحده",correct:!1},{text:"أضع علامة تحذير على الباب وأتركه مفتوحًا كما هو",correct:!1}],explanation:"باب الحريق لا يوقف الدخان والنار إلا وهو مغلق؛ وإذا لزم إبقاؤه مفتوحًا، يركّب المسؤول جهازًا مناسبًا يغلقه تلقائيًا عند الإنذار."},{question:"أيّ هذه الممارسات غير آمنة؟",options:[{text:"وضع الصناديق أمام لوحة الكهرباء",correct:!0},{text:"تمديد كابل بمحاذاة الجدار بعيدًا عن الممر",correct:!1},{text:"وضع علامة على الأرض المبللة حتى تجف",correct:!1},{text:"إبقاء عدّة الانسكاب قرب مخزن الزيت",correct:!1}],explanation:"يجب أن تبقى مساحة خالية أمام لوحة الكهرباء لتُفصل بسرعة في الطوارئ ويعمل الكهربائي بأمان. أما الممارسات الثلاث الأخرى فآمنة."}],steps:[{title:"افحص مكانك قبل العمل",detail:"تجوّل في مكان عملك: يجب أن تكون الممرات والمخارج ومطافئ الحريق ولوحات الكهرباء ونقاط نداء الإنذار مفتوحة وخالية من العوائق.",critical:!0},{title:"عالج الانسكاب فورًا",detail:"نبّه الآخرين وضع علامة تحذير، ثم نظّف بالمادة المناسبة. وفي المواد الكيميائية اقرأ الملصق وصحيفة بيانات السلامة (SDS) أولًا، واستخدم معدات الوقاية الشخصية وعدّة الانسكاب (Spill Kit).",critical:!0},{title:"ضع النفايات في مكانها الصحيح",detail:"الكرتون والورق في الحاويات المخصصة لها، والخِرق المبللة بالزيت أو المذيبات في حاوية معدنية مغلقة مصممة لها."},{title:"خزّن المواد بأمان",detail:"الأشياء الثقيلة على الرفوف المنخفضة، والأكوام ثابتة ولا تتجاوز الارتفاع الذي يحدده الموقع؛ ولا شيء أمام المطافئ أو لوحات الكهرباء أو تحت رؤوس المرشات."},{title:"اترك المكان جاهزًا في نهاية الوردية",detail:"أعد الأدوات إلى أماكنها، وأخرج النفايات، وأبلغ المشرف والوردية التالية بأي مشكلة باقية."}],warnings:["لا تُبقِ باب الحريق مفتوحًا بإسفين أبدًا، ولا تقفل باب الخروج ولا تضع أمامه شيئًا: ففي الحريق هما طريق النجاة والحاجز أمام الدخان.","لا تمسح مادة كيميائية مجهولة بالخِرق أو نشارة الخشب: اقرأ الملصق وصحيفة بيانات السلامة أولًا؛ فبعض المواد تتفاعل معها أو تطلق أبخرة سامة."],tips:["حدّد أماكن التخزين والممرات بخطوط على الأرض.","نظّف أولًا بأول في أثناء العمل، لا في نهاية الوردية فقط.","ضع عدّة الانسكاب قرب أماكن استخدام السوائل وتعلّم طريقة استعمالها.","استخدم قائمة تحقق قصيرة للنظافة والترتيب عند تسليم الوردية."],activity:{prompt:"في نهاية وردية مزدحمة، توجد كومة من الكرتون والخِرق المبللة بالزيت قرب طاولة الجلخ (Grinder) حيث يتطاير الشرر. أنت على وشك المغادرة. ماذا تفعل؟",options:[{text:"أتركها لعامل النظافة الليلي",correct:!1,feedback:"الكرتون والخِرق الزيتية وقود بجانب الشرر؛ وقد يبدأ الحريق قبل وصول عامل النظافة."},{text:"أضع الكرتون في حاويته والخِرق في الحاوية المعدنية المغلقة وأبلغ المشرف",correct:!0,feedback:"صحيح: يُبعَد الوقود عن الشرر، وتبقى الخِرق الزيتية في حاوية مغلقة لأنها قد تسخن ذاتيًا وتشتعل."},{text:"أسكب دلوًا من الماء على الكومة",correct:!1,feedback:"الماء لا يزيل الوقود، ويجعل الأرض زلقة وقد يصل إلى المعدات الكهربائية."},{text:"أغطّي الكومة بغطاء بلاستيكي",correct:!1,feedback:"البلاستيك يحترق أيضًا، ويبقى الوقود قرب الشرر."}]},caseStudy:[{prompt:"أنت مشرف. يخبرك عامل أن برميلًا بلا ملصق يسرّب سائلًا على أرض أحد الممرات وأن هناك رائحة قوية. ما أول ما تفعله؟",options:[{text:"أُبعد الناس، وأمنع أي شرر أو لهب، وأبلغ مسؤول السلامة أو فريق الطوارئ (ERT)، وأبحث عن صحيفة بيانات السلامة",correct:!0,feedback:"صحيح: المادة مجهولة والرائحة قد تعني أبخرة قابلة للاشتعال أو سامة؛ أولًا حماية الناس ثم معرفة المادة."},{text:"أنظّفه فورًا بنشارة الخشب كي لا ينزلق أحد",correct:!1,feedback:"من دون معرفة المادة قد تتفاعل نشارة الخشب معها أو تصبح وقودًا."},{text:"أطلب من العمال القفز فوقه ومتابعة العمل",correct:!1,feedback:"يبقى الناس في الأبخرة وقد يسقطون؛ الخطر لم ينتهِ."},{text:"أحمل البرميل بيدي إلى الخارج",correct:!1,feedback:"من دون معدات وقاية ومعرفة المادة تعرّض نفسك لمادة مجهولة وقد تزيد الانسكاب."}]},{prompt:"تعرّف مسؤول السلامة على المادة: مذيب قابل للاشتعال. التسرّب صغير وقد توقف. ماذا يُفعل بعد ذلك؟",options:[{text:"ينظّف موظفون مدرَّبون بعدّة الانسكاب ومعدات الوقاية وفق صحيفة البيانات، من دون شرر، وتوضع النفايات في حاوية موسومة؛ ثم يعالجون سبب وجود البرميل في الممر",correct:!0,feedback:"صحيح: تنظيف وفق صحيفة البيانات، ثم معالجة السبب (التخزين الخاطئ وغياب الملصق) كي لا يتكرر."},{text:"أغسله بالماء نحو مصرف الأرضية",correct:!1,feedback:"المذيب القابل للاشتعال يجمع الأبخرة في المجاري ويلوّث البيئة."},{text:"نستأنف العمل فورًا لأن التسرّب توقف",correct:!1,feedback:"المادة المسكوبة ما زالت على الأرض وقد تصل أبخرتها إلى شرارة."},{text:"نتركه حتى يتبخر وحده",correct:!1,feedback:"التبخر يعني أبخرة في الهواء؛ وهذا يزيد خطر الحريق والاستنشاق."}]}],realCase:"في ورشة أثاث، كانت نشارة الخشب والقطع المتبقية تُنظَّف في نهاية الأسبوع فقط. وذات مساء سقطت شرارة من آلة الجلخ في كومة من النشارة والقشور الخشبية تحت طاولة وبدأت تدخّن. شمّ أحد العمال الرائحة فأطلق الإنذار واتُّصل بالرقم 115. وبعد أن تأكد زميل مدرَّب من أن الحريق صغير وأن طريق الخروج خلفه، أطفأه بالمطفأة المناسبة. لم يُصب أحد. وغيّر المدير الإجراء: التنظيف أولًا بأول، وفحص نظام جمع الغبار، وفحص النظافة والترتيب عند كل تسليم للوردية."},{id:17,code:"QUAK-117",icon:"Activity",accent:"#d97706",title:"الزلزال في المصانع",subtitle:"Earthquake Safety in Factories",summary:"سلامة العمال في أثناء الزلزال وبعده",blocks:[{body:"يُشكّل الزلزال في المصانع خطرًا مضاعفًا: الاهتزاز نفسه من جهة، ومن جهة أخرى سقوط الآلات الثقيلة، وانسكاب المواد الكيميائية، وتكسّر الأنابيب، وتسرّب الغاز. لذا يجب أن تكون لكل مصنع خطة للزلازل."},{heading:"1. انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)",body:"في أثناء الزلزال:",points:["انخفض إلى الأرض (Drop) وادخل تحت طاولة أو طاولة عمل (Workbench) متينة — بعيدًا عن الآلات الثقيلة والرفوف والزجاج.","إذا لم تكن هناك طاولة، فاجثُ على ركبتيك بجانب جدار داخلي وغطِّ رأسك ورقبتك بيديك (Cover).","تمسّك بالطاولة (Hold On) حتى يتوقف الاهتزاز تمامًا.","لا تركض، ولا تحتمِ تحت الآلات أو بجانب الرفوف! فالآلات الثقيلة والرفوف قد تتحرك أو تسقط عليك."]},{heading:"2. بعد الزلزال",body:"بعد توقف الاهتزاز:",points:["افحص الآلات بحثًا عن أضرار، ولا تشغّل الآلات المتضررة حتى تُفحص.","تحقّق مما إذا كانت المواد الكيميائية قد انسكبت، وابتعد عنها.","إذا شممت رائحة غاز — فاخرج بسرعة، وأخلِ المصنع، واتصل بالرقم 115 من الخارج.","لا يقطع الغازَ إلا الموظفون المدرَّبون والمكلَّفون، وفقط إذا شُمّت رائحته أو سُمع صوت تسرّب وأمكن الوصول إلى صمام الغاز بأمان، دون دخول المكان الذي تجمّع فيه الغاز ودون إحداث أيّ شرارة؛ واقطع الكهرباء إذا تضررت الأسلاك أو اللوحات الكهربائية.","قبل العودة إلى الداخل، يجب أن يفحص مهندسٌ مبنى المصنع بحثًا عن تشققات."]},{heading:"3. الاستعداد",body:"الخطة المسبقة:",points:["أعدّ خطة للزلازل لكل قسم.","ثبّت الآلات الثقيلة بالسلاسل أو البراغي.","ضع البراميل وعبوات المواد الكيميائية على رفوف منخفضة وثابتة.","أبقِ ممرات الإخلاء مفتوحة دائمًا.","أجرِ تمرينًا مرة كل 6 أشهر."]},{heading:"4. أينما كنت عندما يبدأ الاهتزاز",body:"تصرّف بحسب مكان عملك:",points:["عند الآلة: ابتعد عنها وادخل تحت طاولة متينة؛ ولا تحاول إمساك الآلة بيديك.","على رافعة شوكية أو في مركبة: توقف في مكان مكشوف بعيدًا عن الرفوف والمباني وخطوط الكهرباء، وشدّ المكابح، وابقَ في مكانك حتى يتوقف الاهتزاز.","في الخارج: إن أمكنك ذلك بأمان فابتعد عن المباني والرفوف الخارجية وأكوام المواد وخطوط الكهرباء، ثم انخفض وغطِّ رأسك ورقبتك.","في المواقع الكيميائية: تحدد الخطة من يوقف العمليات بأمان بعد الاهتزاز؛ ولا يركض أحد إلى الصمامات واللوحات في أثنائه."]},{heading:"5. واجبات المشرفين والمديرين بعد الاهتزاز",body:"إلى حين وصول فرق الدفاع المدني (115) والمهندس:",points:["أحصِ جميع الموظفين وعمال المقاولين والزوار عند نقطة التجمع.","أبلغ الرقم 115 عن المحاصَرين أو المفقودين، والرقم 122 عن المصابين؛ ولا تدخل المباني المتضررة للبحث.","لا يُستأنف العمل إلا بعد أن يفحص أشخاص مختصون المبنى والغاز والكهرباء والآلات.","فحص المبنى والإذن باستئناف العمل: اتبع تعليمات الدفاع المدني والجهة المختصة."]}],media:[{kind:"image",src:"media/images/factory_earthquake.png",title:"الزلزال",description:"الزلزال في المصنع"}],quiz:[{question:"في أثناء الزلزال في المصنع، ما أول ما تفعله؟",options:[{text:"الركض فورًا إلى الخارج من أقرب باب",correct:!1},{text:"الانخفاض إلى الأرض والدخول تحت طاولة متينة",correct:!0},{text:"إطفاء جميع الآلات قبل أي شيء آخر",correct:!1},{text:"الاقتراب من النوافذ",correct:!1}],explanation:"انخفض، احتمِ، تمسّك (Drop, Cover, Hold On) — هذا هو الإجراء الأول داخل المباني، بعيدًا عن الآلات والرفوف والزجاج."},{question:"بعد الزلزال في مصنع للمواد الكيميائية، ما أول ما يجب فحصه؟",options:[{text:"عدّادات الكهرباء ولوحاتها",correct:!1},{text:"انسكاب المواد الكيميائية",correct:!0},{text:"أنابيب المياه",correct:!1},{text:"خطوط الهاتف",correct:!1}],explanation:"انسكاب المواد الكيميائية خطر كبير بعد الزلزال، ويجب فحصه بسرعة."},{question:"بعد توقف الاهتزاز، شممت رائحة غاز في المصنع. ماذا تفعل؟",options:[{text:"أذهب إلى صمام الغاز وأغلقه بنفسي",correct:!1},{text:"أشغّل مراوح الشفط ليخرج الغاز",correct:!1},{text:"أخرج بسرعة وأتصل بالرقم 115 من الخارج",correct:!0},{text:"أتصل بالرقم 115 من هاتفي أولًا ثم أخرج",correct:!1}],explanation:"إذا شممت رائحة غاز، فاخرج بسرعة، وأخلِ المصنع، واتصل بالرقم 115 من الخارج؛ ولا يقطع الغازَ إلا الموظفون المدرَّبون والمكلَّفون، وفقط إذا أمكن الوصول إلى الصمام بأمان، دون دخول المكان الذي تجمّع فيه الغاز ودون إحداث أي شرارة."},{question:"تقود رافعة شوكية في المستودع عندما يبدأ الاهتزاز. ماذا تفعل؟",options:[{text:"أتوقف بعيدًا عن الرفوف وأشدّ المكابح وأبقى جالسًا",correct:!0},{text:"أقود بسرعة نحو أقرب باب للخروج قبل أن يشتد",correct:!1},{text:"أقفز منها وأركض لأحتمي تحت أقرب رف تخزين",correct:!1},{text:"أرفع الشوكتين عاليًا لأسند الرف المجاور لي",correct:!1}],explanation:"التوقف في مكان مكشوف والبقاء في المقعد يحميانك من الأشياء المتساقطة؛ أما القيادة أو الركض في أثناء الاهتزاز والاقتراب من الرفوف فخطرة."},{question:"بعد الزلزال يقول زميل إن المبنى يبدو سليمًا ويريد تشغيل خط الإنتاج. ما الصحيح؟",options:[{text:"انتظر فحص المهندس والأشخاص المختصين",correct:!0},{text:"شغّله فورًا كي لا تتأخر الطلبات",correct:!1},{text:"شغّل فقط الآلات التي ما زالت فيها كهرباء",correct:!1},{text:"شغّله بعد نظرة سريعة من أحدث العمال",correct:!1}],explanation:"الضرر في المبنى وأنابيب الغاز والأسلاك لا يُرى دائمًا بالعين، والهزات الارتدادية قد تُسقط الأجزاء الضعيفة؛ ولا يأذن بالتشغيل إلا المختصون."},{question:"أيّ هذه الأفعال خطأ في أثناء الزلزال في مكان العمل؟",options:[{text:"الركض نحو المخرج والمبنى ما زال يهتز",correct:!0},{text:"الدخول تحت طاولة عمل متينة بعيدًا عن الآلات",correct:!1},{text:"الجثو بجانب جدار داخلي وتغطية الرأس",correct:!1},{text:"التمسّك بالطاولة حتى يتوقف الاهتزاز تمامًا",correct:!1}],explanation:"الركض في أثناء الاهتزاز يعرّضك للزجاج والأشياء المتساقطة؛ أما الأفعال الثلاثة الأخرى فهي جزء من «انخفض، احتمِ، تمسّك»."}],steps:[{title:"انخفض، احتمِ، تمسّك",detail:"انخفض فورًا وادخل تحت طاولة عمل متينة، بعيدًا عن الآلات الثقيلة والرفوف العالية والزجاج؛ وإن لم تجد طاولة فغطِّ رأسك ورقبتك بجانب جدار داخلي.",critical:!0},{title:"ابقَ مكانك حتى يتوقف الاهتزاز",detail:"لا تركض ولا تخرج من المبنى في أثناء الاهتزاز. وإذا كنت على رافعة شوكية فتوقف في مكان مكشوف بعيد عن الرفوف، وشدّ المكابح، وابقَ في مقعدك.",critical:!0},{title:"بعد الاهتزاز: افحص نفسك والآخرين",detail:"تفقّد المصابين والمحاصَرين، وقدّم الإسعافات الأولية إن كنت مدرَّبًا، واتصل بالرقمين 122 و115. وتوقّع الهزات الارتدادية، وكرّر في كل مرة: انخفض، احتمِ، تمسّك."},{title:"اخرج بحذر من الطريق المحدد في الخطة",detail:"استخدم الدرج لا المصعد، وابتعد عن المواد المنسكبة والأشياء الساقطة والأسلاك التالفة. وإذا شممت رائحة غاز فلا تستخدم أي مفتاح أو هاتف في الداخل، واخرج واتصل بالرقم 115 من الخارج؛ ولا يقطع الغاز إلا الموظفون المدرَّبون والمكلَّفون إذا أمكن الوصول إلى الصمام بأمان.",critical:!0},{title:"أحصِ الجميع عند نقطة التجمع",detail:"يُحصي المشرف العاملين ويبلغ فرق الدفاع المدني (115) باسم كل مفقود وآخر مكان شوهد فيه. ولا يدخل أحد قبل أن يفحص مهندس المبنى.",critical:!0}],warnings:["لا تركض نحو الخارج في أثناء الاهتزاز: فالزجاج وأجزاء الجدران والمواد المكدّسة قد تسقط عليك في الطريق.","لا تعد إلى مبنى متضرر ولا تشغّل آلات متضررة قبل فحصها: فالهزات الارتدادية قد تُسقط المباني الضعيفة.","لا تستخدم المصعد بعد الزلزال: فقد يتوقف أو يكون قد تضرر."],tips:["اعرف أقرب مكان احتماء متين في كل موقع تعمل فيه.","في التمارين، طبّق «انخفض، احتمِ، تمسّك» في مكان عملك نفسه.","ضع الأشياء الثقيلة في أسفل الرفوف، وثبّت الرفوف العالية بالجدار أو الأرض.","احتفظ بمصباح يدوي وصفّارة في حقيبة الطوارئ لكل قسم."],activity:{prompt:"تعمل على مخرطة (Lathe) عندما يبدأ اهتزاز قوي. خلفك رف عالٍ، وباب الخروج في آخر القاعة. ماذا تفعل؟",options:[{text:"أركض بسرعة نحو باب الخروج",correct:!1,feedback:"الركض في أثناء الاهتزاز يعرّضك للأشياء المتساقطة وقد تسقط؛ أول ما تفعله هو الانخفاض."},{text:"أنخفض وأدخل تحت طاولة عمل متينة بعيدًا عن الآلة والرف وأتمسّك",correct:!0,feedback:"صحيح: «انخفض، احتمِ، تمسّك» بعيدًا عن الأشياء التي قد تتحرك أو تسقط."},{text:"أقف تحت إطار الباب القريب",correct:!1,feedback:"إطار الباب ليس أقوى من غيره وقد يرتطم بك الباب؛ هذه الطريقة لا تُعلَّم."},{text:"أبقى بجانب الآلة لأمنعها من السقوط",correct:!1,feedback:"لا يستطيع الإنسان إيقاف آلة ثقيلة؛ فقد تتحرك وتسقط عليك."}]},caseStudy:[{prompt:"توقف الاهتزاز في مستودع مصنع كيميائي. أنت المشرف. سقط برميل وبدأ السائل ينتشر، وفي إحدى الزوايا رائحة غاز. ما أول ما تفعله؟",options:[{text:"أُخرج الجميع عبر طريق الخطة بعيدًا عن الانسكاب والغاز، من دون مفاتيح، وأتصل بالرقم 115 من الخارج",correct:!0,feedback:"صحيح: هناك خطران معًا؛ الأولوية لحياة الناس، والاتصال من الخارج كي لا تتولد شرارة."},{text:"أطفئ الأضواء والآلات بالمفاتيح في طريقي",correct:!1,feedback:"المفاتيح قد تُحدث شرارة وسط الغاز؛ لا يُستخدم أي مفتاح حيث توجد رائحة الغاز."},{text:"ننظّف الانسكاب أولًا كي لا ينتشر",correct:!1,feedback:"البقاء في الداخل مع الغاز ومادة مجهولة يعرّض الناس للخطر؛ يُعالج الانسكاب لاحقًا بفرق مختصة."},{text:"أذهب إلى صمام الغاز في تلك الزاوية لأغلقه",correct:!1,feedback:"الصمام داخل المنطقة التي تجمّع فيها الغاز؛ والذهاب إليه ممنوع. اخرج وأبلغ 115."}]},{prompt:"عند نقطة التجمع تكتشف أن عاملين لم يصلا. ويريد زميلك العودة إلى المستودع للبحث عنهما. ماذا تفعل؟",options:[{text:"أمنعه، وأبلغ فرق 115 بآخر مكان شوهد فيه العاملان",correct:!0,feedback:"صحيح: المبنى متضرر وفيه غاز؛ البحث عمل فرق الإنقاذ وهي تحتاج إلى معلوماتك."},{text:"أسمح له إذا عاد بسرعة",correct:!1,feedback:"الهزات الارتدادية والغاز قد تجعله ضحية أيضًا؛ فيصبح المحاصَرون ثلاثة."},{text:"أعود بنفسي ومعي مصباح",correct:!1,feedback:"على المشرف أن يبقى عند نقطة التجمع وينظّم الإحصاء؛ والدخول يحمل الخطر نفسه."},{text:"أنتظر دون إبلاغ، فربما ذهبا إلى البيت",correct:!1,feedback:"يجب الإبلاغ فورًا عن كل مفقود؛ فالوقت مهم للإنقاذ."}]}],realCase:"وقع زلزال متوسط في أثناء وردية النهار في مصنع لتشكيل المعادن. انخفض العمال المدرَّبون ودخلوا تحت طاولات العمل بعيدًا عن الآلات والرفوف العالية. وسقط رف ثقيل غير مثبّت في أحد الممرات. وبعد توقف الاهتزاز، قاد المشرفون الجميع عبر طرق الخطة وأحصوهم عند نقطة التجمع. وأبلغ عامل صيانة عن رائحة غاز قرب غرفة المرجل؛ فلم يعد أحد إلى الداخل واتُّصل بالرقم 115 من الخارج. وفحص مهندس المبنى قبل استئناف العمل. وبعد ذلك ثبّت المصنع جميع الرفوف."},{id:18,code:"FLOOD-118",icon:"Waves",accent:"#2563eb",title:"السيول والفيضانات",subtitle:"Flood Emergency in Industrial Areas",summary:"حماية المصانع والعمال في أثناء السيول",blocks:[{body:"يمكن للسيول أن تدمّر المصانع تدميرًا كاملًا: فهي تُتلف الآلات، وتنشر المواد الكيميائية، وتجعل الكهرباء مصدر خطر. والمصانع القريبة من الأنهار والوديان أكثر عرضة للخطر."},{heading:"1. قبل السيل",body:"الاستعداد:",points:["تابع تحذيرات الأرصاد الجوية (Meteorology).","انقل المعدات المهمة والمواد الكيميائية إلى مكان مرتفع.","جهّز نظام الكهرباء للفصل التلقائي (Auto-shutoff).","ضع أكياس الرمل (Sandbags) أمام الأبواب وعند أساسات المصنع."]},{heading:"2. في أثناء السيل",body:"الإجراءات العاجلة:",points:["إذا استطعت ذلك بأمان ولم تصل المياه إلى اللوحات الكهربائية، فاقطع الكهرباء والغاز؛ ولا تلمس الكهرباء وأنت في الماء!","لا تدخل مياه السيل — فـ 15 سم من الماء المتدفق بسرعة يمكن أن تُسقط الإنسان، و30 سم يمكن أن تجرف السيارة.","انتقل إلى مكان مرتفع — الطابق الثاني أو السطح.","اتصل بالرقم 115 وابقَ في مكانك حتى تصل فرق الإنقاذ."]},{heading:"3. بعد السيل",body:"العودة والتنظيف:",points:["لا تدخل المصنع حتى يتأكد مهندس من أن المبنى آمن.","لا تلمس المواد الكيميائية التي وصلت إليها المياه — اطلب فريق المواد الخطرة (HazMat) عبر الرقم 115.","لا تُعِد تشغيل الكهرباء حتى يفحص كهربائي مختص النظام.","التقط صورًا لجميع الأضرار من أجل التأمين والتقرير."]},{heading:"4. خطة السيول: واجبات المسؤولين",body:"قبل أن يأتي السيل، يجب أن تجيب الخطة عن هذه الأسئلة:",points:["هل يمكن أن يغمر الماء الموقع؟ (أرض منخفضة، أو قرب نهر أو وادٍ، أو تصريف ضعيف.)","من يقرر إيقاف العمل وإرسال الموظفين إلى بيوتهم أو إلى الطابق العلوي، ومتى؟","قائمة بالمواد الكيميائية والوقود وأماكنها، وتخزينها فوق منسوب المياه المتوقع إن أمكن.","حقيبة الطوارئ (مصباح وحقيبة إسعافات أولية ومذياع وماء للشرب) في الطابق العلوي.","التحذيرات وأوامر الإخلاء: اتبع الدفاع المدني والبيانات الرسمية؛ وتحدد الجهة المختصة قنوات التحذير."]},{heading:"5. مياه السيول والصحة",body:"مياه السيل ليست ماءً فقط:",points:["قد تخفي فتحات مكشوفة وأجسامًا حادة وكهرباء.","قد تكون ملوثة بالمواد الكيميائية والوقود ومياه الصرف.","بعد ملامسة مياه السيل، اغسل يديك وجلدك بالماء النظيف والصابون، وأبلغ مسعف الموقع عن أي جرح.","المولّدات والمضخات العاملة بالبنزين في الخارج فقط، وعلى بعد 6 أمتار على الأقل من النوافذ والأبواب وفتحات التهوية."]}],media:[{kind:"image",src:"media/images/factory_flood.png",title:"السيول",description:"السيول في المصنع"}],quiz:[{question:"في أثناء السيل في المصنع، ما أول ما تفعله؟",options:[{text:"احمِ الآلات بتغطيتها بأغطية بلاستيكية كبيرة",correct:!1},{text:"اقطع الكهرباء والغاز إذا استطعت ذلك بأمان",correct:!0},{text:"اذهب إلى البيت",correct:!1},{text:"ابدأ بسحب الماء بالمضخة قبل أي شيء آخر",correct:!1}],explanation:"الكهرباء والغاز هما الخطران الأولان في أثناء السيل؛ لكن إذا وصلت المياه إلى اللوحات الكهربائية، فلا تقترب منها وانتقل إلى مكان مرتفع."},{question:"كم يكفي من الماء المتدفق بسرعة لإسقاط الإنسان؟",options:[{text:"50 سم",correct:!1},{text:"75 سم",correct:!1},{text:"15 سم",correct:!0},{text:"متر واحد",correct:!1}],explanation:"لا تدخل مياه السيل: فـ 15 سم من الماء المتدفق بسرعة يمكن أن تُسقط الإنسان، و30 سم يمكن أن تجرف السيارة. انتقل إلى مكان مرتفع واتصل بالرقم 115."},{question:"بعد السيل، وجدت براميل مواد كيميائية وصلت إليها المياه. ماذا تفعل؟",options:[{text:"أغسلها بماء نظيف وأعيدها إلى الرف",correct:!1},{text:"لا ألمسها، وأطلب فريق المواد الخطرة (HazMat) عبر الرقم 115",correct:!0},{text:"أنقلها بيدي إلى الخارج قبل أن ترتفع المياه مجددًا",correct:!1},{text:"أفتحها لأتحقق مما إذا دخلها الماء",correct:!1}],explanation:"لا تلمس المواد الكيميائية التي وصلت إليها المياه — اطلب فريق المواد الخطرة (HazMat) عبر الرقم 115."},{question:"صدر تحذير من السيل وأنت في العمل، وسيارتك في مكان منخفض. أي قرار أكثر أمانًا؟",options:[{text:"أتبع الخطة والتعليمات الرسمية وأغادر فقط عبر طريق بلا ماء",correct:!0},{text:"أقود بسرعة عبر الماء قبل أن يرتفع أكثر",correct:!1},{text:"أخوض في الماء إلى السيارة لأنقلها إلى مكان أعلى",correct:!1},{text:"أبقى في الطابق الأرضي لأراقب سيارتي",correct:!1}],explanation:"السيارة تُعوَّض والحياة لا تُعوَّض؛ فـ 30 سم من الماء قد تجرف السيارة و15 سم من الماء السريع قد تُسقط الإنسان."},{question:"بعد السيل اقترح أحدهم تشغيل مضخة تعمل بالبنزين داخل القاعة لسحب الماء. ما الخطر الرئيسي؟",options:[{text:"عادمها أول أكسيد الكربون الذي قد يقتل من في الداخل",correct:!0},{text:"تستهلك الكثير من الوقود وتحتاج إلى وقت طويل",correct:!1},{text:"ضجيجها يزعج عمال الوردية الأخرى",correct:!1},{text:"الماء يُتلف طلاء المضخة بسرعة",correct:!1}],explanation:"محركات البنزين تُنتج أول أكسيد الكربون (CO) وهو غاز بلا لون ولا رائحة، وقد يقتل بسرعة داخل المباني. في الخارج فقط وبعيدًا عن النوافذ والأبواب."},{question:"وصلت المياه إلى لوحات الكهرباء. ماذا تفعل؟",options:[{text:"أبتعد عن اللوحات وأنتقل إلى مكان مرتفع",correct:!0},{text:"أقف على صندوق جاف وأفصل القاطع الرئيسي",correct:!1},{text:"أفصل الآلات واحدة تلو الأخرى بقفازات جافة",correct:!1},{text:"أضع الرمل حول اللوحة لإيقاف الماء",correct:!1}],explanation:"إذا وصلت المياه إلى اللوحات فاللمس خطر صعق قاتل؛ ولا يحمي الصندوق أو القفاز حماية كاملة. ابتعد وأبلغ 115."}],steps:[{title:"عند تحذير السيل: اتبع الخطة",detail:"اتبع تعليمات الدفاع المدني والبيانات الرسمية. احمِ الناس أولًا: أوقف العمل وأرسل غير الضروريين مبكرًا إلى مكان مرتفع؛ ثم ارفع المواد الكيميائية والمعدات المهمة إذا سمح الوقت.",critical:!0},{title:"الكهرباء والغاز بأمان فقط",detail:"اقطع الكهرباء والغاز فقط إذا استطعت ذلك بأمان ولم تصل المياه إلى اللوحات. وإذا كنت واقفًا في الماء أو وصلت المياه إلى اللوحة فلا تقترب.",critical:!0},{title:"اصعد إلى مكان مرتفع، لا إلى الماء",detail:"اصعد إلى الطابق الثاني أو السطح، ولا تدخل مياه السيل سيرًا أو بالسيارة: فـ 15 سم من الماء المتدفق قد تُسقط الإنسان و30 سم قد تجرف السيارة.",critical:!0},{title:"اتصل بالرقم 115 وأحصِ الجميع",detail:"أبلغ الرقم 115 بمكانك وعدد الأشخاص ووجود مصابين إن وُجدوا، وابقَ مكانك حتى تصل فرق الإنقاذ. ويعرف المشرف مكان كل شخص."},{title:"بعد السيل: لا شيء قبل الفحص",detail:"لا تدخل المصنع حتى يؤكد مهندس سلامة المبنى، ولا تُعِد الكهرباء حتى يفحصها كهربائي مختص، ولا تلمس المواد الكيميائية التي وصلتها المياه — اطلب فريق المواد الخطرة (HazMat) عبر الرقم 115.",critical:!0}],warnings:["لا تدخل مياه السيل أبدًا سيرًا أو بالسيارة: فقد تُسقطك وتجرف السيارات وتخفي فتحات صرف مكشوفة وكهرباء.","لا تلمس المفاتيح أو المعدات الكهربائية وأنت واقف في الماء أو يداك مبللتان.","لا تشغّل مولّدًا أو مضخة تعمل بالبنزين داخل المبنى لتجفيفه: فأول أكسيد الكربون (CO) قد يقتل؛ في الخارج فقط."],tips:["احتفظ بنسخ من مخطط الموقع وقائمة المواد الكيميائية وأرقام الموظفين في مكان مرتفع يسهل الوصول إليه.","نظّف المصارف والقنوات وأبقها مفتوحة قبل موسم الأمطار.","اربط البراميل والخزانات الصغيرة جيدًا كي لا تجرفها المياه.","امشِ في التمرين الطريق إلى الطابق العلوي أو المكان المرتفع."],activity:{prompt:"تهطل أمطار غزيرة وتدخل المياه الطابق الأرضي للمصنع حيث لوحة الكهرباء الرئيسية. وصلت المياه إلى أسفل اللوحة وأنت واقف في الماء. ماذا تفعل؟",options:[{text:"أذهب إلى اللوحة وأقطع الكهرباء بيدي",correct:!1,feedback:"المياه وصلت إلى اللوحة وأنت في الماء؛ الصعق الكهربائي قد يقتلك."},{text:"أبتعد عن اللوحة وأصعد مع الآخرين إلى الطابق العلوي وأبلغ 115 أن اللوحة غمرتها المياه",correct:!0,feedback:"صحيح: لا يُقطع التيار إلا إذا كان ذلك آمنًا؛ والآن وقت الصعود وإبلاغ فرق 115."},{text:"أشغّل مضخة كهربائية في الطابق الأرضي لسحب الماء",correct:!1,feedback:"جهاز كهربائي في الماء يزيد خطر الصعق ولا يوقف مياه السيل."},{text:"أقود سيارة المصنع عبر الماء لأجلب المساعدة",correct:!1,feedback:"30 سم من الماء قد تجرف السيارة؛ اتصل بالرقم 115 وابقَ في المكان المرتفع."}]},caseStudy:[{prompt:"في المساء صدر تحذير رسمي من السيول لمنطقتك. المصنع في وادٍ، وبراميل المذيبات في الطابق الأرضي. أنت مسؤول الوردية. ما أول ما تفعله؟",options:[{text:"أتبع التحذير والخطة: أوقف العمل، وأرسل غير الضروريين مبكرًا عبر طريق مرتفع، وإن سمح الوقت يرفع موظفون مدرَّبون البراميل أو يربطونها",correct:!0,feedback:"صحيح: الناس أولًا، والمغادرة المبكرة قبل أن تغمر المياه الطرق أكثر أمانًا؛ ثم حماية المواد كي لا تنشرها المياه."},{text:"نواصل العمل حتى نرى الماء بأعيننا",correct:!1,feedback:"قد يصل السيل بسرعة كبيرة؛ فتُغلق الطرق ولا يبقى وقت للخروج الآمن."},{text:"أصرف الجميع إلى بيوتهم عبر طريق الوادي ولو كان عليه ماء",correct:!1,feedback:"طريق الوادي أول ما تغمره المياه؛ وعبور الماء أخطر ما يمكن فعله."},{text:"أترك كل عامل يقرر بنفسه",correct:!1,feedback:"في الطوارئ نحتاج إلى قرار واضح وخطة موحدة كي لا يبقى أحد في مكان خطر."}]},{prompt:"وصلت المياه إلى الطابق الأرضي. معك عدد من الموظفين في الطابق الثاني. يريد أحد العمال الخوض في الماء للوصول إلى سيارته. ماذا تفعل؟",options:[{text:"أمنعه، ونبقى في الطابق العلوي، ونبلغ 115 بعددنا ومكاننا",correct:!0,feedback:"صحيح: البقاء في المكان المرتفع وانتظار فرق الإنقاذ أكثر أمانًا من دخول الماء."},{text:"أسمح له إذا ربط نفسه بحبل",correct:!1,feedback:"الحبل لا يحمي من التيار السريع والحطام والكهرباء، وقد يسحب الزملاء إلى الماء."},{text:"نخرج جميعًا عبر الماء ونحن متشابكو الأيدي",correct:!1,feedback:"هذا يعرّض الجميع للخطر؛ فمياه السيل تخفي الحفر والكهرباء."},{text:"أنزل لأقطع اللوحة الرئيسية وأنا في الماء",correct:!1,feedback:"لمس اللوحة وأنت في الماء خطر قاتل؛ أبلغ 115 أن اللوحة غمرتها المياه."}]}],realCase:"بعد أمطار غزيرة، تلقّى مصنع صغير للأغذية قرب مجرى موسمي تحذيرًا رسميًا من السيول في المساء. اتبع المشرف خطة الموقع: أُوقف العمل، وغادر معظم الموظفين مبكرًا عبر طريق على أرض مرتفعة، ورُفعت براميل مواد التنظيف إلى رف عالٍ. وبقي عاملا صيانة في الطابق الثاني مع حقيبة الطوارئ، واتصلا بالرقم 115 عندما أحاطت المياه بالمبنى. لم يدخل أحد الماء. وفي اليوم التالي لم يدخل أحد قبل أن يفحص مهندس وكهربائي المبنى والأسلاك."},{id:19,code:"FACT-119",icon:"Siren",accent:"#dc2626",title:"استجابة الدفاع المدني في المصانع",subtitle:"Industrial CD Response & Multi-Agency Coordination",summary:"تشكيل فريق الاستجابة في المصنع عند وقوع الحوادث، والتنسيق مع الدفاع المدني (115)",blocks:[{body:"يجب أن تمتلك المصانع الكبيرة (النفط، والغاز، والكيمياويات، والصلب) فرقًا خاصة بها للاستجابة للطوارئ تعمل قبل وصول فرق الدفاع المدني (115). ويحدّد معيار NFPA 600 (Facility Fire Brigades) تنظيم فرق الإطفاء في المنشآت الصناعية وتدريبها ومعداتها. والدقائق الأولى من الحادث بالغة الأهمية، لذا يجب أن يكون فريق المصنع جاهزًا ومدرَّبًا."},{heading:"1. تشكيل فريق الاستجابة للطوارئ في المصنع (ERT)",body:"المبادئ الأساسية لفريق الاستجابة للطوارئ (Emergency Response Team):",points:["حجم الفريق: يُحدَّد بناءً على تقييم مخاطر المصنع ومهام الفريق؛ ولا يحدّد NFPA 600 نسبة ثابتة لعدد الأعضاء قياسًا بعدد الموظفين.","التدريب: بحسب مهام كل عضو، مع تدريب تنشيطي (Refresher) مرة واحدة في السنة على الأقل.","قائد الحادث (Incident Commander — IC): شخص واحد فقط يُصدر الأوامر، كي لا تتضارب الأوامر.","المهام الرئيسية: إطفاء الحريق، والإنقاذ، والإسعافات الأولية، وإخلاء المبنى.","الاتصال: أجهزة لاسلكي (Radio) على قناة مخصّصة، والهاتف المحمول وسيلةً احتياطية.","زمن الاستجابة: حدّده في الخطة، وقِسه بالتمارين، وحسّنه.","توصية: دورتا ICS-100 وICS-200 (FEMA) لتعلّم نظام قيادة الحوادث."]},{heading:"2. خطة الاستجابة للطوارئ (ERP)",body:"خطة الاستجابة للطوارئ (Emergency Response Plan) وفق المعايير:",points:["يجب أن تكون خطة الطوارئ مكتوبة ومتاحة في المصنع؛ ويجوز للمنشآت التي يعمل فيها 10 موظفين أو أقل إبلاغها شفهيًا (OSHA 29 CFR 1910.38).","الأقسام الرئيسية: المهام، والإجراءات، وطرق الإخلاء، والاتصالات، والموارد، والتمارين، والتقييم بعد الحادث.","نقاط التجمع (Assembly Points): نقطة رئيسية وأخرى احتياطية، في مكان آمن بعيد عن المبنى وعن طريق مركبات الطوارئ.","طرق الإخلاء: طريقان على الأقل من كل طابق بوجه عام (NFPA 101، مع بعض الاستثناءات).","إنذار الحريق (Alarm): يجب أن يُسمع أو يُرى في جميع أنحاء المبنى (NFPA 72).","فريق الإسعافات الأولية: يجب أن يوجد في كل وردية (Shift) موظفون تلقّوا تدريبًا على الإسعافات الأولية والإنعاش القلبي الرئوي (CPR).","التمارين (Drill): تُجرى بانتظام، وتُسجَّل نتائج كل تمرين.","التقييم بعد الحادث (Post-Response Critique): في أقرب وقت ممكن بعد كل حادث."]},{heading:"3. التنسيق مع الدفاع المدني (115)",body:"عند وقوع الحادث ووصول فرق الدفاع المدني (115)، يجب على فريق ERT اتباع الخطوات الآتية:",points:["1. اتصل فورًا بالرقم 115، وبالرقم 122 إذا كان هناك مصابون.","2. قدّم المعلومات الأساسية: الموقع، ونوع الحادث، وعدد المصابين، والمواد الخطرة، وطريق الوصول.","3. جهّز خريطة المصنع (Site Map) عند البوابة، مع مواقع الخطر وأماكن قطع الكهرباء والغاز.","4. ضابط الاتصال (Liaison Officer): شخص واحد فقط يتواصل مع الدفاع المدني (115).","5. جهّز صحائف بيانات السلامة (SDS) لجميع المواد الكيميائية.","6. سجّل أسماء الشهود وإفاداتهم.","7. نقل القيادة: عند وصول الدفاع المدني (115)، تنتقل القيادة إلى قائد فرق الدفاع المدني ويتولّى فريق ERT المساندة.","8. التوثيق: الصور والفيديو وسجلّ الحادث (Incident Log) لأغراض التحقيق والتأمين."]},{heading:"4. العمل مع فريق المواد الخطرة (HazMat)",body:"في الحوادث الكيميائية، يلزم فريق HazMat:",points:["مستويات التدريب على المواد الخطرة (OSHA 1910.120 وNFPA 470، الذي دُمج فيه NFPA 472):","• مستوى التوعية (Awareness): التعرّف على الخطر، والابتعاد، والإبلاغ — لجميع الموظفين.","• مستوى العمليات (Operations): حماية الناس والمحيط بأساليب دفاعية (Defensive) من مسافة بعيدة.","• مستوى الفني (Technician): إيقاف التسرّب من مسافة قريبة (Offensive) بمعدات وقاية شخصية خاصة.","• مستوى الأخصائي (Specialist): معرفة متعمّقة بمواد محدّدة ودعم الفنيين.","ثلاث مناطق: المنطقة الساخنة (Hot Zone)، والمنطقة الدافئة (Warm Zone)، والمنطقة الباردة (Cold Zone).","مستويات معدات الوقاية الشخصية في HazMat: A، B، C، D (المستوى A أعلى درجات الحماية).","تُجرى إزالة التلوث (Decontamination) في المنطقة الدافئة، قبل الانتقال إلى المنطقة الباردة.","لا يدخل الموظفون غير المدرَّبين المنطقة الساخنة؛ بل ينتظرون فرق الدفاع المدني (115).","يجب أن تحدّد خطة المصنع كيفية طلب الفرق المتخصّصة بالمواد الخطرة عبر الرقم 115."]},{heading:"5. الاستجابة المشتركة لعدة جهات (Multi-Agency Response)",body:"تتطلب الحوادث الكبيرة مشاركة عدة جهات:",points:["115 الدفاع المدني: إطفاء الحريق، والإنقاذ، والمواد الخطرة.","122 الإسعاف: العلاج الطبي ونقل المصابين.","104 الشرطة: تطويق المنطقة، وتنظيم المرور، والتحقيق القانوني.","الأجهزة الأمنية: عند الاشتباه بوجود متفجرات أو عمل إرهابي — ويجري إبلاغها عبر الرقم 104.","وزارة الصحة: تجهيز المستشفيات القريبة.","مديرية الكهرباء: قطع الكهرباء عن المنطقة المحيطة.","دوائر الماء والغاز: قطع خطوط الماء والغاز.","هيئة البيئة: إذا انتشرت المواد الكيميائية في البيئة.","مركز عمليات الطوارئ (EOC): للحوادث الكبيرة التي تشارك فيها جهات عديدة."]},{heading:"6. مراحل الاستجابة (5 مراحل)",body:"يمرّ كل حادث بالمراحل الخمس الآتية:",points:["1. الاكتشاف (Detection): الحساسات، أو إنذار الحريق، أو الشهود.","2. الإبلاغ (Notification): الاتصال بالرقم 115، وإبلاغ فريق ERT وضابط الاتصال.","3. الاستجابة (Response): يعمل فريق ERT حتى تصل فرق الدفاع المدني (115).","4. تخفيف الخطر (Mitigation): إطفاء الحريق، والإنقاذ، وإزالة التلوث.","5. التعافي (Recovery): التنظيف، والتحليل، والتقييم بعد الحادث.","يجب توثيق كل مرحلة (خطة عمل الحادث Incident Action Plan — IAP).","الساعة الذهبية (Golden Hour): العلاج السريع بعد الإصابة البالغة يزيد فرص النجاة — لذا فإن الاتصال السريع بالرقم 122 أمر مهم."]},{heading:"7. التمارين والتدريب (Drills & Training)",body:"التمارين أساس الاستعداد (الجدول المقترح):",points:["تمرين المحاكاة المكتبية (Tabletop Exercise): مرة كل 3 أشهر — سيناريو يُناقش حول الطاولة.","التمرين الوظيفي (Functional Drill): مرة كل 6 أشهر — لفريق ERT فقط، لا للمبنى كله.","التمرين الشامل (Full-Scale Drill): مرة في السنة — للمصنع كله بالاشتراك مع الدفاع المدني (115).","التقييم: تقرير ما بعد التمرين (After-Action Report) في أقرب وقت ممكن.","تدريب فريق ERT: بصورة مستمرة وبحسب المهام، ومرة واحدة في السنة على الأقل.","معايير الكفاءة: NFPA 1081 (Facility Fire Brigade Member)، وOSHA 1910 Subpart L، وICS-100/200.","تمرين مشترك مع الدفاع المدني (115): مرة في السنة لأغراض التنسيق."]}],media:[{kind:"video",src:"media/videos/fact_ert_response.mp4",title:"تمرين الاستجابة لفريق ERT",description:"تمرين شامل في مصنع نفط"},{kind:"image",src:"media/images/fact_ics_chart.png",title:"هيكل نظام قيادة الحوادث (ICS)",description:"هيكل نظام قيادة الحوادث (ICS)"}],quiz:[{question:"كيف يُحدَّد حجم فريق الاستجابة للطوارئ (ERT) في المصنع؟",options:[{text:"بنسبة ثابتة: عضو (1) مدرَّب لكل 100 موظف في كل مناوبة",correct:!1},{text:"بناءً على تقييم مخاطر المصنع ومهام الفريق",correct:!0},{text:"بنسبة ثابتة: 1 لكل 200 موظف",correct:!1},{text:"بنسبة ثابتة: 1 لكل 25 موظفًا",correct:!1}],explanation:"لا يحدّد NFPA 600 نسبة ثابتة لعدد الأعضاء قياسًا بعدد الموظفين؛ بل يحدّد كل مصنع حجم فريقه بحسب مخاطره ومهامه."},{question:"ما معنى الساعة الذهبية (Golden Hour)؟",options:[{text:"الساعة الأولى من كل مناوبة عمل، حين يجب إجراء جميع فحوص السلامة",correct:!1},{text:"الوقت الأول بعد الإصابة البالغة، الذي يكون فيه العلاج السريع بالغ الأهمية",correct:!0},{text:"وقت الظهيرة",correct:!1},{text:"حرارة النهار",correct:!1}],explanation:"الساعة الذهبية (Golden Hour) هي الفترة التي تلي الإصابة البالغة، والتي يزيد فيها الإيصال السريع للمصاب إلى العلاج من فرص نجاته؛ لذا اتصل فورًا بالرقم 122."},{question:"في نظام ICS، ما عمل ضابط الاتصال (Liaison Officer)؟",options:[{text:"يُطفئ الحريق",correct:!1},{text:"يتواصل مع الجهات الخارجية",correct:!0},{text:"يُجري CPR",correct:!1},{text:"يحرس البوابة ويراقب الدخول",correct:!1}],explanation:"يتواصل ضابط الاتصال مع الدفاع المدني (115)، والشرطة (104)، والإسعاف (122)، والجهات الأخرى."},{question:"ما عمل مستوى العمليات (Operations) في HazMat؟",options:[{text:"الإبلاغ فقط",correct:!1},{text:"دفاعي (Defensive) — منع الانتشار من مسافة بعيدة",correct:!0},{text:"هجومي (Offensive) — دخول المنطقة الساخنة لإيقاف التسرّب من مسافة قريبة",correct:!1},{text:"التخصّص (Specialist)",correct:!1}],explanation:"مستوى العمليات (Operations) دفاعي (Defensive): منع انتشار المادة من مسافة بعيدة، وليس العمل عن قرب (Offensive)."},{question:"ما المنطقة الساخنة (Hot Zone) في HazMat؟",options:[{text:"مكان بارد وآمن يبقى فيه مركز القيادة وفرق الدعم",correct:!1},{text:"المنطقة التي يُزال فيها التلوث عن الأشخاص والمعدات قبل خروجهم منها",correct:!1},{text:"المنطقة الأشد خطرًا — لا يدخلها إلا فنيو HazMat بمعدات الوقاية الشخصية المناسبة",correct:!0},{text:"منطقة التجمع",correct:!1}],explanation:"المنطقة الساخنة هي موقع المادة الخطرة؛ ولا يدخلها إلا فنيو HazMat بمعدات وقاية شخصية من المستوى A أو B."},{question:"عندما تصل فرق الدفاع المدني (115) إلى موقع الحادث، إلى من تنتقل القيادة؟",options:[{text:"يستمر فريق ERT في القيادة",correct:!1},{text:"قائد فرق الدفاع المدني (115)",correct:!0},{text:"مدير المصنع",correct:!1},{text:"الشرطة",correct:!1}],explanation:"نقل القيادة (ICS Transfer): عند وصول الدفاع المدني (115)، تنتقل القيادة إلى قائد فرق الدفاع المدني ويتولّى فريق ERT المساندة."},{question:"أطفأ فريق الطوارئ حريقًا صغيرًا بالكامل. هل كان يجب الاتصال بالرقم 115 منذ البداية؟",options:[{text:"نعم — يُبلَّغ 115 فورًا مهما كانت التوقعات",correct:!0},{text:"لا — فقط إذا عجز الفريق عن السيطرة",correct:!1},{text:"لا — المدير وحده يقرر لاحقًا الاتصال",correct:!1},{text:"نعم — لكن بعد أن يصل الحريق إلى قسم آخر",correct:!1}],explanation:"قد يكبر الحادث خلال دقائق، وتحتاج فرق 115 إلى وقت للوصول؛ الاتصال المبكر لا يضر، أما التأخير فقد يكلّف أرواحًا."},{question:"عند وصول فرق 115، أيّ تصرّف من المشرف خطأ؟",options:[{text:"إصدار أوامر منفصلة بنفسه لفرق 115",correct:!0},{text:"تسليم مخطط الموقع وصحائف البيانات لقائد 115",correct:!1},{text:"الإبلاغ عن المفقودين وآخر مكان شوهدوا فيه",correct:!1},{text:"إرشاد القائد إلى نقاط فصل الغاز والكهرباء",correct:!1}],explanation:"تنتقل القيادة إلى قائد واحد من 115، والأوامر الموازية تسبب الارتباك؛ أما التصرفات الثلاثة الأخرى فهي مساندة صحيحة."}],steps:[{title:"أطلق الإنذار واتصل بالرقم 115 فورًا",detail:"اتصل بالرقم 115 (و122 إن وُجد مصابون) حتى لو توقّع فريق الطوارئ السيطرة على الحادث: اذكر الموقع ونوع الحادث وعدد المصابين والمواد الخطرة وطريق الوصول.",critical:!0},{title:"قائد واحد وإخلاء",detail:"قائد الحادث (IC) شخص واحد فقط. يبدأ الإخلاء، ولا يقوم فريق الطوارئ إلا بما تدرّب عليه؛ وإذا كبر الحادث انسحب الفريق أيضًا.",critical:!0},{title:"أحصِ الجميع عند نقطة التجمع",detail:"يُحصى الموظفون والمقاولون والزوار، ويُبلَّغ القائد باسم كل مفقود وآخر مكان شوهد فيه.",critical:!0},{title:"استعد لوصول فرق 115",detail:"افتح البوابة وطريق الوصول، وينتظر ضابط الارتباط قائد فرق 115 عند البوابة ومعه مخطط الموقع ونقاط فصل الكهرباء والغاز وصحائف بيانات السلامة."},{title:"سلّم القيادة لفرق 115 وساندها",detail:"بعد إيجاز قصير (الوضع والمخاطر والمفقودون وما تم من إجراءات) تنتقل القيادة إلى قائد فرق 115. ولا يعمل فريق الطوارئ إلا بطلبه، ولا يدخل غير المدرَّبين المنطقة الساخنة (Hot Zone).",critical:!0},{title:"بعد الحادث: التوثيق والمراجعة",detail:"اجمع سجلّ الحادث والصور وإفادات الشهود، وأجرِ مراجعة ما بعد الحادث، وصحّح الخطة."}],warnings:["لا تؤخّر الاتصال بالرقم 115 ليحاول فريق الطوارئ «أولًا»: فالحريق وتسرّب المواد قد يكبران خلال دقائق.","لا يدخل غير المدرَّبين المنطقة الساخنة، ولا يدخل أحد مكانًا ضيقًا مغلقًا (كخزان أو حفرة) لإنقاذ شخص سقط فيه: فهواء المكان قد يقتل المنقذ أيضًا.","لا تُصدر أوامر موازية لأوامر قائد الحادث: قائد واحد وقناة اتصال واحدة."],tips:["احتفظ بصندوق «جاهز» عند البوابة: مخطط الموقع وصحائف البيانات وقائمة موظفي الوردية والمفاتيح.","تدرّب في التمارين على مكالمة 115 بمعلومات كاملة.","أبقِ أجهزة اللاسلكي مشحونة وعلى القناة المتفق عليها.","بالتنسيق مع الدفاع المدني، ادعُ فرق 115 للتعرف على الموقع ومخاطره قبل أي حادث."],activity:{prompt:"حريق في مخزن المذيبات بمصنع كيميائي. يحدّ فريق الطوارئ من انتشاره بالتبريد. وصلت فرق 115. أنت قائد فريق الطوارئ. ماذا تفعل؟",options:[{text:"أواصل إصدار الأوامر وأطلب من فرق 115 الانتظار حتى ننتهي",correct:!1,feedback:"عند وصول 115 تنتقل القيادة إلى قائدها؛ ووجود قائدين يسبب الارتباك والخطر."},{text:"أوجز لقائد 115 (الوضع والمخاطر والمفقودون وصحائف البيانات ونقاط الفصل) وأسلّمه القيادة؛ ويعمل فريقنا بطلبه",correct:!0,feedback:"صحيح: نقل القيادة مع معلومات كاملة هو أساس التنسيق."},{text:"أسحب الفريق كله بسرعة ونغادر دون إيجاز",correct:!1,feedback:"من دون معلوماتك لا تعرف فرق 115 المواد الموجودة ولا إن كان هناك مفقودون."},{text:"أرسل أعضاء الفريق إلى داخل المخزن لإخراج البراميل قبل التسليم",correct:!1,feedback:"دخول مخزن مشتعل فيه براميل مذيبات يحمل خطر الانفجار؛ وهذا قرار قائد فرق 115."}]},caseStudy:[{prompt:"إنذار طوارئ: عامل سقط مغمًى عليه في حفرة مضخة، وهناك رائحة كيميائية. يريد عامل آخر النزول لإخراجه. أنت أول عضو من فريق الطوارئ في المكان. ماذا تفعل؟",options:[{text:"أمنعه من النزول، وأُبعد الجميع بعكس اتجاه الريح، وأتصل بالرقمين 115 و122 مع ذكر «احتمال هواء سام»، وأبلغ قائد الفريق",correct:!0,feedback:"صحيح: كثير من المنقذين ماتوا في الأماكن الضيقة المغلقة؛ والإنقاذ يتم بأجهزة تنفس وفرق مدرَّبة."},{text:"أحبس أنفاسي وأنزل بسرعة لإخراجه",correct:!1,feedback:"الهواء السام أو الخالي من الأكسجين قد يُفقدك الوعي خلال أنفاس قليلة؛ فيصبح هناك ضحيتان."},{text:"أُدلي حبلًا وأطلب منه أن يربط نفسه به",correct:!1,feedback:"الشخص فاقد الوعي لا يستطيع ربط الحبل؛ وهذا يضيّع الوقت دون إبلاغ 115."},{text:"أضع قطعة قماش مبللة على فمي وأنفي وأدخل",correct:!1,feedback:"القماش المبلل لا يحمي من الغازات السامة ولا من نقص الأكسجين."}]},{prompt:"فرق 115 في الطريق. يطلب منك قائد فريق الطوارئ أن تكون ضابط الارتباط. ماذا تجهّز؟",options:[{text:"أنتظر قائد 115 عند البوابة ومعي مخطط الموقع وصحيفة بيانات المادة ومعلومات الحفرة وعدد المصابين ونقاط الفصل",correct:!0,feedback:"صحيح: ضابط الارتباط هو صوت الموقع الوحيد أمام 115، والمعلومات الجاهزة توفّر الوقت."},{text:"أعود إلى الحفرة لأرى إن كان العامل يتحرك",correct:!1,feedback:"هذا ليس دورك ويقرّبك من الهواء الخطر؛ وفرق 115 تحتاجك عند البوابة."},{text:"أتصل بأسرة العامل قبل أي شيء آخر",correct:!1,feedback:"إبلاغ الأسرة يتم لاحقًا عبر الطريق المنظم؛ ومهمتك الآن تجهيز المعلومات لفرق 115."},{text:"أقف عند البوابة دون أي معلومات، فالقائد سيكتشف بنفسه",correct:!1,feedback:"من دون المخطط وصحيفة البيانات تضيّع فرق 115 وقتًا ثمينًا في البحث."}]}],realCase:"ليلًا، انفجر خرطوم في منطقة المضخات بمستودع للوقود فتناثر الوقود على الأرض. أطلق أحد العمال الإنذار، واتصل قائد فريق الطوارئ فورًا بالرقم 115 وذكر الموقع ونوع الوقود وبوابة الوصول. أُوقفت المضخات من غرفة التحكم، وأُبعدت مصادر الشرر واللهب، وتوجّه كل من لا حاجة إليه إلى نقطة التجمع وأُحصوا. وانتظر ضابط الارتباط قائد 115 عند البوابة ومعه مخطط الموقع وصحيفة البيانات. انتقلت القيادة إلى 115، وساند الفريق بإمدادات الرغوة. وحدّثت مراجعة لاحقة خطة فحص الخراطيم."},{id:20,code:"FACT-120",icon:"FlameKindling",accent:"#dc2626",title:"تصنيف الحرائق في المصانع",subtitle:"Industrial Fire Classes — NFPA 30/484/654",summary:"تصنيف خاص بالمصانع: السوائل، والغازات، والمعادن، والغبار القابل للاشتعال",blocks:[{body:"تستخدم هذه الوحدة نظام NFPA: A المواد الصلبة، B السوائل والغازات القابلة للاشتعال، C المعدات الكهربائية، D المعادن، K زيت الطهي. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. والمعايير الخاصة بالمصانع هي: السوائل القابلة للاشتعال (NFPA 30)، والمعادن القابلة للاشتعال (NFPA 484)، والغبار القابل للاشتعال (NFPA 654). ومنذ إصدار 2025، دُمج NFPA 484 وNFPA 654 في المعيار NFPA 660."},{heading:"1. الفئة A — المواد الصلبة القابلة للاشتعال في المصنع",body:"المواد الصلبة الشائعة في المصانع:",points:["الوقود: الورق، والكرتون، والقماش، والخشب، والمطاط، والبلاستيك، والمنصّات النقالة (Pallets).","تخلّف هذه المواد جمرًا ونارًا كامنة؛ لذا برّد المكان بالماء بعد الإطفاء وراقبه.","في المصانع: تنشر مخازن الورق والكرتون والمنصّات الخشبية النار بسرعة.","المطفأة: الماء، الرغوة، مسحوق ABC.","المنصّات الفارغة المكدّسة خطر كبير: لا تكدّسها عاليًا، وخزّنها في الخارج أو في مكان مزوّد بالمرشّات (Sprinklers).","المعيار: NFPA 13 (أنظمة المرشّات)، الذي يشمل حماية المخازن أيضًا.","أمثلة في المصانع: المخازن وخطوط التعبئة والتغليف (Packaging Lines)."]},{heading:"2. الفئة B — السوائل القابلة للاشتعال في المصنع",body:"إحدى أخطر الفئات في المصانع:",points:["الوقود: البنزين، والنفط الأبيض (الكيروسين)، والديزل، والأسيتون (Acetone)، والتولوين (Toluene)، والزايلين (Xylene).","نقطة الوميض (Flash Point): البنزين نحو -43°C، والأسيتون -20°C، والديزل 52°C أو أكثر.","حدود الانفجار (LEL/UEL): أدنى تركيز وأعلى تركيز للبخار في الهواء يمكن أن يشتعل:","• البنزين: 1.4-7.6%.","• الأسيتون: 2.5-12.8%.","• الميثانول (Methanol): 6-36%.","المطفأة: الرغوة (AFFF أو الرغوة الخالية من الفلور)، CO₂، مسحوق ABC. وللأسيتون والميثانول والكحولات والمذيبات القطبية الأخرى: CO₂ أو المسحوق الجاف أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها.","لا ترشّ نفثة ماء مباشرة على السائل — فهي تنشر النار. ويحدث BLEVE (Boiling Liquid Expanding Vapor Explosion) عندما يسخن خزان مضغوط بفعل النار.","فئات السوائل وفق NFPA 30 (Flash Point = نقطة الوميض، Boiling Point = نقطة الغليان):","• الفئة I (سوائل قابلة للاشتعال – Flammable): نقطة الوميض أقل من 37.8°C — IA (الوميض < 22.8°C والغليان < 37.8°C)، IB (الوميض < 22.8°C والغليان 37.8°C أو أكثر)، IC (الوميض من 22.8 إلى < 37.8°C).","• الفئة II (سوائل قابلة للاحتراق – Combustible): نقطة الوميض من 37.8 إلى < 60°C.","• الفئة III (سوائل قابلة للاحتراق – Combustible): IIIA من 60 إلى < 93°C، وIIIB 93°C أو أكثر.","جدران الاحتواء (Diking): وفق NFPA 30، يجب ألّا تقل سعة منطقة الاحتواء عن كمية السائل التي يمكن أن تنسكب من أكبر خزان ممتلئ (100%)؛ أما نسبة 110% فتشترطها بعض القوانين والإرشادات الأخرى (لاستيعاب مياه الأمطار أيضًا).","كثافة البخار (Vapor Density): بخار البنزين أثقل من الهواء (نحو 3-4 مرات) ويتجمّع في الأماكن المنخفضة."]},{heading:"3. الغازات القابلة للاشتعال — NFPA: الفئة B، EN 2: الفئة C",body:"غازات المصانع: الأسيتيلين، والبروبان، والهيدروجين:",points:["المصادر: الأسيتيلين (Acetylene) للحام، والبروبان (Propane) لبعض الرافعات الشوكية، والهيدروجين (Hydrogen) الناتج عن شحن بطاريات الرصاص الحمضية (Lead-acid).","هذه المواد غازية في درجات الحرارة العادية وتشتعل بسهولة. حدود الانفجار في الهواء: الهيدروجين 4-75%، والبروبان 2.1-9.5%، والأسيتيلين من 2.5% فأكثر. (-253°C هي نقطة غليان الهيدروجين، وليست نقطة وميضه.)","تتجاوز حرارة لهب الأكسي-أسيتيلين (Oxy-Acetylene) 3000°C.","يُكوّن الأسيتيلين مع النحاس (Copper) مادة متفجرة (Copper Acetylide)؛ لا تستخدم أنابيب ومعدات نحاسية غير مناسبة.","الإطفاء: أولًا، أغلق صمام الغاز إذا كان ذلك آمنًا. ولا تُطفئ نار الغاز إذا لم تستطع إيقاف تدفقه — فالغاز المتسرّب قد يُحدث انفجارًا.","تستخدم فرق الدفاع المدني (115) رذاذ الماء (Water Spray) من بعيد لتبريد الأسطوانات والخزانات، لا لإطفاء لهب الغاز.","أجهزة كشف الغاز (Gas Detectors) في مخازن الغاز: يجب أن يعمل الإنذار قبل بلوغ LEL بفارق كبير (عادةً عند 10-20% من LEL).","في المصانع: أماكن اللحام، وأماكن شحن الرافعات الشوكية، وغرف البطاريات."]},{heading:"4. الفئة D — المعادن القابلة للاشتعال (NFPA 484)",body:"المعادن القابلة للاشتعال — من أخطر الأنواع:",points:["الوقود: المغنيسيوم، والتيتانيوم، ومسحوق الألمنيوم، والصوديوم، والليثيوم المعدني (Lithium Metal).","تحترق هذه المعادن بحرارة عالية جدًا وتُصدر ضوءًا شديدًا جدًا؛ لا تنظر مباشرة إلى اللهب.","الماء ممنوع! Mg + H₂O → MgO + H₂ (يتكوّن الهيدروجين وقد ينفجر).","CO₂ ممنوع! 2Mg + CO₂ → 2MgO + C (المغنيسيوم يحترق حتى في CO₂).","مطافئ الفئة D فقط، وفقط التي يذكر ملصقها هذا المعدن: فالمادة تختلف من معدن لآخر (مثل مسحوق قائم على كلوريد الصوديوم (NaCl) أو الغرافيت؛ ومسحوق النحاس لليثيوم). ولا تستخدم الماء أو المسحوق العادي أو الرغوة أبدًا. ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة SDS للمعدن وكان جافًا تمامًا.","أمثلة في المصانع: صهر الألمنيوم، وخراطة المغنيسيوم، وبطاريات الليثيوم المعدني.","NFPA 484: تخزين المعادن القابلة للاشتعال ومناولتها وحمايتها (أصبح الآن جزءًا من NFPA 660).","مسحوق الألمنيوم: ينطوي أيضًا على خطر انفجار الغبار (NFPA 654 / 660).","الاستجابة: اتصل فورًا بالرقم 115 ولا تستخدم إلا مطفأة الفئة D التي يذكر ملصقها هذا المعدن. أما بطاريات الليثيوم أيون (Li-ion) فلا تحتوي على ليثيوم معدني، وتُبرَّد بالماء."]},{heading:"5. الغبار القابل للاشتعال — انفجار الغبار (NFPA 654)",body:"خطر قاتل في المصانع:",points:["خماسي الغبار (Dust Pentagon): الوقود (الغبار) + الأكسجين + الحرارة + الانتشار في الهواء + الحيّز المغلق.","المصادر: الطحين، والسكر، والخشب، والفحم، وغبار المعادن، والبلاستيك.","تختلف أدنى درجة حرارة للاشتعال (MIT) باختلاف نوع الغبار؛ راجع صحيفة SDS أو نتائج اختبار الغبار.","ويختلف كذلك أدنى تركيز للانفجار (MEC) باختلاف نوع الغبار؛ والغبار المنتشر في الهواء خطِر دائمًا.","الانفجار الأولي (Primary): داخل جهاز ما (مثل المرشّح أو المطحنة).","الانفجار الثانوي (Secondary): يُثير الانفجار الأولي الغبار المتراكم على الأرض والرفوف والأنابيب، فيحدث انفجار أكبر وأشد فتكًا.","تقليل الخطر: أنظمة تجميع الغبار، وفتحات تنفيس الانفجار (Explosion Vents)، وأنظمة الإخماد.","النظافة: قد تُشكّل طبقة من الغبار بسماكة 0.8 مم (1/32 inch) على أكثر من 5% من مساحة الأرضية خطرًا (NFPA 654 / OSHA).","مثال: في عام 2008، في مصنع السكر Imperial Sugar (الولايات المتحدة)، أودى انفجار غبار السكر بحياة 14 عاملًا (CSB).","المعايير: NFPA 654 (الآن NFPA 660) وOSHA 29 CFR 1910.272 (لمخازن الحبوب)."]},{heading:"6. مراحل تطوّر الحريق في المصنع",body:"4 مراحل قياسية — وقد تكون النار في المصانع أسرع:",points:["البداية (Incipient): نار صغيرة — يمكن لشخص مدرَّب إطفاؤها بالمطفأة اليدوية المناسبة بعد إطلاق الإنذار والاتصال بالرقم 115، وطريق الخروج خلفه؛ وإذا لم تنطفئ فورًا، فاخرج.","النمو (Growth): تزداد النار والدخان بسرعة وتعمل المرشّات — اخرج واتصل بالرقم 115.","الاشتعال الكامل (Fully Developed): بعد الاشتعال الوميضي (Flashover) — لفرق الدفاع المدني (115) فقط.","الخمود (Decay): يقلّ الوقود، لكن خطر الارتداد اللهبي (Backdraft) والانهيار يبقى قائمًا.","في المصانع، يمكن للمخازن المرتفعة والمنصّات النقالة والسوائل أن توصل النار إلى مرحلة الاشتعال الكامل أسرع مما يحدث في المنازل.","خزانات الغاز والسوائل المضغوطة إذا سخنت بفعل النار قد تنفجر بظاهرة BLEVE — أخلِ المنطقة المحيطة بسرعة.","يجب أن تُبقي خطة المصنع طريق وصول فرق الدفاع المدني (115) ومآخذ مياه الإطفاء (Hydrants) جاهزة ومفتوحة.","مراقب الحريق بعد العمل الساخن (Hot Work): في أثناء العمل ولمدة ساعة واحدة على الأقل بعد انتهائه، ثم المراقبة مدة تصل إلى 3 ساعات إضافية بحسب قرار المسؤول عن التصريح (NFPA 51B)."]},{heading:"7. الحمل الحريقي (Fire Load) وتقييم المخاطر",body:"فحص المخاطر في المصنع:",points:["كثافة الحمل الحريقي (Fire Load Density — MJ/m²): كمية الطاقة التي يمكن أن تطلقها المواد القابلة للاشتعال في كل متر مربع. المتوسطات وفق EN 1991-1-2 (Eurocode 1):","• المساكن (Dwelling): نحو 780 MJ/m².","• المكاتب (Office): نحو 420 MJ/m².","• المكتبات (Library): نحو 1500 MJ/m².","• المخازن والمصانع: يُحسب بحسب المواد المخزّنة، وكثيرًا ما يكون أعلى من هذه القيم.","تقييم المخاطر (Risk Assessment): الخطر = احتمال الحدوث (Likelihood) × شدّة العواقب (Severity).","• منخفض (Low): يُسيطر عليه بالإجراءات المعتادة.","• متوسط (Medium): يحتاج إلى ضوابط إضافية ومراقبة.","• مرتفع (High): يتطلب إجراءً عاجلًا قبل مواصلة العمل.","• مرتفع جدًا (Extreme): يتوقف العمل حتى ينخفض الخطر.","تُحدَّد مقاومة الجدران والأسقف للحريق (Fire Resistance Rating) بحسب نوع المبنى واستخدامه وفق أكواد البناء (مثل NFPA 101 وNFPA 5000).","حدّث تقييم مخاطر المصنع (مثل HVA) مرة واحدة في السنة على الأقل، وبعد كل تغيير كبير."]}],media:[{kind:"video",src:"media/videos/fact_dust_explosion.mp4",title:"انفجار الغبار",description:"عرض توضيحي لانفجار الغبار"},{kind:"image",src:"media/images/fact_fire_classes.png",title:"جدول فئات الحريق",description:"تصنيف الحرائق في المصانع"}],quiz:[{question:"لحريق من الفئة D، أيّ مطفأة تكون مناسبة؟",options:[{text:"أقرب مطفأة مسحوق جاف من نوع ABC",correct:!1},{text:"الماء",correct:!1},{text:"مطفأة الفئة D التي يذكر ملصقها هذا المعدن",correct:!0},{text:"مطفأة ثاني أكسيد الكربون CO₂ موجّهة إلى قاعدة النار",correct:!1}],explanation:"لا تصلح إلا مطفأة من الفئة D أو مادة يذكر ملصقها المعدن المشتعل؛ فالمادة تختلف من معدن لآخر. لا تستخدم الماء أو CO₂ أو مسحوق ABC."},{question:"ما معنى BLEVE؟",options:[{text:"معدات طوارئ لتنفيس بخار السائل المشتعل (Burning Liquid Emergency Venting Equipment)",correct:!1},{text:"انفجار البخار المتمدّد للسائل المغلي (Boiling Liquid Expanding Vapor Explosion)",correct:!0},{text:"نظام المرشّات",correct:!1},{text:"فئة الغاز",correct:!1}],explanation:"BLEVE هو انفجار خزان سائل مضغوط عندما يسخن بفعل النار فيتمدّد البخار بسرعة."},{question:"كم عنصرًا في خماسي الغبار (Dust Pentagon)؟",options:[{text:"3",correct:!1},{text:"4",correct:!1},{text:"5",correct:!0},{text:"6",correct:!1}],explanation:"خمسة عناصر: الوقود + الأكسجين + الحرارة + الانتشار + الحيّز المغلق."},{question:"ماذا يُكوّن الأسيتيلين مع النحاس (Copper)؟",options:[{text:"لا يحدث شيء — النحاس آمن تمامًا مع الأسيتيلين",correct:!1},{text:"أسيتيليد النحاس (Copper Acetylide) — مادة متفجرة",correct:!0},{text:"التنظيف",correct:!1},{text:"طبقة خضراء واقية تتكوّن على أنبوب النحاس",correct:!1}],explanation:"يُكوّن الأسيتيلين مع النحاس مادة متفجرة حساسة (Copper Acetylide) تنفجر بالصدم أو بالحرارة."},{question:"ما الخطر الذي ينطوي عليه مسحوق الألمنيوم (Aluminum Powder)؟",options:[{text:"الفئة A، مثل الخشب والورق",correct:!1},{text:"الفئة D وانفجار الغبار",correct:!0},{text:"الغاز فقط",correct:!1},{text:"لا خطر فيه",correct:!1}],explanation:"مسحوق الألمنيوم معدن قابل للاشتعال (الفئة D) وغبار قابل للاشتعال في آن واحد (NFPA 484 / 654، الآن NFPA 660)."},{question:"وفقًا لـ EN 1991-1-2، كم يبلغ متوسط الحمل الحريقي في المساكن (Dwelling) تقريبًا؟",options:[{text:"100 MJ/m²",correct:!1},{text:"230 MJ/m²",correct:!1},{text:"420 MJ/m²",correct:!1},{text:"780 MJ/m²",correct:!0}],explanation:"يبلغ متوسط الحمل الحريقي في المساكن نحو 780 MJ/m²، وفي المكاتب نحو 420 MJ/m² (EN 1991-1-2، الجدول E.4)."},{question:"اشتعلت مقلاة الزيت في مطبخ الموظفين. أي مطفأة مناسبة؟",options:[{text:"مطفأة المادة الكيميائية الرطبة (NFPA K، EN F)",correct:!0},{text:"مطفأة CO₂ لأنها لا تترك بقايا",correct:!1},{text:"مطفأة الماء لأنها تبرّد الزيت",correct:!1},{text:"مطفأة بودرة ABC لأنها تغطي كل الفئات",correct:!1}],explanation:"زيت الطبخ من الفئة K (NFPA) التي تقابلها الفئة F في EN 2؛ ومطفأة المادة الكيميائية الرطبة تكوّن طبقة شبيهة بالصابون وتبرّد الزيت. والماء ينشر النار، وABC لا تغطي K/F. واقطع مصدر الحرارة إن كان ذلك آمنًا."},{question:"بجانب لوحة مطفأتان: على إحداهما شريط أسود وعلى الأخرى شريط أزرق. كيف تختار؟",options:[{text:"أقرأ الملصق: الفئة والمادة مكتوبتان عليه",correct:!0},{text:"آخذ ذات الشريط الأسود لأن الأسود يعني الكهرباء دائمًا",correct:!1},{text:"آخذ ذات الشريط الأزرق لأن الأزرق يعني الفئة C",correct:!1},{text:"آخذ أيًّا منهما لأن ألوان الشرائط تعني الشيء نفسه",correct:!1}],explanation:"اللون ليس فئة الحريق أبدًا: فالأشرطة الملونة (مثل BS 7863) تدل على نوع المادة فقط ولا تتطابق في كل البلدان. الفئات والتعليمات مكتوبة على الملصق."}],steps:[{title:"اعرف أنواع الوقود في قسمك",detail:"حدّد: المواد الصلبة (A)، والسوائل والغازات القابلة للاشتعال (B)، والمعدات الكهربائية الموصولة بالتيار (C)، والمعادن (D)، وزيوت الطبخ (K) — بأحرف NFPA مرجعًا للمشروع. وإذا كانت الملصقات وفق EN: NFPA B (الغازات) = EN C وNFPA K = EN F."},{title:"اقرأ ملصق المطفأة",detail:"تأكد أن المطافئ القريبة مدرجة لتلك الفئات. لون المطفأة أو لون شريطها ليس فئتها؛ اقرأ الملصق دائمًا. ومطفأة ABC تغطي A وB وC فقط، لا D ولا K."},{title:"فحص «نعم أو لا» قبل PASS",detail:"قبل استخدام المطفأة يجب أن تكون كل الإجابات «نعم»: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وأُطلق الإنذار واتُّصل بالرقم 115، وأنت مدرَّب، ولا دخان أو حرارة يسدّان طريقك. فإن كانت إحدى الإجابات «لا» أو لم تنطفئ النار فورًا، فاخرج.",critical:!0},{title:"حريق الغاز: أوقف الغاز فقط إذا كان ذلك آمنًا",detail:"يغلق شخص مؤهَّل صمام الغاز فقط إذا كان الوصول إليه آمنًا. ولا تُطفئ لهب غاز لا يمكن إيقاف تدفقه: فالغاز غير المحترق يتجمع وقد ينفجر. وإلا فأخرج الجميع وأطلق الإنذار واتصل بالرقم 115.",critical:!0},{title:"حريق المعادن: الفئة D المدرجة فقط",detail:"لا تستخدم إلا مطفأة من الفئة D يذكر ملصقها ذلك المعدن؛ ولا تستخدم أبدًا الماء أو CO₂ أو البودرة العادية أو الرغوة. اتصل بالرقم 115؛ وإن لم يكن الحريق صغيرًا فاخرج.",critical:!0},{title:"أبلغ وحدّث تقييم المخاطر",detail:"أبلغ عن كل حريق ولو كان صغيرًا، وأرسل المطفأة المستخدمة لإعادة التعبئة، وحدّث تقييم المخاطر عند وجود مادة جديدة أو مكان جديد."}],warnings:["لا تصبّ الماء على حريق زيت الطبخ (K / F) أو على سائل قابل للاشتعال: فهو ينشر النار. وليس CO₂ ولا بودرة ABC الخيار الصحيح لزيت الطبخ؛ استخدم مطفأة المادة الكيميائية الرطبة.","لا تُطفئ لهب الغاز إذا تعذّر إيقاف الغاز: فالغاز غير المحترق يتجمع وقد ينفجر.","لا تستخدم الماء أو CO₂ أو البودرة العادية أو الرغوة على معدن مشتعل: فهي تزيد النار شدة أو تسبب انفجارًا."],tips:["اكتب في خطة الحريق للموقع فئات الحريق الرئيسية لكل قسم (أحرف NFPA المعتمدة في المشروع، مع ما يقابلها في EN إذا كانت المعدات وفق EN).","عند وصول مادة جديدة، اقرأ القسم 5 من صحيفة بيانات السلامة (تدابير مكافحة الحريق).","في الفحوص البصرية المعتادة، اقرأ ملصق كل مطفأة وأبقها في مكانها.","تذكّر: اللون ليس الفئة أبدًا؛ الملصق هو الذي يحدد."],activity:{prompt:"في منطقة اللحام، اشتعل خرطوم الأسيتيلين عند المنظّم (Regulator) ويخرج منه لهب طويل. صمام الأسطوانة في أعلاها. أنت لحّام مدرَّب. ماذا تفعل؟",options:[{text:"أطفئ اللهب بمطفأة CO₂",correct:!1,feedback:"إن لم يتوقف الغاز فإطفاء اللهب يجمع الغاز وقد ينفجر؛ وCO₂ ليس الحل الصحيح لحريق الغاز."},{text:"إن استطعت الوصول إلى صمام الأسطوانة بأمان أغلقه ليتوقف الغاز؛ وإلا أُخرج الجميع وأطلق الإنذار وأتصل بالرقم 115",correct:!0,feedback:"صحيح: حريق الغاز ينتهي بإيقاف الغاز إذا كان ذلك آمنًا؛ وإلا فالإخلاء والاتصال بالرقم 115."},{text:"أسكب الماء على اللهب لتبريده",correct:!1,feedback:"الماء لا يوقف لهب الغاز؛ وتبريد الأسطوانات من بعيد عمل فرق 115."},{text:"أحمل الأسطوانة المشتعلة إلى الخارج",correct:!1,feedback:"الأسطوانة الساخنة قد تنفجر؛ والاقتراب منها ونقلها يعرّض حياتك للخطر."}]},caseStudy:[{prompt:"في قسم تشغيل قطع المغنيسيوم، اشتعلت الرقائق في حاوية التجميع بضوء أبيض شديد. أنت مشغّل مدرَّب. ما أول ما تفعله؟",options:[{text:"أطفئها بخرطوم الماء",correct:!1,feedback:"الماء مع المغنيسيوم يولّد الهيدروجين وقد يسبب انفجارًا."},{text:"أطلق الإنذار وأتصل بالرقم 115، ولا أستخدم مطفأة الفئة D المدرجة للمغنيسيوم وفق ملصقها إلا إذا كان الحريق صغيرًا؛ وإلا أخرج",correct:!0,feedback:"صحيح: حريق المعادن يُطفأ فقط بعامل من الفئة D مدرج لذلك المعدن، وفحص «نعم أو لا» يبقى ضروريًا."},{text:"أستخدم مطفأة بودرة ABC لأنها لكل الحرائق",correct:!1,feedback:"مطفأة ABC تغطي A وB وC فقط؛ ولا تعمل على المعادن وقد تنشر النار."},{text:"أستخدم مطفأة CO₂ لقطع الأكسجين",correct:!1,feedback:"المغنيسيوم يحترق حتى في CO₂؛ واستخدام CO₂ على المعادن ممنوع."}]},{prompt:"بدأت النار تمتد إلى الغبار على آلة قريبة، والدخان يزداد. ماذا تفعل؟",options:[{text:"أواصل استخدام عامل الفئة D حتى النهاية",correct:!1,feedback:"لم يعد الحريق صغيرًا وقد يسبب الغبار انفجارًا أكبر؛ فحص «نعم أو لا» صار «لا»."},{text:"أتوقف وأُخرج الجميع وأغلق الأبواب وأعطي فرق 115 المعلومات (نوع المعدن والمكان وصحيفة البيانات)",correct:!0,feedback:"صحيح: عندما يكبر الحريق يصبح الواجب هو الإخلاء؛ ومعلوماتك تحمي فرق 115."},{text:"أُزيل الغبار عن الآلة بالهواء المضغوط",correct:!1,feedback:"الهواء المضغوط ينشر الغبار في الجو، وهذا أحد شروط انفجار الغبار."},{text:"أستخدم مطفأة الرغوة على الغبار",correct:!1,feedback:"الرغوة تحتوي على الماء وهي ممنوعة على المعادن المشتعلة."}]}],realCase:"في مصنع للبلاستيك، رأت عاملة دخانًا يتصاعد من كومة كراتين قرب لوحة كهرباء. وقبل أي تصرف تحققت: الحريق صغير، والإنذار أُطلق واتُّصل بالرقم 115، وطريق الخروج خلفها، وهي مدرَّبة. قرأت الملصق واختارت مطفأة مدرجة للمواد الصلبة العادية وللمعدات الكهربائية الموصولة بالتيار، وصوّبت نحو قاعدة النار فانطفأت. وراقبت المكان وأبلغت عن الحادث. ووجدت المراجعة أن الكراتين كانت ملاصقة للوحة؛ فنُقل مكان التخزين وعُلّمت المنطقة أمام اللوحة لتبقى خالية."},{id:21,code:"FACT-121",icon:"ShowerHead",accent:"#2563eb",title:"أنظمة إطفاء الحريق في المصانع",subtitle:"Portable Extinguishers + Fixed Systems (Sprinkler/Foam/CO₂)",summary:"المطافئ اليدوية وأنظمة إطفاء الحريق الثابتة في المصانع",blocks:[{body:"تحتاج المصانع إلى مستويين من إطفاء الحريق: 1) المطافئ اليدوية (Portable Extinguishers) للحرائق الصغيرة في مرحلتها الأولى، 2) أنظمة الإطفاء الثابتة (Fixed Suppression Systems) للحماية المستمرة. وبحسب نوع الخطر: المرشّات (NFPA 13)، والرغوة (NFPA 11 / 16)، وCO₂ (NFPA 12)، والمسحوق الجاف (NFPA 17)، والعامل النظيف (Clean Agent — NFPA 2001). وتشرح هذه الوحدة هذه الأنظمة وجدول الفحص."},{heading:"1. المطافئ اليدوية — الاختيار في المصنع",body:"7 أنواع رئيسية وجدول الاختيار:",points:["مسحوق ABC (Multi-purpose): النوع الأكثر انتشارًا للممرات والأماكن العامة — A، B، C (وليس D وK).","CO₂: للوحات الكهربائية وغرف الخوادم — B، C.","الرغوة (AFFF / Foam): لمخازن السوائل ومناطق جدران الاحتواء — A، B.","المادة الكيميائية الرطبة (Wet Chemical): لمطبخ المصنع ومقصفه — K.","العامل النظيف (Clean Agent): لغرف الخوادم وغرف التحكم.","الفئة D (مادة يذكر ملصقها المعدن المستخدم في المكان): لخراطة المعادن وصهر الألمنيوم.","الرذاذ المائي Water Mist (قطيرات دقيقة من ماء منزوع المعادن): للفئة A، وبعض الطرازات للفئة C — بحسب اعتماد الجهاز (Listing).","مستويات الخطر وفق NFPA 10 (الحد الأدنى لتصنيف مطفأة الفئة A):","• خطر منخفض (Light Hazard — المكاتب): 2-A.","• خطر عادي (Ordinary Hazard — المصنع العادي): 2-A.","• خطر مرتفع (Extra Hazard — مصنع فيه كميات كبيرة من المواد القابلة للاشتعال): 4-A.","مسافة الوصول (Travel Distance) إلى المطفأة:","• الفئة A: حتى 23 مترًا (75 قدمًا) في جميع المستويات.","• الفئة B: 9 أو 15 مترًا (30 / 50 قدمًا) بحسب تصنيف المطفأة ومستوى الخطر."]},{heading:"2. أنظمة المرشّات — NFPA 13",body:"أهم نظام ثابت في كثير من المصانع:",points:["4 أنواع من أنظمة المرشّات:","• الأنابيب الرطبة (Wet Pipe): الأنابيب مملوءة بالماء دائمًا — أسرع استجابة والنوع الأكثر انتشارًا.","• الأنابيب الجافة (Dry Pipe): الأنابيب مملوءة بالهواء أو النيتروجين المضغوط — للأماكن التي تنخفض فيها الحرارة إلى ما دون 4°C.","• التفعيل المسبق (Pre-action): لا يُفتح الصمام إلا بعد اكتشاف الحريق بالكواشف، ثم يُفتح رأس المرشّ بالحرارة — للأماكن التي تحتوي على معدات حساسة.","• الغمر (Deluge): رؤوس مفتوحة ترشّ جميعها الماء معًا — للأماكن عالية الخطورة.","درجة حرارة التشغيل (Activation Temperature) ولون الأمبولة الزجاجية:","• 57°C (برتقالي): الدرجة العادية (Ordinary) — الأماكن ذات الحرارة المنخفضة.","• 68°C (أحمر): الدرجة العادية (Ordinary) — الأكثر انتشارًا في المكاتب والمصانع.","• 79°C (أصفر) و93°C (أخضر): الدرجة المتوسطة (Intermediate) — الأماكن الأكثر حرارة.","• 141°C (أزرق): الدرجة العالية (High) — غرف المراجل وقرب المعدات الساخنة.","مساحة الحماية لكل رأس عادي (Standard Spray): حتى نحو 21 m² (Light)، و12 m² (Ordinary)، و9 m² (Extra Hazard).","كثافة التصريف (Density): 0.10-0.40 gpm/ft² (نحو 4-16 mm/min) بحسب مستوى الخطر.","NFPA 25: الفحص والاختبار وفق جداول أسبوعية وشهرية وسنوية وكل 5 سنوات.","لا تُفتح المرشّات إلا في موضع الحريق؛ ولا تُفتح جميع الرؤوس معًا (باستثناء نظام الغمر Deluge)."]},{heading:"3. أنظمة الرغوة — NFPA 11 / 16",body:"لمخازن السوائل الكبيرة:",points:["3 أنواع من الرغوة بحسب نسبة التمدّد (Expansion):","• منخفضة (Low-Expansion، حتى 20:1): حرائق الخزانات وانسكاب السوائل.","• متوسطة (Medium-Expansion، من 20:1 إلى 200:1): مناطق جدران الاحتواء.","• عالية (High-Expansion، من 200:1 إلى 1000:1): حظائر الطائرات والأماكن المغلقة الكبيرة.","أنواع مركّز الرغوة (Concentrate):","• AFFF: للهيدروكربونات (البنزين، الديزل).","• AR-AFFF (Alcohol-Resistant): للمذيبات القطبية (الكحول، الأسيتون).","• Fluoroprotein: لخزانات التخزين.","• الرغوة الخالية من الفلور (Fluorine-Free Foam — F3): بديل رغوات PFAS.","معدّل التطبيق (Application Rate):","• انسكاب الهيدروكربونات: لا يقل عن نحو 4.1 L/min/m² (0.10 gpm/ft²).","• المذيبات القطبية: بحسب اعتماد الشركة المصنّعة، وهو أعلى عمومًا.","خطر PFAS: تحتوي AFFF على مواد فلورية (PFAS) تتراكم في الجسم والبيئة؛ وتتجه دول كثيرة نحو الرغوة الخالية من الفلور (F3).","في المصانع: مجمّعات الخزانات، وأماكن تحميل الصهاريج، ومصافي النفط."]},{heading:"4. أنظمة CO₂ والعامل النظيف (Clean Agent) — NFPA 12 / 2001",body:"لغرف المعدات والغمر الكلي (Total Flooding):",points:["الغمر الكلي بـ CO₂:","• تركيز التصميم: 34% على الأقل (NFPA 12)، وأكثر لبعض المواد.","• الخطر: تركيز الإطفاء قاتل للبشر — يجب ألّا يبقى أحد في الغرفة.","• إنذار ما قبل التصريف وزمن التأخير (Time Delay): يجب أن يكون كافيًا لإخلاء الغرفة قبل إطلاق الغاز (NFPA 12).","• الاستخدام: غرف المولّدات، وأماكن اختبار المحركات، ومعدات الطباعة.","العامل النظيف (Clean Agent) — FK-5-1-12 / HFC-227ea:","• NOAEL: في الأماكن المشغولة بالأشخاص، لا يتجاوز تركيز التصميم مستوى عدم ظهور أي أثر ضار (NOAEL) (NFPA 2001)؛ ومع ذلك أخلِ الغرفة.","• تركيز التصميم: عادةً نحو 4-9% بحسب نوع المادة.","• التصريف (Discharge): خلال 10 ثوانٍ للمواد الهالوكربونية (NFPA 2001).","• الاستخدام: غرف الخوادم، وغرف التحكم، وغرف لوحات التوزيع الكهربائية.","• تكلفتها أعلى بكثير من أنظمة الماء.","الهالون Halon 1301: أُوقف إنتاجه في الدول المتقدمة منذ 1994 بموجب بروتوكول مونتريال، لأنه يدمّر طبقة الأوزون؛ ولا تُركَّب به أنظمة جديدة.","الاختبار الهيدروستاتيكي للمطافئ اليدوية (NFPA 10): CO₂ كل 5 سنوات، والعامل النظيف كل 12 سنة؛ أما أسطوانات الأنظمة الثابتة فتخضع لـ NFPA 12 / 2001 ولأنظمة الأسطوانات."]},{heading:"5. أنظمة المسحوق الجاف — NFPA 17",body:"للمخاطر الخاصة:",points:["الأنظمة مسبقة التصميم (Pre-Engineered Systems):","• المطابخ التجارية: تُستخدم فيها الآن عمومًا أنظمة المادة الكيميائية الرطبة (Wet Chemical) وفق NFPA 17A، لا المسحوق الجاف.","• غرف الطلاء بالرش (Spray Booths).","• حماية المعدات والمركبات الثقيلة.","• خزانات الغمس (Dip Tanks).","المواد (Agents):","• بيكربونات الصوديوم (Sodium Bicarbonate): B، C.","• بيكربونات البوتاسيوم (Purple-K): B، C — أقوى من بيكربونات الصوديوم على حرائق الفئة B.","• فوسفات أحادي الأمونيوم (Monoammonium Phosphate): A، B، C.","• كلوريد البوتاسيوم (Potassium Chloride): B، C.","التشغيل (Activation): كاشف حرارة أو مقبض تشغيل يدوي (Manual Pull).","بعد التصريف: ينتشر المسحوق في كل مكان وقد يُتلف الأجهزة الإلكترونية؛ والتنظيف صعب.","تُحدَّد مساحة الحماية لكل فوهة (Nozzle) بحسب اعتماد النظام (Listing)."]},{heading:"6. كشف الحريق — NFPA 72",body:"نظام الكشف — خط الإنذار الأول:",points:["أنواع الكواشف:","• الدخان: الكهروضوئي (Photoelectric) للحرائق البطيئة المكتومة (Smoldering)، والتأيّني (Ionization) للحرائق ذات اللهب (Flaming).","• الحرارة: درجة ثابتة (Fixed Temperature، مثل 57°C) أو الارتفاع السريع (Rate-of-Rise).","• اللهب (Flame): UV/IR — تكشف اللهب بسرعة.","• الغاز: كواشف LEL وحساسات CO.","• سحب عينات الهواء (Air-Sampling): لغرف الخوادم — النوع الأكثر حساسية.","المسافات والمساحات:","• الدخان: المسافة بين الكواشف نحو 9 أمتار (30 ft) على السقف المستوي (NFPA 72).","• الحرارة: بحسب المسافة المعتمدة للكاشف (Listed Spacing).","• اللهب: بحسب زاوية الرؤية والمسافة المعتمدة للجهاز.","الإنذار (Alarm Notification):","• الصوتي (Audible): أعلى عمومًا بـ 15 dB على الأقل من متوسط الضجيج في المكان (NFPA 72).","• الضوئي (Strobe): للأماكن الصاخبة ولذوي الإعاقة السمعية.","• الإنذار الصوتي الناطق (Voice / Mass Notification): للمباني والمصانع الكبيرة.","الفحص والاختبار: وفق جداول NFPA 72 (تُختبر أجهزة كثيرة مرة في السنة)."]},{heading:"7. جدول الفحص والصيانة",body:"وفق معايير NFPA:",points:["يوميًا / أسبوعيًا:","• الفحص البصري (قراءة مقاييس الضغط، والأضرار).","• التأكّد من عدم وجود عوائق أمام المرشّات.","• تشغيل مضخة الحريق دون تدفق الماء (No-flow Test): مضخة الديزل كل أسبوع، والكهربائية عمومًا كل شهر (NFPA 25).","شهريًا:","• الفحص البصري للمطافئ اليدوية (NFPA 10).","• فحص لوحة إنذار الحريق وإشارات الأعطال (Trouble).","• فحص أزرار الإنذار اليدوية (Manual Pull Stations) — ظاهرة وغير محجوبة.","سنويًا:","• الصيانة السنوية للمطافئ اليدوية على يد شخص مختص (وهي ليست الاختبار الهيدروستاتيكي).","• فحص المرشّات من مستوى الأرض (NFPA 25).","• أخذ عينة من مركّز الرغوة لاختبارها.","• اختبار الكواشف وأجهزة الإنذار (NFPA 72).","كل بضع سنوات:","• الاختبار الهيدروستاتيكي للمطافئ (اختبار ضغط جسم المطفأة، NFPA 10): كل 5 سنوات للماء والرغوة والمادة الكيميائية الرطبة (Wet Chemical) وCO₂ والمسحوق الجاف ذي الجسم من الفولاذ المقاوم للصدأ؛ وكل 12 سنة للمسحوق الجاف ذي الضغط المخزَّن (stored-pressure) الذي جسمه من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم، وللعامل النظيف (Clean Agent). وبشكل منفصل، كل 6 سنوات تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن التي تحتاج إلى اختبار كل 12 سنة ويُفحص داخلها على يد شخص مختص. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك.","• الفحص الداخلي لأنابيب المرشّات: كل 5 سنوات (NFPA 25).","• استبدال رؤوس المرشّات أو اختبار عينات منها بعد 50 سنة (الرؤوس العادية — NFPA 25).","التسجيل: دوّن جميع عمليات الفحص والاختبار، واحفظ السجلات وفق المعايير ومتطلبات الجهات المختصة."]}],media:[{kind:"video",src:"media/videos/fact_sprinkler_demo.mp4",title:"تشغيل المرشّ",description:"عرض توضيحي لعمل المرشّ"},{kind:"image",src:"media/images/fact_systems_chart.png",title:"جدول أنظمة الإطفاء",description:"الأنظمة الثابتة"}],quiz:[{question:"ما أهم نظام ثابت في معظم المصانع؟",options:[{text:"المطافئ اليدوية",correct:!1},{text:"المرشّات (NFPA 13)",correct:!0},{text:"CO₂ فقط",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"تعمل المرشّات تلقائيًا وتسيطر على الحريق في مرحلته الأولى، حتى عند عدم وجود أحد في المكان؛ أما المطافئ اليدوية فهي للحرائق الصغيرة فقط."},{question:"لأيّ مكان لا يصلح نظام الأنابيب الرطبة (Wet Pipe)؟",options:[{text:"غرف المعدات (ICT)",correct:!1},{text:"المكاتب ذات درجة الحرارة العادية",correct:!1},{text:"الأماكن التي تنخفض فيها الحرارة إلى ما دون 4°C",correct:!0},{text:"المخازن المدفّأة التي تبقى حرارتها فوق 10°C طوال العام",correct:!1}],explanation:"في الأماكن الباردة يتجمّد الماء في الأنابيب؛ ونظام الأنابيب الجافة (Dry Pipe) هو المناسب."},{question:"هل تُركَّب أنظمة جديدة تعمل بالهالون Halon 1301؟",options:[{text:"نعم",correct:!1},{text:"لا — أُوقف إنتاجه بموجب بروتوكول مونتريال",correct:!0},{text:"نعم — ما زال المادة المعتمدة لغرف ICT الجديدة",correct:!1},{text:"نعم، ولكن فقط في غرف الخوادم الجديدة التي لا يصلح فيها العامل النظيف",correct:!1}],explanation:"يدمّر Halon 1301 طبقة الأوزون؛ وقد أُوقف إنتاجه في الدول المتقدمة منذ 1994."},{question:"لماذا يجب أن يخرج الجميع من الغرفة قبل تصريف نظام الغمر الكلي بـ CO₂؟",options:[{text:"لا داعي لذلك، فـ CO₂ غير ضار بأي تركيز داخل الغرفة",correct:!1},{text:"لأن تركيز الإطفاء (34% فأكثر) قاتل للبشر",correct:!0},{text:"لأن CO₂ يرشّ الماء",correct:!1},{text:"لأن صوت تفريغ CO₂ عالٍ لدرجة أنه قد يُتلف سمع الأشخاص بشكل دائم",correct:!1}],explanation:"يبلغ تركيز تصميم CO₂ في أنظمة الغمر الكلي 34% على الأقل (NFPA 12)، وهذا التركيز يُفقد الإنسان وعيه ويقتله خلال وقت قصير؛ ولهذا يوجد إنذار ما قبل التصريف وزمن التأخير."},{question:"كم تبلغ مساحة الحماية لكل رأس مرشّ (Standard Spray) تقريبًا؟",options:[{text:"2-5 m²",correct:!1},{text:"12-21 m²",correct:!0},{text:"30-40 m²",correct:!1},{text:"80-100 m²",correct:!1}],explanation:"وفق NFPA 13: نحو 21 m² للخطر المنخفض، و12 m² للخطر العادي؛ وأقل من ذلك للخطر المرتفع (نحو 9 m²)."},{question:"ما الاختبار الأسبوعي لمضخة الحريق الديزل؟",options:[{text:"الفحص البصري فقط، دون تشغيل المضخة",correct:!1},{text:"تشغيل المضخة دون تدفق الماء (Start / No-flow Test)",correct:!0},{text:"الاختبار الهيدروستاتيكي",correct:!1},{text:"تشغيل المضخة بتدفق الماء الكامل طوال يوم كامل",correct:!1}],explanation:"وفق NFPA 25: تُشغَّل مضخة الديزل كل أسبوع، والمضخة الكهربائية عمومًا كل شهر، وتُختبر دون تدفق الماء."},{question:"تعمل في غرفة المولّدات المحمية بنظام CO₂ ويدوّي إنذار ما قبل التصريف. ماذا تفعل؟",options:[{text:"أخرج فورًا وأغلق الباب خلفي",correct:!0},{text:"أبحث عن النار وأستخدم المطفأة اليدوية أولًا",correct:!1},{text:"أبقى منخفضًا داخل الغرفة حتى يُصرَّف الغاز",correct:!1},{text:"أفتح النوافذ وأنتظر في الداخل",correct:!1}],explanation:"تركيز CO₂ اللازم للإطفاء قد يقتل الإنسان؛ ومهلة ما قبل التصريف مخصصة للخروج. والانخفاض لا يحمي لأن CO₂ أثقل من الهواء ويتجمع قرب الأرض."},{question:"أي ممارسة خطأ في مستودع مزوّد بالمرشات؟",options:[{text:"تكديس الصناديق حتى تلامس رؤوس المرشات",correct:!0},{text:"إبقاء المساحة تحت رؤوس المرشات خالية",correct:!1},{text:"الإبلاغ عن رأس مرش أتلفته رافعة شوكية",correct:!1},{text:"التحقق من أن صمام التحكم مفتوح ومؤمَّن",correct:!1}],explanation:"يحتاج المرش إلى مساحة خالية تحته ليصل الماء إلى النار، والمواد القريبة تحجبه؛ أما الممارسات الثلاث الأخرى فتحافظ على عمل النظام."}],steps:[{title:"اعرف أي نظام يحمي قسمك",detail:"مرشات أو رغوة أو CO₂ أو عامل نظيف أو مادة كيميائية: اعرف ما يحدث عند تشغيل النظام، وكيف يكون الإنذار، وأين محطات التشغيل اليدوي."},{title:"إنذار ما قبل التصريف: اخرج فورًا",detail:"في غرفة محمية بنظام CO₂ أو العامل النظيف، عندما يدوّي إنذار ما قبل التصريف اخرج فورًا وأغلق الباب خلفك؛ ولا تبقَ لإطفاء النار.",critical:!0},{title:"لا تعرقل النظام",detail:"أبقِ رؤوس المرشات والكواشف والفوهات والصمامات ومحطات التشغيل خالية من العوائق؛ ولا تكدّس المواد تحت رؤوس المرشات."},{title:"أبلغ عن أي خلل",detail:"أبلغ فورًا عن صمام مغلق أو إشارة عطل على اللوحة أو رأس مرش متضرر. ويطبّق المسؤول إجراء «تعطّل النظام»."},{title:"المطفأة اليدوية: الفحص قبل PASS",detail:"فقط إذا كانت كل الإجابات «نعم»: حريق صغير، ومطفأة مناسبة، وطريق خروج خلفك، وإنذار واتصال بالرقم 115، وتدريب. ابدأ من المسافة المكتوبة على الملصق؛ PASS لمعظم المطافئ، والبقية وفق ملصقها.",critical:!0},{title:"بعد التصريف: لا تدخل وأعد النظام",detail:"لا تدخل غرفة صُرّف فيها CO₂ أو العامل النظيف حتى تُهوّى ويأذن الشخص المسؤول. وتُعاد تعبئة المطفأة بعد كل استخدام، ويعيد أشخاص مختصون النظام إلى الخدمة.",critical:!0}],warnings:["لا تدخل الغرفة بعد تصريف CO₂ حتى تُهوّى ويُؤذن بالدخول: فتركيز الإطفاء قد يقتل الإنسان.","لا تغلق صمام المرشات ولا توقف إنذار الحريق من دون إذن ومن دون إجراء التعطّل: فيبقى المصنع بلا حماية ولا يعلم أحد.","لا تكدّس المواد قريبًا من رؤوس المرشات بحيث تحجب رذاذ الماء: فلن يصل المرش إلى النار."],tips:["اعرف مكان صمام التحكم الرئيسي للمرشات ومحطات التشغيل اليدوي ومن يحق له تشغيلها.","درّب الموظفين على معنى إنذار ما قبل التصريف والعلامات على أبواب الغرف.","ضع بطاقة «نظام معطّل» على أي صمام خارج الخدمة وسجّل ذلك في السجل.","أبقِ سجلات الفحص في متناول اليد، واتبع مواعيد الفحص التي يحددها الدفاع المدني والجهة المختصة."],activity:{prompt:"تعمل في غرفة تحكم محمية بنظام العامل النظيف. يتصاعد دخان من خزانة ويدوّي إنذار ما قبل التصريف. ماذا تفعل؟",options:[{text:"أبقى وأطفئ الخزانة بمطفأة يدوية قبل أن يُصرَّف العامل",correct:!1,feedback:"إنذار ما قبل التصريف يعني: أخلِ الغرفة؛ فالنظام نفسه سيطفئ النار."},{text:"أخرج فورًا وأغلق الباب وأطلق الإنذار وأبلغ المسؤول، ولا أعود قبل الإذن",correct:!0,feedback:"صحيح: الباب المغلق يحفظ تركيز العامل في الغرفة ليطفئ النار، وتبقى أنت بعيدًا عن العامل والدخان."},{text:"أضغط زر الإيقاف (Abort) لأُكمل عملي",correct:!1,feedback:"زر الإيقاف للإنذارات الكاذبة وبإذن المسؤول، لا لإكمال العمل والدخان موجود."},{text:"أترك الباب مفتوحًا ليخرج العامل وأراقب من الخارج",correct:!1,feedback:"الباب المفتوح يخفض تركيز العامل فلا تنطفئ النار، وينتشر الدخان."}]},caseStudy:[{prompt:"في عطلة نهاية الأسبوع يريد مقاول إغلاق صمام التحكم في المرشات لإصلاح أنبوب في المستودع. ما زالت في المستودع بضائع وبعض العمال. أنت مدير المصنع. ما قرارك؟",options:[{text:"فقط وفق إجراء التعطّل: إذن، وإبلاغ الجهات التي تحددها الخطة، ومدة قصيرة، ومراقبة للحريق، ومنع الأعمال الساخنة",correct:!0,feedback:"صحيح: الإصلاح ضروري، لكن المصنع يحتاج حماية إضافية في أثناء التعطّل ويجب أن يعلم الجميع."},{text:"أسمح له بإغلاقه بهدوء كي لا يدوّي الإنذار",correct:!1,feedback:"النظام المغلق الذي لا يعلم به أحد هو الأخطر؛ ففي الحريق لا يتوقع أحد أن الماء لن يأتي."},{text:"أرفض أي إصلاح نهائيًا",correct:!1,feedback:"النظام يحتاج إلى صيانة؛ والرفض يؤدي إلى أعطال أكبر. الحل هو الإجراء الآمن."},{text:"أسمح بإغلاقه ويبقى مغلقًا حتى فحص يوم الإثنين",correct:!1,feedback:"أي تعطّل يجب أن يكون قصيرًا ومراقبًا؛ وتركه أيامًا يترك المصنع بلا حماية."}]},{prompt:"انتهى الإصلاح. ماذا يجب أن يتم قبل مغادرة المقاول؟",options:[{text:"يُفتح الصمام بالكامل، ويتأكد شخص مختص من عودة النظام إلى الخدمة، وتُزال البطاقة، ويُسجَّل ذلك، وتُبلَّغ كل الجهات التي أُخطرت",correct:!0,feedback:"صحيح: تُثبت عودة النظام إلى الخدمة بالفحص والتسجيل لا بالكلام."},{text:"نترك الصمام كما هو، فالفحص القادم سيكتشفه",correct:!1,feedback:"هذا هو الخلل نفسه الذي يترك المصانع بلا حماية؛ الفتح والفحص قبل المغادرة."},{text:"نفتح الصمام نصف فتحة كي لا يتسرب الماء",correct:!1,feedback:"الصمام نصف المفتوح قد لا يعطي الماء اللازم للحريق؛ يجب أن يكون مفتوحًا بالكامل ومؤمَّنًا."},{text:"نبلغ مسؤول المقاول فقط",correct:!1,feedback:"الجهات التي أُبلغت عند الإغلاق يجب أن تعلم بعودة النظام، والتسجيل ضروري."}]}],realCase:"في مستودع للورق، أُغلق صمام للمرشات من أجل إصلاح ولم يُعد فتحه. وفي فحص بصري معتاد تبيّن أن الصمام مغلق وأن النظام خارج الخدمة. فأوقف المدير الأعمال الساخنة، وعيّن مراقبة للحريق، وأبلغ الجهات التي تحددها خطة الموقع، وفي اليوم نفسه فتح فني مختص الصمام وفحص النظام. ووجد التحقيق أنه لم تكن هناك بطاقة ولا سجل للتعطّل. فاعتمد المصنع بطاقات للصمامات وسجلًا للتعطّل، ودرّب موظفي الصيانة عليهما."},{id:22,code:"BUS-122",icon:"Building2",accent:"#0f766e",title:"السلامة من الحريق في المحلات والأسواق والمراكز التجارية",subtitle:"المخارج والتخزين والكهرباء والغاز المسال وأدوار الموظفين في الطوارئ",summary:"تمتلئ المحلات والأسواق والمراكز التجارية بزبائن لا يعرفون المبنى، وببضائع سريعة الاشتعال وأجهزة كهربائية، وكثيرًا ما توجد فيها أسطوانات الغاز المسال (LPG). هذا الدرس موجّه إلى أصحاب المحلات ومديريها وموظفيها: كيف تبقى المخارج ومعدات الحريق ظاهرة وخالية من العوائق، وكيف تُمنع حرائق الكهرباء والغاز، وما الذي يفعله كل موظف عندما يدوّي إنذار الحريق. أما قواعد الترخيص والتفتيش المحلية فيحددها الدفاع المدني والجهة المانحة للترخيص؛ فالتزموا بمتطلباتهما.",blocks:[{heading:"1. المخارج ومسارات الهروب والتخزين",body:"يحاول الزبائن عادةً الخروج من الطريق الذي دخلوا منه، لذا يجب أن تكون كل طرق الخروج جاهزة في كل وقت:",points:["أبقِ المخارج والممرات والسلالم خالية تمامًا: لا بضائع ولا صناديق ولا عربات ولا بسطات في الطريق، ولو لوقت قصير.","يجب أن تُفتح أبواب الخروج من الداخل فورًا ومن دون مفتاح أو رمز ما دام في المكان أشخاص؛ وأزل السلاسل والقضبان والأقفال الإضافية قبل فتح المحل.","أبقِ لافتات الخروج ظاهرة: لا يجوز أن تحجب البضائع أو الملصقات الإعلانية أو الزينة باب الخروج أو لافتته.","ضع البضائع الزائدة في المخزن، لا في الممرات ولا تحت السلالم ولا في الأماكن التي يمشي فيها الزبائن.","لا تكدّس البضائع أو الكرتون أو مواد التغليف بجانب اللوحات الكهربائية أو المصابيح أو المدافئ أو معدات الطبخ.","في السوق أو المركز التجاري، اتفق مع الإدارة على المخارج المشتركة وجرس الإنذار ونقطة التجمع، وشارك في التمارين المشتركة."]},{heading:"2. الكهرباء: الحمل الزائد ووصلات التمديد",body:"المقابس المحمّلة فوق طاقتها والأسلاك التي ترتفع حرارتها من الأسباب الشائعة للحرائق في المحلات:",points:["لا تحمّل المقابس ولا المشتركات الكهربائية (Power strip) فوق طاقتها، واستعمل مشتركات مزوّدة بحماية داخلية من الحمل الزائد.","وصلة التمديد (Extension lead) للاستعمال المؤقت فقط، ولا تحلّ أبدًا محل التمديدات الكهربائية الثابتة للمبنى؛ وإذا احتجت إلى مقابس أكثر فاطلب من كهربائي مؤهل تركيبها.","صِل الثلاجات والمجمّدات والمدافئ والأفران وغيرها من الأجهزة الكبيرة بمقبس الجدار مباشرةً، ولا تصلها أبدًا بوصلة تمديد.","لا تمدّ الأسلاك تحت السجاد أو الحُصر، ولا عبر الأبواب أو الممرات، حيث يمكن أن تُسحق أو يتعثّر بها الناس.","استبدل فورًا الأسلاك والقوابس التالفة. فرائحة الاحتراق أو القابس الساخن أو الشرر أو القاطع الكهربائي (Breaker) الذي ينفصل مرارًا تعني: افصل الكهرباء واستدعِ كهربائيًا مؤهلًا."]},{heading:"3. أسطوانات الغاز المسال في المحلات والأسواق",body:"الغاز المسال (LPG) أثقل من الهواء: فالغاز المتسرّب يتجمّع قرب الأرض وفي الأماكن المنخفضة مثل المجاري والسراديب.",points:["لا تُبقِ في المحل إلا أقل عدد من الأسطوانات يحتاجه العمل، وضع الباقي في مخزن منفصل جيد التهوية، ويُفضَّل أن يكون في الهواء الطلق.","لا تضع الأسطوانات أبدًا تحت مستوى الأرض أو في سرداب أو قرب فتحات المجاري.","أبقِ الأسطوانات قائمة وصمّاماتها محمية، في مكان لا يصل إليه الزبائن، بعيدًا عن الحرارة واللهب والمواد القابلة للاشتعال.","لا تضع الأسطوانات أبدًا على السلالم أو بجانب أبواب الخروج أو في أي مكان تسدّ فيه طريق الخروج.","لا يركّب المنظّمات والخراطيم والأجهزة إلا فنيّ مؤهل. ولا تبحث أبدًا عن التسرّب بلهب.","عدد الأسطوانات المسموح للمحل بالاحتفاظ بها ومكانها يحددهما الدفاع المدني والجهة المانحة للترخيص."]},{heading:"4. إذا شممت رائحة الغاز",body:`1. لا تُشعل أي لهب، ولا تُشغّل المصابيح أو الأجهزة أو الآلات ولا تُطفئها. ولا تستعمل الهاتف في الداخل.
2. أوقف البيع، وأخرج الزبائن والموظفين بهدوء من أقرب مخرج.
3. لا تُغلق صمّام الغاز إلا إذا كان قريبًا منك وتستطيع الوصول إليه دون الدخول إلى المكان الذي تجمّع فيه الغاز ودون إحداث أي شرارة؛ وإلا فلا تقترب منه.
4. أبعد الناس عن المدخل ونبّه المحلات المجاورة.
5. اتصل بالرقم 115 من الخارج، ولا تسمح لأحد بالعودة إلى الداخل حتى يؤكّد المختصون أن المكان آمن.`,critical:!0},{heading:"5. أدوار الموظفين عندما يدوّي إنذار الحريق",body:"يعرف كل موظف دوره قبل وقوع الطوارئ، وتحدّد خطة الطوارئ شخصًا لكل مهمة في كل مناوبة:",points:["الإنذار: اصرخ «حريق!»، واضغط أقرب نقطة نداء لإنذار الحريق (Call point) إن وُجدت، وتأكّد أن أحدًا يتصل بالرقم 115 من مكان آمن.","توجيه الزبائن: أوقف البيع، واطلب من الزبائن بهدوء أن يغادروا، ودُلّهم على أقرب مخرج، لا على المدخل الرئيسي وحده.","التفقّد: تفقّد دورات المياه وغرف القياس والمخازن والمكاتب في طريقك إلى الخارج، فقط إذا كان ذلك آمنًا، وأغلق الأبواب خلفك.","المساعدة: ساعد من يحتاج إلى المساعدة، مثل كبار السن والأطفال الذين بلا مرافق والأشخاص ذوي الإعاقة. ولا تستعمل المصاعد أبدًا.","عند نقطة التجمع: عُدّ الموظفين، وأبلغ عن أي مفقود، وأخبر رجال الإطفاء بالأماكن التي قد يكون فيها أشخاص وبوجود أسطوانات الغاز وأي مخاطر أخرى.","لا يعود أحد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن."]},{heading:"6. إخلاء الحشود بأمان",body:"في المحل أو المركز التجاري المزدحم، تحدّد طريقة توجيه الموظفين للناس سرعة خروج الجميع:",points:["تكلّم بهدوء وأعطِ تعليمات قصيرة وواضحة، مثل: «اخرجوا من هذا المخرج. امشوا ولا تركضوا.»","استعمل كل المخارج المتاحة، ووجّه الناس إلى مخرج آخر إذا ازدحم أحد المخارج أو سدّه الدخان.","لا تسمح للناس بالتوقف للدفع أو لجمع البضائع أو للعودة إلى الداخل.","أبقِ عدد الموجودين في الداخل ضمن الحد المقرّر للمبنى، ولا سيما في الأعياد وأيام التخفيضات.","في المركز التجاري، اتبع تعليمات فريق الطوارئ في المركز والإعلانات الصوتية، وابتعد مسافة كافية عن المبنى نحو نقطة التجمع."]},{heading:"7. معدات الحريق وحقيبة الإسعافات الأولية وجهاز AED",body:"لا تنقذ المعدات الأرواح إلا إذا استطاع الناس رؤيتها والوصول إليها واستعمالها:",points:["أبقِ مطفآت الحريق ونقاط نداء الإنذار وبطانيات الحريق ظاهرة وفي أماكنها وخالية من العوائق، وتأكّد كل يوم أن لا شيء يحجبها.","لا تستعمل مطفأة الحريق إلا إذا كنت مدرّبًا، وكانت النار صغيرة وفي بدايتها، وكان الملصق يبيّن أنها مناسبة لهذه النار، ونُبِّه الآخرون، واتُّصل بالرقم 115، وكان طريق خروجك خلفك. وإلا فاخرج وأغلق الباب.","تحتاج كل مطفأة إلى فحص نظري كل شهر (في مكانها، ومسمار الأمان والختم سليمان، ومؤشر مقياس الضغط في المنطقة الخضراء، ولا ضرر ظاهرًا) وإلى صيانة على يد شخص مؤهل؛ أما الجدول المحلي فيحدده الدفاع المدني.","ضع حقيبة إسعافات أولية مكتملة في مكان يصل إليه الموظفون بسرعة، واعرف من المدرَّب على الإسعافات الأولية في كل مناوبة.","إذا كان في المحل أو المركز التجاري جهاز إزالة الرجفان الخارجي الآلي (AED)، فإن كل الموظفين يعرفون مكانه. وإذا سقط شخص ولا يتنفس بشكل طبيعي: اتصل بالرقم 122، وابدأ الإنعاش القلبي الرئوي (CPR)، وأرسل أحدًا فورًا لإحضار الجهاز."]}],media:[{kind:"image",src:"media/images/w8_shop_evacuation.webp",title:"إخلاء محل تجاري",description:"موظف يوجّه الزبائن نحو أقرب مخرج وزميله يتفقّد المخزن"}],quiz:[{question:"المخزن ممتلئ ووصلت شحنة جديدة. أين يمكن وضع الصناديق الزائدة؟",options:[{text:"في ممر مخرج الحريق، حتى نهاية يوم العمل",correct:!1},{text:"تحت السلالم، ما دام الزبائن لا يرونها",correct:!1},{text:"في مخزن آخر أو مكان بعيد عن المخارج والممرات",correct:!0},{text:"أمام مطفأة الحريق، حيث توجد مساحة فارغة على الأرض",correct:!1}],explanation:"يجب أن تبقى المخارج والممرات والسلالم خالية في كل وقت، ولو لمدة قصيرة، ولا يجوز أن يحجب شيء معدات الحريق. فالبضائع الزائدة توضع في مخزن بعيد عن المخارج والممرات."},{question:"ثلاجة عرض جديدة تحتاج إلى الكهرباء. ما الطريقة الآمنة لتوصيلها؟",options:[{text:"صِلها بالمشترك الذي تعمل عليه المصابيح وصندوق الدفع منذ مدة",correct:!1},{text:"صِلها بمقبس الجدار مباشرةً، ويضيف الكهربائي مقابس عند الحاجة",correct:!0},{text:"مدّ وصلة تمديد إليها تحت سجادة الأرض حتى لا يتعثر بها أحد",correct:!1},{text:"اربط وصلتي تمديد معًا للوصول إلى المقبس الذي بجانب الباب",correct:!1}],explanation:"تُوصَل الأجهزة الكبيرة بمقبس الجدار مباشرةً. فوصلة التمديد مؤقتة وتُحمَّل فوق طاقتها بسهولة، والسلك الممدود تحت السجادة قد يُسحق ويسخن."},{question:"يشمّ الموظفون رائحة غاز قوية قرب أسطوانات المحل، والصمّام في وسط مكان الرائحة. ما التصرف الصحيح؟",options:[{text:"اذهب إلى الصمّام وأغلقه، ثم شغّل المروحة لطرد الغاز من المحل",correct:!1},{text:"أشعل المصابيح لترى التسرّب، واختبر الخرطوم بالقدّاحة",correct:!1},{text:"اتصل بشركة الغاز من داخل المحل وأنت تبحث عن التسرّب",correct:!1},{text:"ابتعد عن الصمّام، وأخرج الجميع، واتصل بالرقم 115 من الخارج",correct:!0}],explanation:"لا يُغلق الصمّام إلا إذا أمكن الوصول إليه دون دخول منطقة الغاز ودون أي شرارة. وهنا لا يمكن ذلك، فلا يقترب منه أحد: لا مفاتيح كهربائية، ولا هاتف في الداخل، ويخرج الجميع، ويُتّصل بالرقم 115 من الخارج."},{question:"يدوّي إنذار الحريق في محل مزدحم. ماذا يفعل الموظف المسؤول عن دورات المياه والمخازن؟",options:[{text:"يتفقّدها في طريقه إن كان ذلك آمنًا، ثم يبلّغ عند نقطة التجمع",correct:!0},{text:"يبقى عند صندوق الدفع لإكمال كل عمليات البيع قبل أن يغادر المبنى",correct:!1},{text:"يقفل المخازن حتى لا يأخذ أحد أي بضائع منها في أثناء الحريق",correct:!1},{text:"يعود وحده إلى داخل المبنى بعد العدّ ليبحث عن أي شخص مفقود",correct:!1}],explanation:"تفقّد دورات المياه والمخازن في طريق الخروج، فقط إذا كان ذلك آمنًا، يضمن ألّا يبقى أحد في الداخل. وتُبلَّغ النتيجة عند نقطة التجمع؛ ولا يعود أحد إلى الداخل."},{question:"في أثناء الإخلاء، يزدحم الزبائن عند المدخل الرئيسي بينما مخرج آخر خالٍ. ماذا يفعل الموظفون؟",options:[{text:"يطلبون من الجميع الانتظار داخل المحل حتى يخلو المدخل الرئيسي",correct:!1},{text:"يوجّهون الناس بهدوء وبتعليمات قصيرة وواضحة إلى المخرج الخالي",correct:!0},{text:"يشغّلون المصاعد ليتمكّن عدد أكبر من الناس من مغادرة الطابق معًا",correct:!1},{text:"يطلبون من الزبائن الدفع بسرعة حتى يتحرك الطابور أسرع",correct:!1}],explanation:"يميل الناس إلى الخروج من الطريق الذي دخلوا منه. فيستعمل الموظفون كل المخارج المتاحة ويوجّهون الناس بهدوء إلى مخرج خالٍ؛ ولا تُستعمل المصاعد أبدًا في الحريق."},{question:"يريد مدير منع السرقة عبر المخرج الخلفي في أثناء ساعات العمل. أي حل يُبقي المخرج آمنًا؟",options:[{text:"قفل يُفتح من الداخل فورًا، بلا مفتاح ولا رمز",correct:!0},{text:"قفل وسلسلة، مع حفظ المفتاح عند صندوق الدفع",correct:!1},{text:"صناديق مكدّسة خلف الباب حتى لا يُدفع ويُفتح",correct:!1},{text:"قفل برمز لا يعرف طريقة فتحه إلا المدير",correct:!1}],explanation:"يجب أن تُفتح أبواب الخروج من الداخل فورًا، بلا مفتاح ولا رمز، ما دام في الداخل أشخاص. فالسلسلة والمفتاح المحفوظ في مكان آخر والصناديق والرمز كلها تؤخّر الإخلاء في الحريق."}],steps:[{title:"أطلق الإنذار",detail:"اصرخ «حريق!»، واضغط أقرب نقطة نداء لإنذار الحريق إن وُجدت، وتأكّد أن أحدًا يتصل بالرقم 115 من مكان آمن.",critical:!0},{title:"أوقف البيع ووجّه الزبائن إلى الخارج",detail:"اطلب من الزبائن بهدوء أن يغادروا من أقرب مخرج، لا من المدخل الرئيسي وحده. استعمل كل المخارج المتاحة، ولا تدع أحدًا يتوقف للدفع أو لجمع البضائع.",critical:!0},{title:"تفقّد في طريقك إلى الخارج",detail:"تفقّد دورات المياه وغرف القياس والمخازن والمكاتب فقط إذا كان ذلك آمنًا، وأغلق الأبواب خلفك لتبطئ انتشار الدخان."},{title:"ساعد من يحتاج إلى المساعدة",detail:"ساعد كبار السن والأطفال الذين بلا مرافق والأشخاص ذوي الإعاقة على الوصول إلى أقرب مخرج. ولا تستعمل المصاعد أبدًا.",critical:!0},{title:"عُدّ وأبلغ عند نقطة التجمع",detail:"عُدّ الموظفين، وأبلغ عن أي مفقود، وأخبر رجال الإطفاء بالأماكن التي قد يكون فيها أشخاص وبوجود أسطوانات الغاز وأي مخاطر أخرى. ولا يعود أحد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن.",critical:!0}],warnings:["لا تقفل باب الخروج ولا تربطه بسلسلة أبدًا ما دام في الداخل أشخاص: ففي الحريق قد يحبس المخرج المقفل الزبائن والموظفين.","لا تترك البضائع في الممرات أو على السلالم أو أمام معدات الحريق أبدًا، ولو لوقت قصير: فالطرق المسدودة تبطئ الإخلاء وتخفي المعدات.","لا تبحث عن تسرّب الغاز بلهب أبدًا، ولا تشغّل أي شيء أو تطفئه إذا شممت رائحة الغاز: فقد تشعله شرارة."],tips:["امشِ في طرق الخروج كل يوم قبل الافتتاح: وتأكّد أن الأبواب تُفتح من الداخل وأن اللافتات ظاهرة.","سمِّ شخصًا لكل مهمة طوارئ في كل مناوبة، واكتب الأسماء في خطة الطوارئ.","في اليوم الأول، أرِ كل موظف جديد المخارج ونقاط نداء الإنذار والمطافئ ونقطة التجمع."],activity:{prompt:"الصباح قبل افتتاح المحل. تجد باب الخروج الخلفي مقفلًا بسلسلة بعد سرقة وقعت الأسبوع الماضي، وصناديق شحنة جديدة مكدّسة في الممر المؤدي إليه. ماذا تفعل؟",options:[{text:"أزيل السلسلة والصناديق قبل الافتتاح، وأبلغ المدير، وأطلب وسيلة لمنع السرقة تُبقي الباب قابلًا للفتح من الداخل فورًا",correct:!0,feedback:"صحيح: يجب أن تُفتح أبواب الخروج من الداخل بلا مفتاح ما دام في الداخل أشخاص، وأن يبقى الطريق إليها خاليًا دائمًا."},{text:"أترك السلسلة؛ فالمدخل الرئيسي يكفي الزبائن",correct:!1,feedback:"قد لا يستطيع الزبائن الوصول إلى المدخل الرئيسي في الحريق أو الدخان؛ فيجب أن تكون كل المخارج جاهزة للاستعمال."},{text:"أنقل الصناديق لكن أُبقي السلسلة وأترك المفتاح عند صندوق الدفع",correct:!1,feedback:"في الحريق لا وقت لأحد ليجلب المفتاح؛ فأبواب الخروج تُفتح فورًا من الداخل بلا مفتاح أو رمز."},{text:"أفك السلسلة لكن أترك الصناديق، لأنها ستبقى حتى المساء فقط",correct:!1,feedback:"يجب أن تبقى الممرات إلى المخارج خالية دائمًا ولو لوقت قصير: فالصناديق تبطئ الناس وقد تشتعل."}]},caseStudy:[{prompt:"في يوم تخفيضات مزدحم، يخبرك زبون أن دخانًا يخرج من تحت باب المخزن في مؤخرة المحل. أنت مشرف المناوبة. ماذا تفعل أولًا؟",options:[{text:"أطلق الإنذار، وأتأكد من الاتصال بالرقم 115، وأوقف البيع، وأبدأ إخراج الجميع من أقرب المخارج",correct:!0,feedback:"صحيح: الإنذار والاتصال أولًا، ثم إخراج الجميع. ويبقى باب المخزن مغلقًا."},{text:"أفتح باب المخزن على مصراعيه لأرى حجم الحريق",correct:!1,feedback:"فتح الباب يُدخل الهواء ويُخرج الدخان، وقد يكبر الحريق فورًا. أبقِه مغلقًا وأطلق الإنذار."},{text:"أُنهي عمليات البيع الجارية حتى لا يغادر الزبائن دون دفع",correct:!1,feedback:"الأرواح قبل البضائع والمال. أوقف البيع فورًا وأخرج الناس."},{text:"أرسل موظفًا إلى المخزن بدلاء من الماء",correct:!1,feedback:"لا يدخل أحد الدخان، وقد يحتوي المخزن على أجهزة كهربائية أو علب رذاذ. ولا تُستعمل المطفأة إلا بعد فحص «نعم أو لا»."}]},{prompt:"الزبائن يغادرون. يتزاحم كثيرون عند المدخل الرئيسي، وقد وصل الدخان إلى الممر القريب من المخزن، ورجل مسنّ يمشي ببطء قرب غرف القياس. ماذا تفعل الآن؟",options:[{text:"أوجّه الناس بهدوء إلى المخرج الآخر الخالي، وأطلب من زميل مساعدة الرجل المسن على الخروج، ونغلق الأبواب خلفنا",correct:!0,feedback:"صحيح: استعمل كل المخارج، وساعد من يحتاج، وأغلق الأبواب لتبطئ الدخان؛ ثم عُدّ الجميع عند نقطة التجمع."},{text:"أرسل الجميع عبر المدخل الرئيسي، لأن الزبائن يعرفون ذلك الطريق أكثر",correct:!1,feedback:"المدخل الرئيسي مزدحم أصلًا. يوجّه الموظفون الناس إلى كل المخارج المتاحة."},{text:"أدخل الممر المليء بالدخان لأتفقّد المخزن مرة أخرى",correct:!1,feedback:"لا تدخل الدخان أبدًا. أخبر رجال الإطفاء بمكان الحريق وما هو مخزَّن هناك."},{text:"أطلب من الرجل المسن أن ينتظر في غرفة قياس حتى يصل رجال الإطفاء",correct:!1,feedback:"يستطيع الخروج بالمساعدة، والدخان ينتشر. يساعد الموظفون من يحتاج على الخروج."}]}],realCase:"في محل للملابس، بدأ مشترك كهربائي محمَّل فوق طاقته خلف طاولة البيع يُصدر دخانًا. شمّ أحد الموظفين رائحة احتراق، فصرخ «حريق!» وضغط نقطة نداء الإنذار، واتصل زميل بالرقم 115 من الخارج. أوقف المشرف البيع ووجّه الزبائن إلى المخرجين كليهما، لا إلى الباب الرئيسي وحده. وتفقّدت زميلة أخرى غرف القياس ودورة المياه في طريقها إلى الخارج وأغلقت الأبواب خلفها. وعند نقطة التجمع عدّ المشرف الموظفين وأخبر رجال الإطفاء بأسطوانة الغاز في الغرفة الخلفية. خرج الجميع لأن المخارج كانت خالية وكان كل شخص يعرف دوره."},{id:23,code:"BUS-123",icon:"CookingPot",accent:"#c2410c",title:"السلامة من الحريق في المطاعم والمطابخ التجارية",subtitle:"حرائق الزيت والدهون وأنظمة غطاء الشفط والغاز وتدريب الموظفين",summary:"يجمع المطبخ التجاري الحرارة والزيت والدهون والغاز في مكان ضيق، ويمكن أن تمتد النار من مقلاة أو قلّاية إلى غطاء الشفط (Hood) ومجراه خلال لحظات. هذا الدرس موجّه إلى أصحاب المطاعم ومديريها والطهاة وموظفي الخدمة: كيف يتعاملون مع حريق الزيت، وما الذي يفعله نظام إطفاء الحريق في غطاء الشفط، وكيف يستعملون الغاز بأمان، ولماذا يجب تنظيف الدهون، وكيف يُخرجون الزبائن. التزموا بمتطلبات الدفاع المدني والجهة المانحة للترخيص.",blocks:[{heading:"1. حرائق الزيت والدهون: لا ماء أبدًا",body:"يحتاج الزيت والدهن المشتعلان إلى تعامل خاص:",points:["لا تصبّ الماء أبدًا على الزيت أو الدهن المشتعل: فالماء يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل في كرة نار.","لا تحمل المقلاة أو القلّاية المشتعلة ولا تحرّكها.","حريق صغير في مقلاة: أطفئ الحرارة أو الغاز عند الجهاز فقط إذا استطعت الوصول إليه بأمان، ثم مرّر غطاءً معدنيًا فوق المقلاة أو غطّها ببطانية الحريق، واتركها مغطاة حتى تبرد.","مطفأة مسحوق ABC أو مطفأة الرغوة غير مناسبة للقلّاية العميقة (Deep fryer): فالزيت يبقى ساخنًا وقد يشتعل من جديد.","إذا لم تكن النار صغيرة، أو وصلت إلى غطاء الشفط، أو لم تنطفئ فورًا: اخرج وأغلق الباب واتصل بالرقم 115."],critical:!0},{heading:"2. مطفأة المادة الكيميائية الرطبة (الفئة K / الفئة F)",body:"تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. لذا فالفئة K (NFPA) والفئة F (EN 2) فئة واحدة: زيوت الطبخ ودهونه.",points:["صُنعت مطفأة المادة الكيميائية الرطبة (Wet Chemical) لزيوت الطبخ ودهونه: فهي تكوّن طبقة شبيهة بالصابون على سطح الزيت تعزل الهواء وتبرّد الزيت.","إذا كان في المطبخ نظام إطفاء في غطاء الشفط، فشغّل النظام أولًا (تلقائيًا أو بمقبض التشغيل اليدوي)، ثم استعمل المطفأة بعد ذلك. وتوضّح ذلك لافتةٌ بجانب المطفأة.","اقرأ الملصق قبل وقوع الطوارئ: الفئة ومدى التشغيل وطريقة الاستعمال. فبعض مطافئ المادة الكيميائية الرطبة تُشغَّل بطريقة تختلف عن PASS؛ اتبع الملصق وتعليمات الشركة المصنّعة.","لا تستعملها إلا إذا كنت مدرّبًا، وكانت النار صغيرة، وقد أُطلق الإنذار، وكان طريق خروجك خلفك.","لون المطفأة ليس فئتها: اقرأ الملصق دائمًا."]},{heading:"3. نظام إطفاء الحريق في غطاء الشفط",body:"في كثير من المطابخ التجارية نظام إطفاء ثابت داخل غطاء الشفط فوق القلّايات والشوّايات والطبّاخات. لا يتولّى الموظفون صيانته، لكن يجب أن يعرف الجميع كيف يعمل:",points:["عندما تسخّن نارٌ تحت غطاء الشفط النظامَ، يعمل تلقائيًا ويرشّ مادة إطفاء من فوهات الرش (Nozzles) على أسطح الطبخ وداخل غطاء الشفط ومجراه.","وعندما يعمل يقطع أيضًا الغاز أو الكهرباء عن أجهزة الطبخ الموجودة تحت غطاء الشفط، ولا يعيد تشغيلها بعد ذلك إلا شخص مؤهل.","إذا لم يعمل تلقائيًا، فاستعمل مقبض التشغيل اليدوي (Pull station). وهو على طريق الخروج من المطبخ، ويجب أن يعرف كل طاهٍ مكانه، ولا يجوز أن يحجبه شيء.","أبقِ مرشّحات غطاء الشفط نظيفة وفي أماكنها. وأبقِ فوهات الرش نظيفة، ولا تغطّها ولا تثنِها ولا تحرّكها أبدًا.","لا تنقل أجهزة الطبخ التي تحت غطاء الشفط ولا تُضف إليها ولا تستبدلها من دون أن يفحص مركّب النظام ذلك: ففوهات الرش موجّهة إلى أجهزة محددة.","تفحص شركة مؤهلة النظام وتصونه بانتظام وتعلّق عليه بطاقة الصيانة؛ أما المدة بين الفحوص فيحددها الدفاع المدني والجهة المانحة للترخيص."]},{heading:"4. أسطوانات الغاز ومشعب الغاز والأنابيب",body:"لا يكون الغاز في المطبخ آمنًا إلا إذا رُكّب واستُعمل بطريقة صحيحة:",points:["أبقِ أسطوانات الغاز ومشعبها (Manifold، وهو الأنبوب الذي يربط عدة أسطوانات معًا) خارج المطبخ، في مكان جيد التهوية، قائمةً ومحميةً من الحرارة ومن العبث؛ ولا تضعها أبدًا في سرداب أو تحت مستوى الأرض.","لا يركّب أنابيب الغاز والمنظّمات والأجهزة ولا يوصلها ولا يصلحها ولا يصونها إلا فنيّ غاز مؤهل. ولا يغيّر الموظفون الأسطوانات إلا إذا تدرّبوا على ذلك.","درّب الموظفين على البحث كل يوم عن الأعطال الظاهرة، مثل خرطوم أو وصلة تالفة، أو لهب ينطفئ ولا يبقى مشتعلًا، أو رائحة غاز، وعلى الإبلاغ عنها والتوقف عن استعمال الجهاز.","إذا كان الغاز مربوطًا بمروحة الشفط (Interlock)، فإن الغاز ينقطع عندما تتوقف المروحة. ولا تتجاوز هذا الربط أبدًا ولا تعطّله.","يعرف كل طاهٍ مكان صمّام غاز المطبخ، ولا يستعمله إلا بالطريقة التي تسمح بها قاعدة رائحة الغاز أدناه.","لا تبحث أبدًا عن تسرّب الغاز بلهب."]},{heading:"5. إذا شممت رائحة الغاز في المطبخ",body:`1. لا تُشعل أي لهب، ولا تُشغّل المصابيح أو المراوح أو الأجهزة ولا تُطفئها. ولا تستعمل الهاتف في الداخل.
2. لا تُغلق صمّام الغاز إلا إذا كان قريبًا منك وتستطيع الوصول إليه دون الدخول إلى المكان الذي تجمّع فيه الغاز ودون إحداث أي شرارة؛ وإلا فلا تقترب منه.
3. أخرج الموظفين والزبائن بهدوء ونبّه الجيران.
4. اتصل بالرقم 115 من الخارج، ولا تعد إلى الداخل حتى يؤكّد المختصون أن المكان آمن.`,critical:!0},{heading:"6. الدهون: تنظيف غطاء الشفط والمرشّحات والمجرى",body:"الدهون التي تتراكم في غطاء الشفط والمرشّحات ومجرى العادم وقودٌ ينتظر لهبًا:",points:["قد يُشعل لهبُ القلي أو الشوي أو الفلمبيه (Flambé) الدهونَ المتراكمة، ويمكن أن ينتشر الحريق في المجرى عبر المبنى.","نظّف المرشّحات وأسطح غطاء الشفط والجدران والأرضيات والأجهزة وفق جدول محدد، حتى لا تتراكم الدهون.","اطلب من شركة مؤهلة تنظيف مجرى العادم بانتظام، واحتفظ بالسجل. ويعتمد عدد مرات التنظيف على نوع الطبخ وكميته؛ أما المتطلب فيحدده الدفاع المدني والجهة المانحة للترخيص.","لا تُفرغ القلّاية ولا تنظّفها إلا بعد أن يبرد الزيت، ولا تحرّك القلّاية أبدًا والزيت ساخن.","أبقِ الكرتون والقماش والورق وعبوات الزيت بعيدًا عن أجهزة الطبخ والحرارة."]},{heading:"7. تدريب الموظفين وإخراج الزبائن",body:"يعرف الجميع في المطعم الخطة منذ اليوم الأول للعمل:",points:["تحدّد خطة الطوارئ من يُطلق الإنذار، ومن يتصل بالرقم 115، ومن يقطع الغاز إذا كان ذلك آمنًا، ومن يوجّه الزبائن، ومن يعدّ الموظفين عند نقطة التجمع.","يطلب موظفو الخدمة من الزبائن بهدوء الخروج من أقرب مخرج، ولا يسمحون لهم بالتوقف للدفع أو لجمع أغراضهم.","تفقّد دورات المياه وقاعات الطعام والمخازن في طريق الخروج، فقط إذا كان ذلك آمنًا، وأغلق الأبواب خلفك.","أبقِ الباب الخلفي ومخرج المطبخ خاليين، ولا تقفل أبواب الخروج أبدًا ما دام في الداخل موظفون أو زبائن.","في اليوم الأول، أرِ كل موظف جديد المخارج ومقبض التشغيل اليدوي والمطفأة وبطانية الحريق وصمّام الغاز، واختبروا الخطة بالتمارين.","عند نقطة التجمع، أخبر رجال الإطفاء هل عمل نظام غطاء الشفط، وهل قُطع الغاز، وهل هناك أحد مفقود."]}],media:[{kind:"image",src:"media/images/w8_kitchen_grease_fire.webp",title:"حريق زيت في مطبخ تجاري",description:"طاهٍ يمرّر غطاءً معدنيًا فوق مقلاة مشتعلة، ويظهر مقبض التشغيل اليدوي ومطفأة المادة الكيميائية الرطبة قرب المخرج"}],quiz:[{question:"يشتعل حريق صغير في مقلاة على الطبّاخ. ما التصرف الصحيح؟",options:[{text:"اسكب كوب ماء على المقلاة ليبرد الزيت بسرعة وتنطفئ النار",correct:!1},{text:"احمل المقلاة بسرعة إلى الخارج لتُخرج النار من المطبخ",correct:!1},{text:"إن كان آمنًا أطفئ الحرارة وغطِّ المقلاة بغطاء معدني",correct:!0},{text:"أحضر مطفأة مسحوق ABC من المكتب ورشّها على المقلاة",correct:!1}],explanation:"تغطية المقلاة تعزل الهواء، وإطفاء الحرارة يمنع ازدياد سخونة الزيت. أما الماء فيقذف الزيت المشتعل في كرة نار، وتحريك المقلاة ينشر النار، ومسحوق ABC غير مصنوع لزيت الطبخ."},{question:"حريق تحت غطاء الشفط لا ينطفئ، وفي المطبخ نظام إطفاء في غطاء الشفط ومطفأة مادة كيميائية رطبة. ما الذي يأتي أولًا؟",options:[{text:"شغّل نظام غطاء الشفط بالمقبض اليدوي، ثم استعمل المطفأة",correct:!0},{text:"استعمل المطفأة أولًا واترك النظام لحريق أكبر منه",correct:!1},{text:"أوقف مروحة الشفط وانزع المرشّحات ليخرج الدخان من المطبخ",correct:!1},{text:"انتظر حتى يعمل النظام وحده قبل أن تفعل أي شيء آخر",correct:!1}],explanation:"يقطع نظام غطاء الشفط الغاز أو الكهرباء ويغطي أسطح الطبخ وغطاء الشفط والمجرى بمادة الإطفاء. وقد صُنعت مطفأة المادة الكيميائية الرطبة لتُستعمل بعد تشغيل النظام، كما تقول اللافتة التي بجانبها."},{question:"لماذا لا يجوز نقل أجهزة الطبخ التي تحت غطاء الشفط أو استبدالها من دون مركّب النظام؟",options:[{text:"لأن الأجهزة الأثقل قد تكسر بلاط الأرض الموجود تحت غطاء الشفط",correct:!1},{text:"لأن فوهات الرش موجّهة إلى أجهزة محددة وقد لا تغطي جهازًا جديدًا",correct:!0},{text:"لأن نقلها يزيد ضجيج المطبخ كثيرًا ويزعج الطهاة والزبائن في المطعم",correct:!1},{text:"لأن الأجهزة الجديدة تأتي دائمًا مع نظام إطفاء خاص بها مدمج فيها",correct:!1}],explanation:"يحمي النظام الأجهزة التي صُمّم لها. فإذا نُقل جهاز أو استُبدل، يجب أن يتحقق المركّب من أن فوهات الرش ما زالت تغطيه."},{question:"أين يجب أن تكون أسطوانات الغاز المسال ومشعب الغاز في المطعم؟",options:[{text:"في السرداب، حيث تبقى باردة وبعيدة عن طريق الموظفين",correct:!1},{text:"داخل المطبخ تحت الطبّاخ، قرب الشعلات التي تغذيها",correct:!1},{text:"في مخزن قاعة الطعام، خلف الكراسي المكدّسة هناك",correct:!1},{text:"في الخارج في مكان جيد التهوية، قائمة ومحمية من الحرارة",correct:!0}],explanation:"الغاز المسال أثقل من الهواء ويتجمّع في الأماكن المنخفضة مثل السراديب. لذا توضع الأسطوانات في الخارج في مكان جيد التهوية، قائمة وبعيدة عن الحرارة، ويركّب فنيّ مؤهل الوصلات."},{question:"لماذا يُعدّ تنظيف الدهون من غطاء الشفط والمرشّحات والمجرى مهمة من مهام السلامة من الحريق؟",options:[{text:"لأن الدهون المتراكمة قد تشتعل من لهب الطبخ وتنتشر في المجرى",correct:!0},{text:"لأن الدهون تغيّر رائحة الطعام فقط ولا تزيد خطر الحريق أبدًا",correct:!1},{text:"لأن المجاري النظيفة تجعل نظام غطاء الشفط يعمل خطأً أكثر",correct:!1},{text:"لأن طبقة الدهون تحمي معدن المجرى من حرارة الطبخ العالية",correct:!1}],explanation:"قد يُشعل لهب القلي أو الشوي أو الفلمبيه الدهونَ في غطاء الشفط والمجرى، ويمكن أن ينتشر الحريق في المجرى عبر المبنى. والتنظيف المنتظم يزيل هذا الوقود."},{question:"مطفأة مادة كيميائية رطبة جديدة للمطبخ مكتوب عليها الفئة F. يقول أحد الطهاة إن المطبخ يحتاج إلى مطفأة من الفئة K بدلًا منها. ما الصحيح؟",options:[{text:"الفئة F (EN 2) والفئة K (NFPA) فئة واحدة: زيوت الطبخ",correct:!0},{text:"الفئة F للغازات القابلة للاشتعال، فهي خطأ في المطبخ",correct:!1},{text:"الفئة F درجة أدنى، فيجب إضافة مطفأة من الفئة K",correct:!1},{text:"الحرف لا يهم، ما دام جسم المطفأة أصفر اللون",correct:!1}],explanation:"NFPA K = EN F: الحرفان يعنيان زيوت الطبخ ودهونه. واللون ليس الفئة أبدًا؛ اقرأ الملصق لتعرف الفئة والمدى وطريقة الاستعمال."}],steps:[{title:"لا ماء أبدًا، ولا تحرّك المقلاة",detail:"لا تصبّ الماء على الزيت أو الدهن المشتعل: فهو يتحوّل إلى بخار ويقذف الزيت المشتعل في كرة نار. ولا تحمل المقلاة أو القلّاية المشتعلة ولا تحرّكها.",critical:!0},{title:"أطفئ الحرارة إن كان ذلك آمنًا",detail:"أطفئ الحرارة أو الغاز عند الجهاز فقط إذا استطعت الوصول إلى المفتاح بأمان، دون أن تنحني فوق اللهب.",critical:!0},{title:"اخنق حريق المقلاة الصغير",detail:"مرّر غطاءً معدنيًا فوق المقلاة أو ضع عليها بطانية الحريق برفق، واتركها مغطاة حتى تبرد تمامًا.",critical:!0},{title:"تحت غطاء الشفط: النظام أولًا",detail:"إذا كان الحريق في القلّاية أو وصل إلى غطاء الشفط، فشغّل نظام غطاء الشفط بمقبض التشغيل اليدوي وأنت في طريقك إلى الخارج. وبعد ذلك فقط، إذا كنت مدرّبًا وكانت النار صغيرة وطريق خروجك خلفك، استعمل مطفأة المادة الكيميائية الرطبة (NFPA K = EN F) كما يقول ملصقها."},{title:"إذا لم تنطفئ فورًا، فاخرج",detail:"أخرج الموظفين والزبائن، وأغلق الباب، واتصل بالرقم 115. وعند نقطة التجمع أخبر رجال الإطفاء هل انطلق نظام غطاء الشفط، وهل قُطع الغاز، وهل هناك مفقود.",critical:!0}],warnings:["لا تصبّ الماء أبدًا على الزيت أو الدهن المشتعل: فالماء يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل في كرة نار.","لا تستعمل مطفأة مسحوق ABC أو الرغوة على القلّاية العميقة: فالزيت يبقى ساخنًا وقد يشتعل من جديد.","لا ترفع الغطاء أو بطانية الحريق لتنظر قبل أن تبرد المقلاة: فالهواء الجديد قد يُشعل الزيت الساخن من جديد."],tips:["احفظ بطانية الحريق ومطفأة المادة الكيميائية الرطبة على طريق الخروج من المطبخ، وتأكّد كل يوم أن لا شيء يحجبها أو يحجب مقبض التشغيل اليدوي.","أبقِ في متناول كل طاهٍ في أثناء القلي غطاءً معدنيًا يناسب المقلاة.","تدرّب على خطوات حريق المقلاة في التمارين بمقلاة باردة وغطاء، دون نار حقيقية."],activity:{prompt:"طاهٍ جديد يقلي حين اشتعل الزيت في مقلاة عميقة. اللهب صغير وفي المقلاة وحدها. ويركض زميل إلى المغسلة ليجلب الماء. ماذا تفعل؟",options:[{text:"أوقف زميلي، وأطفئ الحرارة إن استطعت الوصول إليها بأمان، وأمرّر غطاءً معدنيًا أو أضع بطانية الحريق فوق المقلاة",correct:!0,feedback:"صحيح: التغطية تقطع الهواء، وإطفاء الحرارة يمنع الزيت من أن يسخن أكثر. اتركها مغطاة حتى تبرد."},{text:"أدع زميلي يصبّ الماء بسرعة قبل أن يكبر اللهب",correct:!1,feedback:"الماء على الزيت المشتعل يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل في كرة نار."},{text:"أحمل المقلاة عبر الباب الخلفي وأضعها في الخارج",correct:!1,feedback:"تحريك المقلاة المشتعلة يسكب الزيت المشتعل ويسبب الحروق وينشر النار."},{text:"أرشّ المقلاة بمطفأة مسحوق ABC الموجودة في صالة الطعام",correct:!1,feedback:"مسحوق ABC لم يُصنع لزيت الطبخ: فالزيت يبقى ساخنًا وقد يشتعل من جديد. غطِّ المقلاة بدلًا من ذلك."}]},caseStudy:[{prompt:"في أثناء خدمة عشاء مزدحمة، امتدت النار من قلّاية إلى غطاء الشفط فوقها، ولم يعمل نظام الغطاء تلقائيًا. أنت رئيس الطهاة. ماذا تفعل أولًا؟",options:[{text:"أشغّل نظام غطاء الشفط بمقبض التشغيل اليدوي وأنا في طريقي إلى الخارج، وأطلق الإنذار",correct:!0,feedback:"صحيح: يغطي النظام أسطح الطهي والغطاء والمجرى ويقطع الغاز أو الكهرباء. وتأتي المطفأة بعده."},{text:"أستعمل مطفأة المادة الكيميائية الرطبة أولًا وأترك نظام الغطاء لحريق أكبر",correct:!1,feedback:"الترتيب معكوس: نظام الغطاء أولًا ثم المطفأة، كما تقول اللافتة بجانبها."},{text:"أنزع فلاتر غطاء الشفط ليخرج الدخان",correct:!1,feedback:"مدّ يدك داخل الغطاء يضعك في اللهب ويغذّي النار بالهواء. استعمل مقبض التشغيل اليدوي واخرج."},{text:"أصبّ دلوًا من الماء في القلّاية لتبريد الزيت",correct:!1,feedback:"الماء على الزيت المشتعل يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل في كرة نار."}]},{prompt:"انطلق نظام غطاء الشفط وانقطع الغاز عن خط الطهي. خفّت ألسنة اللهب في القلّاية لكنها ما زالت مشتعلة، والدخان يصل إلى صالة الطعام. ماذا تفعل الآن؟",options:[{text:"يُخرج موظفو الخدمة الزبائن، وأستعمل أنا مطفأة المادة الكيميائية الرطبة كما يقول ملصقها إن كنت مدرّبًا وطريق خروجي خلفي؛ وإذا لم تنطفئ النار فورًا أخرج وأتصل بالرقم 115",correct:!0,feedback:"صحيح: يغادر الزبائن ما إن يصلهم الدخان، وتُستعمل مطفأة المادة الكيميائية الرطبة بعد النظام وبعد فحص «نعم أو لا» فقط."},{text:"أعيد فتح الغاز ليُكمل الطهاة الآخرون الطلبات",correct:!1,feedback:"بعد انطلاق النظام لا يعيد الغاز أو الكهرباء إلا شخص مؤهّل، والنار ما زالت مشتعلة."},{text:"أُبقي الزبائن في الداخل حتى لا يذعروا في الشارع",correct:!1,feedback:"الدخان في صالة الطعام الآن. يُخرج موظفو الخدمة الزبائن بهدوء من أقرب مخرج."},{text:"أصعد إلى غطاء الشفط لأتحقق هل يحترق المجرى",correct:!1,feedback:"حريق المجرى من عمل فرق 115. أخبر رجال الإطفاء أن النظام قد انطلق وأين النار."}]}],realCase:"في مطبخ مطعم مزدحم، اشتعل الزيت في مقلاة. أمسك طاهٍ جديد إبريق ماء، لكن رئيسة الطهاة أوقفته. أطفأت الغاز عند الجهاز لأنها استطاعت الوصول إليه بأمان، ومرّرت غطاءً معدنيًا فوق المقلاة وتركتها مغطاة. انطفأ اللهب ولم ينسكب أي زيت. اتصل المدير بالرقم 115 لفحص المطبخ، واستعمل الحادثة لاحقًا في تمرين للموظفين: لا ماء أبدًا على الزيت المشتعل، ولا تحريك للمقلاة، واعرف أين الغطاء وبطانية الحريق ومقبض التشغيل اليدوي."},{id:24,code:"BUS-124",icon:"Building",accent:"#6d28d9",title:"السلامة من الحريق في الفنادق وأماكن إقامة النزلاء",subtitle:"إنذارات الليل ومعلومات النزلاء وأدوار الموظفين والنزلاء الذين يحتاجون إلى مساعدة",summary:"في الفندق ينام النزلاء في مبنى لا يعرفونه، وبعضهم لا يستطيع الخروج من دون مساعدة؛ لذلك يكون الحريق ليلًا أكبر خطر. هذا الدرس موجّه إلى أصحاب الفنادق ومديريها وموظفي الاستقبال وموظفي المناوبة الليلية: ما الذي يجب إبلاغ النزلاء به، وقاعدة باب الغرفة، وما الذي يفعله كل موظف ليلًا، وكيف يُساعَد النزلاء ذوو الإعاقة، وكيف تحمي أجهزة إنذار الدخان وأبواب الحريق الجميع. التزموا بمتطلبات الدفاع المدني والجهة المانحة للترخيص.",blocks:[{heading:"1. لماذا يكون الليل أكبر خطر",body:"يجب أن تنجح خطة الحريق في الفندق في أسوأ الأوقات أيضًا:",points:["يستيقظ النزلاء النائمون ببطء وقد يكونون مرتبكين، ولا يعرفون المبنى ولا مخارجه.","بعد أن يدوّي الإنذار، قد لا تتوفر إلا دقائق قليلة للخروج بأمان.","ينتشر الدخان في الممرات ويصعد عبر السلالم؛ والأبواب المغلقة تبطئ انتشار الدخان والحرارة والنار.","يكون عدد الموظفين ليلًا في أدنى حدوده، لذا يجب أن تنجح الخطة بفريق المناوبة الليلية وحده، وأن يكون عدد الموظفين كافيًا لمساعدة النزلاء الذين لا يستطيعون الخروج وحدهم."]},{heading:"2. الإنذار وكواشف الدخان وأبواب الحريق",body:"تحمي هذه الوسائل النزلاء وهم نائمون، ما دامت تعمل:",points:["في كل غرفة نزلاء كاشف دخان وجهاز إنذار صوته عالٍ بما يكفي لإيقاظ نزيل نائم.","اعرض على النزلاء الصمّ أو ضعاف السمع غرفة فيها إنذار بضوء وامض أو بوسادة اهتزاز (Vibrating pad)، إن وُجدت.","تُغلق أبواب الحريق (Fire door) في الممرات والسلالم من تلقاء نفسها. فلا تُبقِها مفتوحة أبدًا بإسفين أو بربطها، وأبلغ فورًا عن أي باب لا يُغلق تمامًا.","يوفّر نظام الرشاشات (Sprinkler) في كل غرفة نزلاء حماية إضافية حيث يكون مركّبًا.","تأكّد كل يوم أن طرق الخروج خالية، وأن أبواب الخروج تُفتح، وأن إنارة الطوارئ تعمل؛ أما مواعيد الاختبار والصيانة فيحددها الدفاع المدني."]},{heading:"3. ما يجب أن يعرفه كل نزيل",body:"أعطِ كل نزيل معلومات الحريق عند تسجيل وصوله:",points:["تُبيّن خطة الإخلاء المثبّتة على الوجه الداخلي لباب الغرفة موقعَ الغرفة والطرقَ المؤدية إلى أقرب المخارج.","أخبر النزلاء كيف يبدو صوت إنذار الحريق وأين أقرب مخرجين، واقترح عليهم أن يعدّوا الأبواب بين غرفتهم والمخرج؛ فهذا يساعد في الظلام أو في الدخان.","أبقِ مفتاح الغرفة بجانب السرير وخذه معك عند الخروج.","عندما يدوّي الإنذار: اخرج فورًا، وأغلق الأبواب خلفك، واستعمل الدرج، ولا تستعمل المصعد أبدًا.","تُفتح أبواب الخروج على طرق الإخلاء من الداخل دون مفتاح في كل الأوقات."]},{heading:"4. قاعدة باب الغرفة",body:"علّمها للموظفين واكتبها على إرشادات الحريق في كل غرفة:",points:["قبل فتح باب الغرفة، تحسّس الباب ومقبضه بظاهر يدك. فإن كان ساخنًا، أو كان الدخان يتسرّب من حوله، فأبقِه مغلقًا.","إذا كان الباب باردًا، فافتحه ببطء وكن مستعدًا لإغلاقه فورًا إذا كان في الخارج دخان أو نار.","إذا كان الممر خاليًا، فاخرج وأغلق الباب خلفك واتجه إلى أقرب مخرج؛ وإذا كان هناك دخان فانخفض.","إذا كانت كل طرق الخروج مسدودة: ابقَ في الغرفة والباب مغلق، وسدّ الفتحات حول الباب وفتحات التهوية بالمناشف أو أغطية السرير، وأطفئ المراوح والمكيّف، واتصل بالرقم 115 واذكر رقم الغرفة، ولوّح من النافذة.","لا تقفز من الطوابق العالية؛ انتظر رجال الإطفاء."]},{heading:"5. أدوار الموظفين ليلًا",body:"تحدّد الخطة الليلية من يفعل ماذا، حتى لو لم يكن في المناوبة إلا موظف أو اثنان:",points:["يتحقق موظف الاستقبال من الإنذار، ويتصل فورًا بالرقم 115، ويذكر العنوان ومكان الحريق وعدد النزلاء في الفندق.","يأخذ موظف الاستقبال قائمة الغرف المشغولة وقائمة النزلاء الذين يحتاجون إلى مساعدة إلى نقطة التجمع.","ينبّه الموظفون النزلاء ويوجّهونهم إلى المخارج في طريقهم إلى الخارج، ولا يتفقّدون الغرف ودورات المياه والممرات إلا حيث يكون ذلك آمنًا؛ ولا يدخلون الدخان أبدًا ولا يفتحون بابًا ساخنًا.","عند نقطة التجمع، قارن قائمة الغرف المشغولة بالأشخاص الحاضرين.","استقبل رجال الإطفاء عند وصولهم وأخبرهم بالغرف التي قد يكون فيها نزلاء بعدُ، وبمكان انتظار النزلاء الذين يحتاجون إلى مساعدة، وبأي مخاطر خاصة مثل الغاز.","لا يعود أحد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن."]},{heading:"6. النزلاء ذوو الإعاقة",body:"خطّط لهم قبل الليلة التي يحتاجون فيها إلى المساعدة:",points:["عند تسجيل الوصول، اسأل النزلاء بلطف وعلى انفراد هل سيحتاجون إلى مساعدة للخروج في حالة الطوارئ، واحتفظ في الاستقبال بقائمة بأسمائهم وأرقام غرفهم.","امنح هؤلاء النزلاء إن أمكن غرفة في طابق منخفض وقريبة من مخرج.","لا تستعمل أبدًا المصعد العادي في الحريق. فالنزيل الذي لا يستطيع استعمال الدرج يُبعَد عن النار عبر أبواب الحريق في الطابق نفسه، أو ينتظر مع أحد الموظفين في منطقة اللجوء المجاورة لدرج محمي، كما تنص خطة الفندق.","لا تترك نزيلًا وحده أبدًا في منطقة اللجوء، وأخبر رجال الإطفاء فورًا وبدقة بمكان انتظاره.","لا يجوز أن تعتمد الخطة على رجال الإطفاء لإنقاذ النزلاء المنتظرين: يجب أن يكون هناك عدد كافٍ من الموظفين المدرّبين لمساعدتهم."]},{heading:"7. التدريب والتمارين",body:"لا يستطيع الموظفون أن يفعلوا ليلًا إلا ما تدرّبوا عليه:",points:["درّب كل موظف جديد قبل أول مناوبة ليلية له: الإنذار، والمخارج، وأبواب الحريق، وقوائم الغرف، ودوره الخاص.","نفّذ التمارين، ومنها تمارين في الأوقات التي يكون فيها عدد الموظفين في أدنى حدوده، وتدرّبوا على افتراض أن أحد المخارج أو السلالم مسدود.","أبقِ خطة الطوارئ وقوائم الغرف في متناول اليد في الاستقبال، وحدّث القوائم عند كل تسجيل وصول ومغادرة.","يحدد الدفاع المدني والجهة المانحة للترخيص عدد مرات التمارين والتدريب المطلوب."]}],media:[{kind:"image",src:"media/images/w8_hotel_night_evacuation.webp",title:"إخلاء النزلاء ليلًا في فندق",description:"موظف المناوبة الليلية يوجّه النزلاء بمصباح يدوي عبر الممر نحو درج الخروج، وباب حريق مغلق خلفهم"}],quiz:[{question:"ماذا يجب أن تُبيّن خطة الإخلاء المثبّتة على الوجه الداخلي لباب غرفة النزيل؟",options:[{text:"موقع الغرفة والطرق المؤدية إلى أقرب مخرجين",correct:!0},{text:"رقم هاتف الفندق وموعد المغادرة فقط",correct:!1},{text:"الطريق إلى المصعد والطريق إلى المدخل الرئيسي وحدهما",correct:!1},{text:"مكان مطعم الفندق ومكان موقف السيارات",correct:!1}],explanation:"تبيّن الخطة على الباب موقع الغرفة والطرق إلى المخارج، ليجد النزيل طريقه بسرعة حتى في الظلام. ولا يُستعمل المصعد في الحريق."},{question:"يدوّي الإنذار ليلًا، ويشعر نزيل بأن مقبض باب غرفته ساخن. ماذا يجب أن يفعل؟",options:[{text:"يفتح الباب بسرعة ويركض عبر الممر نحو أقرب درج للخروج",correct:!1},{text:"يفتح الباب قليلًا لينظر إلى الممر ثم يقرّر ما يفعل",correct:!1},{text:"يُبقي الباب مغلقًا ويسدّ الفتحات ويتصل بالرقم 115 ويلوّح",correct:!0},{text:"ينزل بالمصعد لأن الممر قد يكون مليئًا بالدخان الكثيف",correct:!1}],explanation:"المقبض الساخن يعني وجود نار أو دخان ساخن خلف الباب. والباب المغلق يحمي النزيل: سُدّ الفتحات وفتحات التهوية، واتصل بالرقم 115، واذكر رقم الغرفة، ولوّح من النافذة."},{question:"في أثناء الإخلاء الليلي، أي مهمة تخصّ موظف الاستقبال؟",options:[{text:"البقاء عند المكتب للرد على اتصالات النزلاء حتى تنطفئ النار",correct:!1},{text:"الاتصال بالرقم 115 وأخذ قائمة الغرف المشغولة إلى نقطة التجمع",correct:!0},{text:"دخول كل الغرف، ومنها الغرف المليئة بالدخان، للبحث فيها",correct:!1},{text:"جمع حقائب النزلاء قبل الخروج من المبنى",correct:!1}],explanation:"يتصل موظف الاستقبال بالرقم 115 فورًا ويأخذ قوائم الغرف، حتى يجري العدّ عند نقطة التجمع ويعرف رجال الإطفاء الغرف التي قد يكون فيها نزلاء بعدُ. ولا يدخل أحد الدخان."},{question:"نزيل يستعمل كرسيًا متحركًا في الطابق الثالث عندما يدوّي الإنذار. ما التصرف الصحيح؟",options:[{text:"ينزل به موظف في المصعد العادي لأنه أسرع من الدرج",correct:!1},{text:"يتركه الموظفون وحده في منطقة اللجوء وينتظرون رجال الإطفاء في الخارج",correct:!1},{text:"يطلب منه الموظفون البقاء في غرفته حتى يتوقف الإنذار وحده",correct:!1},{text:"يأخذه موظف إلى منطقة اللجوء، ويبقى معه، ويُبلغ رجال الإطفاء بمكانه",correct:!0}],explanation:"لا يُستعمل المصعد العادي في الحريق. يُبعَد النزيل عن النار أو ينتظر مع موظف في منطقة اللجوء، ولا يُترك وحده أبدًا، ويعرف رجال الإطفاء مكانه فورًا."},{question:"لماذا لا يجوز إبقاء أبواب الحريق في ممرات الفندق مفتوحة بإسفين؟",options:[{text:"لأن الأبواب المفتوحة تُدخل هواء الدرج البارد إلى ممرات النزلاء في ساعات الليل المتأخرة",correct:!1},{text:"لأن باب الحريق المغلق يبطئ الدخان والحرارة والنار ويحمي طريق الخروج",correct:!0},{text:"لأن الأبواب المفتوحة تجعل النزلاء يسمعون الإنذار عاليًا جدًا في غرفهم",correct:!1},{text:"لأن أبواب الحريق ثقيلة والإسفين يُتلف مفصّلاتها مع مرور الوقت",correct:!1}],explanation:"لا يحمي باب الحريق إلا وهو مغلق: فهو يبطئ انتشار الدخان والحرارة والنار ويُبقي طريق الخروج آمنًا للنزلاء. أما الباب المفتوح بإسفين فلا يوفّر هذه الحماية."},{question:"يسجّل نزيل أصمّ دخوله إلى الفندق. ماذا ينبغي أن يعرض عليه الاستقبال؟",options:[{text:"غرفة فيها إنذار بضوء وامض أو بوسادة اهتزاز، إن وُجدت",correct:!0},{text:"غرفة هادئة في الطابق الأعلى، بعيدة عن ضجيج السلالم",correct:!1},{text:"لا شيء إضافي، فإنذار الممر عالٍ بما يكفي لكل النزلاء",correct:!1},{text:"ملاحظة تطلب منه ترك باب الغرفة مفتوحًا في الليل",correct:!1}],explanation:"قد لا يسمع النزيل الأصم أو ضعيف السمع الإنذار. ويمكن للإنذار بالضوء الوامض أو بوسادة الاهتزاز أن يوقظه؛ واسأله بلطف وعلى انفراد هل سيحتاج إلى المساعدة، وإن كان كذلك فأضفه إلى القائمة. والباب المفتوح يُدخل الدخان."}],steps:[{title:"تحقّق من الإنذار واتصل بالرقم 115",detail:"يتحقّق موظف الاستقبال من الإنذار ويتصل فورًا بالرقم 115، ويذكر العنوان ومكان الحريق وعدد النزلاء في الفندق.",critical:!0},{title:"خذ القوائم",detail:"يأخذ موظف الاستقبال قائمة الغرف المشغولة وقائمة النزلاء الذين يحتاجون إلى المساعدة إلى نقطة التجمع."},{title:"نبّه النزلاء ووجّههم",detail:"في طريقهم إلى الخارج يطرق الموظفون الأبواب، وينبّهون النزلاء، ويوجّهونهم إلى السلالم لا إلى المصعد أبدًا. ولا يدخلون الدخان ولا يفتحون بابًا ساخنًا أبدًا.",critical:!0},{title:"ابقَ مع النزلاء الذين يحتاجون إلى المساعدة",detail:"النزيل الذي لا يستطيع استعمال الدرج يُبعَد عن النار عبر أبواب الحريق في الطابق نفسه، أو ينتظر مع موظف في منطقة اللجوء، كما تنص خطة الفندق. ولا يُترك وحده أبدًا.",critical:!0},{title:"عُدّ وأبلغ رجال الإطفاء",detail:"عند نقطة التجمع قارن قائمة الغرف المشغولة بالحاضرين. وأخبر رجال الإطفاء بالغرف التي قد يبقى فيها نزلاء وبمكان انتظار النزلاء الذين يحتاجون إلى المساعدة. ولا يعود أحد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن."}],warnings:["لا تُثبّت باب الحريق مفتوحًا بإسفين أو حبل أبدًا: فالباب المفتوح يُدخل الدخان والحرارة والنار إلى الممرات والسلالم.","لا تستعمل المصعد العادي في الحريق ولا ترسل النزلاء إليه أبدًا: فقد يتوقف ويحبسهم.","لا تفتح بابًا ساخنًا عند لمسه أبدًا: فقد تكون خلفه نار أو دخان ساخن."],tips:["حدّث قوائم الغرف عند كل تسجيل دخول وخروج، واحفظها مع خطة الطوارئ في الاستقبال.","في بداية كل مناوبة ليلية امشِ في طرق الهروب: تأكّد أنها خالية، وأن أبواب الحريق تنغلق، وأن أبواب الخروج تُفتح.","احفظ مصباحًا يدويًا في الاستقبال لكل فرد من فريق الليل.","تدرّب على خطة الليل بالعدد الفعلي لموظفي الليل، كأن أحد السلالم مسدود."],activity:{prompt:"منتصف الليل. يدوّي إنذار الحريق ويُظهر حريقًا في الطابق الثالث. أنت في الاستقبال، وزميل واحد في الطوابق. ماذا تفعل أولًا؟",options:[{text:"أتصل بالرقم 115 وأذكر العنوان ومكان الحريق وعدد النزلاء، وآخذ قوائم الغرف، وأطلب من زميلي تنبيه النزلاء في طريقه إلى المخارج",correct:!0,feedback:"صحيح: الاتصال بالرقم 115 يكون فورًا، والقوائم تسمح بعدّ الجميع، والزميل ينبّه النزلاء دون أن يدخل الدخان."},{text:"أُسكت الإنذار حتى لا يفزع النزلاء، ثم أصعد لأرى ما يحدث",correct:!1,feedback:"إسكات الإنذار يمنع النزلاء النائمين من الاستيقاظ، والصعود يؤخّر الاتصال. اتصل بالرقم 115 فورًا."},{text:"أتصل هاتفيًا بكل غرفة مشغولة واحدة تلو الأخرى قبل الاتصال بالرقم 115",correct:!1,feedback:"هذا يستغرق وقتًا طويلًا جدًا. الإنذار يوقظ النزلاء، ويُتصل بالرقم 115 فورًا، وينبّه الموظفون النزلاء في طريقهم إلى الخارج."},{text:"أغادر المبنى فورًا وأترك القوائم لأوفّر الوقت",correct:!1,feedback:"بلا القوائم لا يمكن عدّ أحد، ولن يعرف رجال الإطفاء أي الغرف قد يبقى فيها نزلاء."}]},caseStudy:[{prompt:"في وقت متأخر من الليل، أُبلغ عن دخان في ممر بالطابق الثاني وتم الاتصال بالرقم 115. يتصل نزيل بالاستقبال من غرفة في الطابق الثاني: مقبض الباب ساخن والدخان يدخل من تحت الباب. ماذا تقول للنزيل؟",options:[{text:"أبقِ الباب مغلقًا، وسُدّ الفتحات وفتحات التهوية بالمناشف أو أغطية السرير، وأطفئ المراوح والتكييف، وأشِر من النافذة؛ وسأعطي رقم غرفتك لرجال الإطفاء",correct:!0,feedback:"صحيح: المقبض الساخن يعني نارًا أو دخانًا ساخنًا خلف الباب. والباب المغلق يحمي النزيل حتى يصل رجال الإطفاء."},{text:"افتح الباب واركض بسرعة في الممر إلى أقرب سلالم",correct:!1,feedback:"المقبض الساخن يعني نارًا أو دخانًا ساخنًا خلف الباب. وفتحه يُدخل الدخان والحرارة إلى الغرفة."},{text:"انزل بالمصعد، لأن السلالم قد تكون مليئة بالدخان",correct:!1,feedback:"لا يُستعمل المصعد العادي في الحريق أبدًا: فقد يتوقف ويحبس الناس، وسيضطر النزيل إلى عبور الممر."},{text:"افتح النافذة واقفز إذا اشتد الدخان",correct:!1,feedback:"لا تقفز من طابق علوي. أبقِ الباب مغلقًا، وأشِر من النافذة، وانتظر رجال الإطفاء."}]},{prompt:"وصل رجال الإطفاء. عند نقطة التجمع تُظهر قائمتك غرفتين مشغولتين لم يحضر نزلاؤهما، ونزيل غرفة الطابق الثاني ما زال في الداخل. ماذا تفعل؟",options:[{text:"أستقبل رجال الإطفاء وأعطيهم أرقام الغرف الثلاث ومكان انتظار النزيل وأي مخاطر خاصة",correct:!0,feedback:"صحيح: يحتاج رجال الإطفاء إلى أرقام الغرف بدقة وفورًا، والعدّ مقابل القائمة هو ما يجعل ذلك ممكنًا."},{text:"أعود إلى الداخل مع زميل للبحث عن النزلاء المفقودين",correct:!1,feedback:"لا يعود أحد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن. أعطِ رجال الإطفاء أرقام الغرف بدلًا من ذلك."},{text:"أنتظر حتى تنطفئ النار ثم أذكر النزلاء المفقودين",correct:!1,feedback:"يحتاج رجال الإطفاء إلى المعلومات فور وصولهم؛ وأي تأخير قد يكلّف حياة."},{text:"أخبر رجال الإطفاء أن الجميع خرجوا، لأن معظم النزلاء حاضرون",correct:!1,feedback:"العدّ الناقص قد يكلّف حياة. أبلغ بدقة عن الغرف التي لم يُتحقّق من نزلائها."}]}],realCase:"في وقت متأخر من الليل، أطلق كاشف الدخان الإنذار في غرفة بأحد الفنادق. اتصلت موظفة الاستقبال الليلية بالرقم 115 فورًا، وذكرت العنوان والطابق، وأخذت قائمة الغرف المشغولة وقائمة النزلاء الذين يحتاجون إلى المساعدة. وطرق زميل الأبواب على طول الممر ووجّه النزلاء إلى السلالم. وبقي زميل آخر مع نزيل يستعمل كرسيًا متحركًا في منطقة اللجوء المجاورة للدرج المحمي، وأخبرت موظفة الاستقبال رجال الإطفاء بمكانهما بالضبط. بقيت أبواب الحريق مغلقة، وبقي الدخان في طابق واحد، وتطابق العدّ عند نقطة التجمع مع القائمة."},{id:25,code:"BUS-125",icon:"Fuel",accent:"#b45309",title:"السلامة في محطات الوقود",subtitle:"Ignition Control, Static, Spills, Emergency Stop & LPG",summary:"تخزّن محطات الوقود كميات كبيرة من السوائل والغازات القابلة للاشتعال وتوزّعها. تبيّن هذه الوحدة للعاملين والمشرفين والمديرين كيف يسيطرون على مصادر الاشتعال والكهرباء الساكنة، ويتعاملون مع انسكاب الوقود، ويستخدمون زر الإيقاف الطارئ، ويعبّئون غاز البترول المسال (LPG) بأمان، وماذا يفعلون إذا نشب حريق عند المضخة.",blocks:[{body:"يطلق البنزين أبخرة قابلة للاشتعال حتى في الطقس البارد (نقطة وميضه نحو -43°C)، وأبخرته أثقل من الهواء: تنتشر على الأرض وتتجمع في الأماكن المنخفضة مثل مجاري الصرف والحفر والأقبية. ويمكن أن تشعلها شرارة أو لهب أو سيجارة أو محرك يعمل. ويضع الدفاع المدني والجهة المانحة للترخيص قواعد ترخيص محطات الوقود وتصميمها وتجهيزاتها: التزم بمتطلباتهما. وتوضح هذه الوحدة ما يجب على كل عامل ومشرف ومدير أن يفعله."},{heading:"1. السيطرة على مصادر الاشتعال عند المضخات",body:"قبل التعبئة وفي أثنائها، يتأكد العامل من أن:",points:["محرك المركبة مطفأ عند المضخة.","لا أحد يدخّن أو يستخدم ولّاعة أو لهبًا مكشوفًا قرب المضخات، وأن لافتتَي «ممنوع التدخين» و«أطفئ المحرك» مثبتتان قرب المضخات.","المراقبة مستمرة: ترى كل مركبة وكل شخص عند المضخات، ولا تشغّل المضخة إلا حين لا يوجد أي خطر.","لا تعبّئ إذا كان المحرك يعمل، أو كان أحد يدخّن بالقرب، أو كانت العبوة غير معتمدة؛ واستدعِ المشرف إذا رفض الزبون.","الهواتف: طبّق قاعدة محطتك (تطلب بعض الإرشادات عدم استخدام الهواتف وأجهزة اللاسلكي عند المضخات)، وأبقِ انتباهك على مصادر الاشتعال الرئيسية: التدخين واللهب والمحركات العاملة والكهرباء الساكنة.","ساحة المضخات نظيفة، من دون خِرَق أو كرتون أو مواد أخرى قابلة للاشتعال قرب المضخات."]},{heading:"2. الكهرباء الساكنة وعبوات الوقود",body:"يمكن لشرارة كهرباء ساكنة عند فوهة المضخة (nozzle) أن تشعل أبخرة الوقود:",points:["يُفضَّل أن يبقى الزبائن خارج المركبة في أثناء التعبئة: فالانزلاق على المقعد يولّد كهرباء ساكنة. وإذا اضطروا إلى العودة إلى المركبة، يلمسون جزءًا معدنيًا من السيارة بعيدًا عن فتحة التعبئة قبل أن يلمسوا الفوهة مرة أخرى.","لا تملأ عبوة الوقود إلا وهي على الأرض، ولا تملأها أبدًا داخل صندوق السيارة أو على مقعد أو في حوض شاحنة صغيرة (بيك أب).","المس العبوة بفوهة المضخة قبل فتحها، وأبقِ الفوهة ملامسة لفتحة العبوة طوال التعبئة.","لا تملأ إلا عبوات وقود مناسبة ومعتمدة، ولا تملأ أبدًا القناني أو الدلاء أو أوعية الطعام؛ وتحدد الجهة المانحة للترخيص العبوات والأحجام المسموح بها.","أغلق العبوة بإحكام؛ ولا تُنقل عبوات الوقود وأسطوانات الغاز أبدًا في مقصورة الركاب."]},{heading:"3. انسكاب الوقود",body:"يستطيع العاملون المدرَّبون التعامل مع انسكاب صغير، كالذي يحدث عند الإفراط في التعبئة؛ أما الانسكاب الكبير فحالة طوارئ:",points:["1. أوقف التدفق: اترك مقبض الفوهة أو أوقف المضخة؛ وإن لم يتوقف، فاضغط زر الإيقاف الطارئ.","2. أبعِد الناس والمركبات؛ ولا يشغّل أحد بالقرب محركًا أو يدخّن أو يشغّل أي جهاز كهربائي.","3. مع ارتداء القفازات، غطِّ الانسكاب بالرمل أو بمادة ماصّة (absorbent) من عُدّة الانسكاب؛ ولا تمشِ في الوقود.","4. لا تغسل الوقود بالماء: فالماء يحمله إلى مجاري الصرف، حيث تتجمع الأبخرة ويمكن أن تنفجر.","5. اجمع المادة المشبعة بالوقود في وعاء معدني مغلق: فهي ما زالت قابلة للاشتعال.","اتصل بالرقم 115 فورًا إذا وصل الوقود إلى مجرى صرف أو إلى الشارع، أو شُمّت رائحة الوقود داخل مبنى، أو كان الانسكاب كبيرًا، أو اشتعل."]},{heading:"4. زر الإيقاف الطارئ",body:"يقطع زر الإيقاف الطارئ (Emergency Stop) الكهرباء عن جميع المضخات دفعة واحدة. ويحدد الدفاع المدني والجهة المانحة للترخيص مكان تركيبه ومواعيد اختباره:",points:["يعرف كل عامل مكان كل زر إيقاف طارئ، في الداخل عند صندوق الدفع وفي الخارج في ساحة المضخات، وقد تدرّب على الضغط عليه.","اضغطه عند أي انسكاب لا تستطيع إيقافه، وأي حريق، وأي تسرّب عند نقطة تعبئة الغاز المسال، وأي مركبة تصطدم بمضخة.","أبقِه ظاهرًا وموسومًا بوضوح، ولا تحجبه أبدًا بالبضائع أو رفوف العرض أو السيارات المتوقفة.","تتضمن خطة الطوارئ في المحطة مخططًا للموقع يبيّن الخزانات والمضخات وأزرار الإيقاف الطارئ والمطافئ وعُدّة الانسكاب ونقطة التجمع.","يعرف كل عامل العنوان الدقيق للمحطة وكيف يصف موقعها عند الاتصال بالرقم 115."]},{heading:"5. تعبئة غاز البترول المسال للسيارات (LPG)",body:"يُخزَّن غاز البترول المسال سائلًا تحت الضغط. وعند تسرّبه يكوّن سحابة غاز أثقل من الهواء يمكن أن تشتعل بعيدًا عن مكان التسرّب. وفي الملف المرجعي للمشروع تُصنَّف حرائق هذا الغاز ضمن الفئة B في نظام NFPA (الغازات)، وضمن الفئة C في نظام EN 2.",points:["لا يعبّئ الغاز المسال إلا عاملون مدرَّبون؛ ولا يعبّئه الزبائن بأنفسهم ما لم تسمح الجهة المانحة للترخيص بذلك.","يبقى العامل عند المركبة طوال التعبئة، حتى يُطفأ الجهاز وتُغلق الصمامات.","المحركات مطفأة، ولا أحد يدخّن أو يستخدم لهبًا قرب نقطة التعبئة.","ارتدِ القفازات وواقي العينين: فالغاز المسال السائل يسبّب حروقًا باردة في الجلد.","افحص صمام التعبئة في المركبة قبل التوصيل؛ وإذا تسرّب الغاز من الوصلة فأوقف التعبئة.","إذا استمر تسرّب الغاز أو اشتعل: اضغط زر الإيقاف الطارئ، وأبعِد الناس، واتصل بالرقم 115. لا تغلق مصدر الغاز إلا إذا أمكن الوصول إليه بأمان؛ ولا تطفئ أبدًا لهب غاز لا يمكن إيقاف مصدره."]},{heading:"6. حريق عند المضخة",body:"إذا اشتعلت مركبة أو مضخة:",points:["اضغط زر الإيقاف الطارئ فورًا وأطلق إنذار الحريق.","اطلب من السائق أن يترك الفوهة في السيارة ويبتعد؛ وأخرِج الجميع من المركبات وأبعِدهم عن المضخات.","اتصل بالرقم 115 (وبالرقم 122 إذا أصيب أحد)، واذكر اسم المحطة وعنوانها أولًا.","أبقِ الجميع على بُعد 30 مترًا (100 قدم) على الأقل من المركبة المشتعلة، وامنع دخول مركبات أخرى إلى المحطة.","لا تفتح غطاء المحرك أو صندوق السيارة المشتعلة: فالهواء النقي يزيد الحريق.","يجوز لعامل مدرَّب استخدام المطفأة على حريق صغير بدأ للتو فقط، بمطفأة يغطي ملصقها الوقود المشتعل (الفئة B؛ NFPA B للسوائل = EN B)، وطريق الخروج خلفه، وبعد إطلاق الإنذار. ابدأ من المسافة المكتوبة على الملصق؛ وإذا لم ينطفئ الحريق فورًا، فابتعد.","تدرّبوا على هذه الخطوات في تمارين منتظمة مع جميع العاملين، وسجّلوا كل تمرين."],critical:!0}],media:[{kind:"image",src:"media/images/w8_fuel_station_safety.webp",title:"التعبئة الآمنة عند المضخة",description:"المحرك مطفأ، والعبوة على الأرض، وزر الإيقاف الطارئ والمطفأة جاهزان"}],quiz:[{question:"عاد زبون إلى سيارته في أثناء التعبئة، وهو الآن يعود إلى المضخة. ماذا يفعل قبل أن يلمس الفوهة؟",options:[{text:"يلمس معدن السيارة بيده، بعيدًا عن فتحة التعبئة",correct:!0},{text:"يمسح مقبض الفوهة بقطعة قماش جافة أولًا",correct:!1},{text:"يسحب الفوهة بسرعة ثم يعيد تشغيل المضخة",correct:!1},{text:"يبقى داخل السيارة حتى تتوقف المضخة وحدها",correct:!1}],explanation:"الانزلاق على المقعد يولّد كهرباء ساكنة، ولمس المعدن بعيدًا عن فتحة التعبئة يفرّغها قبل أن تصل اليد إلى الفوهة، حيث قد تشعل الشرارة الأبخرة."},{question:"يتدفق الوقود على أرض المحطة من فوهة لا تُغلق. ما أول إجراء؟",options:[{text:"اغسل الوقود بالماء نحو مجاري الصرف",correct:!1},{text:"أوقف التدفق من المضخة أو بزر الإيقاف الطارئ",correct:!0},{text:"شغّل السيارة وأبعِدها عن الانسكاب",correct:!1},{text:"انثر مادة ماصّة حوله واترك المضخة تعمل",correct:!1}],explanation:"أوقف المصدر أولًا، ثم أبعِد مصادر الاشتعال والناس، وسيطر على الانسكاب بمادة ماصّة. فالماء يحمل الوقود إلى المجاري حيث تتجمع الأبخرة، وتشغيل محرك قد يشعلها."},{question:"أين يجب أن تكون عبوة الوقود في أثناء تعبئتها؟",options:[{text:"في حوض شاحنة بيك أب، جاهزة للانطلاق",correct:!1},{text:"على المقعد الخلفي، يمسكها أحد الركاب",correct:!1},{text:"على الأرض، والفوهة ملامسة للعبوة",correct:!0},{text:"في صندوق السيارة، وغطاؤه مفتوح بالكامل",correct:!1}],explanation:"داخل المركبة يعزل السجاد أو بطانة الحوض البلاستيكية العبوة عن الأرض، فلا تتسرب الكهرباء الساكنة الناتجة عن تدفق الوقود، وقد تحدث شرارة عند الفوهة (NIOSH). أما على الأرض ومع ملامسة الفوهة فتتسرب الشحنة إلى الأرض بأمان."},{question:"في أثناء تعبئة الغاز المسال بدأ الغاز يتسرب من الوصلة. ماذا يفعل العامل؟",options:[{text:"يوقف التعبئة ويغلق الصمامات ويُبعد الناس والمحركات",correct:!0},{text:"يُنهي التعبئة بسرعة ثم يشدّ الوصلة بعد ذلك",correct:!1},{text:"يرشّ التسرّب بمطفأة CO₂ لتبريد الوصلة",correct:!1},{text:"يطلب من السائق تشغيل المحرك والمغادرة فورًا",correct:!1}],explanation:"الغاز المسال المتسرّب يكوّن سحابة يمكن أن تشتعل. أوقف التعبئة، وأغلق الغاز إذا أمكن الوصول إليه بأمان، وأبعِد مصادر الاشتعال؛ وإذا لم يتوقف التسرّب فاضغط زر الإيقاف الطارئ واتصل بالرقم 115."},{question:"اشتعلت سيارة عند إحدى المضخات. أي إجراء صحيح؟",options:[{text:"اسحب الفوهة من السيارة قبل أي شيء آخر",correct:!1},{text:"افتح غطاء المحرك لترى الحريق وتصل إليه",correct:!1},{text:"رشّ الماء بالخرطوم على الوقود المشتعل",correct:!1},{text:"اضغط زر الطوارئ، وأخلِ المكان، واتصل بالرقم 115",correct:!0}],explanation:"يقطع زر الإيقاف الطارئ الوقود عن جميع المضخات. اترك الفوهة مكانها، وأبقِ غطاء المحرك مغلقًا، وأبعِد الجميع جيدًا؛ فالماء ينشر الوقود المشتعل."},{question:"في أثناء تعبئة الغاز المسال، يطلب زبون أن يعبّئ الغاز بنفسه ليتفرّغ العامل لخدمة المضخات الأخرى. ماذا يفعل العامل؟",options:[{text:"يعبّئه بنفسه كما تدرّب، ويبقى حتى تُغلق الصمامات",correct:!0},{text:"يسلّم فوهة المضخة للزبون ويعود لخدمة المضخات الأخرى",correct:!1},{text:"يدع الزبون يعبّئ ويراقبه من نافذة صندوق الدفع",correct:!1},{text:"يبدأ التعبئة ويعود حين يتوقف العدّاد عن الدوران",correct:!1}],explanation:"لا يعبّئ الغاز المسال إلا عاملون مدرَّبون، ما لم تسمح الجهة المانحة للترخيص للزبائن بذلك، ويبقى العامل مع المركبة طوال التعبئة حتى يُطفأ الجهاز وتُغلق الصمامات. ويجب إيقاف أي تسرّب فورًا."}],steps:[{title:"اضغط زر الإيقاف الطارئ",detail:"فهو يقطع الكهرباء عن جميع المضخات دفعة واحدة. ثم أطلق إنذار الحريق.",critical:!0},{title:"أبعد الناس عن المضخات",detail:"اطلب من السائق أن يترك فوهة المضخة في السيارة ويبتعد. أخرج الجميع من المركبات وأبعدهم جيدًا، وامنع المركبات الأخرى من دخول ساحة المضخات.",critical:!0},{title:"اتصل بالرقم 115",detail:"اتصل بالرقم 115 (وبالرقم 122 إذا أُصيب أحد)، واذكر اسم المحطة وعنوانها أولًا.",critical:!0},{title:"المطفأة فقط بعد فحص «نعم أو لا»",detail:"لا يتعامل العامل المدرَّب إلا مع حريق صغير بدأ للتو، بمطفأة يشمل ملصقها الوقود السائل المشتعل (الفئة B)، وطريق الخروج خلفه، والإنذار قد أُطلق. ابدأ من المسافة المذكورة على الملصق؛ وإذا لم تنطفئ النار فورًا فابتعد."},{title:"استقبل فرق 115",detail:"أعطهم مخطط الموقع وأخبرهم بمكان الخزانات ونقطة تعبئة الغاز المسال وأزرار الإيقاف الطارئ، وهل هناك مصاب أو مفقود."}],warnings:["لا تغسل الوقود المنسكب بالماء أبدًا: فالماء يحمله إلى المجاري حيث يتجمّع البخار وقد ينفجر.","لا تفتح غطاء محرك السيارة المشتعلة أو صندوقها الخلفي أبدًا: فالهواء الجديد يُكبّر النار. واترك فوهة المضخة في السيارة.","لا تُطفئ أبدًا لهب تسرّب الغاز المسال إذا تعذّر إيقاف الغاز: فالغاز غير المحترق قد يتجمّع وينفجر."],tips:["في بداية كل مناوبة، تأكّد أن كل زر إيقاف طارئ ظاهر وغير محجوب وأن عُدّة الانسكاب مكتملة.","احفظ العنوان الدقيق للمحطة ووصفًا قصيرًا لكيفية الوصول إليها بجانب الهاتف عند صندوق الدفع.","تدرّب في التمارين على الضغط على زر الإيقاف الطارئ واستعمال عُدّة الانسكاب، وسجّل كل تمرين."],activity:{prompt:"يملأ زبون عبوة بلاستيكية موضوعة في صندوق سيارته الخلفي، والمحرك يعمل. ماذا تفعل؟",options:[{text:"أوقف المضخة، وأطلب منه إطفاء المحرك ووضع عبوة معتمدة على الأرض؛ وإذا رفض أستدعي المشرف ولا أعبّئ",correct:!0,feedback:"صحيح: المحرك العامل مصدر اشتعال، والعبوة داخل المركبة لا تستطيع تفريغ شحنتها الساكنة. أما على الأرض وفوهة المضخة تلامسها، فتذهب الشحنة إلى الأرض بأمان."},{text:"أدعه يُكمل، لأنها كمية صغيرة من الوقود",correct:!1,feedback:"الكمية لا تهم: فشرارة ساكنة أو المحرك العامل قد يُشعل البخار فورًا."},{text:"أعبّئها له بينما يُثبّت العبوة في الصندوق الخلفي",correct:!1,feedback:"العبوة ما زالت داخل المركبة حيث لا تستطيع تفريغ شحنتها الساكنة، والمحرك ما زال يعمل."},{text:"أطلب منه تقريب السيارة من المضخة لينتهي أسرع",correct:!1,feedback:"سيبقى المحرك يعمل وتبقى العبوة في الصندوق الخلفي؛ فلم يُزَل أي من الخطرين."}]},caseStudy:[{prompt:"اشتعل محرك سيارة في أثناء تعبئتها عند المضخة، واللهب يخرج من تحت غطاء المحرك. أنت العامل. ماذا تفعل أولًا؟",options:[{text:"أضغط زر الإيقاف الطارئ، وأطلق الإنذار، وأطلب من السائق أن يترك فوهة المضخة في السيارة ويبتعد",correct:!0,feedback:"صحيح: زر الإيقاف الطارئ يقطع الوقود عن جميع المضخات، ويبتعد الناس قبل أي شيء آخر."},{text:"أنزع فوهة المضخة من السيارة وأعيدها إلى المضخة",correct:!1,feedback:"اترك فوهة المضخة مكانها. فالذهاب إلى السيارة المشتعلة يعرّضك للخطر وقد يسكب الوقود."},{text:"أفتح غطاء المحرك لتصل المطفأة إلى النار",correct:!1,feedback:"الهواء الجديد يزيد النار اشتعالًا. أبقِ الغطاء مغلقًا."},{text:"أرشّ الماء بالخرطوم على السيارة والساحة",correct:!1,feedback:"الماء ينشر الوقود المشتعل ويحمله إلى المجاري."}]},{prompt:"توقفت المضخات وخرج الجميع من السيارات. ما زال سائقون آخرون يدخلون المحطة، وأحد الركاب احترقت يده. ماذا تفعل الآن؟",options:[{text:"أتصل بالرقمين 115 و122، وأذكر اسم المحطة وعنوانها أولًا، وأُبقي الجميع بعيدًا، وأمنع المركبات الأخرى من الدخول",correct:!0,feedback:"صحيح: الحريق والإصابة يعنيان 115 و122، والعنوان أولًا، وتبقى الساحة خالية من المركبات والناس."},{text:"أدع السائقين الآخرين يعبّئون بسرعة من المضخات الأبعد عن النار",correct:!1,feedback:"أُوقفت كل المضخات لسبب. أبقِ كل المركبات خارج الساحة حتى تقول فرق 115 إن المكان آمن."},{text:"أقود السيارة المشتعلة بنفسي بعيدًا عن المضخات",correct:!1,feedback:"لا تركب مركبة مشتعلة أبدًا. ابقَ بعيدًا ودع فرق 115 تتعامل معها."},{text:"أنتظر لأرى هل تنطفئ النار وحدها قبل الاتصال، تجنّبًا لبلاغ لا داعي له",correct:!1,feedback:"اتصل فورًا. فحريق سيارة في محطة وقود قد ينتشر في لحظات."}]}],realCase:"في محطة وقود، علقت فوهة المضخة مفتوحة في أثناء تعبئة سيارة زبون، فسال الوقود عبر الساحة نحو مجرى تصريف. ضغط العامل زر الإيقاف الطارئ فورًا وطلب من كل من حوله ألا يشغّلوا محركاتهم أو يدخّنوا. وارتدى زميل مدرَّب قفازين وغطّى الانسكاب بمادة ماصّة من عُدّة الانسكاب ليمنع انتشاره. كان بعض الوقود قد وصل إلى المجرى، فاتصل المشرف بالرقم 115 وذكر اسم المحطة وعنوانها. جُمعت المادة المشبعة في وعاء معدني مغلق، وبقيت المضخة خارج الخدمة حتى أُصلحت."},{id:26,code:"IND-126",icon:"Package",accent:"#0f766e",title:"السلامة من الحريق في المستودعات والمخازن",subtitle:"Stacking, Clearances, Sprinklers, Battery Charging & Security",summary:"يمكن للحريق في المستودع أن يتسلق كومة البضائع حتى السقف في دقائق. تبيّن هذه الوحدة للعاملين والمشرفين والمديرين كيف يكدّسون البضائع ويخزّنونها بأمان، ويحافظون على عمل المرشّات، ويشحنون بطاريات الرافعات الشوكية، ويتعاملون مع بطاريات الليثيوم أيون والمواد الخطرة، ويحمون المبنى ليلًا.",blocks:[{body:"في البضائع المكدّسة والرفوف العالية ينتشر اللهب بسرعة إلى أعلى الكومة ثم جانبيًا إلى جميع المستويات؛ وفي اختبارات على صناديق مخزّنة على رفوف بارتفاع 10 أمتار، وصل الحريق مرارًا إلى قمة الرفوف خلال دقيقتين (دليل الحكومة البريطانية للسلامة من الحريق في المصانع والمستودعات). ويتوقف الحِمل الحراري (Fire Load) للمستودع على ما يُخزَّن فيه، وكثيرًا ما يكون أعلى منه في المنازل والمكاتب. والقواعد الآتية ممارسات جيدة عامة؛ وعلى كل مبنى أن يستوفي أولًا متطلبات الدفاع المدني والجهة المانحة للترخيص."},{heading:"1. التكديس والمسافات الخالية",body:"يجب أن تكون البضائع المخزّنة مستقرة، وألا تعيق الناس أو المرشّات أو رجال الإطفاء:",points:["كدّس البضائع بحيث تكون مستقرة: مسنودة ومتشابكة ومحدودة الارتفاع، فلا تنزلق ولا تنهار.","لا تفرط في التخزين: لكل موقع تخزين حد أقصى مكتوب.","اترك فراغًا لا يقل عن متر واحد بين أعلى البضائع والسقف أو جسوره أو وحدات الإنارة (إرشادات HSE البريطانية).","تحت رؤوس المرشّات، حافظ على الخلوص الذي يحدده تصميم نظام المرشّات؛ والحد الأدنى العام وفق OSHA هو 45 سنتيمترًا (18 بوصة)، وبعض أنواع المرشّات تحتاج إلى أكثر.","لا تسمح أبدًا للرفوف أو البضائع بأن تحجب رؤوس المرشّات.","لا تكدّس بضائع قابلة للاشتعال على الأجهزة الكهربائية أو وحدات الإنارة أو المدافئ، حتى وهي مطفأة.","احفظ المنصّات الخشبية الفارغة ومواد التغليف والنفايات في مكان مخصّص بعيدًا عن المبنى والمخارج والنوافذ، أو في منطقة محمية بالمرشّات."]},{heading:"2. الممرات والمخارج وأبواب الحريق",body:"الطرق المفتوحة تتيح للناس الخروج ولفرق 115 الوصول إلى الحريق:",points:["أبقِ الممرات خالية من العوائق وفي حالة جيدة؛ والممرات الدائمة معلَّمة على الأرض.","لا تضع البضائع أبدًا في طرق الإخلاء أو أمام المخارج وأبواب الحريق والستائر المعدنية المقاومة للحريق (fire shutters) والمطافئ ونقاط إطلاق الإنذار.","اترك فراغًا بين البضائع والجدران الداخلية ليصل رجال الإطفاء إلى الحريق (الإرشادات البريطانية: 0.5 متر).","يجب أن تُفتح مخارج الحريق من الداخل من دون مفتاح ما دام في المبنى أحد.","لا يقود الرافعات الشوكية إلا مشغّلون مدرَّبون ومرخَّصون، ويسير المشاة في الممرات المعلَّمة."]},{heading:"3. المرشّات: حافظ على جاهزيتها",body:"تسيطر المرشّات على الحريق تلقائيًا، حتى ليلًا حين لا يوجد أحد، ولكن فقط إذا لم يعقها شيء:",points:["لا تعلّق أبدًا أي شيء على رؤوس المرشّات أو أنابيبها، ولا تطلِها أو تغطِّها أو تصدمها؛ وأبلغ فورًا عن أي رأس تالف أو يسرّب الماء.","تبقى صمامات التحكم في المرشّات مفتوحة بالكامل. ولا يجوز إغلاق أي منها إلا لشخص مخوَّل، وفق إجراء الموقع لتعطيل الحماية من الحريق، مع مراقبة حريق إضافية حتى يُعاد فتحه.","إذا وجدت صمامًا مغلقًا أو رأسًا محجوبًا، فأبلغ المشرف فورًا: فقد تكون المنطقة بلا حماية.","لا تنفتح المرشّات إلا حيث تصلها حرارة الحريق، لذلك يمكن لحريق تحت رأس محجوب أن يكبر دون أن يُرى.","يُجرى الفحص والاختبار والصيانة وفق NFPA 25 ومتطلبات الدفاع المدني؛ واحتفظ بالسجلات.","بعض المنتجات لا يجوز تخزينها أصلًا في مناطق محمية بالمرشّات؛ وتذكر ذلك صحيفة بيانات السلامة (SDS)."]},{heading:"4. شحن بطاريات الرافعات الشوكية",body:"يطلق شحن بطاريات الرصاص الحمضية (lead-acid) غاز الهيدروجين، وهو غاز شديد الاشتعال؛ وإذا تجمّع ووصلته شرارة أو لهب، فقد ينفجر:",points:["اشحن في منطقة الشحن المخصّصة فقط: منطقة جيدة التهوية (مع تهوية عالية فوق البطاريات)، بعيدة عن البضائع المخزّنة ومصادر الاشتعال.","لا تدخين ولا لهب ولا أعمال ساخنة ولا هواتف في منطقة الشحن.","أطفئ الشاحن قبل توصيل البطارية أو فصلها، لتجنب الشرر.","أبعِد الأدوات والأجسام المعدنية الأخرى عن سطح البطاريات، وانزع الساعة والخاتم والقطع المعدنية الأخرى قبل العمل عليها.","افتح غطاء البطارية في أثناء الشحن، وارتدِ معدات الوقاية الشخصية المحددة لهذه المهمة (قفازات ومريلة وواقيًا للعينين من الحمض).","بدّل أسطوانات الغاز (LPG) للرافعات العاملة بالغاز في الخارج، بعيدًا عن مصادر الاشتعال.","لا يبدّل البطاريات أو يشحنها إلا عاملون مدرَّبون."]},{heading:"5. بطاريات الليثيوم أيون",body:"يمكن لبطاريات الليثيوم أيون التالفة أو المحمومة أو المشحونة بطريقة خاطئة أن تشتعل أو تنفجر، وقد تنتقل حرارة خلية متعطلة إلى الخلية المجاورة (الانفلات الحراري thermal runaway):",points:["اتبع تعليمات الشركة المصنّعة في التخزين والاستخدام والشحن، ولا تستخدم إلا الشاحن المصنوع لتلك البطارية.","خزّن البطاريات والأجهزة في أماكن جافة وباردة بعيدًا عن المدافئ ومصادر الحرارة الأخرى، وافصلها عن الشاحن عند امتلائها.","ابحث عن علامات الخطر: الانتفاخ أو التشقق، أو الهسهسة، أو التسرّب، أو ارتفاع الحرارة، أو الدخان. وتُسحب البطارية التي تظهر عليها أي علامة منها من الاستخدام فورًا.","إذا كان لمسها آمنًا، فانقلها إلى المكان المخصّص بعيدًا عن المواد القابلة للاشتعال، مثل وعاء معدني مقاوم للحريق فيه رمل، وأرسلها للتخلص منها بالطريقة المعتمدة.","إذا كانت البطارية تُطلق دخانًا أو تحترق، فلا تحملها: نبّه الآخرين، وأطلق الإنذار، واخرج، واتصل بالرقم 115. خلايا الليثيوم أيون لا تحتوي على ليثيوم معدني، وتُبرَّد بكمية كبيرة من الماء؛ أما الحريق في البطاريات المخزّنة فمن عمل فرق 115.","قد تشتعل حرائق البطاريات من جديد بعد أن تبدو منطفئة؛ فأخبر فرق 115 بأماكن تخزين البطاريات."],critical:!0},{heading:"6. النظافة والترتيب والمواد الخطرة",body:"قلة النفايات تعني وقودًا أقل للحريق، والتخزين الصحيح يُبقي الحادث الصغير صغيرًا:",points:["أبقِ مناطق التخزين خالية من مواد التغليف المتناثرة والنفايات؛ واجمع النفايات في حاويات مناسبة وأزِلها بانتظام.","التدخين ممنوع في مناطق التخزين.","اقرأ الملصق وصحيفة بيانات السلامة (SDS) لكل منتج خطر قبل تخزينه؛ ويبيّن القسم 7 من الصحيفة شروط التخزين والمواد غير المتوافقة.","افصل المواد غير المتوافقة بعضها عن بعض: فإذا خُزّنت معًا فقد تزيد سرعة نمو الحريق أو تطلق دخانًا سامًا.","لا تُدخل العبوات التالفة أو المسرّبة إلى المخزن؛ ضعها في صينية أو حوض احتواء (bund) واتبع تعليمات المورّد.","احتفظ بسجل محدَّث للمواد الخطرة وأماكن تخزينها، في مكان يمكن منه تسليمه لفرق 115 في حالة الطوارئ."]},{heading:"7. الحماية الليلية والإنذار",body:"الحريق الذي يبدأ والمبنى مغلق قد يكبر دون أن يراه أحد، والمباني الخالية هدف للحرق العمد (arson):",points:["أنِر محيط المبنى جيدًا وأبقِ حدود الموقع مؤمَّنة؛ وأغلق الأبواب والنوافذ وفتحات السقف دون أن تسد طرق الإخلاء.","لا تضع حاويات النفايات الكبيرة ملاصقة للمبنى؛ واحفظ صناديق النفايات في حظيرة مقفلة بعيدًا عنه.","أقفل على السوائل والغازات القابلة للاشتعال حتى لا يستخدمها المتسللون.","يخضع إنذار الحريق وإنذار السرقة للمراقبة، ويستجيب أحد فورًا لكل إنذار.","يعرف الحراس كيف يطلقون الإنذار، وكيف يتصلون بالرقم 115 ويذكرون العنوان الدقيق، وكيف يستقبلون فرق 115 عند البوابة ومعهم المفاتيح ومخطط الموقع.","أبلغ عن الأشخاص الذين يتصرفون بشكل مريب وعن أي حرائق صغيرة مجهولة السبب؛ فقد تكون إنذارًا بحرق عمد.","حدّث تقييم مخاطر الحريق مرة في السنة على الأقل وبعد كل تغيير كبير فيما تخزّنه أو في طريقة تخزينه."]}],media:[{kind:"image",src:"media/images/w8_warehouse_fire_safety.webp",title:"مستودع منظم وآمن من الحريق",description:"ممرات مفتوحة، وفراغ تحت المرشّات، ومنطقة شحن منفصلة"}],quiz:[{question:"وفق إرشادات HSE البريطانية، ما الفراغ الذي يجب تركه بين أعلى البضائع المخزّنة والسقف أو الجسور أو وحدات الإنارة؟",options:[{text:"متر واحد على الأقل",correct:!0},{text:"10 سنتيمترات على الأقل",correct:!1},{text:"25 سنتيمترًا على الأقل",correct:!1},{text:"لا شيء، إذا كانت الكومة مستقرة",correct:!1}],explanation:"تطلب إرشادات HSE للمستودعات مترًا واحدًا على الأقل بين أعلى البضائع والسقف أو جسوره أو وحدات الإنارة؛ وتحت المرشّات يُطبَّق الخلوص الذي يحدده تصميم النظام (والحد الأدنى العام وفق OSHA هو 45 سنتيمترًا)."},{question:"أي ممارسة صحيحة عند شحن بطاريات الرافعات الشوكية؟",options:[{text:"الشحن بين الرفوف لتكون الرافعة جاهزة للوردية التالية",correct:!1},{text:"فصل البطارية والشاحن ما زال يعمل",correct:!1},{text:"استخدام منطقة الشحن المهوّاة بلا تدخين ولا لهب",correct:!0},{text:"وضع الأدوات المعدنية على سطح البطارية لتكون في المتناول",correct:!1}],explanation:"يطلق الشحن غاز الهيدروجين. والمنطقة المخصّصة الجيدة التهوية الخالية من مصادر الاشتعال تمنع تجمّعه واشتعاله؛ وإطفاء الشاحن قبل الفصل وإبعاد الأدوات المعدنية عن البطارية يمنعان الشرر."},{question:"في أثناء جرد البضائع وجدت صمام تحكم في المرشّات مغلقًا. ماذا تفعل؟",options:[{text:"أبلّغ المشرف فورًا ليُعاد فتحه بأمان",correct:!0},{text:"أتركه مغلقًا، فإنذار الحريق سينبّه إلى أي حريق",correct:!1},{text:"أفتحه إلى المنتصف ليبقى ضغط الماء منخفضًا",correct:!1},{text:"أعلّق عليه ورقة وأفحصه في تفتيش الشهر القادم",correct:!1}],explanation:"صمام التحكم المغلق قد يترك منطقة كاملة بلا حماية بالمرشّات. يجب الإبلاغ عنه فورًا، ويعيد فتحه شخص مخوَّل وفق إجراء الموقع."},{question:"بطارية ليثيوم أيون مخزّنة منتفخة وتسخن. ما الإجراء الصحيح؟",options:[{text:"اسحبها من الاستخدام؛ وإن أطلقت دخانًا فأطلق الإنذار واتصل بالرقم 115",correct:!0},{text:"أعدها إلى الشحن لتتوازن خلاياها وتبرد",correct:!1},{text:"لفّها بالكرتون واتركها على الرف حتى تُنقل",correct:!1},{text:"رشّها مرة بثاني أكسيد الكربون CO₂ وأعدها إلى الرف",correct:!1}],explanation:"الانتفاخ والسخونة علامتا تعطّل البطارية. اسحبها من الاستخدام، وإذا كان لمسها آمنًا فاعزلها بعيدًا عن المواد القابلة للاشتعال؛ وإن أطلقت دخانًا أو احترقت فلا تلمسها: أطلق الإنذار، واخرج، واتصل بالرقم 115."},{question:"أي إجراء يحمي المستودع المغلق من الحرق العمد على أفضل وجه؟",options:[{text:"حاويات نفايات كبيرة ملاصقة للجدار ليراها الحارس",correct:!1},{text:"إطفاء الإنذار ليلًا لتجنب الإنذارات الكاذبة",correct:!1},{text:"النفايات بعيدة عن المبنى وإنذار خاضع للمراقبة",correct:!0},{text:"ترك السوائل القابلة للاشتعال قرب الباب لتسليمها صباحًا",correct:!1}],explanation:"كثيرًا ما يستخدم مرتكبو الحرق العمد النفايات والسوائل القابلة للاشتعال الموجودة في الموقع. وإبعاد حاويات النفايات عن المبنى، والإقفال على المواد القابلة للاشتعال، ووجود إنذارات مراقَبة يُستجاب لها، كلها تقلل الخطر (دليل الحكومة البريطانية)."},{question:"انتهى شحن بطارية رافعة شوكية ويجب فصلها. ما الطريقة الآمنة؟",options:[{text:"أطفئ الشاحن أولًا، ثم افصل البطارية",correct:!0},{text:"افصل البطارية أولًا، ثم أطفئ الشاحن",correct:!1},{text:"اسحب الكابل والشاحن يعمل، لتبقى الشحنة كاملة",correct:!1},{text:"أغلق غطاء البطارية أولًا، ثم اسحب الكابل بسرعة",correct:!1}],explanation:"يطلق الشحن غاز الهيدروجين. وإطفاء الشاحن قبل الفصل يمنع الشرارة في مكان قد يكون الغاز تجمّع فيه؛ ويبقى غطاء البطارية مفتوحًا في أثناء الشحن."}],steps:[{title:"أطلق الإنذار واتصل بالرقم 115",detail:"اضغط أقرب نقطة نداء للإنذار واتصل بالرقم 115، واذكر العنوان الدقيق للموقع وما الذي يحترق.",critical:!0},{title:"أخرج الجميع عبر الممرات المحدّدة",detail:"يتوقف سائقو الرافعات الشوكية ويتركون رافعاتهم حيث لا تسدّ الممرات أو المخارج. ويذهب الجميع إلى نقطة التجمع، ولا يبقى أحد لإنقاذ البضائع.",critical:!0},{title:"لا تكافح حريقًا في البضائع المكدّسة",detail:"يصعد اللهب في البضائع المكدّسة إلى السقف بسرعة كبيرة. لا تستعمل المطفأة إلا على حريق صغير بدأ للتو وبعد فحص «نعم أو لا»؛ وإلا فاخرج ودع المرشّات وفرق 115 تتعامل معه.",critical:!0},{title:"دخان البطاريات: لا تلمسها",detail:"إذا كانت بطارية أو منطقة الشحن تُصدر دخانًا أو تحترق، فلا تحمل شيئًا: نبّه الآخرين واخرج وأخبر 115 بأن الأمر يتعلق ببطاريات.",critical:!0},{title:"استقبل فرق 115 عند البوابة",detail:"عُدّ الجميع، ثم أعطِ فرق 115 المفاتيح ومخطط الموقع وسجلّ البضائع الخطرة، وأخبرهم بمكان تخزين البطاريات."}],warnings:["لا تكدّس البضائع أبدًا بحيث تحجب رؤوس المرشّات أو تملأ الفراغ تحتها: فالحريق تحت رأس محجوب قد يكبر دون أن يُرى.","لا تغلق صمام التحكم في المرشّات أبدًا ما لم تكن مخوّلًا وفق إجراء الموقع: فالمنطقة تبقى بلا حماية.","لا تحمل أبدًا بطارية ليثيوم أيون تُصدر دخانًا أو تحترق: فقد تشتعل من جديد وتطلق دخانًا سامًّا."],tips:["في نهاية كل مناوبة، امشِ في الممرات وتأكّد أن المخارج وأبواب الحريق والمطافئ ونقاط نداء الإنذار غير محجوبة.","احفظ سجلّ البضائع الخطرة ومخطط الموقع عند البوابة أو في مكتب الحراس، جاهزين لتسليمهما إلى فرق 115.","علّم على الأرض المناطق التي يجب أن تبقى خالية أمام المخارج ومعدات الحريق، ليراها الجميع."],activity:{prompt:"وصلت شحنة كبيرة والرفوف ممتلئة. يقترح مشرف وضع المنصات الزائدة في الممر الرئيسي وفوق أعلى رف، قريبًا تحت المرشّات، حتى الأسبوع القادم. ماذا تفعل؟",options:[{text:"أرفض، وأجد منطقة تخزين أخرى أو أؤجّل جزءًا من الشحنة، مع إبقاء الممرات والفراغ تحت المرشّات خالية",correct:!0,feedback:"صحيح: الممرات طرق للإخلاء والوصول، ولكل موقع تخزين حد أقصى مكتوب، ويجب أن يبقى الفراغ تحت المرشّات خاليًا."},{text:"أوافق، لأن المنصات ستبقى هناك بضعة أيام فقط",correct:!1,feedback:"الحريق لا ينتظر الأسبوع القادم. الممرات المسدودة والمرشّات المحجوبة خطرة من الساعة الأولى."},{text:"أضعها في الممر الرئيسي مع ترك فجوة ضيقة لمرور الناس",correct:!1,feedback:"يجب أن تبقى الممرات خالية للإخلاء ولفرق 115، والتخزين الزائد يتجاوز الحد الأقصى المكتوب."},{text:"أضعها أمام مخرج الحريق الخلفي الذي نادرًا ما يُستعمل",correct:!1,feedback:"لا تخزّن البضائع أمام المخارج أبدًا. فالمخرج النادر الاستعمال قد يكون الطريق الوحيد للخروج في الحريق."}]},caseStudy:[{prompt:"في المناوبة الليلية، يرى حارس دخانًا يخرج من منطقة شحن البطاريات، حيث تُشحن ثلاث رافعات شوكية. ماذا يفعل الحارس أولًا؟",options:[{text:"يطلق الإنذار ويتصل بالرقم 115 ذاكرًا العنوان الدقيق، ويقول إن الدخان في منطقة شحن البطاريات",correct:!0,feedback:"صحيح: الإنذار والاتصال أولًا، ويجب أن تعرف فرق 115 أن الأمر قد يتعلق ببطاريات وهيدروجين."},{text:"يدخل الدخان لفصل الشواحن واحدًا تلو الآخر",correct:!1,feedback:"لا يدخل أحد الدخان. فالشحن يطلق الهيدروجين، والفصل والتيار يمرّ قد يُحدث شررًا."},{text:"يقود الرافعات الشوكية خارج منطقة الشحن لإنقاذها",correct:!1,feedback:"ركوب رافعة قد تكون بطاريتها مشتعلة يعرّضه لخطر كبير. فالبضائع والآلات يمكن تعويضها."},{text:"يفتح كل الأبواب ليخرج الدخان قبل أن يتصل بأحد",correct:!1,feedback:"الهواء الجديد يغذّي النار، وكل دقيقة بلا اتصال تجعلها تكبر. أطلق الإنذار واتصل بالرقم 115 أولًا."}]},{prompt:"فرق 115 في الطريق. الإنذار يدوّي، وانضم عاملان من منطقة التحميل إلى الحارس عند البوابة. ماذا يفعل الحارس الآن؟",options:[{text:"يتأكد من عدّ كل من في الموقع، ويفتح البوابة، ويعطي فرق 115 المفاتيح ومخطط الموقع ومكان تخزين البطاريات والبضائع الخطرة",correct:!0,feedback:"صحيح: العدّ والمفاتيح ومعلومات الموقع تسمح لفرق 115 بالبدء فورًا وبأمان."},{text:"يعود إلى منطقة الشحن بمطفأة ليكافح النار",correct:!1,feedback:"حريق في منطقة شحن فيها عدة بطاريات من عمل فرق 115. ويبقى الحارس عند البوابة ليرشدهم."},{text:"يرسل العاملين إلى منزليهما حتى لا يعيقا العمل",correct:!1,feedback:"يبقى الجميع عند نقطة التجمع ليُعدّوا وليجيبوا عن أسئلة فرق 115."},{text:"يقفل البوابة حتى لا يدخل أحد إلى الموقع",correct:!1,feedback:"يجب أن تدخل فرق 115 فورًا. والبوابة المقفلة دون من يحمل المفتاح تضيّع الوقت."}]}],realCase:"في أثناء جرد البضائع في مستودع، لاحظت عاملة أن المنصات كُدّست عاليًا حتى حجبت رأسين من رؤوس المرشّات، وأن صمام تحكم قريبًا في المرشّات بقي نصف مغلق بعد إصلاح. أبلغت المشرف بالأمرين فورًا. نُقلت المنصات إلى منطقة تخزين أخرى، وأعاد شخص مخوّل فتح الصمام وفق إجراء الموقع وفحص النظام. وأضاف المدير النقطتين إلى الجولة التفقدية المنتظمة. وإذا بدأ حريق في تلك المنطقة الآن، فالمرشّات قادرة على أداء عملها."},{id:27,code:"IND-127",icon:"HardHat",accent:"#ca8a04",title:"السلامة في مواقع البناء",subtitle:"Fire Plan, Hot Work, Temporary Electrics, Cylinders, Excavations & UXO",summary:"كثيرًا ما تفتقر المباني قيد الإنشاء إلى مرشّات أو إنذارات حريق عاملة، مع أنها مليئة بمصادر الاشتعال والمواد القابلة للاحتراق. تبيّن هذه الوحدة للعمال والمشرفين والمديرين كيف يخططون لمواجهة الحريق؛ ويسيطرون على الأعمال الساخنة والكهرباء المؤقتة وأسطوانات الوقود والغاز؛ ويتعرفون على الخطر عند السقالات والحفريات؛ ويقدّمون الإسعافات الأولية؛ وماذا يفعلون عند العثور على جسم مشبوه في أثناء الحفر.",blocks:[{body:"بحسب NFPA، فإن الأسباب الرئيسية للحرائق في المباني قيد الإنشاء هي معدات الطهي، ومعدات توزيع الكهرباء والإنارة، ومعدات التدفئة. وقد لا تكون المرشّات وكواشف الدخان وإنذارات الحريق عاملة بعد، كما تجذب المواقع المفتوحة المتسللين ومرتكبي الحرق العمد. ويضع الدفاع المدني والجهة المانحة للترخيص قواعد مواقع البناء وتصاريحها ورخصها: التزم بمتطلباتهما. وتقدّم هذه الوحدة القواعد الأساسية لكل من في الموقع."},{heading:"1. خطة الحريق في الموقع ونقطة التجمع",body:"قبل بدء العمل، يُعدّ المقاول الرئيسي المسيطر على الموقع خطة الحريق:",points:["تقييم لمخاطر الحريق وخطة طوارئ مكتوبة، جاهزان قبل بدء العمل ويُحدَّثان مع ارتفاع المبنى.","شخص مسمّى يدير الوقاية من الحريق في الموقع (في NFPA 241: مدير برنامج الوقاية من الحريق).","طرق إخلاء من كل منطقة عمل، مفتوحة وموسومة، ولا تُقفل أبدًا ما دام في الموقع أحد؛ ومساران في اتجاهين مختلفين حيثما أمكن.","إنذار حريق يسمعه الجميع فوق ضجيج الموقع، ولافتات تعليمات الحريق عند نقاط الحريق ومداخل الموقع وأماكن تناول الطعام.","نقاط حريق فيها مطافئ مناسبة، وأشخاص معيَّنون مدرَّبون على استخدامها.","نقطة تجمع يُحصى فيها الجميع، بالعدّ أو بتفقد المنطقة.","تمارين إخلاء لاختبار الخطة والتدريب؛ ويتعرّف كل عامل جديد وكل زائر على الخطة عند التعريف الأولي بالموقع."]},{heading:"2. الأعمال الساخنة: التصريح ومراقبة الحريق",body:"يتسبب اللحام والقطع والجلخ (grinding) والعمل باللهب في كثير من حرائق مواقع البناء. استخدم طريقة أخرى إن كانت تؤدي الغرض؛ وإلا:",points:["لا تعمل إلا بتصريح العمل الساخن (Hot Work Permit) الصادر عن الشخص المخوَّل بالموافقة عليه.","أزِل المواد القابلة للاحتراق ضمن 11 مترًا (35 قدمًا) من العمل، أو احمِها ببطانيات أو ستائر مقاومة للحريق، أو انقل العمل إلى مكان آمن.","جهّز مطفأة مناسبة في مكان العمل.","يبقى مراقب الحريق (Fire Watch) في أثناء العمل وفي فترات الاستراحة، ولمدة ساعة واحدة على الأقل بعد انتهاء العمل؛ ويجوز للمسؤول عن التصريح أن يطلب مراقبة أطول (NFPA 51B).","خطّط لإنهاء العمل الساخن قبل نهاية يوم العمل بوقت كافٍ لإجراء الفحوص قبل إغلاق الموقع (HSE البريطانية: قبل ساعتين)."]},{heading:"3. الكهرباء المؤقتة",body:"تسبب أسلاك الكهرباء المؤقتة في الموقع حرائق وصعقات كهربائية عندما تُحمَّل فوق طاقتها أو تتلف أو يعدّلها أشخاص غير مؤهلين:",points:["لا يصمّم التمديدات المؤقتة أو يركّبها أو يعدّلها أو يفحصها إلا كهربائي مؤهل؛ ولا يضيف إليها أحد غيره شيئًا أو يغيّرها.","تُحمى المقابس التي يستخدمها العمال بجهاز حماية من تيار التسرّب (RCD)، يقطع الكهرباء بسرعة عند تسرّب التيار إلى الأرض؛ اضغط زر اختباره بانتظام. ويقلل هذا الجهاز الخطر لكنه لا يغني عن تمديدات سليمة.","لا تُحمّل المقابس والمشتركات متعددة المخارج فوق طاقتها، ولا توصل أسلاك التمديد بعضها ببعض، وافرد بكرات الأسلاك بالكامل قبل الاستخدام.","استخدم كابلًا مرنًا مناسبًا لأسلاك التمديد، مرفوعًا عن الأرض؛ واسحب الأسلاك والأدوات التالفة من الاستخدام بدلًا من لفّها بالشريط العازل.","لا تمدّ الكابلات المؤقتة أو لوحات توزيع الكهرباء في طرق الإخلاء، وأبعِد النفايات عن لوحات التوزيع."]},{heading:"4. الوقود وأسطوانات الغاز في الموقع",body:"يُدخل الوقود والغاز المسال (LPG) والأسيتيلين والأكسجين كمية كبيرة من الطاقة المخزّنة إلى الموقع:",points:["لا تُبقِ في الموقع إلا أقل كمية لازمة، في مخزن مؤمَّن وجيد التهوية بعيدًا عن المواد القابلة للاحتراق ومناطق العمل، ولا تخزّنها أبدًا داخل المبنى قيد الإنشاء.","لا تستخدم للوقود إلا عبوات معتمدة، ولا تخزّن الوقود أبدًا في المخارج أو السلالم أو الممرات.","زوّد الآليات بالوقود في مكان مخصّص، والمحركات مطفأة، ومن دون تدخين، ومع مطفأة قريبة.","أبقِ أسطوانات الغاز قائمة ومثبتة حتى لا تسقط، مع أغطية الصمامات عندما لا تُستخدم، وبعيدة عن الشرر وخَبَث اللحام الساخن واللهب.","خزّن أسطوانات الأكسجين منفصلة عن أسطوانات الغاز القابل للاشتعال: بينهما 6 أمتار (20 قدمًا) على الأقل، أو خلف حاجز مقاوم للحريق (OSHA).","أقفل على الوقود والأسطوانات في نهاية اليوم حتى لا يستخدمها المتسللون.","إذا تسرّب الغاز من أسطوانة أو اشتعل: لا تغلق الصمام إلا إذا أمكن الوصول إليه بأمان؛ ولا تطفئ أبدًا لهب غاز لا يمكن إيقافه؛ وأبعِد الجميع واتصل بالرقم 115."]},{heading:"5. السقالات والحفريات: تعرّف على الخطر وتوقف",body:"يقتل السقوط من المرتفعات وانهيار الخنادق عمال البناء. وتصميم السقالات ودعامات الخنادق عمل المختصين الأكفاء؛ أما كل من في الموقع فعليه أن يتعرّف على الخطر ويتوقف:",points:["لا تستخدم السقالة إلا بعد أن يفحصها شخص كفء قبل الوردية؛ ولا تستخدم أبدًا سقالة تالفة أو ناقصة أو بلا حواجز حماية، ولا تعدّلها بنفسك أبدًا.","يحتاج العمل على ارتفاع 1.8 متر (6 أقدام) أو أكثر فوق مستوى أدنى، أو قرب حافة مفتوحة أو فتحة، إلى حماية من السقوط: حواجز حماية أو أغطية أو حزام أمان كامل مربوط بنقطة تثبيت متينة.","لا تدخل أبدًا خندقًا غير محمي. ووفق OSHA تحتاج الحفريات التي يبلغ عمقها 1.5 متر (5 أقدام) أو أكثر إلى نظام حماية مصمَّم للموقع، ما لم تكن محفورة في صخر ثابت.","أبعِد أكوام التراب والمواد والآليات 0.6 متر (قدمين) على الأقل عن الحافة.","يفحص شخص كفء الحفريات كل يوم وبعد المطر.","عند ظهور علامات الانهيار (تشققات في الأرض، أو انتفاخ الجدران، أو تسرّب الماء إلى الداخل، أو تساقط التراب): اخرج فورًا، وامنع الآخرين من الدخول، وأبلغ المشرف؛ ولا يُستأنف العمل إلا بعد السيطرة على الخطر."]},{heading:"6. وصول فرق 115 والإسعافات الأولية",body:"في الحريق أو الإصابة، كل دقيقة مهمة:",points:["أبقِ مدخل الموقع وبواباته وطرق الوصول إليه مفتوحة لسيارات الإطفاء التابعة للرقم 115 وسيارات الإسعاف؛ ولا تركن عليها ولا تضع فيها مواد.","أبقِ حنفيات الحريق ونقاط المياه ومعدات الإطفاء ظاهرة وسهلة الوصول.","تتواصل المواقع الكبيرة مع الدفاع المدني قبل بدء العمل وكلما تغيّرت طرق الوصول أو المخاطر، وتُبقي ملف معلومات (مخطط الموقع، والمخاطر، والوقود والغاز والبطاريات المخزّنة) جاهزًا لفرق 115.","يوجد في الموقع شخص مدرَّب على الإسعافات الأولية وحقيبة إسعافات أولية مجهّزة.","علّق عنوان الموقع وإرشادات الوصول إليه والرقمين 115 و122 قرب الهواتف وفي مكتب الموقع وعند المدخل.","بعد السقوط من مرتفع، لا تحرّك المصاب إلا إذا كان المكان غير آمن أو احتاج إلى الإنعاش القلبي الرئوي (CPR)؛ واتصل بالرقم 122."]},{heading:"7. جسم مشبوه في أثناء الحفر",body:"قد يُعثر على ذخائر قديمة غير منفجرة في أثناء الحفر، حتى في أماكن تُعدّ آمنة، وقد تنفجر إذا حُرّكت أو صُدمت. إذا كشفت آلة أو عامل أو أداة جسمًا مشبوهًا:",points:["أوقف الآلة والعمل فورًا.","لا تلمس الجسم أبدًا، ولا تحرّكه أو ترفعه أو تحفر حوله أو تسحبه، ولا تضعه أبدًا في دلو الآلة أو في مركبة.","أخلِ المنطقة من الجميع، وامنع الناس والآليات من دخولها.","ابتعد كثيرًا (50 مترًا على الأقل، وفق UNMAS) قبل استخدام الهاتف أو جهاز اللاسلكي، ثم اتصل بالرقم 115 واتبع تعليمات الدفاع المدني.","من مكان آمن، تذكّر موضع الجسم وأخبر به فرق 115؛ ولا يُستأنف العمل إلا عندما تعلن الجهات المختصة أن الموقع آمن."],critical:!0}],media:[{kind:"image",src:"media/images/w8_construction_site_fire_safety.webp",title:"موقع بناء مستعد لمواجهة الحريق",description:"تصريح عمل ساخن مع مراقب حريق، وأسطوانات مثبتة، وطريق وصول مفتوح"}],quiz:[{question:"وفق NFPA 51B، كم يجب أن يبقى مراقب الحريق بعد انتهاء العمل الساخن؟",options:[{text:"ساعة واحدة على الأقل، أو أكثر إذا طلب التصريح ذلك",correct:!0},{text:"حتى يجمع اللحّام أدواته ويغادر الموقع",correct:!1},{text:"نحو 10 دقائق، إذا لم يُرَ دخان حتى ذلك الوقت",correct:!1},{text:"لا حاجة إلى مراقبة ما دامت هناك مطفأة قريبة",correct:!1}],explanation:"قد يبقى الشرر في أماكن خفية ويُشعل حريقًا لاحقًا. ويشترط NFPA 51B بقاء مراقب الحريق ساعة واحدة على الأقل بعد العمل، ويجوز للمسؤول عن التصريح أن يطلب مراقبة أطول."},{question:"تلف العازل في سلك تمديد في الموقع. ماذا يجب أن يُفعل؟",options:[{text:"يُسحب من الاستخدام ويستبدله شخص مؤهل",correct:!0},{text:"يُلفّ الجزء التالف بالشريط العازل ويستمر العمل",correct:!1},{text:"يوصَل بسلك آخر ليحمل كل منهما تيارًا أقل",correct:!1},{text:"يُستخدم للأدوات اليدوية الصغيرة فقط حتى ينتهي العمل",correct:!1}],explanation:"الأسلاك التالفة تسبب الصعق والحرائق. تُسحب من الاستخدام ويستبدلها أو يصلحها شخص كفء إصلاحًا صحيحًا، ولا تُلفّ بالشريط أبدًا (HSE البريطانية)؛ وجهاز RCD يقلل الخطر لكنه لا يجعل السلك التالف آمنًا."},{question:"ظهرت تشققات في الأرض وبدأ التراب يتساقط في خندق يعمل فيه زميل. ما التصرف الصحيح؟",options:[{text:"أخرِج الجميع، وامنع الدخول، وأبلغ المشرف",correct:!0},{text:"أكمِل الجزء المتبقي بسرعة قبل أن يتحرك الجدار",correct:!1},{text:"انزل وادعم الجدار بألواح خشبية إضافية",correct:!1},{text:"أوقف الحفّارة على الحافة ليثبّت وزنها التراب",correct:!1}],explanation:"التشققات وتساقط التراب علامات انهيار. يخرج العمال فورًا ويبقون خارج الخندق حتى يجعله شخص كفء آمنًا؛ والآلة الثقيلة على الحافة تزيد احتمال الانهيار."},{question:"كشفت حفّارة جسمًا صدئًا يشبه قذيفة. ما الإجراء الصحيح؟",options:[{text:"ارفعه بلطف بدلو الحفّارة وضعه جانبًا",correct:!1},{text:"أزِل التراب عنه لتتأكد مما إذا كان حقيقيًا",correct:!1},{text:"أوقف العمل، وأخلِ المنطقة، واتصل بالرقم 115 من مكان بعيد",correct:!0},{text:"انقله إلى مكتب الموقع حتى تصل الشرطة",correct:!1}],explanation:"قد تنفجر الذخائر عند تحريكها أو صدمها. توقف فورًا، وأبعِد الجميع، ولا تحرّكها أبدًا، واتصل بالرقم 115 من مكان بعيد، وتجنّب استخدام الهاتف أو اللاسلكي قرب الجسم (UNMAS)."},{question:"أي ترتيب صحيح لأسطوانات الغاز في موقع البناء؟",options:[{text:"ممددة على جنبها حتى لا تسقط",correct:!1},{text:"على السلالم، لأنها أبرد مكان في الموقع",correct:!1},{text:"الأكسجين والأسيتيلين مربوطان معًا بسلسلة في مخزن واحد",correct:!1},{text:"قائمة ومثبتة، والأغطية عليها، وبعيدة عن الشرر والحرارة",correct:!0}],explanation:"تُحفظ الأسطوانات قائمة ومثبتة مع أغطية الصمامات، بعيدًا عن الشرر والحرارة، ويُفصل الأكسجين عن الغاز القابل للاشتعال (OSHA 1926.350). والسلالم طرق إخلاء يجب أن تبقى خالية من الوقود والأسطوانات."},{question:"ما زال اللحام مستمرًا، لكن مراقب الحريق ذهب لتناول الغداء. ماذا يجب أن يحدث؟",options:[{text:"تتوقف الأعمال الساخنة حتى يعود مراقب الحريق إلى مكانه",correct:!0},{text:"يستمر العمل، لأن المطفأة جاهزة في موقع العمل",correct:!1},{text:"يُنهي عامل اللحام العمل بسرعة قبل أن يعود المراقب",correct:!1},{text:"يراقب عامل اللحام الشرر بنفسه وهو يواصل العمل",correct:!1}],explanation:"وفق NFPA 51B يبقى مراقب الحريق في أثناء العمل وفترات الاستراحة. ولا يستطيع عامل اللحام مراقبة الشرر وهو يعمل، والمطفأة لا تنفع إلا إذا كان هناك من يرى النار."}],steps:[{title:"التصريح قبل البدء",detail:"استعمل طريقة أخرى إن كانت تؤدي العمل. وإلا فلا تعمل إلا بتصريح أعمال ساخنة صادر عن الشخص المخوّل بالموافقة عليه.",critical:!0},{title:"أزِل المواد القابلة للاحتراق أو احمِها",detail:"أزِل المواد القابلة للاحتراق من حول العمل كما يقول التصريح، وغطِّ ما لا يمكن نقله ببطانيات أو ستائر مقاومة للنار، أو انقل العمل إلى مكان آمن.",critical:!0},{title:"المطفأة ومراقب الحريق في مكانهما",detail:"أبقِ مطفأة مناسبة جاهزة في موقع العمل. ويبقى مراقب الحريق في أثناء العمل وفترات الاستراحة."},{title:"واصل المراقبة بعد انتهاء العمل",detail:"يبقى مراقب الحريق ساعة واحدة على الأقل بعد انتهاء العمل، أو أكثر إن نصّ التصريح على ذلك (NFPA 51B)، ويطلق الإنذار عند أول علامة دخان.",critical:!0},{title:"أنهِ مبكرًا وتفقّد قبل إغلاق الموقع",detail:"خطّط لأن تنتهي الأعمال الساخنة قبل نهاية يوم العمل بوقت كافٍ، لكي يُتفقَّد المكان قبل أن يغادر الجميع."}],warnings:["لا تلمس أبدًا جسمًا مشبوهًا عُثر عليه في أثناء الحفر، ولا تحرّكه ولا تحفر حوله: فقد ينفجر إذا حُرّك أو صُدم.","لا تدخل أبدًا خندقًا غير محمي أو خندقًا تظهر فيه علامات الانهيار: فقد تنهار جدرانه دون إنذار.","لا تخزّن الوقود أو أسطوانات الغاز أبدًا داخل المبنى قيد الإنشاء أو في المخارج والسلالم: فالحريق هناك يقطع طريق الخروج."],tips:["عرّف كل عامل وزائر جديد عند التعريف الأولي بخطة الحريق والإنذار ونقطة التجمع.","في نهاية كل يوم، تأكّد أن مواقع الأعمال الساخنة قد فُحصت، وأن الوقود والأسطوانات مقفل عليها، وأن طرق الوصول خالية.","احفظ ملف معلومات الموقع عند البوابة، جاهزًا لفرق 115."],activity:{prompt:"في نهاية اليوم، يريد عامل لحام قطع عارضة فولاذية بسرعة. لا يوجد تصريح، وتوجد عبوات كرتون قريبة، ولا أحد متفرّغ ليكون مراقب الحريق. أنت المشرف. ماذا تفعل؟",options:[{text:"أوقف العمل حتى يتوفّر التصريح، ويُزال الكرتون، وتكون المطفأة جاهزة، ويُسمّى مراقب الحريق، وأخطّط له في وقت أبكر من يوم العمل",correct:!0,feedback:"صحيح: لا تبدأ الأعمال الساخنة إلا بتصريح، ومواد قابلة للاحتراق مُزالة أو محمية، ومطفأة، ومراقب حريق، وتنتهي قبل إغلاق الموقع بوقت كافٍ."},{text:"أسمح به، لأن القطع سيستغرق دقائق قليلة فقط",correct:!1,feedback:"الشرارة لا تحتاج إلا إلى لحظة، وقد تبدأ حرائق الأعمال الساخنة بعد انتهاء العمل."},{text:"أسمح به إذا أبقى عامل اللحام دلو ماء بجانبه",correct:!1,feedback:"دلو الماء لا يغني عن التصريح وإزالة المواد القابلة للاحتراق ومراقب الحريق."},{text:"أسمح به وأطلب من أول عامل يصل صباحًا أن يتفقّد المكان",correct:!1,feedback:"حتى الصباح قد يكبر حريق خفي لساعات في موقع خالٍ. يُراقَب المكان بعد العمل ويُتفقَّد قبل إغلاق الموقع."}]},caseStudy:[{prompt:"تكشف حفّارة تحفر أساسًا عن جسم معدني صدئ مدبّب. يتجمّع العمال حوله للنظر. أنت مشرف الموقع. ماذا تفعل أولًا؟",options:[{text:"أوقف الآلة وكل الأعمال، وأُبعد الجميع عن المكان، وأمنع الناس والآلات من الاقتراب",correct:!0,feedback:"صحيح: الجسم المتفجر القديم قد ينفجر إذا حُرّك أو صُدم. توقّف، وأبعد الجميع، وأبقِهم بعيدين."},{text:"أطلب من عامل أن يضعه في دلو الحفّارة وينقله إلى طرف الموقع",correct:!1,feedback:"لا تحرّك جسمًا مشبوهًا ولا ترفعه أبدًا؛ فتحريكه قد يفجّره."},{text:"أزيل التراب عنه لأرى هل هو فعلًا ذخيرة قديمة",correct:!1,feedback:"لا تحفر حوله ولا تنظّفه أبدًا. فالتعرّف عليه من عمل المختصين الذين يأتون عبر 115."},{text:"أدع العمل يستمر في جزء آخر من الخندق ريثما أقرّر",correct:!1,feedback:"يتوقف كل العمل: فالآلات والحفر القريب قد يصدم الجسم أو يحرّكه. ولا يُستأنف العمل إلا حين تقول السلطات إن الموقع آمن."}]},{prompt:"ابتعد الجميع عن الجسم. يقول عامل إنه سيلتقط صورة قريبة بهاتفه ويتصل بالرقم 115 من مكانه بجانب الخندق. ماذا تفعل؟",options:[{text:"أطلب منه ألا يقترب، وأُبعد الجميع جيدًا قبل أن يستعمل أحد هاتفًا أو جهازًا لاسلكيًا، ثم أتصل بالرقم 115 وأتبع تعليمات الدفاع المدني",correct:!0,feedback:"صحيح: لا يُستعمل الهاتف أو اللاسلكي إلا بعد الابتعاد جيدًا، ومن مكان آمن تُبلَّغ فرق 115 بمكان الجسم."},{text:"أدعه يلتقط الصورة، لأنها ستساعد فرق 115",correct:!1,feedback:"الاقتراب واستعمال الهاتف بجانب الجسم كلاهما خطر. صِف مكانه من مكان آمن بدلًا من ذلك."},{text:"أغطي الجسم بلوح خشبي حتى لا يدوس عليه أحد",correct:!1,feedback:"التغطية تعني الوصول إليه ولمسه. أبقِ الجميع بعيدًا واتركه كما هو تمامًا."},{text:"أعيد تشغيل الحفّارة في جزء آخر من الموقع بعد أن يغيب الجسم عن النظر",correct:!1,feedback:"لا يُستأنف العمل إلا حين تقول السلطات إن الموقع آمن. فقد تكون هناك أجسام أخرى مدفونة قريبًا."}]}],realCase:"في موقع بناء، كان عامل يلحم حاملًا معدنيًا في طابق علوي بعد الظهر. كان المشرف قد أصدر تصريح أعمال ساخنة، وأُزيل الكرتون وقطع الخشب القريبة، وسُمّي زميل مراقبًا للحريق. وبعد انتهاء اللحام بقي الزميل يراقب المكان كما يشترط التصريح. وبعد مدة رأى دخانًا يتصاعد من فجوة في الأرضية، حيث سقطت شرارة على مادة عازلة في الأسفل. فأطلق الإنذار، واتصل المشرف بالرقم 115، وأُطفئ الحريق الصغير قبل أن ينتشر. ولولا مراقب الحريق لكان قد كبر بعد إغلاق الموقع."},{id:28,code:"BUS-128",icon:"FireExtinguisher",accent:"#b91c1c",title:"بطانية الحريق والمطافئ ذات العجلات ومطافئ المركبات",subtitle:"متى تُستخدم وكيف بأمان، ولماذا تحتاج حرائق بطاريات الليثيوم أيون إلى عناية خاصة",summary:"إلى جانب المطافئ اليدوية، تستخدم أماكن العمل بطانيات الحريق والمطافئ الكبيرة ذات العجلات ومطافئ المركبات، ولكلٍّ منها حدوده. يشرح هذا الدرس متى تُستخدم وكيف بأمان، وماذا تفعل عندما ترتفع حرارة بطارية ليثيوم أيون بشدة أو تشتعل.",blocks:[{body:`لكل معدة إطفاء وظيفة وحدود. ويُطبَّق فحص «نعم أو لا» نفسه عليها جميعًا: الحريق صغير وفي بدايته، والمعدة مناسبة له، والمخرج خلفك، وأُطلق الإنذار واتُّصل بالرقم 115، وأنت مدرَّب. وإذا كانت أي إجابة «لا» فاخرج. ولم يُؤكَّد بعدُ أيّ معيار للمطافئ يُطبَّق في دهوك (NFPA 10 أو EN 3)، ولا من يحق له صيانة المطافئ؛ فاتبع متطلبات الدفاع المدني والجهة المانحة للترخيص.

تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.`},{heading:"1. بطانية الحريق: حريق مقلاة صغير",body:"بطانية الحريق قطعة من قماش مقاوم للنار في عبوة سريعة الفتح، تُخمد الحريق الصغير في المقلاة أو القدر بقطع الهواء عنه:",points:["احفظها قرب باب المطبخ، لا بجوار الموقد، لتصل إليها وتبقى قادرًا على الخروج.","اسحب الشريطين (tabs) إلى الأسفل بقوة لتخرج البطانية.","أمسكها أمامك ولفّ حوافها على يديك لتحمي يديك ووجهك.","ضعها برفق فوق المقلاة ولا ترمِها، وتأكّد من أنها تغطي المقلاة كلها.","أطفئ مصدر الحرارة فقط إذا استطعت الوصول إلى مفتاحه بأمان.","اترك البطانية في مكانها ولا تحرّك المقلاة، ولا ترفع البطانية لترى إن انطفأت النار حتى يبرد كل شيء تمامًا.","اتصل بالرقم 115 حتى لو بدت النار منطفئة؛ وإذا لم تنطفئ فورًا فاخرج وأغلق الباب. ولا تصبّ الماء أبدًا على الزيت المشتعل."]},{heading:"2. بطانية الحريق: اشتعال الملابس",body:"إذا اشتعلت النار في ملابس شخص:",points:["يتوقّف الشخص، وينبطح على الأرض، ويغطّي وجهه بيديه، ويتدحرج حتى تنطفئ النار.","إذا كانت لديك بطانية حريق، فلفّها حول اللهب وحول الشخص، وساعده على الانبطاح والتدحرج.","احمِ يديك بحواف البطانية.","ثم برّد الحرق بالماء البارد الجاري لمدة 20 دقيقة، ولا تفقأ الفقاعات، واتصل بالرقم 122.","تُستخدم بطانية الحريق مرة واحدة ثم تُستبدل. اشترِ بطانية يبيّن ملصقها المعيار الذي تطابقه، مثل EN 1869؛ فالبطانية التي لا تحمل علامة معيار قد لا تعمل. ولم يُؤكَّد بعدُ المعيار المقبول محليًّا."]},{heading:"3. المطافئ ذات العجلات",body:"تحمل المطافئ ذات العجلات كمية من المادة أكبر بكثير من المطفأة اليدوية، على عربة بخرطوم طويل، وتحمي أماكن مثل مخازن الوقود وورش الصيانة ومناطق التحميل:",points:["لا يستخدمها إلا العاملون المدرَّبون على هذا الطراز تحديدًا: فأدوات التحكم وترتيب الخطوات والمدى تختلف من طراز لآخر، فاتبع الملصق.","اعملوا في ثنائي كلما أمكن: يتحكم أحدكما بالعربة والصمام كما يبيّن الملصق، ويمسك الآخر الخرطوم والفوهة. وبعض الطرازات مصمَّمة ليشغّلها شخص واحد مدرَّب.","انقل الوحدة إلى موضع ضمن المدى المذكور على الملصق والمخرج خلفك، واتبع خطوات الملصق بالترتيب.","فحص «نعم أو لا» هو نفسه: المطفأة ذات العجلات لا تجعل مكافحة حريق كبير أمرًا آمنًا.","بعد أي استخدام، يعيد فنّي مؤهَّل تعبئتها."]},{heading:"4. مطافئ المركبات",body:"كثيرًا ما تحمل الشاحنات والرافعات الشوكية والحافلات وسيارات الشركات مطفأة صغيرة، لكن معظم حرائق المركبات ليست مما يكافحه السائق:",points:["توقّف على جانب الطريق حالما يكون ذلك آمنًا، وأطفئ المحرّك، وأخرِج الجميع، وابتعدوا كثيرًا عن المركبة وعن حركة السير، 30 مترًا (100 قدم) على الأقل.","اتصل بالرقم 115 (وبالرقم 122 إن أُصيب أحد)، ونبّه حركة السير؛ ولا تعد أبدًا لأخذ أغراضك.","لا تفتح أبدًا غطاء المحرّك أو صندوق السيارة إن ظننت أن النار في داخلهما: فالهواء الجديد يزيد النار اشتعالًا.","لا تستخدم مطفأة المركبة إلا على حريق صغير في بدايته، وإذا كنت مدرَّبًا، وقد خرج الجميع، وطريق تراجعك مفتوح. وفي حريق حجرة المحرّك أبقِ الغطاء مغلقًا؛ وتنصح بعض أجهزة الإطفاء بالتصويب عبر الشبكة الأمامية (grille) أو الفتحة عند حافة الغطاء.","إذا ساورك الشك فلا تقترب من النار. ولا تصبّ الماء أبدًا على حريق المحرّك.","الرافعات الشوكية والمركبات الأخرى العاملة بالبطاريات: إذا كانت البطارية مشتعلة فتعامل معها كحريق بطارية (القسم 5)."]},{heading:"5. حرائق بطاريات الليثيوم أيون",body:"توجد بطاريات الليثيوم أيون في الهواتف والحواسيب المحمولة والعُدد الكهربائية والدراجات الكهربائية والرافعات الشوكية وأنظمة تخزين الطاقة. وعندما تتضرّر أو تُشحن أكثر من اللازم أو يكون فيها عيب، قد تسخن بشدة أو تطلق غازًا سامًّا أو تشتعل أو تنفجر:",points:["علامات الخطر: رائحة غريبة، أو سخونة، أو انتفاخ أو تغيّر في الشكل أو اللون، أو أصوات فرقعة، أو دخان. أوقف استخدامها أو شحنها فورًا.","إن كان ذلك آمنًا، افصلها عن الكهرباء وأبعدها عن كل ما يمكن أن يحترق.","إذا اشتعلت: أخرِج الجميع، وأغلق الباب، واتصل بالرقم 115 من الخارج، وقل إنه حريق بطارية.","لا تستنشق الدخان: فالبطارية المتضرّرة قد تطلق غازًا سامًّا لا يُرى.","التبريد بكمية كبيرة من الماء هو الطريقة الموصى بها، لكن لا يقوم به إلا المدرَّبون بالمعدات المناسبة؛ ومسحوق ABC العادي وCO₂ لا يوقفان النار تمامًا.","بطاريات الليثيوم أيون ليست من الفئة D: فمواد الفئة D مخصّصة لبطاريات الليثيوم المعدني وللمعادن المشتعلة فقط.","الوقاية: استخدم شاحن الشركة المصنّعة أو شاحنًا توافق عليه فقط، واشحن على سطح صلب بعيدًا عمّا يحترق وعن المخارج، وأخرِج البطاريات المتضرّرة من الاستخدام."],critical:!0},{heading:"6. الفحص والصيانة",body:"أبقِ كل هذه المعدات جاهزة:",points:["في الفحص البصري الدوري افحص بطانيات الحريق أيضًا: في مكانها، وسهلة الوصول، وعبوتها سليمة، وشريطاها متدلّيان بحرية.","تخضع المطافئ ذات العجلات ومطافئ المركبات للفحص البصري نفسه الذي تخضع له المطافئ الأخرى: في مكانها، والمسمار والختم سليمان، ومقياس الضغط في المنطقة الخضراء إن وُجد، ولا ضرر فيها.","إعادة التعبئة بعد أي استخدام؛ ويتولى فنّي مؤهَّل الصيانة السنوية واختبارات الضغط. ولم تُؤكَّد بعدُ قواعد الصيانة المحلية ولا من يحق له صيانة المطافئ.","استبدل بطانية الحريق المستعملة، وأبلغ فورًا عن أي مطفأة استُعملت."]}],media:[{kind:"image",src:"media/images/w8_fire_blanket_pan.webp",title:"استخدام بطانية الحريق على حريق مقلاة صغير",description:"عاملة في مطبخ الموظفين تمسك بطانية الحريق أمامها ويداها محميتان خلف القماش، وتضعها برفق فوق مقلاة مشتعلة؛ والباب خلفها مفتوح."}],quiz:[{question:"اشتعلت مقلاة زيت صغيرة على الموقد، ولديك بطانية حريق. ما الطريقة الصحيحة؟",options:[{text:"احمِ يديك بحوافها، وضعها برفق فوق المقلاة، واتركها هناك",correct:!0},{text:"ارمِ البطانية على المقلاة من الطرف الآخر للمطبخ لتبقى بعيدًا عن النار",correct:!1},{text:"غطِّ المقلاة، ثم ارفع البطانية بعد دقيقة لتتأكد من انطفاء النار",correct:!1},{text:"اسكب كوب ماء على المقلاة أولًا، ثم غطّها بالبطانية",correct:!1}],explanation:"ضع البطانية برفق فوق المقلاة ويداك محميتان خلفها، وأطفئ مصدر الحرارة إن استطعت بأمان، واتركها حتى يبرد كل شيء، واتصل بالرقم 115. ولا ماء أبدًا على الزيت المشتعل."},{question:"اشتعلت النار في ملابس زميل في العمل. ماذا تفعل؟",options:[{text:"أجعله يتوقف وينبطح ويتدحرج، وألفّ بطانية حريق حول اللهب إن وُجدت",correct:!0},{text:"أطلب منه أن يركض بسرعة إلى أقرب صنبور ماء ليطفئ الماء اللهب عن جسمه",correct:!1},{text:"أرشّه بمطفأة CO₂ موجّهة مباشرة ومن قرب إلى وجهه وصدره حتى ينطفئ اللهب",correct:!1},{text:"أنزع ملابسه المشتعلة عن جسمه بيديّ العاريتين وبأسرع ما يمكنني",correct:!1}],explanation:"التوقّف والانبطاح والتدحرج تُخمد اللهب، وتساعد بطانية الحريق الملفوفة حوله؛ واحمِ يديك بحوافها. ثم برّد الحرق بالماء البارد الجاري لمدة 20 دقيقة واتصل بالرقم 122."},{question:"من يجب أن يستخدم المطفأة ذات العجلات؟",options:[{text:"العاملون المدرَّبون على هذا الطراز، وفق الملصق، ويُفضَّل في ثنائي",correct:!0},{text:"أي موظف يكون الأقرب إلى النار عندما يرنّ الإنذار",correct:!1},{text:"حارس البوابة فقط، لأن هذه المطافئ تُحفظ قرب البوابة الرئيسية",correct:!1},{text:"أي شخص استخدم مطفأة يدوية صغيرة في البيت مرة واحدة على الأقل",correct:!1}],explanation:"تختلف المطافئ ذات العجلات من طراز لآخر. لا يستخدمها إلا العاملون المدرَّبون على هذا الطراز، وفق الملصق، ويُفضَّل في ثنائي، وبعد فحص «نعم أو لا» نفسه فقط."},{question:"يخرج دخان من تحت غطاء محرّك شاحنة الشركة. ما التصرّف الصحيح؟",options:[{text:"توقّف وأطفئ المحرّك وأخرِج الجميع وابتعد، واتصل بالرقم 115 ولا تفتح الغطاء",correct:!0},{text:"افتح الغطاء بالكامل لتتمكّن من توجيه المطفأة مباشرة إلى المحرّك",correct:!1},{text:"واصل القيادة إلى أقرب ورشة ليفحص الميكانيكي المحرّك",correct:!1},{text:"اسكب ماء زجاجة على المحرّك عبر الفتحة الموجودة تحت الغطاء",correct:!1}],explanation:"فتح الغطاء يدخل هواءً جديدًا فتشتعل النار أكثر. أخرِج الجميع وابتعدوا 30 مترًا (100 قدم) على الأقل، واتصل بالرقم 115، ولا تصبّ الماء أبدًا على حريق المحرّك."},{question:"بطارية عُدّة كهربائية على رفّ الشحن منتفخة ويخرج منها دخان. ماذا تفعل؟",options:[{text:"أفصلها وأبعدها إن كان ذلك آمنًا؛ وإن اشتعلت أخرج وأتصل بالرقم 115",correct:!0},{text:"أغطيها بمسحوق الفئة D، لأن بطاريات الليثيوم أيون حرائق معادن",correct:!1},{text:"أضعها في خزانة معدنية وأغلق بابها بإحكام كي يبقى الدخان في الداخل",correct:!1},{text:"أواصل شحنها، لأن الانتفاخ يزول عندما تمتلئ البطارية تمامًا",correct:!1}],explanation:"الانتفاخ والدخان علامتا خطر. إن كان ذلك آمنًا فافصلها وأبعدها عمّا يحترق؛ وإن اشتعلت فأخرِج الجميع وأغلق الباب واتصل بالرقم 115. وبطاريات الليثيوم أيون ليست من الفئة D."},{question:"توجد مطفأة ذات عجلات بجانب مخزن الوقود. يرى عامل لم يستعمل إلا المطافئ اليدوية حريقًا هناك آخذًا في الانتشار. ما الصحيح؟",options:[{text:"يتركها ويخرج ويطلق الإنذار، لأن النار آخذة في الانتشار",correct:!0},{text:"يستعملها، لأنها تحمل مادة أكثر بكثير من المطفأة اليدوية",correct:!1},{text:"يستعملها وحده بالخطوات نفسها التي يتبعها مع المطفأة اليدوية",correct:!1},{text:"يستعملها من قرب شديد حتى لا تضيع المادة في الطريق",correct:!1}],explanation:"لا يستعمل المطفأة ذات العجلات إلا من تدرّب على ذلك الطراز، وفحص «نعم أو لا» هو نفسه: النار المنتشرة تعني أن تخرج وتطلق الإنذار وتتصل بالرقم 115. والجهاز الأكبر لا يجعل الحريق الكبير آمنًا للمكافحة."}],steps:[{title:"فحص «نعم أو لا» أولًا",detail:"لا تستعمل البطانية إلا إذا كانت النار صغيرة وفي بدايتها، وفي مقلاة أو قدر، وطريق خروجك خلفك، وقد نُبّه الآخرون، وكنت تعرف كيف تستعملها. وإذا كان أي جواب «لا» فاخرج واتصل بالرقم 115.",critical:!0},{title:"أخرج البطانية واحمِ يديك",detail:"اسحب الشريطين (tabs) إلى الأسفل بقوة لتخرج البطانية. وأمسكها أمامك ولفّ حوافها على يديك لتحمي يديك ووجهك."},{title:"ضعها برفق فوق المقلاة",detail:"لا ترمِها. تأكّد من أنها تغطي المقلاة كلها، ثم أطفئ مصدر الحرارة فقط إذا استطعت الوصول إلى مفتاحه بأمان.",critical:!0},{title:"اتركها مكانها حتى تبرد",detail:"لا تحرّك المقلاة ولا ترفع البطانية لتنظر حتى يبرد كل شيء تمامًا."},{title:"اتصل بالرقم 115، واخرج إن لم تنطفئ",detail:"اتصل بالرقم 115 حتى لو بدت النار منطفئة. وإذا لم تنطفئ فورًا فاخرج وأغلق الباب. واستبدل البطانية بعد استعمالها.",critical:!0}],warnings:["لا تصبّ الماء أبدًا على الزيت المشتعل: فالماء يتحوّل إلى بخار ويقذف الزيت المشتعل في كرة نار.","لا تفتح غطاء المحرك أو الصندوق الخلفي للمركبة أبدًا إذا ظننت أن النار في داخله: فالهواء الجديد يزيدها اشتعالًا.","لا تحمل أبدًا بطارية ليثيوم أيون تُصدر دخانًا أو تحترق ولا تستنشق دخانها: فقد تطلق غازًا سامًّا وتشتعل من جديد."],tips:["احفظ بطانية الحريق قرب باب المطبخ لا بجوار الموقد، وتأكّد في الفحص البصري المنتظم أن الشريطين يتدلّيان بحرية.","قبل الطوارئ، تدرّب على طراز المطفأة ذات العجلات الموجود في موقعك واقرأ ملصقه: فأدوات التحكم والمدى تختلف بين الطرازات.","اعرف مكان المطفأة في مركبتك، وأدرجها في الفحص البصري المنتظم.","اشحن البطاريات بشاحن الشركة المصنّعة أو بشاحن توافق عليه فقط، على سطح صلب بعيدًا عن المواد القابلة للاشتعال وعن المخارج."],activity:{prompt:"في منطقة التحميل، يرى سائق رافعة شوكية دخانًا يخرج من حجرة بطارية رافعته. توجد قربه مطفأة ذات عجلات، لكنه لم يتدرّب عليها قط. ماذا يجب أن يفعل؟",options:[{text:"يتوقف، ويطفئ الرافعة، وينزل منها ويبتعد، وينبّه الآخرين، ويطلق الإنذار، ويتصل بالرقم 115 ذاكرًا أن الأمر قد يتعلق ببطارية",correct:!0,feedback:"صحيح: إذا كانت البطارية مشمولة يُعامل الحريق كحريق بطارية. فيبتعد، وينبّه الآخرين، ويدع فرق 115 تتعامل معه."},{text:"يستعمل المطفأة ذات العجلات فورًا وحده، ويتعلّم طريقة تشغيلها في أثناء العمل",correct:!1,feedback:"لا يستعمل المطفأة ذات العجلات إلا من تدرّب على ذلك الطراز؛ فأدوات التحكم وترتيب الخطوات تختلف. وحريق البطارية من عمل فرق 115."},{text:"يفتح غطاء البطارية ليرى من أين يخرج الدخان",correct:!1,feedback:"فتحه يُدخل الهواء ويضع وجهه في الغاز السام الذي قد تطلقه البطارية التالفة."},{text:"يقود الرافعة بسرعة إلى الخارج حتى لا يملأ الدخان المبنى",correct:!1,feedback:"البقاء على مركبة قد تشتعل يعرّضه للخطر، وقيادتها قد تسدّ الطرق أو تنشر النار."}]},caseStudy:[{prompt:"يشمّ سائق شاحنة تابعة للشركة رائحة احتراق ويرى دخانًا يخرج من تحت غطاء المحرك وهو يقود على طريق مزدحم. ماذا يفعل السائق أولًا؟",options:[{text:"يتوقف على جانب الطريق ما إن يكون ذلك آمنًا، ويطفئ المحرك، ويُخرج الجميع، ويبتعد كثيرًا عن الشاحنة وعن حركة السير",correct:!0,feedback:"صحيح: التوقف وإطفاء المحرك وإبعاد الجميع عن المركبة وعن حركة السير تأتي أولًا."},{text:"يواصل القيادة إلى مستودع الشركة حيث توجد مطافئ أكثر",correct:!1,feedback:"تكبر النار والشاحنة تسير. توقّف ما إن يكون ذلك آمنًا."},{text:"يتوقف ويفتح غطاء المحرك ليرى من أين يخرج الدخان",correct:!1,feedback:"الهواء الجديد يزيد حريق المحرك اشتعالًا. أبقِ الغطاء مغلقًا."},{text:"يتوقف ويصبّ ماء قارورة عبر الشبكة الأمامية على المحرك",correct:!1,feedback:"لا تصبّ الماء على حريق المحرك أبدًا؛ فقد ينتشر الوقود والزيت المشتعلان."}]},{prompt:"خرج الجميع وابتعدوا جيدًا، وتم الاتصال بالرقم 115. يخرج دخان قليل فقط من الشبكة الأمامية، والسائق مدرَّب، وفي الشاحنة مطفأة. ما الصحيح؟",options:[{text:"فقط إذا كانت النار ما زالت صغيرة وطريق عودته مفتوحًا، يستعملها والغطاء مغلق عبر الشبكة أو الفجوة عند حافة الغطاء؛ وإذا لم تنطفئ فورًا يبتعد",correct:!0,feedback:"صحيح: فحص «نعم أو لا» ما زال ساريًا، ويبقى الغطاء مغلقًا، وإن كان مترددًا فلا يتعامل مع النار."},{text:"يعود إلى المقصورة ليأخذ هاتفه وأوراق الشحنة",correct:!1,feedback:"لا تعد أبدًا إلى مركبة مشتعلة من أجل الأغراض."},{text:"يرفع غطاء المحرك قليلًا ليوجّه المطفأة بشكل أفضل",correct:!1,feedback:"حتى الفتحة الصغيرة تُدخل الهواء الجديد، وقد تندفع النار نحو وجهه."},{text:"ينتظر بجانب الشاحنة مباشرة ليخبر رجال الإطفاء بما حدث",correct:!1,feedback:"يبقى بعيدًا عن المركبة وعن حركة السير، ويستقبل رجال الإطفاء من مكان آمن."}]}],realCase:"في مطبخ الموظفين، كانت موظفة تسخّن زيتًا في مقلاة حين اشتعل. أخذت بطانية الحريق من جانب الباب، وسحبت الشريطين إلى الأسفل بقوة، وأمسكت البطانية أمامها ولفّت حوافها على يديها. ثم وضعتها برفق فوق المقلاة، وأطفأت الموقد لأنها استطاعت الوصول إليه بأمان، وتركت البطانية مكانها. وأطلق زميل الإنذار واتصل بالرقم 115. فحص رجال الإطفاء المطبخ وتأكّدوا أن النار انطفأت. واستُبدلت البطانية المستعملة في اليوم نفسه."},{id:29,code:"IND-129",icon:"Lock",accent:"#b45309",title:"الإقفال والوسم للطاقة الخطرة (LOTO)",subtitle:"الإيقاف والعزل والقفل وتفريغ الطاقة المخزنة والتحقق قبل الصيانة",summary:"قد تتحرك الآلة على نحو غير متوقع أثناء الصيانة أو التنظيف أو إزالة شيء عالق، لأن شخصًا ضغط زر التشغيل أو لأن طاقة مخزنة بقيت فيها. تعرض هذه الوحدة على العمال والفنيين والمشرفين كيف تُقطع جميع مصادر الطاقة وتُقفل، وكيف تُفرَّغ الطاقة المخزنة، وكيف يُتحقق قبل لمس الآلة من أنها لا يمكن أن تتحرك.",blocks:[{body:"تقع كثير من الإصابات في المصانع أثناء الصيانة لا أثناء العمل العادي: يد داخل الآلة وشخص آخر لا يعلم يشغّلها، أو جزء مرفوع يسقط بوزنه، أو أنبوب تحت الضغط يُفتح. يضبط إجراء الإقفال والوسم (Lockout/Tagout) هذه المخاطر: تُقطع جميع مصادر الطاقة وتُقفل، وتبين بطاقة من وضع القفل ولماذا. يضع المصنع إجراء LOTO مكتوبًا لكل آلة؛ اتبع متطلبات الدفاع المدني والجهة المختصة."},{heading:"1. أنواع الطاقة الخطرة",body:"قبل العمل، دوّن جميع مصادر طاقة الآلة، لا الكهرباء وحدها:",points:["الكهرباء: اللوحات والمقابس والبطاريات والمكثفات التي قد تبقى مشحونة بعد الفصل.","ضغط الهواء والزيت (الهوائي والهيدروليكي) في الأنابيب والأسطوانات والمراكم.","الطاقة الميكانيكية: النوابض والحدافات التي ما زالت تدور والأجزاء المرفوعة التي تسقط بالجاذبية.","الحرارة والبخار والمواد الكيميائية والغازات في الأنابيب والأوعية."]},{heading:"2. قفل لكل شخص والبطاقة",body:"القفل حاجز مادي؛ والبطاقة تحذير فقط. القواعد الأساسية:",points:["لكل شخص يعمل قفله الخاص ومفتاحه؛ وفي العمل الجماعي يضع كل واحد قفله على مشبك جماعي (hasp).","تبين البطاقة اسم الشخص والوقت وسبب الإقفال.","لا يزيل القفل إلا من وضعه؛ وإزالة قفل شخص آخر تكون فقط بالإجراء المكتوب للمصنع وبعد التأكد من أنه ليس في الموقع.","البطاقة وحدها لا تكفي إذا كان جهاز العزل قابلًا للقفل."]},{heading:"3. ما ليس عزلًا",body:"زر الإيقاف وزر الإيقاف الطارئ ومفاتيح التحكم وأقفال الحماية في الأبواب (interlock) قد توقف الآلة لكنها لا تقطع الطاقة عنها: قد يعيد تشغيلها قِصَر في سلك أو خطأ في البرمجيات أو شخص ما. العزل الحقيقي يكون بجهاز عزل يُفصل يدويًا ويُقفل: المفتاح الرئيسي للكهرباء أو صمام الأنبوب أو نزع القابس حين يبقى القابس تحت سيطرة من يعمل. إذا لم تعرف أي جهاز يقطع كل الطاقة، فلا تعمل واسأل المشرف."},{heading:"4. إعادة الآلة إلى العمل",body:"بعد العمل يلزم الحذر نفسه: أزل الأدوات والقطع المتبقية من الآلة، وأعد واقيات الآلة (guards) إلى مكانها، وتأكد من ابتعاد الجميع عن منطقة الخطر، وأبلغ العمال المعنيين، ثم يزيل كل شخص قفله بنفسه. لا تُعاد الطاقة إلا بعد ذلك. وإذا استمر العمل عند تبديل المناوبة، تضع المناوبة الجديدة أقفالها قبل أن تزيل المناوبة السابقة أقفالها، حتى لا تبقى الآلة بلا قفل في أي لحظة."},{heading:"5. إذا عَلِق شخص في الآلة",body:"أوقف الآلة بزر الإيقاف الطارئ واقطع الطاقة إن أمكن ذلك بأمان. لا تُدخل يدك في آلة ما زالت تتحرك. إذا أصيب شخص بصعق كهربائي فلا تلمسه حتى تُقطع الكهرباء. اتصل بـ 115 و122، وأوقف النزف الشديد بالضغط المباشر كما في درس الإسعافات الأولية. لا تُدِر الآلة عكسيًا بنفسك لإخراج الشخص إن لم تعرف ما سيحدث؛ اتبع تعليمات فرق 115.",critical:!0}],steps:[{title:"1. التحضير والإبلاغ",detail:"اقرأ إجراء LOTO المكتوب للآلة، وحدد جميع مصادر الطاقة، وأبلغ العمال الآخرين بأن الآلة ستُوقف."},{title:"2. الإيقاف",detail:"أوقف الآلة بطريقة التشغيل العادية، لا بسحب السلك أو قطع الطاقة وهي ما زالت تحت الحمل."},{title:"3. العزل",detail:"شغّل كل جهاز عزل في القائمة (المفتاح الرئيسي والصمام والقابس) حتى تُقطع جميع مصادر الطاقة.",critical:!0},{title:"4. القفل والبطاقة",detail:"ضع قفلك الخاص وبطاقة باسمك على كل جهاز عزل؛ واحتفظ بالمفتاح معك.",critical:!0},{title:"5. تفريغ الطاقة المخزنة",detail:"أفرغ الضغط المتبقي، وثبّت الأجزاء المرفوعة بدعامات مناسبة أو أنزلها، وفرّغ شحنة المكثفات وفق الإجراء المكتوب.",critical:!0},{title:"6. التحقق",detail:"بعد ابتعاد الجميع، جرّب تشغيل الآلة للتأكد من أنها لا تعمل، ويفحص شخص مؤهل الكهرباء بجهاز القياس؛ ثم أعد أدوات التحكم إلى وضع الإيقاف.",critical:!0}],warnings:["لا تُدخل يدك في آلة لمجرد أن زر الإيقاف ضُغط: الزر لا يقطع الطاقة وقد تتحرك الآلة فجأة.","لا تُزل قفل غيرك ولا تعطِ مفتاحك لأحد: القفل يحمي حياة من وضعه.","لا تتخطَّ التحقق: من دون تجربة لا تعرف هل قُطعت كل الطاقة أم بقي مصدر آخر منسي."],tips:["ضع على كل آلة قائمة قصيرة بمصادر الطاقة ومواقع أجهزة العزل.","اجعل أقفال LOTO بلون وشكل مختلفين عن أقفال المصنع الأخرى ليسهل تمييزها.","اسأل قبل العمل: «ماذا يحدث لو ضغط أحد الزر الآن؟»","العمال الجدد وعمال المقاولين يعملون بإجراء LOTO نفسه."],activity:{prompt:"توقف سير ناقل (conveyor) لأن كرتونة عَلِقت فيه. يقول المشرف: «أسرع، اضغط زر الإيقاف الطارئ فقط وأخرج الكرتونة.» ماذا تفعل؟",options:[{text:"أضغط زر الطوارئ وأخرج الكرتونة بسرعة.",correct:!1,feedback:"زر الطوارئ لا يقطع الطاقة؛ قد يتحرك السير فجأة ويسحب اليد."},{text:"أقطع الطاقة وفق إجراء LOTO، وأضع قفلي وبطاقتي، وأجرب أن السير لا يعمل، ثم أخرج الكرتونة.",correct:!0,feedback:"إزالة شيء عالق عمل صيانة ويحتاج إلى LOTO حتى لو كان قصيرًا."},{text:"أترك عاملًا آخر عند الزر كي لا يضغطه أحد بينما أعمل.",correct:!1,feedback:"قد يخطئ الإنسان أو يغادر المكان؛ لا يحل محل قفلك ولا يقطع الطاقة المخزنة."},{text:"أخرج الكرتونة بعصا طويلة كي لا تدخل يدي.",correct:!1,feedback:"قد تعلق العصا في الآلة وتُقذف؛ ما زالت الآلة تحت الطاقة وقد تتحرك."}]},caseStudy:[{prompt:"سيصلح فريق من ثلاثة أشخاص مضخة هيدروليكية. فُصل مفتاح الكهرباء وعليه قفل واحد هو قفل رئيس الفريق. أنت أحد أعضاء الفريق. ماذا تفعل قبل البدء؟",options:[{text:"أضع قفلي على المشبك الجماعي وأسأل هل فُرّغ ضغط الزيت.",correct:!0,feedback:"كل شخص يضع قفله، والضغط الهيدروليكي طاقة مخزنة لا يفرغها قطع الكهرباء."},{text:"قفل رئيس الفريق يكفي لأنه المسؤول.",correct:!1,feedback:"قد يزيل الرئيس قفله وأنت ما زلت تعمل؛ قفلك وحده يحميك."},{text:"أفك الأنبوب الهيدروليكي فورًا لأرى المضخة.",correct:!1,feedback:"قد يقذف الضغط المتبقي الزيت بقوة ويسبب إصابات بالغة."}]},{prompt:"انتهى العمل. ذهب رئيس الفريق إلى بيته وما زال قفله على المشبك. يريد المدير إعادة الآلة إلى العمل فورًا. ماذا يجب أن يُفعل؟",options:[{text:"نقطع القفل بمقص ونشغّل الآلة.",correct:!1,feedback:"إزالة قفل شخص آخر دون الإجراء المكتوب قد تسبب إصابة إن كان هو أو غيره ما زال عند الآلة."},{text:"الإجراء المكتوب للمصنع: يتأكد المشرف أنه ليس في الموقع ويتصل به، ثم يزيل القفل بعد فحص الآلة.",correct:!0,feedback:"هذا هو الصواب: التأكد من خلو المكان وإبلاغ صاحب القفل قبل الإزالة."},{text:"نزيل البطاقة ونترك القفل، ثم نوصل الكهرباء بمفتاح آخر.",correct:!1,feedback:"تجاوز القفل بمصدر آخر يُبطل LOTO كليًا ويحمل الخطر نفسه."}]}],realCase:"سيناريو تدريبي: في مصنع تعبئة، دخل فني أثناء المناوبة الليلية إلى آلة تغليف ليزيل قطعة عالقة، وكان قد ضغط زر الإيقاف فقط. رأى عامل آخر لم يلحظ وجود أحد بالداخل أن الآلة متوقفة فشغّلها بزر التشغيل. نجا الفني بإصابة بالغة في يده. بعد ذلك وضع المصنع إجراء LOTO مكتوبًا لكل آلة، ووزّع أقفالًا خاصة على كل عامل، وجعل التدريب على التحقق قبل كل عمل صيانة إلزاميًا.",quiz:[{question:"ستغيّر سير آلة. مفتاح الكهرباء مفصول ومقفل. ما الخطوة التالية قبل أن تلمسها؟",options:[{text:"فرّغ الطاقة المخزنة وجرّب أن الآلة لا تعمل",correct:!0},{text:"ابدأ العمل لأن القفل على المفتاح الرئيسي",correct:!1},{text:"أضف بطاقة باسمك على زر التشغيل",correct:!1},{text:"اطلب من عامل آخر البقاء عند اللوحة",correct:!1}],explanation:"النوابض والجاذبية والضغط والمكثفات قد تحرك الآلة بعد الفصل؛ والتجربة تثبت أن العزل نجح."},{question:"أي مما يلي جهاز عزل للطاقة يُستخدم في LOTO؟",options:[{text:"زر الإيقاف الطارئ على لوحة التحكم",correct:!1},{text:"المفتاح الكهربائي الرئيسي الذي يُفصل يدويًا ويُقفل",correct:!0},{text:"قفل الحماية في باب الآلة (interlock)",correct:!1},{text:"مفتاح اختيار وضع التشغيل على الشاشة",correct:!1}],explanation:"الأزرار ومفاتيح التحكم وأقفال الأبواب لا تقطع الطاقة وقد تعيد التشغيل خطأً."},{question:"في عمل جماعي يعمل أربعة عمال على آلة واحدة. كم قفلًا يلزم؟",options:[{text:"قفل واحد للمشرف لأنه مسؤول عن الجميع",correct:!1},{text:"يضع كل عامل قفله على المشبك الجماعي",correct:!0},{text:"قفلان: واحد للمناوبة الصباحية وآخر للمسائية",correct:!1},{text:"لا أقفال، بل بطاقة كبيرة بأسماء الجميع",correct:!1}],explanation:"كل شخص يحميه قفله وحده؛ ولا تُشغّل الآلة حتى يُزال آخر قفل."},{question:"أي فعل خاطئ عند إعادة الآلة إلى العمل بعد الصيانة؟",options:[{text:"إزالة الأدوات من الآلة وإعادة الواقيات إلى مكانها",correct:!1},{text:"إبلاغ العمال المعنيين قبل إعادة الطاقة",correct:!1},{text:"أن يزيل شخص واحد كل الأقفال لإنهاء العمل أسرع",correct:!0},{text:"التأكد من ابتعاد الجميع عن منطقة الخطر",correct:!1}],explanation:"يزيل كل شخص قفله بنفسه، فلا يُنسى أحد ما زال عند الآلة."},{question:"عَلِقت يد زميل في آلة ما زالت تدور. ما أول تصرف صحيح؟",options:[{text:"اسحب يده بقوة قبل أن تجذبها الآلة أكثر",correct:!1},{text:"أوقف الآلة بزر الطوارئ واتصل بـ 115 و122",correct:!0},{text:"أدِر الآلة عكسيًا ليخرج اليد وحدها",correct:!1},{text:"ابقَ بعيدًا وانتظر المشرف ليقرر",correct:!1}],explanation:"إيقاف الحركة فورًا ضروري؛ السحب أو التدوير العكسي قد يزيد الإصابة. ثم 115 للإنقاذ و122 للمصاب."},{question:"لم تُنهِ المناوبة الصباحية العمل على آلة وستكمله المسائية. كيف تُبدَّل الأقفال؟",options:[{text:"تزيل المناوبة الصباحية أقفالها وتضع المسائية أقفالها لاحقًا",correct:!1},{text:"تبقى أقفال الصباح وتُسلَّم مفاتيحها للمسائية",correct:!1},{text:"تضع المسائية أقفالها قبل أن تزيل الصباحية أقفالها",correct:!0},{text:"تبقى بطاقة فقط أثناء تبديل المناوبة",correct:!1}],explanation:"هكذا لا تبقى الآلة بلا قفل أبدًا ولا تُسلَّم المفاتيح لغير أصحابها."}]},{id:30,code:"IND-130",icon:"CloudFog",accent:"#a16207",title:"الغبار القابل للاحتراق والأجواء القابلة للانفجار",subtitle:"مخمّس انفجار الغبار والانفجار الثانوي والتنظيف وضبط مصادر الاشتعال",summary:"الطحين والسكر والخشب والبلاستيك والأعلاف والفحم وبعض المعادن، حين تصير غبارًا ناعمًا وتنتشر في الهواء، قد تحترق بانفجار قوي. تعرض هذه الوحدة على العمال والمشرفين كيف يصبح الغبار القابل للاحتراق خطرًا، ولماذا يكون الانفجار الثانوي أكبر من الأول، وكيف يُمنع بالتنظيف وضبط مصادر الاشتعال.",blocks:[{body:"قد يحترق الغبار المتراكم على الأرض أو على الآلات ببطء فقط، لكن الغبار نفسه حين ينتشر في الهواء كالسحابة داخل مكان مغلق قد يحترق كله معًا في وقت قصير جدًا ويولّد ضغطًا كبيرًا. هذا هو انفجار الغبار. يضع الدفاع المدني والجهة المختصة قواعد الغبار القابل للاحتراق وتفتيش المصانع؛ اتبع متطلباتهما."},{heading:"1. مخمّس انفجار الغبار",body:"يضيف مثلث الحريق (الوقود والأكسجين والحرارة) ضلعين آخرين للانفجار. إذا غاب أحد الخمسة لم يقع الانفجار:",points:["الوقود: غبار ناعم قابل للاحتراق.","الأكسجين: الهواء العادي.","مصدر الاشتعال: شرارة أو سطح ساخن أو لهب أو كهرباء ساكنة.","التشتت: الغبار معلق في الهواء كالسحابة.","الحصر: معدة أو مخزن أو مجرى أو مبنى مغلق يحبس الضغط."]},{heading:"2. الانفجار الثانوي",body:"كثيرًا ما يهز انفجار صغير داخل معدة (مثل مجمّع الغبار أو الطاحونة) المبنى. يرفع هذا الاهتزاز الغبار المتراكم على العوارض والرفوف ووحدات الإنارة وفوق السقف المستعار فيكوّن سحابة كبيرة. تشعل نار الانفجار الأول هذه السحابة فيقع انفجار أكبر في المبنى كله. لذلك يكون الغبار المتراكم في الأماكن المرتفعة والمخفية أخطر من غبار الأرض، والتنظيف المنتظم هو الضبط الأساسي."},{heading:"3. ضبط الغبار",body:"الهدف ألا يتراكم الغبار وألا يتحول إلى سحابة:",points:["التقط الغبار عند مصدره بنظام تجميع مصمم للغبار القابل للاحتراق.","نظّف بانتظام، خاصة الأماكن المرتفعة والمخفية، واستخدم مكنسة شفط مناسبة للغبار القابل للاحتراق.","لا تُزل الغبار بالهواء المضغوط أو بالكنس العنيف لأن ذلك يكوّن سحابة.","أبلغ عن تسرب الغبار من المعدات والمجاري وأصلحه بسرعة.","يجري شخص مختص تحليلًا لمخاطر الغبار (Dust Hazard Analysis) لعمليات المصنع."]},{heading:"4. ضبط مصادر الاشتعال",body:"في أماكن الغبار القابل للاحتراق: لا عمل ساخن إلا بتصريح العمل الساخن وبعد تنظيف محيط العمل؛ ومعدات كهربائية مناسبة لأماكن الغبار؛ وربط المعدات وتأريضها (bonding وgrounding) ضد الكهرباء الساكنة؛ ومغناطيس أو مصافٍ لإزالة القطع المعدنية قبل الطحن؛ ومراقبة سخونة المحامل والسيور؛ ومنع التدخين واللهب."},{heading:"5. عند حريق أو دخان في منطقة الغبار",body:"أطلق إنذار الحريق، وأخرج الجميع وفق خطة الإخلاء، واتصل بـ 115. لا تفتح باب مجمّع الغبار أو معدة يخرج منها الدخان، لأن الهواء يدخل وقد تنفجر النار. لا توجّه ماءً قويًا أو مطفأة حريق إلى الغبار المتراكم لأن ذلك يرفع سحابة جديدة. أخبر فرق 115 بنوع الغبار الموجود؛ فبعض غبار المعادن يزداد خطرًا مع الماء (حسب SDS). برّد الحروق بماء جارٍ بارد 20 دقيقة واتصل بـ 122.",critical:!0}],steps:[{title:"1. اعرف الغبار القابل للاحتراق",detail:"اقرأ في SDS لكل مادة هل غبارها يحترق أو ينفجر، ودوّن أماكن تولد الغبار."},{title:"2. أوقف التراكم",detail:"نظّف الأماكن المرتفعة والمخفية بمكنسة شفط مناسبة، ولا تستخدم الهواء المضغوط للتنظيف.",critical:!0},{title:"3. اضبط مصادر الاشتعال",detail:"لا عمل ساخن إلا بتصريح، ومعدات مؤرّضة، ولا تدخين ولا لهب في أماكن الغبار.",critical:!0},{title:"4. أبلغ",detail:"أبلغ المشرف فورًا عن الغبار المتراكم أو التسرب من المعدات أو رائحة الاحتراق أو سخونة المعدات."},{title:"5. عند الحريق",detail:"أطلق الإنذار، واخرج وفق الخطة، واتصل بـ 115، ولا تفتح معدات الغبار.",critical:!0}],warnings:["لا تستخدم الهواء المضغوط لتنظيف الغبار: يكوّن سحابة قد تفجرها شرارة صغيرة.","لا تفتح معدة غبار يخرج منها دخان: الهواء الجديد قد يحول النار إلى انفجار.","لا تستخدم مكنسة منزلية أو عادية للغبار القابل للاحتراق: محركها قد يكون مصدر اشتعال."],tips:["انظر إلى لون الأسطح المرتفعة: إذا اختفى لونها تحت الغبار فقد حان وقت التنظيف.","ضع جدول تنظيف للأماكن المرتفعة ودوّن اسم من ينظّف.","جرّب في تمرين الإخلاء طرق الخروج من مناطق الغبار.","بعد أي تغيير في العملية (مادة جديدة أو معدة جديدة) اسأل هل حُدّث تحليل مخاطر الغبار."],activity:{prompt:"في مصنع طحين ترى طبقة سميكة من الغبار على عوارض السقف ووحدات الإنارة. يقول زميل: «سننزلها بخرطوم الهواء ثم نكنسها.» ماذا تقول؟",options:[{text:"حسنًا، لكن لنفعل ذلك والآلات تعمل كي لا نضيع الوقت.",correct:!1,feedback:"سحابة الغبار قرب معدات عاملة وساخنة قد تنفجر فورًا."},{text:"لا؛ هذا يكوّن سحابة خطرة. ننظفها بمكنسة شفط مناسبة للغبار القابل للاحتراق ونبلغ المشرف.",correct:!0,feedback:"المكنسة المناسبة تزيل الغبار دون تكوين سحابة؛ ويجب الإبلاغ عن التراكم السميك لمعالجة سببه."},{text:"نرش عليه الماء ليسقط الغبار.",correct:!1,feedback:"الماء قرب المعدات الكهربائية خطر وبعض الغبار يزداد خطرًا معه؛ طريقة التنظيف حسب إجراء المصنع المكتوب."},{text:"غبار الأماكن المرتفعة لا خطر منه، ننظف الأرض فقط.",correct:!1,feedback:"غبار الأماكن المرتفعة وقود الانفجار الثانوي وهو أخطر من غبار الأرض."}]},caseStudy:[{prompt:"في ورشة نجارة يرى عامل دخانًا خفيفًا يخرج من مجمّع الغبار ورائحة احتراق. الآلات ما زالت تعمل. ما أول تصرف؟",options:[{text:"يفتح باب المجمّع ليرى أين النار.",correct:!1,feedback:"فتح الباب يُدخل الهواء وقد يسبب انفجارًا."},{text:"يطلق إنذار الحريق ويُخرج الجميع وفق الخطة ويتصل بـ 115.",correct:!0,feedback:"النار داخل المجمّع قد تصبح انفجارًا؛ إبعاد الناس وإبلاغ 115 أولًا."},{text:"يرش مطفأة البودرة على المجمّع والغبار حوله.",correct:!1,feedback:"الرش القوي على الغبار المتراكم يرفع سحابة جديدة وينقل النار خارج المعدة."}]},{prompt:"الجميع في نقطة التجمع ووصلت فرق 115. يسأل قائد الفريق عمّا في المكان. ماذا تقول؟",options:[{text:"نوع الغبار، وموقع المجمّع، وهل بقي أحد، وهل قُطعت الكهرباء.",correct:!0,feedback:"هذه المعلومات تساعد الفريق على السيطرة على النار وإنقاذ الأشخاص بأمان."},{text:"أقول إنها نار صغيرة وأستطيع العودة لإطفائها.",correct:!1,feedback:"العودة إلى المبنى دون إذن فريق 115 خطرة؛ فقد يقع انفجار ثانوي لاحقًا."},{text:"أقول فقط إنه كان هناك دخان ولا أعرف ما في الداخل.",correct:!1,feedback:"يحتاج الفريق إلى نوع الغبار ومعرفة المفقودين؛ قلة المعلومات قد تجعل طريقة الإطفاء خاطئة."}]}],realCase:"سيناريو تدريبي: في مصنع سكر، كان غبار السكر يتراكم مدة طويلة على عوارض السقف وعلى السيور الناقلة. وفي أحد الأيام أشعل محمل محموم داخل سير مغلق سحابة صغيرة. هزّ الانفجار الصغير المبنى، فارتفع الغبار عن العوارض إلى الهواء ووقع انفجار أكبر. ساعد إنذار الحريق والتدريب على الإخلاء العمال على الخروج بسرعة. بعد ذلك وضع المصنع جدولًا لتنظيف الأماكن المرتفعة، واستخدم مكانس شفط مناسبة، وراقب سخونة المحامل.",quiz:[{question:"لماذا يكون الانفجار الثانوي عادةً أكبر من الأول؟",options:[{text:"لأن الاهتزاز يرفع الغبار المتراكم في المبنى فيكوّن سحابة كبيرة",correct:!0},{text:"لأن رجال الإطفاء يرشون الماء على المعدات الساخنة",correct:!1},{text:"لأن أكسجين الهواء يزداد أثناء الحريق",correct:!1},{text:"لأن الكهرباء تنقطع تلقائيًا في الانفجار الأول",correct:!1}],explanation:"غبار العوارض والرفوف وقود الانفجار الثانوي؛ وتنظيفه هو الضبط الأساسي."},{question:"أي طريقة صحيحة لتنظيف الغبار القابل للاحتراق عن المعدات؟",options:[{text:"خرطوم الهواء المضغوط لإنهاء التنظيف أسرع",correct:!1},{text:"مكنسة شفط مناسبة للغبار القابل للاحتراق",correct:!0},{text:"مكنسة خشنة ليرتفع كل الغبار بقوة",correct:!1},{text:"المكنسة المنزلية العادية الموجودة في المصنع",correct:!1}],explanation:"المكنسة المناسبة تزيل الغبار دون سحابة ودون أن تكون مصدر اشتعال؛ أما الهواء المضغوط والمكنسة الخشنة فيكوّنان سحابة."},{question:"ماذا يحدث إذا غاب أحد أضلاع مخمّس الانفجار؟",options:[{text:"يقع الانفجار لكنه أصغر",correct:!1},{text:"لا يقع انفجار الغبار",correct:!0},{text:"يقع الانفجار الثانوي فقط",correct:!1},{text:"يتحول الغبار إلى غاز سام",correct:!1}],explanation:"الأضلاع الخمسة كلها لازمة؛ لذلك يمنع ضبط الغبار والاشتعال والتشتت الانفجار."},{question:"يلزم عمل لحام في منطقة غبار قابل للاحتراق. أي طريقة صحيحة؟",options:[{text:"اللحام والآلات تعمل كي لا يتوقف الإنتاج",correct:!1},{text:"اللحام خلف جدار دون تنظيف المحيط",correct:!1},{text:"تصريح العمل الساخن وتنظيف المحيط ومراقب الحريق",correct:!0},{text:"مطفأة بودرة قريبة والبدء فورًا",correct:!1}],explanation:"شرر اللحام مصدر اشتعال قوي؛ والتصريح والتنظيف والمراقبة تقلل الخطر (NFPA 51B)."},{question:"يخرج دخان من طاحونة. أي فعل خاطئ؟",options:[{text:"إطلاق إنذار الحريق والخروج وفق الخطة",correct:!1},{text:"فتح باب الطاحونة لرؤية النار",correct:!0},{text:"الاتصال بـ 115 وذكر نوع الغبار",correct:!1},{text:"عدّ العمال في نقطة التجمع",correct:!1}],explanation:"فتح معدة يخرج منها الدخان يُدخل الهواء وقد يسبب انفجارًا."},{question:"أصيب عامل بحرق في يده أثناء حريق غبار. ما الإسعاف الأولي الصحيح؟",options:[{text:"ماء جارٍ بارد 20 دقيقة والاتصال بـ 122",correct:!0},{text:"ثلج على الحرق ليبرد بسرعة",correct:!1},{text:"زيت أو كريم على الحرق كي لا يصله الهواء",correct:!1},{text:"فقء الفقاعات ليخرج منها السائل",correct:!1}],explanation:"الماء الجاري البارد 20 دقيقة يقلل ضرر الحرق؛ والثلج والزيت وفقء الفقاعات تزيده."}]},{id:31,code:"IND-131",icon:"Fuel",accent:"#0e7490",title:"المراجل وأوعية الضغط وأسطوانات الغاز",subtitle:"حدود التشغيل وصمام الأمان وتخزين الأسطوانات ونقلها وما تفعله عند التسرب أو الحريق",summary:"تختزن المراجل وخزانات الهواء المضغوط وأسطوانات الغاز طاقة كبيرة. وحين ينفتح وعاء على نحو غير متوقع يندفع البخار أو الغاز بقوة، وتُقذف القطع، وتقع حرائق أو حروق. تعرض هذه الوحدة على العمال والمشغلين كيف يعملون ضمن الحدود الآمنة، ويتعرفون إلى علامات الخطر، ويخزنون الأسطوانات وينقلونها بأمان، وماذا يفعلون عند تسرب الغاز أو الحريق.",blocks:[{body:"لكل وعاء ضغط لوحة تعريف (nameplate) تبين أعلى ضغط ودرجة حرارة مسموح بهما. والعمل خارج هذه الحدود أو تعديل الوعاء أو اللحام عليه أو العبث بأجهزة الحماية قد يفجّره. لا يشغّل المراجل وأوعية الضغط إلا أشخاص مدرَّبون ومخوَّلون، ويفحصها شخص مختص. تضع الجهة المختصة التراخيص ومواعيد الفحص؛ اتبع تعليمات الدفاع المدني والجهة المختصة."},{heading:"1. المراجل: علامات الخطر",body:"يفحص المشغل المقاييس ومستوى الماء وفق تعليمات الصانع ويبلغ فورًا عن هذه العلامات:",points:["ارتفاع الضغط أو الحرارة فوق الحد العادي.","انخفاض مستوى الماء في زجاجة المستوى أو اختفاؤه.","تكرار تنفيس صمام الأمان للبخار.","تسرب البخار أو الماء، أو أصوات غير عادية، أو رائحة احتراق."]},{heading:"2. صمام الأمان وفتح الأوعية",body:"صمام الأمان هو آخر حماية من الانفجار. لا تسدّه ولا تربطه ولا تضع عليه ثقلًا ولا تغيّر ضبطه أبدًا؛ وإذا تكرر تنفيسه فهذه علامة مشكلة يجب أن يعالجها شخص مختص. قبل فتح أي وعاء أو أنبوب أو غطاء، فرّغ الضغط كاملًا واقطع مصادر الضغط وأقفلها كما في درس الإقفال والوسم (LOTO). صرّف الماء المتجمع من خزانات الهواء المضغوط وفق تعليمات الصانع لأنه يسبب الصدأ ويُضعف الجدار.",critical:!0},{heading:"3. تخزين أسطوانات الغاز ونقلها",body:"تُملأ أسطوانات الغاز بضغط عالٍ؛ وإذا انكسر الصمام قد تنطلق الأسطوانة كالقذيفة:",points:["أبقِ الأسطوانات قائمة ومثبتة بسلسلة أو حزام، مع غطاء الصمام حين لا تُستخدم.","خزّنها في مكان جيد التهوية بعيدًا عن الحرارة واللهب والأسلاك الكهربائية.","خزّن أسطوانات الأكسجين بعيدًا عن أسطوانات الغاز القابل للاشتعال: 6 أمتار (20 قدمًا) على الأقل أو خلف جدار مقاوم للحريق (OSHA).","انقل الأسطوانات بعربة مناسبة؛ لا تدحرجها ولا تجرّها ولا ترفعها من الصمام.","لا تضع زيتًا أو شحمًا على صمامات الأكسجين ومنظماته، ولا تستخدم الأكسجين لتنظيف الملابس أو الغبار.","افحص التسرب بالماء والصابون، لا باللهب أبدًا."]},{heading:"4. تسرب الغاز والبخار والحريق",body:"إذا شممت رائحة غاز: لا تستخدم المفاتيح أو الإنارة أو الهاتف أو اللهب هناك. أغلق الصمام فقط إذا كان قريبًا ويمكن الوصول إليه دون دخول منطقة تجمع الغاز ودون أي شرارة؛ وإلا فلا تقترب، واخرج، وحذّر الآخرين، واتصل بـ 115 من الخارج. إذا اشتعلت أسطوانة أو كان حريق قرب الأسطوانات: لا تطفئ لهب الغاز إن لم تستطع إيقاف الغاز، ولا تقترب من الأسطوانات الساخنة، وأبعد الجميع، وأخبر فرق 115 بعدد الأسطوانات ومكانها. إذا خرج البخار من مرجل فابتعد عن المكان واتصل بـ 115. برّد حروق البخار بماء جارٍ بارد 20 دقيقة واتصل بـ 122.",critical:!0}],steps:[{title:"1. اعرف الحدود",detail:"اقرأ قبل العمل لوحة التعريف وتعليمات الصانع: الضغط والحرارة المسموحان ومن المخوَّل بالتشغيل."},{title:"2. افحص المقاييس",detail:"افحص الضغط والحرارة ومستوى الماء وسجّلها حسب جدول المصنع؛ وأبلغ فورًا عن أي أمر غير عادي."},{title:"3. لا تعبث بأجهزة الحماية",detail:"لا تسد صمام الأمان وأجهزة الإيقاف ولا تربطها ولا تغيّر ضبطها.",critical:!0},{title:"4. فرّغ الضغط قبل الفتح",detail:"قبل فتح أي وعاء أو أنبوب، فرّغ الضغط كاملًا وأقفل المصادر وفق LOTO.",critical:!0},{title:"5. ثبّت الأسطوانات",detail:"أبقِ الأسطوانات قائمة مثبتة بغطائها بعيدًا عن الحرارة، وانقلها بالعربة."},{title:"6. عند التسرب أو الحريق",detail:"اتبع قاعدة تسرب الغاز، ولا تقترب من الأسطوانات الساخنة، وأبعد الجميع، واتصل بـ 115 من الخارج.",critical:!0}],warnings:["لا تسد صمام الأمان ولا تضع عليه ثقلًا أبدًا: إنه آخر ما يمنع انفجار الوعاء.","لا تفحص تسرب الغاز باللهب: اللهب يشعل الغاز؛ استخدم الماء والصابون.","لا تقترب من أسطوانة في النار أو ساخنة: قد تنفجر حتى بعد إطفاء النار."],tips:["ضع عند كل مرجل سجلًا تُدوَّن فيه قراءات المقاييس والفحوص.","خزّن الأسطوانات الممتلئة والفارغة منفصلة وعليها علامة.","لا تستخدم أسطوانة تالفة أو صدئة أو بلا ملصق وأعدها إلى المورّد.","حدد في خطة الطوارئ مواقع المراجل والأسطوانات والصمامات الرئيسية على الخريطة لفرق 115."],activity:{prompt:"أثناء المناوبة ترى صمام الأمان في خزان هواء مضغوط ينفّس الهواء مرارًا. يقول عامل: «صوته مزعج، سنربطه بسلك.» ماذا تفعل؟",options:[{text:"أمنعه، وأوقف الضاغط بالطريقة العادية، وأبلغ المشرف والشخص المختص.",correct:!0,feedback:"تكرار فتح الصمام علامة ضغط زائد أو عطل في المنظم؛ وسدّه يحوّل الخزان إلى قنبلة."},{text:"أتركه يربطه لكنني أراقب مقياس الضغط بنفسي.",correct:!1,feedback:"لا يمكن لإنسان مراقبة المقياس دائمًا، ولا وقت للتصرف حين يرتفع الضغط بسرعة."},{text:"أرفع ضبط الصمام حتى يفتح أقل.",correct:!1,feedback:"ضبط الصمام يحدده لوحة التعريف والشخص المختص فقط؛ ورفعه يدفع الخزان خارج حدوده."},{text:"أبتعد عن الخزان وأتركه حتى نهاية المناوبة.",correct:!1,feedback:"تبقى المشكلة وقد يربط العامل الصمام فعلًا؛ يجب الإبلاغ والإصلاح."}]},caseStudy:[{prompt:"في مخزن الأسطوانات تشم رائحة غاز LPG قوية. الصمام الرئيسي داخل المخزن قرب الأسطوانات. ماذا تفعل؟",options:[{text:"أدخل وأشعل الضوء وأغلق الصمام.",correct:!1,feedback:"مفتاح الإنارة يُحدث شرارة ودخول منطقة الغاز يعرّضك للخطر."},{text:"لا أقترب، وأحذّر الآخرين، وأخرج، وأتصل بـ 115 من الخارج.",correct:!0,feedback:"الصمام داخل منطقة تجمع الغاز، لذا تقضي القاعدة بعدم الاقتراب والاتصال بـ 115 من الخارج."},{text:"ألتقط صورة بالهاتف داخل المخزن لأبيّن مكان التسرب.",correct:!1,feedback:"الهاتف داخل منطقة الغاز قد يكون مصدر اشتعال."}]},{prompt:"بعد قليل يبدأ حريق صغير عند باب المخزن والأسطوانات قريبة منه. لم تصل فرق 115 بعد. يريد عامل سحب الأسطوانات إلى الخارج. ماذا تقول؟",options:[{text:"حسنًا، سنسحبها معًا بسرعة.",correct:!1,feedback:"الأسطوانات قرب النار قد تنفجر في أي لحظة؛ الاقتراب يعرّض الحياة للخطر."},{text:"لا؛ نبتعد جميعًا ونمنع الناس من الاقتراب ونخبر 115 بعدد الأسطوانات ومكانها.",correct:!0,feedback:"الابتعاد والمعلومات الدقيقة لفرق 115 تحمي الأرواح؛ والأسطوانات الساخنة من عمل الفرق المدربة."},{text:"نرش الماء على النار ونبقى قرب الأسطوانات.",correct:!1,feedback:"البقاء قرب الأسطوانات المجاورة للنار خطر، وإطفاء النار وحده مع تسرب الغاز يجمع غازًا غير محترق."}]}],realCase:"سيناريو تدريبي: في مصنع أغذية لاحظ مشغل جديد أن صمام الأمان في أحد المراجل ينفّس البخار مرارًا. أبلغ المشرف فأُوقف المرجل بالطريقة العادية. وجد شخص مختص أن منظم الضغط معطل وأن الضغط كان يتجاوز الحد العادي، ولو سُدّ الصمام لأمكن أن ينفجر الوعاء. استبدل المصنع المنظم، وشكر المشغل، وجعل سجل قراءات المقاييس إلزاميًا في كل مناوبة.",quiz:[{question:"يفتح صمام الأمان في مرجل مرارًا. ما التصرف الصحيح؟",options:[{text:"إبلاغ المشرف ليجد شخص مختص السبب",correct:!0},{text:"ربط الصمام بسلك حتى نهاية المناوبة",correct:!1},{text:"رفع ضبط الصمام ليفتح أقل",correct:!1},{text:"وضع ثقل على الصمام لإيقاف الصوت",correct:!1}],explanation:"تكرار الفتح علامة مشكلة؛ والسد أو الثقل أو تغيير الضبط يلغي آخر حماية."},{question:"كيف تفحص تسرب الغاز من منظم أسطوانة؟",options:[{text:"بعود ثقاب قرب الوصلة",correct:!1},{text:"بالماء والصابون على الوصلة",correct:!0},{text:"بشم الوصلة عن قرب مدة طويلة",correct:!1},{text:"بفتح الصمام كاملًا والاستماع",correct:!1}],explanation:"تظهر الفقاعات عند التسرب دون مصدر اشتعال؛ أما اللهب فيشعل الغاز."},{question:"ما الطريقة الصحيحة لنقل أسطوانة أكسجين داخل المصنع؟",options:[{text:"دحرجتها على الأرض بالقدم",correct:!1},{text:"رفعها من الصمام بيد واحدة",correct:!1},{text:"على عربة، مثبتة وبغطائها",correct:!0},{text:"جرّها بحزام على الأرض",correct:!1}],explanation:"العربة والتثبيت والغطاء تحمي الصمام من الكسر؛ والصمام المكسور قد يقذف الأسطوانة."},{question:"ما المطلوب قبل فتح غطاء خزان هواء مضغوط للفحص؟",options:[{text:"أن يكون الضاغط متوقفًا بزر الإيقاف ومصباحه مطفأ",correct:!1},{text:"تفريغ الضغط كاملًا وإقفال المصادر بـ LOTO",correct:!0},{text:"أن يبين المقياس نصف الضغط العادي أو أقل",correct:!1},{text:"وقوف عامل عند الضاغط كي لا يشغّله أحد",correct:!1}],explanation:"الضغط المتبقي قد يقذف الغطاء بقوة؛ والزر لا يقطع الطاقة ولا يحل شخص محل القفل."},{question:"يبدأ حريق قرب مجموعة أسطوانات غاز. أي فعل خاطئ؟",options:[{text:"إبعاد الجميع ومنع الاقتراب",correct:!1},{text:"الاتصال بـ 115 وذكر عدد الأسطوانات ومكانها",correct:!1},{text:"الاقتراب من الأسطوانات الساخنة لسحبها باليد",correct:!0},{text:"عدم إطفاء لهب الغاز إن تعذّر إيقاف الغاز",correct:!1}],explanation:"الأسطوانات المحمومة قد تنفجر؛ والاقتراب يعرّض الحياة للخطر. هذا عمل فرق 115."},{question:"أصيب عامل بحرق من بخار المرجل. ما الإسعاف الأولي الصحيح؟",options:[{text:"ماء جارٍ بارد 20 دقيقة والاتصال بـ 122",correct:!0},{text:"ثلج على الحرق حتى يزول الألم",correct:!1},{text:"معجون أسنان على الحرق ليبرد",correct:!1},{text:"زيت طعام كي لا يجف الجلد",correct:!1}],explanation:"الماء الجاري البارد 20 دقيقة يبرد الحرق؛ والثلج والمعجون والزيت تزيد الضرر."}]},{id:32,code:"IND-132",icon:"Thermometer",accent:"#dc2626",title:"الإجهاد الحراري في العمل",subtitle:"الماء والراحة والظل والتأقلم مع الحر والتعرف إلى الإنهاك الحراري والإسعاف الأولي لضربة الحرّ",summary:"العمل في الحر، في الخارج تحت الشمس أو قرب الأفران والمراجل، يُفقد الجسم الماء والأملاح وقد يسبب الإنهاك الحراري وضربة الحرّ التي قد تقتل. تعرض هذه الوحدة على العمال والمشرفين كيف يضبطون الحر، ويتعرفون إلى العلامات الأولى، وماذا يفعلون فورًا عند ضربة الحرّ.",blocks:[{body:"يبرّد الجسم نفسه بالتعرق. وحين يكون الجو حارًا ورطبًا، أو العمل شاقًا، أو تمنع ملابس الوقاية مرور الهواء، لا يكفي التعرق فترتفع حرارة الجسم. لا توجد درجة حرارة يقال إن الجو عندها آمن تمامًا؛ فالخطر يتعلق بالحرارة والرطوبة والشمس وشدة العمل والملابس. تضع الجهات المختصة أوقات العمل في الحر وقواعده؛ اتبع تعليمات الدفاع المدني والجهة المختصة."},{heading:"1. من الأكثر عرضة للخطر",body:"قد يصاب أي عامل بأمراض الحر، لكن الخطر أعلى لدى:",points:["العمال الجدد والعائدون بعد غياب طويل، لأن أجسامهم لم تتأقلم مع الحر بعد.","العمل الشاق أو تحت الشمس أو قرب مصادر الحرارة.","ملابس الوقاية التي تمنع مرور الهواء.","المرض ونقص الماء في الجسم وبعض الأدوية وإصابة سابقة بأمراض الحر؛ ويمكن للعامل إبلاغ المشرف بسرية."]},{heading:"2. الوقاية: الماء والراحة والظل",body:"يضع المصنع خطة للحر ويتبعها كل عامل:",points:["ماء بارد نظيف قرب مكان العمل، وشربه بانتظام قبل الشعور بالعطش.","استراحة في مكان بارد أو ظليل، والأعمال الشاقة في أبرد أوقات النهار.","التأقلم مع الحر: يبدأ العمال الجدد بعمل أخف ويزيدونه تدريجيًا.","الظل والتهوية والمراوح والحواجز العازلة لحرارة المصادر في الأماكن الحارة.","نظام الزميل: يراقب كل عامل زميله، لأن المصاب كثيرًا ما لا يلاحظ علاماته."]},{heading:"3. الإنهاك الحراري",body:"علامات الإنهاك الحراري: تعرق غزير، وضعف، ودوار، وصداع، وغثيان أو قيء، وعطش، وتشنج العضلات. أوقف العامل عن العمل، وانقله إلى مكان بارد، وأرخِ ملابسه، وبرّد جسمه بالماء البارد والقماش المبلل. إذا كان واعيًا تمامًا فليشرب الماء ببطء. إذا ساءت العلامات أو لم تتحسن فاتصل بـ 122. وإذا اضطرب وعيه فهذه ضربة الحرّ."},{heading:"4. ضربة الحرّ: حالة طارئة تهدد الحياة",body:"اضطراب الوعي، والسلوك الغريب، والكلام المتداخل، والتشنج أو السقوط في الحر علامات ضربة الحرّ؛ وقد يبقى الجلد متعرقًا. اتصل بـ 122 واطلب المساعدة، وابدأ التبريد فورًا: أفضل طريقة غمر الجسم من الرقبة إلى الأسفل في ماء بارد 15 دقيقة أو حتى يصفو تفكيره، أيهما أسبق. وإن تعذّر ذلك فاستخدم الدش البارد والمناشف المبللة وكمادات الثلج الملفوفة بقماش والتهوية. لا تعطه شيئًا ليشربه ما دام وعيه مضطربًا. إذا فقد الوعي وكان يتنفس طبيعيًا ولا يُشتبه بإصابة في الرقبة أو الظهر، فضعه على جنبه (وضعية الإفاقة) وابقَ معه.",critical:!0}],steps:[{title:"1. اشرب الماء",detail:"اشرب الماء بانتظام قبل العطش، وأبقِ الماء البارد قرب مكان العمل."},{title:"2. الراحة والظل",detail:"استرح في مكان بارد وفق خطة الحر، واترك العمل الشاق لأبرد الأوقات."},{title:"3. راقب زميلك",detail:"اعرف علامات الإنهاك الحراري فيك وفي زميلك وأبلغ عنها فورًا."},{title:"4. الإنهاك: أوقف العمل وبرّد",detail:"انقله إلى مكان بارد، وأرخِ ملابسه، وبرّده، وأعطه ماءً إن كان واعيًا؛ وإن لم يتحسن فاتصل بـ 122.",critical:!0},{title:"5. ضربة الحرّ: 122 والتبريد فورًا",detail:"اتصل بـ 122 وبرّده فورًا بالماء البارد، والأفضل غمر الجسم من الرقبة إلى الأسفل في ماء بارد؛ ولا تعطه شيئًا يشربه إن اضطرب وعيه.",critical:!0}],warnings:["لا تعطِ شيئًا للشرب لشخص مضطرب الوعي أو فاقده: قد يختنق.","لا تؤخر التبريد بانتظار الإسعاف: في ضربة الحرّ كل دقيقة مهمة.","لا تترك عاملًا مريضًا وحده ولا تدعه يقود سيارته إلى البيت وحده."],tips:["لون البول مؤشر بسيط: البول الداكن علامة نقص الماء.","البس ملابس خفيفة فاتحة اللون تسمح بمرور الهواء إن سمحت ملابس الوقاية.","جهّز قبل الصيف مكانًا للتبريد وحوضًا للماء البارد في المصنع.","حدّث خطة العمل مع المشرف في موجات الحر غير المعتادة."],activity:{prompt:"عند الظهيرة يقول زميل جديد قرب الفرن إن رأسه يؤلمه ويشعر بالدوار ويتعرق كثيرًا. كلامه طبيعي. ماذا تفعل؟",options:[{text:"أقول له: «اشرب ماءً وأكمل العمل، المناوبة توشك أن تنتهي.»",correct:!1,feedback:"هذه علامات إنهاك حراري؛ والاستمرار قرب الفرن قد يؤدي إلى ضربة الحرّ."},{text:"أوقفه عن العمل، وأنقله إلى مكان بارد، وأبرّده وأعطيه ماءً، وإن لم يتحسن أتصل بـ 122.",correct:!0,feedback:"هو واعٍ لذا الماء والتبريد صحيحان؛ والمراقبة لازمة لأن حالته قد تسوء."},{text:"أعطيه حبة لصداع الرأس وأتركه في مكانه.",correct:!1,feedback:"الدواء لا يخفض الحرارة وهو ما زال قرب مصدرها؛ يحتاج إلى التبريد."},{text:"أقول له أن يقود سيارته إلى البيت ويرتاح.",correct:!1,feedback:"قد يضطرب وعيه في الطريق؛ لا يُترك المريض وحده."}]},caseStudy:[{prompt:"في ساحة تحميل خارجية يبدأ عامل بالكلام المتداخل ولا يعرف أين هو ثم يسقط. ما زال جلده متعرقًا. ما أول تصرف؟",options:[{text:"أعطيه ماءً باردًا ليشربه حتى يتحسن.",correct:!1,feedback:"وعيه مضطرب؛ والشرب قد يسبب الاختناق."},{text:"أتصل بـ 122، وأطلب المساعدة، وأبدأ التبريد بالماء البارد فورًا.",correct:!0,feedback:"هذه ضربة حرّ؛ والجلد المتعرق لا ينفيها. التبريد الفوري و122 ينقذان الحياة."},{text:"أنتظر حتى يتوقف تعرقه لأعرف هل هي ضربة حرّ.",correct:!1,feedback:"قد يبقى الجلد متعرقًا في ضربة الحرّ؛ والانتظار يؤخر التبريد."}]},{prompt:"وصل المساعدون. في المصنع حوض كبير للماء البارد ولم تصل سيارة الإسعاف بعد. ما زال العامل مضطرب الوعي لكنه يتنفس. ماذا يفعلون؟",options:[{text:"يغمرون جسمه من الرقبة إلى الأسفل في الماء البارد ويُبقون رأسه فوق الماء، حتى 15 دقيقة أو حتى يصفو تفكيره.",correct:!0,feedback:"هذه أسرع طريقة للتبريد؛ ويجب أن يبقى الرأس فوق الماء وأن يكون معه أحد."},{text:"يضعونه في سيارة مع مروحة حتى تصل الإسعاف.",correct:!1,feedback:"المروحة وحدها تبرد ببطء شديد مع توفر الماء البارد؛ المطلوب تبريد سريع."},{text:"يمسحون وجهه فقط بقماش مبلل وينتظرون الإسعاف.",correct:!1,feedback:"قماش على الوجه لا يخفض حرارة الجسم؛ يجب تبريد الجسم كله بسرعة."}]}],realCase:"سيناريو تدريبي: في مصنع للطابوق كان عامل جديد يعمل تحت الشمس في يومه الثاني. لاحظ زميله أن كلامه صار متداخلًا وأنه لا يعرف أين هو، فاتصل بالمشرف وبـ 122. غمر فريق المصنع جسمه فورًا في حوض ماء بارد مع إبقاء رأسه فوق الماء، ولم يعطوه شيئًا ليشربه. بعد دقائق صفا تفكيره أكثر، ونقلته سيارة الإسعاف إلى المستشفى. بعد ذلك وضع المصنع خطة تأقلم للعمال الجدد وجعل نظام الزميل إلزاميًا.",quiz:[{question:"عامل يتكلم بكلام متداخل في الحر لكن جلده ما زال متعرقًا. علامَ يدل ذلك؟",options:[{text:"قد تكون ضربة حرّ؛ والتعرق لا ينفيها",correct:!0},{text:"مجرد تعب عادي لأنه ما زال يتعرق",correct:!1},{text:"علامة انخفاض السكر ويحتاج إلى حلوى",correct:!1},{text:"تشنج عضلي يتحسن بالتدليك",correct:!1}],explanation:"اضطراب الوعي في الحر العلامة الرئيسية لضربة الحرّ حتى مع جلد رطب؛ يلزم 122 والتبريد الفوري."},{question:"ما أفضل طريقة لتبريد مصاب بضربة الحرّ إن توفرت؟",options:[{text:"غمر الجسم من الرقبة إلى الأسفل في ماء بارد",correct:!0},{text:"وضعه في غرفة وانتظار الإسعاف",correct:!1},{text:"إعطاؤه ماءً دافئًا ليتأقلم الجسم ببطء",correct:!1},{text:"لفه ببطانية لإيقاف الرجفة",correct:!1}],explanation:"الغمر في الماء البارد 15 دقيقة أو حتى يصفو التفكير هو الأسرع؛ وإلا فالدش والمناشف المبللة والثلج والتهوية."},{question:"أي فعل خاطئ مع عامل مضطرب الوعي بسبب ضربة الحرّ؟",options:[{text:"الاتصال بـ 122 وطلب المساعدة",correct:!1},{text:"إعطاؤه ماءً ليشرب حتى يزول عطشه",correct:!0},{text:"التبريد بالماء البارد والمناشف المبللة",correct:!1},{text:"البقاء معه ومراقبة تنفسه",correct:!1}],explanation:"مضطرب الوعي لا يبلع بأمان وقد يختنق؛ لا تعطه شيئًا يشربه."},{question:"يبدأ عامل جديد أسبوعه الأول قرب فرن. ما الصحيح؟",options:[{text:"نفس عمل القدامى وساعاتهم من اليوم الأول",correct:!1},{text:"عمل أخف في البداية وزيادة تدريجية مع المراقبة",correct:!0},{text:"العمل وقت الظهيرة فقط ليتأقلم أسرع",correct:!1},{text:"الشرب في نهاية المناوبة فقط كي لا يتوقف العمل",correct:!1}],explanation:"يحتاج الجسم إلى وقت ليتأقلم مع الحر؛ والعمال الجدد والعائدون أكثر عرضة للخطر."},{question:"عامل يتعرق بغزارة ويشعر بالدوار والغثيان لكنه واعٍ تمامًا. ما أول تصرف؟",options:[{text:"إيقاف العمل والنقل إلى مكان بارد والتبريد",correct:!0},{text:"مواصلة العمل حتى موعد الاستراحة",correct:!1},{text:"مشروب سكري بالكافيين للطاقة",correct:!1},{text:"نقله إلى عمل آخر تحت الشمس",correct:!1}],explanation:"هذه علامات إنهاك حراري؛ التوقف والتبريد يمنعان ضربة الحرّ. وإن لم يتحسن فـ 122."},{question:"يقول مشرف: «درجة الحرارة اليوم عادية، فلا خطر من الحر.» لماذا هذا خطأ؟",options:[{text:"لأن الحرارة تُقاس دائمًا خطأً في المصانع",correct:!1},{text:"لأن الرطوبة والشمس والعمل والملابس مهمة أيضًا",correct:!0},{text:"لأن أمراض الحر تحدث ليلًا فقط",correct:!1},{text:"لأن العمال القدامى لا يصابون بأمراض الحر أبدًا",correct:!1}],explanation:"لا توجد درجة حرارة تحدد السلامة وحدها؛ فالخطر مرتبط بعوامل عدة."}]}],e={lessons:t};export{e as default,t as lessons};
